ROOT = Path(__file__).resolve().parent
CONFIG_PATH = ROOT / "session.config.json"
# The generated, inherited canon digest (ADR-0022 tier 2). `start` injects it into
# the session as additionalContext so the universal principles/habits reach the
# Architect's context deterministically every session — the code channel delivering
# the text tier, instead of trusting the LLM to remember to read a file (P15). Absent
# is tolerated (federation always has it; a fresh kit ships it).
CANON_PATH = ROOT / "CANON.md"
# The generated, inherited standard role-doc section (ADR-0024). `start` injects it
# alongside CANON.md so the session rituals + standard substrate reach the Architect's
# context every session, instead of living as hand-authored prose in each role doc that
# an Architect can re-author and drop a step from (the stamp bug one member hit; ADR-0024 §3).
# Generated from standard-source.md by curate/standardize.py. Absent is tolerated.
STANDARD_PATH = ROOT / "STANDARD.md"


# --- WI-0029: one layout declaration, one resolver ----------------------------------
#
# Every member-variable path the shared substrate looks up INSIDE a member's repo is
# declared in one place — the optional `layout` block in session.config.json — and read
# through one function. Nothing else may name these paths as literals.
#
# The shape this replaces grew a top-level config key per assumption (`adr_dir`,
# `user_profile`, `inbox`, `handoff`), and each key only ever fixed the single call site
# that happened to read it. The proof is `curate/metrics.py`: `_handoff_name` derived the
# handoff filename from the member's own config, and `mine_briefs` read the inbox from
# the literal `proposed-edits` twelve lines below it. Any member on another layout mined
# zero briefs and reported `0 briefs waiting` — a wrong answer wearing the shape of a
# clean one, which is the whole harm. One key per bug cannot converge: the fix has to be
# a place to look, not another key to add.
#
# Resolution order, most specific first:
#   1. cfg["layout"][key]   the declaration
#   2. cfg[key]             the legacy top-level key — what every member ships today
#   3. LAYOUT_DEFAULTS[key] the federation shape, which is what everyone actually runs
#
# So no member's behaviour changes until it writes a `layout` block, and a path added
# later costs ONE default here instead of a hunt through every reader.
#
# An empty default means "no honest default exists" — `role_doc` is per-system and
# required; `inbox` absent means the member has no mailbox, which is different from a
# mailbox at a default location; `user_profile` is absent for every member but the
# federation, which hosts it. Empty is returned as empty so a caller can tell
# "not declared" from "declared as the default" rather than folding them together.
LAYOUT_DEFAULTS = {
    "handoff": "session-handoff.md",
    # `status_file`, not `status` — the key name must match the LEGACY top-level key,
    # because tier 2 of the resolution reads `cfg[key]` by that same name. A default
    # filed under a different name than the lookup silently resolves to "" and joins to
    # the repo ROOT; caught by the default-shape test rather than in the wild.
    "status_file": "STATUS.md",
    # The THIRD trunk-only compiled view (ADR-0105), and the one that was never declared.
    # Its two siblings above resolved through `layout_of` from the day this block existed;
    # `ROADMAP.md` stayed a hardcoded literal in six call sites. `_harness_owned` is the
    # clearest evidence: it names all three in one expression and resolves exactly two of
    # them. A path the substrate writes but the config cannot name is a hole in the single
    # source, and it is precisely the hole the rebase resolver fell into — it asked CFG
    # "what is generated here?" and got an answer missing this file (WI-0252).
    "roadmap": "ROADMAP.md",
    "adr_dir": "adr",
    # Not a path, and deliberately filed here anyway (WI-0128, reported by a member
    # Architect): WHERE a member's ADRs live and WHAT they are called are one
    # arrangement, and only the first was declarable. That member names all of its own
    # ADRs `ADR-NNN-slug.md`, so after correctly declaring `adr_dir` the counter still read ZERO ADRs — the
    # allocator answered `0001` and the land gate built to catch that collision read the
    # same counter and certified clean. Two layers blind on one assumption, the second
    # member to hit it through a different door. Empty default = today's pattern exactly.
    "adr_prefix": "",
    # Not a repo path either (see `adr_prefix` above) and filed here for the same
    # reason: WHICH interpreter a member runs on is part of how that member is
    # arranged, and `layout_of` is the one resolver every surface already reads. The
    # empty default means "not declared" — `interpreter.resolve` then falls to the
    # per-OS default rather than to a path nobody chose (WI-0328).
    "interpreter": "",
    "work_items": "work-items",
    "journal_dir": "sessions/journal",
    "role_doc": "",
    # ADR-0123. WHERE a member keeps its role-doc CHANGELOG, when it keeps it
    # anywhere but inside the role doc. Empty is the FLEET DEFAULT and means inline —
    # every member but the federation is here, and none of them needs an edit. This is
    # deliberately NOT a second `role_doc`: repointing that key would move the version
    # line, the land warn-gate, the reconcile drift read and the adopt-runner with it.
    "changelog_doc": "",
    "inbox": "",
    "user_profile": "",
}


def layout_of(cfg: dict | None, key: str) -> str:
    """The repo-relative path a member declares for `key`, as a plain string.

    PURE on purpose — it takes an already-parsed config dict rather than reading one, so
    the identical resolution serves this repo (`_load_config`) and ANOTHER member's repo
    (the curate scripts, which mine every member checkout). A second implementation on the curate
    side is exactly the duplication this item exists to remove, so there is one function
    and both sides import it.

    Never raises and never returns None: a missing/!dict config, an unknown key, or a
    non-string declaration all fall through to the default, because a layout lookup must
    not be able to break a status probe. Unknown keys return "" rather than KeyError —
    a caller asking for a path we have no opinion about should get "no opinion"."""
    if isinstance(cfg, dict):
        block = cfg.get("layout")
        if isinstance(block, dict):
            v = block.get(key)
            if isinstance(v, str) and v:
                return v
        v = cfg.get(key)
        if isinstance(v, str) and v:
            return v
    return LAYOUT_DEFAULTS.get(key, "")


# ─────────────────────────────────────────────── ADR-0095: the declared data root
#
# Shared gitignored data lives OUTSIDE the repository, reached through a declared data
# root. ADR-0009 decided this on 2026-05-23 and the REJECTED option is what shipped —
# every data path a repo-relative literal resolved against ROOT — which was harmless
# until ADR-0060 worktree lanes, since a worktree materialises TRACKED files only and
# gitignored data is simply ABSENT in a lane.
#
# Resolution order, first hit wins (ADR-0095 D2):
#   1. POGA_DATA_ROOT              the escape hatch, and the seam the tests drive
#   2. ${XDG_DATA_HOME:-$HOME/.local/share}/poga/<system-id>/
#
# `$HOME` is what solves the multi-machine problem: a disk shared between machines can
# resolve to a different absolute path on each, and `$HOME` resolves correctly on each WITHOUT either machine storing the other's prefix.
# That is why this is a convention plus an env var rather than a config field: a
# `data-root.local` beside `reconcile-roots.local` would be circular — invisible in a
# lane for the exact reason this mechanism exists.
DATA_ROOT_ENV = "POGA_DATA_ROOT"

# The three outcomes, kept apart on purpose (ADR-0095 D6 /
# [`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
# Folding "cannot see it" into "nothing there" is the originating defect of this whole
# neighbourhood — session 90's `inbox: (empty)` printed over two live briefs.
DATA_ROOT_RESOLVED = "resolved"
DATA_ROOT_UNREADABLE = "declared-but-unreadable"
DATA_ROOT_UNDECLARED = "undeclared"


def system_id_of(cfg: dict | None) -> str:
    """The member's system id — `architect_id` minus the `-arch` suffix per ADR-0006.

    Honours an explicit `system_id` when a member declares one, because the convention is
    a derivation rule and not a law of nature; a member that renamed one half before the
    other (mid-rename) needs somewhere to say so."""
    if not isinstance(cfg, dict):
        return ""
    explicit = cfg.get("system_id")
    if isinstance(explicit, str) and explicit:
        return explicit
    aid = cfg.get("architect_id")
    if isinstance(aid, str) and aid:
        return aid[:-len("-arch")] if aid.endswith("-arch") else aid
    return ""


def data_root_of(cfg: dict | None, env: dict | None = None) -> tuple[Path | None, str, str]:
    """(root, state, why) for a member's declared data root. PURE — takes a parsed config
    and an environment, so the identical resolution serves this repo and any member repo
    the curate scripts mine, exactly like `layout_of`.

    Returns one of the three DATA_ROOT_* states and never raises. `why` is a sentence for
    the human, always populated, including on success — a detector whose good path says
    nothing cannot be told from one that did not run.

    An UNSET `$HOME` resolves to UNDECLARED rather than to a plausible-looking path.
    `pathlib.Path.home()` would happily fall back to the password database and hand back a
    real directory that is not where anybody's data is — a silently wrong answer wearing
    the shape of a right one, which is the specific failure this ADR exists to end."""
    env = os.environ if env is None else env
    explicit = env.get(DATA_ROOT_ENV)
    if isinstance(explicit, str) and explicit.strip():
        return (Path(explicit.strip()).expanduser(), DATA_ROOT_RESOLVED,
                f"{DATA_ROOT_ENV} is set")
    sid = system_id_of(cfg)
    if not sid:
        return (None, DATA_ROOT_UNDECLARED,
                "no `architect_id` (or `system_id`) in session.config.json, so the "
                "per-system default has no name to build on")
    xdg = env.get("XDG_DATA_HOME")
    if isinstance(xdg, str) and xdg.strip():
        return (Path(xdg.strip()).expanduser() / "poga" / sid, DATA_ROOT_RESOLVED,
                "XDG_DATA_HOME default")
    home = env.get("HOME")
    if not (isinstance(home, str) and home.strip()):
        return (None, DATA_ROOT_UNDECLARED,
                f"neither {DATA_ROOT_ENV}, XDG_DATA_HOME nor HOME is set — refusing to "
                f"guess a data root from the password database, which would return a "
                f"real directory that is not where the data is")
    return (Path(home.strip()) / ".local" / "share" / "poga" / sid, DATA_ROOT_RESOLVED,
            "$HOME default")


def data_paths_of(cfg: dict | None) -> list[str]:
    """The member's own declared data paths (ADR-0095 D3), or [] when it declares none.

    Declared BY THE MEMBER and never hardcoded here, because `session.py` is byte-identical
    fleet substrate: the list it used to carry (`SHARED_LANE_PATHS`) enumerated the
    FEDERATION's data paths and shipped to everyone, so a member whose data path was not on
    our list got no link, no warning, and an empty view that read exactly like having
    nothing to say.

    An empty list means "declares no shared data", which is honest and correct for a fresh
    Architect — never "use the federation's set"."""
    if not isinstance(cfg, dict):
        return []
    block = cfg.get("data")
    if not isinstance(block, list):
        return []
    return [p for p in block if isinstance(p, str) and p and not p.startswith("/")]


def data_root_state(cfg: dict | None = None, env: dict | None = None
                    ) -> tuple[Path | None, str, str]:
    """`data_root_of` plus the readability half — the third state D6 requires.

    A root that resolves on paper but cannot be read is NOT the same fact as one that was
    never declared, and reporting them identically is how a missing data root would hide
    behind a member that simply has no data."""
    root, state, why = data_root_of(CFG if cfg is None else cfg, env)
    if state != DATA_ROOT_RESOLVED or root is None:
        return root, state, why
    if not data_paths_of(CFG if cfg is None else cfg):
        return root, state, f"{why}; the member declares no `data` paths"
    if not root.is_dir():
        return (root, DATA_ROOT_UNREADABLE,
                f"{why}, but {root} is not a readable directory — data is declared and "
                f"NOT visible, which is not the same as having none")
    return root, state, why


# ──────────────────────────────────── ADR-0106: residency — where a system runs, and
#                                      where its production data lives
#
# The 2026-08-22 ruling: dev work happens on the dev box; the always-on runner host is
# reserved for production/operational work — any member whose production mode is more than
# a dev tool or dev environment runs there. The axis is RUNTIME, not system identity.
#
# TWO AXES, NOT ONE (D1), because one cannot express the ruling operator had already made —
# "a member's data root is not one location per system, it is potentially TWO." A single
# `production: yes/no` field would resolve some members' production data onto the
# dev box, because those systems have no daemon to justify a Runner
# presence. And the federation is the mirror image: a DEV system that owns a production
# process on the Runner (the ADR-0050 adoption runner, a LaunchAgent that must sit in the
# Runner's Aqua session because `claude -p` reads the login keychain). Neither is
# expressible as one fact per member.
#
# VALUES ARE MACHINE-MAP LABELS, NEVER PATHS (D2). ADR-0095 D2's argument on a second
# surface: a disk shared between machines can resolve to a different absolute path on
# each, so a literal is wrong on at least one of them by construction. A label resolves through the member's own `machine_map` and the same
# tracked declaration is correct everywhere.
#
# A MISSING BLOCK IS UNDECLARED, NEVER "NO PRODUCTION". Folding "we never asked" into
# "there is nothing" is the collapse that printed session 90's `inbox: (empty)` over two
# live briefs, and a promotion path is a worse place to repeat it
# ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
RESIDENCY_DECLARED = "declared"
RESIDENCY_UNRESOLVABLE = "declared-but-unresolvable"
RESIDENCY_UNDECLARED = "undeclared"
RESIDENCY_CONTRADICTED = "declared-and-contradicted"

# The role this machine's data root plays for this member. `unknown` is a real answer,
# not a failure to compute one: without a residency declaration nothing can say whether
# the root under your feet is the production copy or the dev copy, and guessing is how a
# session edits production records believing they are scratch.
DATA_ROLE_PRODUCTION = "production"
DATA_ROLE_DEV = "dev"
DATA_ROLE_UNKNOWN = "unknown"

RESIDENCY_BYPASS_ENV = "POGA_ALLOW_DEV_ON_PROD"


def residency_of(cfg: dict | None) -> dict | None:
    """The member's declared `residency` block, normalised, or None when UNDECLARED.

    PURE, like `layout_of` and `data_root_of`, and for the same reason: the identical
    resolution has to serve this repo and any member repo the curate scripts mine, or the
    second implementation becomes the drift.

    Returns None for a missing or malformed block — the caller must then treat the member
    as UNDECLARED and fail OPEN, never as "no production". A present block with a missing
    key is ALSO None-valued for that key, which is the honest reading: `{"process": null}`
    declares no production process, `{}` declares nothing at all.

    A declared value is a machine LABEL (`"Runner"`), never a path. Anything that is not a
    non-empty string — a number, a list, an accidental absolute path — normalises to None
    rather than being carried forward as a value nothing can resolve."""
    if not isinstance(cfg, dict):
        return None
    block = cfg.get("residency")
    if not isinstance(block, dict):
        return None

    def _label(key: str) -> str | None:
        v = block.get(key)
        if isinstance(v, str) and v.strip() and not v.startswith("/"):
            return v.strip()
        return None

    if "process" not in block and "data" not in block:
        return None
    # `restart` WAS a third key here, under the superseded ADR-0106 D4. It is withdrawn:
    # how a promoted process gets picked up is the deploy contract's own `restart` field
    # (ADR-0103 D5), which lives in the deployed system's repo where the rest of its
    # deploy facts already are. Two declarations of one fact is the P16 duplication that
    # D1's own argument rejects, and the contract's copy is the one the runner reads.
    # A stale `restart` key in a member's config is IGNORED rather than an error — a
    # member that declared one under the old design must not fail to load.
    return {"process": _label("process"), "data": _label("data")}


def machine_labels_of(cfg: dict | None) -> set[str]:
    """Every machine label this member's `machine_map` can produce.

    The resolvability half of D2. A residency value naming a machine that is absent from
    the map is NOT a pass and NOT a silent skip — it is the WI-0148 failure, where a
    session on a machine the member's map has no row for stamps a raw ComputerName.
    A declaration nothing can resolve has to read differently from
    one that resolves to "not here"."""
    if not isinstance(cfg, dict):
        return set()
    m = cfg.get("machine_map")
    if not isinstance(m, dict):
        return set()
    return {v for v in m.values() if isinstance(v, str) and v}


def residency_state(cfg: dict | None, machine: str,
                    production_root_present: bool | None = None) -> tuple[str, str]:
    """(state, why) — the four outcomes of D8, kept apart on purpose.

    PURE: `machine` is passed in rather than detected, so a test can drive the Runner's
    answer from devbox. A check that read the real machine would pass on the box that
    wrote it and prove nothing about the other one — the same discipline ADR-0095's tests
    hold for `$HOME`.

    `production_root_present` is the caller's observation, not this function's: the pure
    core must stay testable without a filesystem. Pass None and the contradiction state
    simply cannot be reached, which is the correct answer for a caller that did not look.

    Four states rather than a boolean, per
    [`ship-the-detector-with-the-capability`](habits/master.md#ship-the-detector-with-the-capability):
    an exemption that defaults to "pass" does not merely fail to detect a gap, it
    certifies it."""
    res = residency_of(cfg)
    if res is None:
        return (RESIDENCY_UNDECLARED,
                "no `residency` block in session.config.json — which is NOT the same as "
                "declaring no production mode (ADR-0106 D1). Nothing here can say whether "
                "this machine is a production host or whether the data under it is the "
                "production copy.")

    known = machine_labels_of(cfg)
    named = [v for v in (res.get("process"), res.get("data")) if v]
    # NOT `if known and v not in known`. That short-circuit made an EMPTY or absent
    # `machine_map` pass every declaration as `declared` — the cleanest verdict this
    # function has — when a member with no map can resolve nothing at all. The tell it
    # was never intended is three lines down: the message already renders that case as
    # "it yields nothing", a branch the short-circuit made unreachable.
    unresolvable = [v for v in named if v not in known]
    if unresolvable:
        return (RESIDENCY_UNRESOLVABLE,
                f"residency names {', '.join(sorted(set(unresolvable)))}, which "
                f"machine_map cannot produce (it yields "
                f"{', '.join(sorted(known)) or 'nothing'}) — the WI-0148 failure. A "
                f"label no map resolves is not a location.")

    proc, data = res.get("process"), res.get("data")
    if (production_root_present is False and data and data == machine):
        return (RESIDENCY_CONTRADICTED,
                f"this machine is {machine}, declared as the production DATA host, but "
                f"the production data root is not present here. The declaration and the "
                f"disk disagree, and the declaration is the one being trusted by "
                f"everything else.")
    return (RESIDENCY_DECLARED,
            f"process={proc or 'none'}, data={data or 'none'}; this machine is {machine}.")


def is_production_host(cfg: dict | None, machine: str) -> bool | None:
    """Does this member run its production PROCESS on this machine?

    True / False / **None**, and the None is the point (D6). It means UNDECLARED — the
    caller must fail OPEN. `session.py` ships byte-identical fleet-wide, so refusing on
    "could not determine" would block every launch on every member that has not yet
    declared, turning a missing declaration into a missing capability. That is ADR-0096
    D6's argument, and it applies here unchanged."""
    res = residency_of(cfg)
    if res is None:
        return None
    proc = res.get("process")
    if proc is None:
        return False
    return proc == machine


def data_role_of(cfg: dict | None, machine: str) -> tuple[str, str]:
    """(role, why) — is the data root under this machine the PRODUCTION copy or the DEV copy?

    D7. The path formula does not change and deliberately so: both roots sit under
    `${XDG_DATA_HOME:-$HOME/.local/share}/poga/<system-id>/`, which already differs per
    machine by construction, so the two roots need no second naming scheme and no machine
    stores the other's prefix. What was missing was never a second path — it was the
    ANSWER to which copy you are standing on, and without it a session can edit production
    records believing they are scratch.

    A member declaring `data: null` has one root everywhere; that is today's behaviour and
    needs no migration."""
    res = residency_of(cfg)
    if res is None:
        return (DATA_ROLE_UNKNOWN,
                "no `residency` block — nothing can say which copy this is (ADR-0106 D1)")
    data = res.get("data")
    if data is None:
        return (DATA_ROLE_DEV,
                "the member declares no production data root, so the dev root is the "
                "only root and this is it")
    if data == machine:
        return (DATA_ROLE_PRODUCTION,
                f"this machine is {machine}, the declared production data host")
    return (DATA_ROLE_DEV,
            f"the production data root is on {data}; this machine is {machine}, so this "
            f"is the dev copy")


def read_member_config(repo: Path) -> dict | None:
    """A member repo's raw `session.config.json`, or None if it is absent/unreadable.

    The one reader every consumer shares, so "how do I find a member's declarations" has
    a single answer. Returns None — not {} — so a caller can distinguish "no config
    here" from "a config that declares nothing" ([`declare-what-a-check-assumes`])."""
    try:
        c = json.loads((Path(repo) / "session.config.json").read_text(
            encoding="utf-8", errors="replace"))
        return c if isinstance(c, dict) else None
    except (OSError, ValueError):
        return None


def member_layout(repo: Path, key: str) -> str:
    """`layout_of` for another member's repo — read its config, resolve one key.

    The convenience the curate scripts want; it is deliberately a thin join of the two
    functions above rather than its own logic, so there is nowhere for a second set of
    fallback rules to grow."""
    return layout_of(read_member_config(repo), key)


def _load_config() -> dict | None:
    """System-specific config — the ONLY thing that differs per system; the script
    itself is identical across federation and every participating Architect (ADR-0022
    code channel). Returns derived values, or None on ANY error. None is tolerated so
    the `check-bash` PreToolUse guard can never break just because config is missing
    or malformed — only `start`/`end` need it, and they guard explicitly."""
    try:
        c = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
        # WI-0029: every layout path below resolves through `layout_of` — the `layout`
        # block, then the legacy top-level key, then the standard default. Reading
        # `c[...]` directly for one of these is the defect this item names.
        # `role_doc` keeps its required-ness (no honest default exists for it): when
        # nothing declares it, `c["role_doc"]` raises and the whole config degrades to
        # None, exactly as before.
        _inbox = layout_of(c, "inbox")
        return {
            "handoff": ROOT / layout_of(c, "handoff"),
            "role_doc": ROOT / (layout_of(c, "role_doc") or c["role_doc"]),
            "tz": ZoneInfo(c["timezone"]),
            "machine_map": c["machine_map"],
            "architect_name": c["architect_name"],
            "architect_id": c["architect_id"],
            "inbox": (ROOT / _inbox) if _inbox else None,
            # The bound user's name, for prose the harness addresses to them (the
            # orphan directive). Config-only variance: the script stays byte-identical
            # across the federation; a config without the field (pre-v2.15.0) degrades
            # to the generic address, so old converged repos need no edit.
            "user_name": c.get("user_name", "the user"),
            # STATUS.md, whose mechanical frontmatter fields `end` stamps (ADR-0035).
            "status": ROOT / layout_of(c, "status_file"),
            # The NON-Claude runtime this member declares for its external `stamp`
            # path. `start`/`end` are the Claude-Code hook path and always
            # record CLAUDE_RUNTIME; only `stamp` consults this. A config without the
            # field (every Claude-only member) degrades to None and `stamp` falls back
            # to its --runtime arg, then "external" — so no existing config needs an edit.
            "runtime": c.get("runtime"),
            # ADR-0106 D1. Carried through RAW, unlike the layout paths above: the
            # residency helpers are pure functions that normalise it themselves, and
            # they must serve another member's config (the curate scripts mine ten
            # checkouts) exactly as they serve this one. Absent degrades to None, which
            # the helpers read as UNDECLARED — a third state, never "no production".
            "residency": c.get("residency"),
            # ADR-0056 (concurrency Phase 2 / C3). All three degrade to the pre-Phase-2
            # behaviour when absent, so an un-refreshed member is unaffected until its
            # config is updated. `trunk`: the trunk branch (default "main"). `branch_sessions`:
            # cut a session branch per session — ADR-0058 flipped the default to FALSE:
            # branches are no longer load-bearing for isolation (attribution + the isolated
            # gate do that job), and two sessions in one tree cannot have separate branches
            # anyway. Kept as an opt-in for the future worktree-lane world. `gate`: the
            # merge-gate command list (default computed at gate time — unittest iff a tests/
            # dir exists).
            "trunk": c.get("trunk", "main"),
            "branch_sessions": c.get("branch_sessions", False),
            "gate": c.get("gate"),
            # Off-repo launch pads. All absent for an ordinary member,
            # which is what makes the whole lane-pad path a no-op there. Kept RAW
            # (repo-relative strings, not ROOT-joined Paths) precisely because the
            # lane-pad builder resolves them against a LANE's worktree, not this one.
            "pad_dir": c.get("pad_dir"),
            "harness_dir": c.get("harness_dir"),
            "settings_path": c.get("settings_path"),
            "architect_settings_path": c.get("architect_settings_path"),
            "role_doc_rel": layout_of(c, "role_doc") or c["role_doc"],
            # Member-variable paths the harness used to hardcode as the federation's
            # own layout (a member, session 10). These two were the first instances of the
            # pattern WI-0029 generalises — a key added per assumption — and they now
            # resolve through the same door as every other layout path. Kept as None
            # when undeclared so existing callers that test for None still work.
            "adr_dir": layout_of(c, "adr_dir") or None,
            "adr_prefix": layout_of(c, "adr_prefix") or None,
            "user_profile": layout_of(c, "user_profile") or None,
        }
    except Exception:
        return None


CFG = _load_config()
# The RAW parsed config, kept beside the derived one so module-level layout lookups
# (JOURNAL_DIR, WI_DIRNAME) resolve through the same `layout_of` door as everything
# else (WI-0029). `_load_config` returns DERIVED values — ROOT-joined Paths and
# defaults already applied — which is the wrong input for a resolver whose whole job
# is to apply those defaults. None when the config is absent or malformed; every
# lookup below degrades to the standard default in that case rather than failing.
CFG_RAW = read_member_config(ROOT)

# A real dated session entry header: '## 2026-06-04 — Session 22 — title'
ENTRY_RE = re.compile(r"^## (\d{4}-\d{2}-\d{2}) — Session (\d+\w*) — (.*)$")
# A SESSION LOG data row: '| 22 | 2026-06-04 | 22:20 UTC | Laptop | v1.3.0 | title |'
ROW_RE = re.compile(r"^\| *(\d+)(NC)? *\|")

# The runtime recorded on stamps written by the Claude-Code hook path (`start`/`end`).
# S1 (2026-07-14-federation-metrics): the runtime is the last ` · ` field on each
# Start/End stamp line, so cross-runtime operation is minable from git rather than
# asserted. The external `stamp` path records a member's declared non-Claude runtime.
CLAUDE_RUNTIME = "claude-code"


def sh(args: list[str], check: bool = True, cwd: Path | None = None,
       env: dict | None = None, stdin=None) -> subprocess.CompletedProcess:
    """Run a command in the repo. `cwd` overrides the repo root (ADR-0058 D4 runs the
    gate inside a scratch worktree); `env` overrides the environment (ADR-0058 D3
    points GIT_INDEX_FILE at a private index so concurrent sessions never share one);
    `stdin` overrides the INHERITED stdin, which the gate must do — see `_run_gate`."""
    return subprocess.run(
        args, cwd=cwd or ROOT, text=True, capture_output=True, check=check, env=env,
        stdin=stdin
    )


#: Cache for `_real_live_stores`; the answer cannot change within a process.
_REAL_LIVE_STORES = None


def _real_live_stores() -> list:
    """The `.session-state/` directories that belong to a REAL session rather than to a
    fixture's tmpdir: the checkout this process was launched in, and the main checkout's,
    which a lane reaches across trees.

    `_LAUNCH_SESSION_STATE_DIR` is the one that must be used here and not
    `SESSION_STATE_DIR` — a fixture rebinds the latter, which is exactly the point; the
    launch anchor never moves, so the two compared together answer "is this write aimed at
    somebody's live coordination state?" (WI-0146's argument, WI-0270's defect).

    IMMOVABLE ANCHORS ONLY, and the first cut of this function got it wrong in exactly
    the way this whole guard exists to prevent: it asked `_shared_work_root()`, which
    fixtures PATCH, so under a fixture it returned the tmpdir and the guard refused a
    correct write into it. A question about what is real cannot be put to a handle a test
    is allowed to move.

    The second entry is the MAIN checkout's store, which a lane reaches across trees —
    resolved from `_LAUNCH_ROOT` rather than `ROOT`, and cached, so one `git` call serves
    the whole process."""
    global _REAL_LIVE_STORES
    if _REAL_LIVE_STORES is not None:
        return _REAL_LIVE_STORES
    out = []
    try:
        out.append(_LAUNCH_SESSION_STATE_DIR.resolve())
    except (OSError, ValueError):
        pass
    try:
        r = subprocess.run(["git", "rev-parse", "--path-format=absolute",
                            "--git-common-dir"], cwd=str(_LAUNCH_ROOT), text=True,
                           capture_output=True, check=False)
        if r.returncode == 0 and r.stdout.strip():
            out.append((Path(r.stdout.strip()).resolve().parent / ".session-state").resolve())
    except (OSError, ValueError):
        pass
    _REAL_LIVE_STORES = out
    return out


def _suite_write_refused(path: Path) -> str:
    """Refusal reason when a write made WHILE THE SUITE IS RUNNING targets a real
    coordination store; the empty string when the write is fine (WI-0286, ADR-0133).

    THE FLOOR SITS AT THE WRITE, NOT IN EACH FIXTURE'S `setUp`, for the reason
    `_wi_write_item` and `_sidecar_write` already give one level down: one hook point
    cannot be forgotten by the next module someone adds, and an opt-in neutraliser is
    missing exactly when a capability is newly wired and the fixtures are stale against
    it.

    WHY THE STEM RULE DID NOT ALREADY COVER THIS. `_sidecar_stem_refused` refuses a
    FORGED identity at the real store. It cannot see a test that inherited the operator's
    real `CLAUDE_CODE_SESSION_ID`, because that stem is well-formed by construction.
    MEASURED 2026-09-13 (session ~314) with an audit hook on `open` across a full
    4,234-test run: **52 writes landed in a real `.session-state/`, and the shipped floor
    passed every one of them** — 35 of `announce.txt` from one module, plus `wi-feed.json`,
    a `.touched` sidecar stamped with this session's own live id, and three
    `wi-snapshot-<sid>.json`.

    SCOPED BY MEASUREMENT, NOT BY SHAPE. The refusal names the two directories that are
    actually somebody's live state, so the far larger number of correct writes into a
    fixture's own tmpdir is untouched. That is WI-0270's 171-to-1 finding applied on its
    own terms: a rule keyed on shape alone would break 171 correct writes to catch one.

    FAILS CLOSED, and the direction is set by what is on the other side
    (`add-structural-guard-on-recurrence`): a forged beat in the live sidecar held four
    real lanes unrecoverable for 48h while nothing went red. Failing closed is safe here
    by construction — the guard can only ever engage inside the suite, so no production
    write can reach it.

    WHAT IT DOES NOT COVER, stated rather than implied (`declare-what-a-check-assumes`):
    a test that spawns the real harness as a SUBPROCESS writes from a process where
    `_test_suite_is_running()` is false, and this floor never runs there. Three of the 52
    measured writes were of that kind. It also covers `atomic_write` only — an append
    (`curate/adopt-runner.py`'s `RUNNER_LOG`, 9 measured writes) goes around it."""
    if not _test_suite_is_running():
        return ""
    try:
        target = path.resolve().parent
    except (OSError, ValueError):
        return ""          # cannot tell where this lands: fail open, as the stem rule does
    for real in _real_live_stores():
        if target == real or real in target.parents:
            return (f"refusing to write {path.name!r} into {real} — that is a REAL "
                    f"session's coordination state and this process is the test suite. "
                    f"Redirect the anchor with `neutralize_live_store(self)` from "
                    f"tests/coord_fixture.py, or pin `session.SESSION_STATE_DIR` to a "
                    f"tmpdir of your own (WI-0286).")
    return ""


def atomic_write(path: Path, text: str) -> None:
    """Write via a same-directory temp file + os.replace, so a crash or dropped
    volume mid-write can never truncate the target. The handoff's in-progress
    stamps are uncommitted until session end, so git does not cover them — the
    atomic rename is the only thing between a mid-write failure and losing the
    file. (curate/common.py carries a copy: session.py ships standalone to every
    Architect and cannot import federation-only modules.)

    Carries the suite write-floor (`_suite_write_refused`) because it is the one funnel
    every durable harness write already passes through — 43 of the 52 measured escapes
    came through here."""
    refused = _suite_write_refused(path)
    if refused:
        raise RuntimeError("session.py: " + refused)
    tmp = path.with_name(path.name + ".tmp")
    tmp.write_text(text, encoding="utf-8")
    os.replace(tmp, path)


def role_doc_version() -> str:
    role_doc = CFG["role_doc"]
    # Tolerant of common variants so the harness parses differently-styled role
    # docs (e.g. a non-Claude system's — a member's `**Version**: `v0.1.5``):
    # colon inside OR outside the bold, an optional backtick, an optional `v`.
    for line in role_doc.read_text(encoding="utf-8").splitlines():
        m = re.match(r"\*\*Version:?\*\*:? *`?v?([0-9]+\.[0-9]+\.[0-9]+)", line)
        if m:
            return m.group(1)
    raise SystemExit(f"session.py: could not read **Version:** from {role_doc.name}")


def detect_machine() -> str:
    try:
        name = sh(["scutil", "--get", "ComputerName"]).stdout.strip()
    except (subprocess.CalledProcessError, FileNotFoundError):
        name = ""
    machine_map = CFG["machine_map"]
    if name in machine_map:
        return machine_map[name]
    # Fallback: hostname-based guess, else the raw name so it's visibly wrong
    low = name.lower()
    if "runner" in low:
        return "Runner"
    if "laptop" in low:
        return "Laptop"
    return name or "UNKNOWN"


def structural_name(n: int, machine: str, stamp: str, did: str = "") -> str:
    """The startup session name, e.g. 'federation-arch·S24-ab25·Laptop·ThuJan1'.

    THE ORDINAL DOES NOT MAKE THIS UNIQUE, and this docstring used to say it did:
    *"Unique (S<n> alone guarantees it)"*. It is false, and measurably so — two devbox
    sessions an hour apart both stamped ordinal 162, and six journals share ordinal 191.
    The ordinal is DERIVED from the landed record at start (ADR-0069 D1 made it a
    compiled presentation label, not an allocated number), so every lane cut from one
    base derives the same one. The single field carrying the uniqueness this name claimed
    was the one that collides.

    `did` is the durable session id, whose 4-char tail IS unique (ADR-0051 C1) and is
    already how every journal is named. Appended to the ordinal as `S<n>-<tail>`, because
    the tail's job here is to say WHICH n — they are one fact, not two. Optional so a
    caller with no id in hand still gets a name rather than an exception; that name is
    then glanceable but NOT unique, which is the old behaviour and is now admitted rather
    than asserted. (WI-0157 / WI-0152; ADR-0129 is the same doctrine for lane slots.)

    Glanceable. The label prefix is the
    ADR-0006 `architect_id` (`<system-id>-arch`) — NOT a hand-chosen short tag.
    Deriving it from the standard identifier is deliberate: a free-text prefix
    field invited non-standard / conflated values (an operator codename, or a
    bare system abbreviation with the `-arch` suffix dropped), the exact
    ADR-0006 collapse the naming convention forbids. `architect_id` always carries `-arch`, so the
    label can never be read as the system or the orchestrator agent. Date built
    by hand to avoid zero-padding the day across platforms."""
    d = datetime.strptime(stamp.split(" ", 1)[0], "%Y-%m-%d")
    short = d.strftime("%a%b") + str(d.day)  # 'ThuJan1'
    _, tail = _durable_id_parts(did)
    sess = f"S{n}-{tail}" if tail else f"S{n}"
    return f"{CFG['architect_id']}·{sess}·{machine}·{short}"


def parse_start_dt(stamp: str) -> datetime | None:
    """Parse the date+time out of a stamp like '... · 2026-06-04 22:20 UTC'."""
    m = re.search(r"(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}) [A-Z]{3,4}", stamp)
    if not m:
        return None
    return datetime.strptime(f"{m.group(1)} {m.group(2)}", "%Y-%m-%d %H:%M").replace(
        tzinfo=CFG["tz"]
    )


def format_duration(start: datetime, end: datetime) -> str:
    mins = int(round((end - start).total_seconds() / 60))
    if mins < 0:
        mins = 0
    if mins < 60:
        return f"{mins}m"
    return f"{mins // 60}h {mins % 60:02d}m"


def next_session_number(text: str) -> int:
    """Highest real session number in the SESSION LOG + 1. NC rows don't count."""
    highest = 0
    for line in text.splitlines():
        m = ROW_RE.match(line)
        if m and not m.group(2):  # group(2) == 'NC' -> skip
            highest = max(highest, int(m.group(1)))
    return highest + 1


def insert_start(text: str, n: int, version: str, machine: str, stamp: str,
                 runtime: str = CLAUDE_RUNTIME) -> str:
    """Insert the SESSION LOG row and the prose entry header (newest-first). `runtime`
    (S1) is appended as the last ` · ` field on the Start stamp line so it is minable;
    the SESSION LOG table schema is deliberately unchanged (runtime lives on the stamp
    line, not in a new column)."""
    lines = text.splitlines()
    date = stamp.split(" ", 1)[0]
    time_cell = stamp.split(" ", 1)[1]  # 'HH:MM UTC'

    # 1. SESSION LOG row: after the table's separator line.
    sep_idx = next(
        i for i, l in enumerate(lines) if re.match(r"^\|[- ]+\|[- |]+$", l)
    )
    row = f"| {n} | {date} | {time_cell} | {machine} | v{version} | (in progress) |"
    lines.insert(sep_idx + 1, row)

    # 2. Prose entry header: directly before the first dated session entry.
    entry_idx = next(i for i, l in enumerate(lines) if ENTRY_RE.match(l))
    block = [
        f"## {date} — Session {n} — (in progress)",
        "",
        f"**Start:** {CFG['architect_name']} v{version} · {machine} · {stamp} · {runtime}",
        "",
        "### What happened",
        "- Session opened.",
        "",
        "---",
        "",
    ]
    lines[entry_idx:entry_idx] = block
    return "\n".join(lines) + "\n"


def git_sync(dry_run: bool, push: bool = True) -> tuple[str, list[str]]:
    """Classify remote sync on a CLEAN working tree and take the safe routine
    action — never a bare BLOCKED. Returns (note, orientation_extra_lines).

    ADR-0035: `start` DETECTS-and-DIAGNOSES instead of detecting only. Each
    abnormal state is named with its one-command fix, and the safe routine
    actions (ff-pull a behind branch; push our own committed sessions —
    routine-ops-autonomy) happen in code so the Architect stops discovering the
    state one turn at a time. The P9 never-auto-resolve floor holds for the one
    genuinely ambiguous case (diverged history): it is surfaced, not resolved,
    and the session still opens locally. Remote-unreachable degrades to an
    OFFLINE start (stamp locally, carry 'sync owed') rather than blocking the
    whole session on GitHub availability.

    `push=False` (the ADR-0055 lazy hook path) defers the auto-push — the one
    outward act — to first activity (`_push_if_ahead`); fetch/diagnose/ff-pull
    still run, so the session opens on fresh trunk either way."""
    fetch = sh(["git", "fetch", "--quiet"], check=False)
    if fetch.returncode != 0:
        return ("offline — remote unreachable; started locally, sync owed", [
            "SYNC:    OFFLINE — remote unreachable; started locally. Owed when "
            "GitHub is reachable: `git pull --ff-only` then `git push`.",
        ])
    rev = sh(["git", "rev-list", "--left-right", "--count", "@{u}...HEAD"], check=False)
    if rev.returncode != 0:
        return ("no upstream tracking — pull/push skipped", [
            "SYNC:    no upstream tracking for this branch — pull/push skipped.",
        ])
    try:
        behind, ahead = (int(x) for x in rev.stdout.split())
    except ValueError:
        return ("sync state unreadable — skipped", [])
    if behind and ahead:
        return (f"DIVERGED ({ahead} ahead / {behind} behind) — needs reconcile", [
            f"SYNC:    DIVERGED — {ahead} local and {behind} remote commit(s) have "
            "both moved. This is the one human case: reconcile (rebase/merge) before "
            "pushing. Session opened locally; do NOT push blindly — needs operator.",
        ])
    if behind:
        if dry_run:
            return (f"behind {behind} — would ff-pull", [])
        merge = sh(["git", "merge", "--ff-only", "@{u}"], check=False)
        if merge.returncode != 0:
            return (f"behind {behind} — ff-merge failed", [
                f"SYNC:    ff-merge failed: {(merge.stderr or merge.stdout).strip()}",
            ])
        return (f"ff-pulled {behind} commit(s)", [])
    if ahead:
        if dry_run:
            return (f"{ahead} unpushed commit(s) — would auto-push", [])
        if not push:
            return (f"{ahead} unpushed commit(s) — push deferred to first activity", [])
        push_r = sh(["git", "push"], check=False)
        if push_r.returncode != 0:
            return (f"{ahead} unpushed — auto-push failed", [
                f"SYNC:    {ahead} unpushed commit(s) from a prior session; auto-push "
                f"failed: {(push_r.stderr or push_r.stdout).strip()}. Run `git push`.",
            ])
        return (f"auto-pushed {ahead} own commit(s) from a prior session", [])
    return ("up to date", [])


# --- session liveness sidecar + orphan triage (ADR-0036) --------------------
#
# `.session-state/<session_id>.live` / `.ended` are gitignored, ephemeral, and
# fully derivable — they add EVIDENCE for orphan triage, they never replace the
# tracked start stamp (durability model unchanged). SessionStart writes .live;
# the Stop hook AND an all-tools PreToolUse hook heartbeat it (ADR-0054 — Stop
# fires only BETWEEN turns, so one long working turn used to make a live session
# look crashed; tool calls beat constantly DURING a turn); the SessionEnd hook
# writes .ended. When machines share the checkout, one machine's heartbeat is visible to
# another machine's start — that is the live-elsewhere detector.
SESSION_STATE_DIR = ROOT / ".session-state"
#: The session-state directory of the checkout this process was actually launched in,
#: captured once at import — the sidecar twin of `_LAUNCH_JOURNAL_DIR`, and here for the
#: same reason (WI-0146's argument, WI-0270's defect). A fixture rebinds
#: `SESSION_STATE_DIR` to its tmpdir; this never moves, so the two compared together
#: answer "is this write aimed at a REAL checkout's coordination state?" — which nothing
#: could ask, and which is why a test's heartbeat could hold four lanes unrecoverable.
_LAUNCH_SESSION_STATE_DIR = SESSION_STATE_DIR
#: The checkout this process was launched in, captured at import for the same
#: reason and used by `_real_live_stores`. `ROOT` itself is rebound by fixtures
#: (that is the point of them), so anything that must answer "is this somebody's
#: REAL state?" has to ask a handle nothing can move.
_LAUNCH_ROOT = ROOT
#: The two shapes a sidecar stem is ever legitimately made of. The stem is a session
#: IDENTITY: either a claude-session-id (a UUID) or, for a runtime that has none and for
#: the supervisor's pre-adoption fallback, the durable journal id `durable_session_id`
#: mints — `<utc-compact>-<machine>-<rand>`. VERIFIED 2026-09-12 by enumerating every
#: sidecar stem across all twelve trees on this machine (the main checkout and eleven
#: lanes): 78 distinct stems — 72 UUIDs, 5 durable ids, and `testsession`, the fixture
#: escape this rule exists to refuse. Two shapes and one forgery, with nothing else in
#: the population.
#:
#: THE SURVEY COVERED THE SIDECAR SUFFIXES AND NOTHING ELSE, which is load-bearing: the
#: first cut of the janitor rule applied this regex to `wi-snapshot-<sid>.json` too, where
#: `<sid>` falls back to the literal `"app"` for any runtime with no
#: `CLAUDE_CODE_SESSION_ID` — real state, read back to resolve an item range. Do not reuse
#: this pattern on a class the survey did not enumerate.
#: BOTH shapes, deliberately: keying on the UUID alone would break the durable-id keying
#: `_supervise_key` depends on, which is the trap WI-0270's own triage flagged.
SIDECAR_STEM_RE = re.compile(
    r"\A(?:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"
    r"|\d{8}T\d{4}Z-[a-z0-9]+-[0-9a-z]+)\Z")
HEARTBEAT_STALE_MIN = 15   # a .live beat younger than this proves LIVE; older proves nothing
HEARTBEAT_MIN_INTERVAL_SEC = 60   # heartbeat write-throttle (PreToolUse fires per tool call)
# A stale heartbeat alone is NOT death evidence — a session merely working through a
# long turn (pre-ADR-0054) or sitting idle-open goes silent too (the session-74 false
# reap). The reaper treats the crash class (stale beat, no later `.ended`) as provably
# dead only once the silence exceeds this grace; a clean-exit `.ended` needs no grace.
REAP_CRASH_GRACE_MIN = 48 * 60
# ADR-0082 D7 reconciled with ADR-0054. The 48 h grace above is sized for a HOOK beat,
# which is driven by ACTIVITY — Stop between turns, PreToolUse per tool call — so an
# idle-open session emits nothing and silence cannot be read as death. A SUPERVISOR beat
# is driven by a TIMER (`SUPERVISE_INTERVAL_SEC`, unconditional for as long as the watched
# process lives), so its silence carries a different meaning entirely: the watcher stopped.
# Inheriting the hook-sized grace for it was never a decision, only an omission — the
# provenance was recorded and then read by nobody, which is `declare-what-a-check-assumes`
# failing at the consuming end rather than the declaring one.
#
# Silence from a supervised session is therefore RESOLVED rather than waited out, wherever
# it can be: the beat carries the pid being watched, and on the same machine the reaper
# asks the OS directly. This grace is only the fallback for when it cannot ask (a sidecar
# written on the other machine — pids are not comparable across machines — or one written
# before the pid was recorded). 2 h is 120 missed beats: far past any plausible scheduling
# hiccup, far short of holding a lane's journal open for two days.
REAP_SUPERVISED_GRACE_MIN = 120

# The user-visible session banner (start stamp + any just-closed orphan end
# stamp). `start` STAGES it; the `announce` hook — a second SessionStart 'startup'
# hook — PRINTS it to plain stdout and consumes it. This exists because `start`'s
# intended announce channel, hookSpecificOutput.systemMessage, is upstream-broken
# (anthropics/claude-code #9090, #50542) and additionalContext is model-only;
# plain stdout is the one SessionStart channel that renders to the user. Splitting
# it into a second hook keeps `start`'s own stdout pure JSON (a stray print there
# corrupts the parse). Gitignored, ephemeral, fully derivable — never load-bearing.
#
# COORDINATION (session 59): SessionStart hooks run in PARALLEL with no ordering
# guarantee (Claude Code: "all matching hooks run in parallel") — `announce` is
# NOT guaranteed to run after `start`. The v2.21.0 design used one shared
# `announce.txt` with a plain read+unlink, so `announce` won the race and printed
# the PREVIOUS session's leftover banner (always one session stale; nothing at all
# on a system whose file never existed yet). The fix keys the banner file by the
# `session_id` both hooks receive on stdin, and has `announce` POLL for its own
# session's file (bounded, fail-open) rather than assume it is already written:
#   * cross-session staleness is structurally impossible (filename is per-session);
#   * `announce` waits out the race instead of eating it, so a fresh system prints
#     on its first run;
#   * `start` writes a per-session file at EVERY exit — the real banner on the
#     normal path, an empty sentinel on the early-return paths (already-open /
#     concurrent / residual) — so `announce`'s poll always resolves promptly.
# A manual terminal `start` (no hook stdin, session_id is None) has no paired
# `announce` hook, so it falls back to the unkeyed legacy name.
#: The legacy unkeyed banner filename (no session_id on hook stdin). A NAME, not a
#: bound path: a path computed from `SESSION_STATE_DIR` at import does not follow a
#: fixture that rebinds the directory, which is how 35 test writes a run reached the
#: operator's real store. Callers join it to `SESSION_STATE_DIR` at call time.
BANNER_NAME = "announce.txt"

# Bounded wait `announce` polls for its per-session banner when it loses the race
# with `start` (which writes the file only after its git ff-pull). Generous enough
# to cover a slow pull; near-instant in the common case start-wins. Override via
# env for tests. Fail-open on timeout (print nothing — never hang a startup).
ANNOUNCE_WAIT_S = float(os.environ.get("SESSION_ANNOUNCE_WAIT_S", "20"))
ANNOUNCE_POLL_S = float(os.environ.get("SESSION_ANNOUNCE_POLL_S", "0.1"))


# How long a hook payload may take to arrive before we stop waiting for it. A real hook
# writes its JSON and closes immediately, so this is never reached in the healthy case —
# it exists so the UNhealthy case is bounded ([P19](principles/master.md#p19--cap-what-can-run-away)).
HOOK_STDIN_TIMEOUT_SEC = 5.0


def _parse_iso(iso: str | None) -> datetime | None:
    if not iso:
        return None
    # git prints a UTC time with a trailing `Z`, which fromisoformat rejects before 3.11.
    if iso.endswith("Z"):
        iso = iso[:-1] + "+00:00"
    try:
        return datetime.fromisoformat(iso)
    except Exception:
        return None


def _iso_age_min(iso: str | None) -> float | None:
    """Minutes since an ISO timestamp, or None if unparseable."""
    dt = _parse_iso(iso)
    if dt is None:
        return None
    now = datetime.now(dt.tzinfo) if dt.tzinfo else datetime.now()
    return (now - dt).total_seconds() / 60.0


def _now_iso() -> str:
    return datetime.now(CFG["tz"]).isoformat()


# The profile-injection cap. Generous on purpose: it exists for the ADR-0035 turn budget,
# not as an editorial limit, so it must sit far above any profile a user actually writes.
# Was 6000 — under the size of a real profile in use, which meant a THIRD of it never
# reached any session on any member, silently (WI-0066). What fell off was the tail, and a
# profile grows at the tail, so the cap always ate the NEWEST preference: one entry lost
# its entire body and the next was lost whole. Raising it is only half a fix — a limit
# that fails silently just re-breaks on the next entry — so `_capped` reports the loss.
PROFILE_INJECT_CAP = 20000


def _capped(text: str, cap: int) -> tuple[str, int]:
    """(text, chars-dropped). `dropped` is 0 when nothing was cut, so a caller can never
    mistake a partial delivery for a complete one ([`declare-what-a-check-assumes`]:
    "I gave you some" and "I gave you all" must not share an output)."""
    return (text, 0) if len(text) <= cap else (text[:cap], len(text) - cap)


def _user_profile_text(cap: int = PROFILE_INJECT_CAP) -> tuple[str, int]:
    """The bound user's profile/overrides + how much the cap dropped. Data is gitignored
    and stays in the Architect's OWN context (never leaves the session) — injecting it
    saves the step-6 read (ADR-0035). `("", 0)` if absent/unreadable.

    Resolution order:
      1. a declared `user_profile` in session.config.json — a path relative to
         `_shared_work_root()` (the MAIN checkout, not a lane's own worktree root),
         allowed to escape it (`../…`), because for every member except the federation
         the profile lives in the FEDERATION's data root (ADR-0011), not in the
         member's own tree, and because it names gitignored/external state that only
         physically exists in the main checkout — a lane's tracked-only working tree
         never has it, whatever it resolves relative to;
      2. the in-repo `users/*/profile.md` glob — right for the federation itself.

    The declaration exists because assumption (2) was shipped fleet-wide as if it were
    universal. A member with no `users/` directory (its profile lives in the federation
    repo, which it declares as its data root) saw the glob return nothing, the block
    was silently omitted, and the banner claimed it had been delivered anyway — while
    STANDARD.md told the Architect not to bother reading it. Reported by that member, session 10.
    Resolving against `ROOT` instead of `_shared_work_root()` was a second instance of
    the same bug class one layer down: correct in the main checkout, silently absent in
    every poga lane (the lane's `ROOT` is its own worktree, two directories deeper).
    Reported by that member, session 11.
    """
    rel = (CFG or {}).get("user_profile")
    if isinstance(rel, str) and rel.strip():
        try:
            return _capped((_shared_work_root() / rel.strip()).resolve()
                           .read_text(encoding="utf-8"), cap)
        except OSError:
            # A declared-but-unreadable path reads as ABSENT, and the banner will say so.
            # Never fall through to the glob: that would restore the silent-omission
            # behaviour this declaration exists to end.
            return "", 0
    try:
        for p in sorted((ROOT / "users").glob("*/profile.md")):
            return _capped(p.read_text(encoding="utf-8"), cap)
    except Exception:
        pass
    return "", 0


def _sidecar_stem_refused(session_id: str) -> str:
    """`""` to allow the write; otherwise the reason this stem is refused, naming it.

    WI-0270. A sidecar stem is a session IDENTITY, and a `.live` file bearing a fresh
    beat and no `.ended` is — BY DESIGN, that being the whole point of the file —
    indistinguishable from a session that is working. So a stem that belongs to no
    session at all is not a cosmetic wart: it is forged liveness evidence, and every
    conservative refusal in the lane lifecycle reads it. `test_attention`'s `"testsession"`
    held four lanes unrecoverable for the full 48h crash grace (session ~185, 2026-09-04),
    and was still holding `poga-7` on 2026-09-12 — whose real session had stamped `.ended`
    that morning.

    SCOPED TO A REAL CHECKOUT'S STORE, and that scope is the decision, not an oversight.
    MEASURED over the full suite (3,823 tests, 242 sidecar writes, 2026-09-12): 171 of
    those writes use a non-conforming stem — `csid-sib-1`, `eph-real`, `sess-main` and 33
    others across six modules — and every single one lands in the fixture's own tmpdir,
    where a short readable id is correct and a UUID would only obscure what the test is
    about. Exactly ONE write escaped to a real checkout, and it is the defect above.
    Refusing on shape alone everywhere would therefore break 171 correct writes to catch
    one wrong one. The hazard was never the shape; it is a shape that is wrong FOR THE
    PLACE IT LANDS.

    ASSUMES, and says so rather than folding it into the pass ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)):
    that a fixture reaching a real store reaches THIS process's launch store. That is the
    escape's actual mechanism — the store is import-bound, so a fixture that fails to
    redirect it writes exactly where the process started. A fixture that redirected the
    anchor to some OTHER checkout's real `.session-state/` is not covered here; nothing
    does that today, and `neutralize_live_store`'s detector is what keeps it that way.

    Same argument, same shape, and deliberately the same place as
    `_machine_close_would_hit_the_real_repo`: the guard sits at the write, not in each
    fixture's setUp, because a fixture that forgets is invisible and this is the one
    line the damage goes through."""
    if SIDECAR_STEM_RE.match(session_id or ""):
        return ""
    try:
        if SESSION_STATE_DIR.resolve() != _LAUNCH_SESSION_STATE_DIR.resolve():
            return ""                  # a redirected store — the fixture's own, leave it
    except (OSError, ValueError):
        return ""                      # cannot tell where this lands: fail open
    return (f"sidecar stem {session_id!r} is neither a claude-session-id (UUID) nor a "
            f"durable session id, and this write targets the real checkout's "
            f"{_LAUNCH_SESSION_STATE_DIR.name}/ — refusing to plant liveness evidence "
            f"for a session that does not exist (WI-0270)")


def _sidecar_write(session_id: str, suffix: str, payload: dict) -> None:
    """Best-effort write of a sidecar file; never raises — a liveness-marker
    failure must never break the hook it rides on (fail-open, like the guards).

    The stem check is the one thing here that fails CLOSED, per
    [`add-structural-guard-on-recurrence`](habits/master.md#add-structural-guard-on-recurrence):
    the direction is set by what is on the other side. Skipping a sidecar write costs an
    orphan triage that has to wait out its grace; letting a forged one through strands
    real work behind a heartbeat nobody can disprove. No evidence is recoverable from;
    false evidence is what `recover` cannot see past."""
    if not session_id:
        return
    refused = _sidecar_stem_refused(session_id)
    if refused:
        # Named, not swallowed. A refusal nobody can find is the silent-skip this whole
        # item is about, one layer up ([`denial-audit-log`](habits/master.md#denial-audit-log)).
        with contextlib.suppress(Exception):
            _log_guard_firing("sidecar-stem", refused)
        return
    try:
        SESSION_STATE_DIR.mkdir(exist_ok=True)
        atomic_write(SESSION_STATE_DIR / f"{session_id}.{suffix}",
                     json.dumps(payload, ensure_ascii=False, indent=2) + "\n")
    except Exception:
        pass


# The append-only guard-firing log (S2, 2026-07-14-federation-metrics). Today the
# guards act silently — a `deny` is emitted to the hook channel and forgotten, so
# enforced-invariant counts are unminable. One structured line per firing makes
# them minable (curate/metrics.py reads this file fleet-wide). Gitignored + ephemeral
# like the sidecars — it is telemetry (data), not system state (P3).
#: The denial-audit log's filename. Same rule as `BANNER_NAME`, and the reason is
#: recorded in `_log_guard_firing`, which has resolved it at call time since
#: 2026-08-07 — the bound constant it replaced put 432 of 532 records into the real
#: fleet telemetry from test fixtures.
GUARD_FIRINGS_NAME = "guard-firings.jsonl"

#: WI-0278 — the per-session escalation ledger `.session-state/<durable-id>.escalations.jsonl`.
#: Written beside the live `attention` record rather than instead of it: that record is
#: CURRENT STATE, one row per lane, and `_attention_clear` destroys it at the moment the
#: question is answered — which is the one moment you would want the event kept. The
#: 2026-09-04 fan-out left eleven journal entries behind roughly fifty relayed answers
#: (WI-0274) because the only durable source was what a session still remembered at close.
#:
#: The suffix is deliberately NOT one any liveness reader globs (`LIVENESS_SUFFIXES`), so a
#: ledger can never be read as evidence that a session is alive — the forged-liveness shape
#: WI-0270 closed. It IS on `JANITOR_SIDECAR_SUFFIXES`, because once `end` has folded it
#: into the tracked journal what is left here is per-session residue like `.end-ran`.
ESCALATION_LOG_SUFFIX = "escalations.jsonl"


def _pending_marker(sid: str) -> Path:
    """The ADR-0055 lazy-start marker `.session-state/<csid>.pending-start`:
    written by the hook-path `start` instead of the journal, consumed by the
    first heartbeat, which materializes the deferred start work. A phantom
    preload never beats, so its marker is inert debris (swept later)."""
    return SESSION_STATE_DIR / f"{sid}.pending-start"


def _prep_marker() -> Path:
    """The ADR-0082 D1 prep-inversion rendezvous, `.session-state/prep.json`.

    Prep inversion means the wrapper runs the session-start ritual BEFORE it launches an
    agent — so at prep time the runtime's own session id does not exist yet, and the
    journal `start` writes carries an empty `claude-session-id`. The runtime then boots
    and its own start looks itself up by exactly that key (`_my_open_journal` →
    `find_open_journal(claude_session_id=…)`), misses, and would open a SECOND journal
    for one session. This file is the handshake that closes that gap: prep records which
    journal it just created, and the runtime's start ADOPTS it rather than allocating
    again.

    One marker per worktree, not per session id, because a lane IS one session and the
    id that would key it is precisely the thing that does not exist yet."""
    return SESSION_STATE_DIR / "prep.json"


def _write_prep_marker(did: str, runtime: str) -> None:
    """Record the journal prep just created, for the runtime's start to adopt.

    Best-effort like every sidecar write. A lost marker degrades to today's behaviour —
    the runtime opens its own journal and prep's is reaped as a phantom — never to a
    crash, because a start that dies is a session that never runs."""
    try:
        SESSION_STATE_DIR.mkdir(exist_ok=True)
        atomic_write(_prep_marker(), json.dumps({
            "session_id": did, "runtime": runtime, "prepped": _now_iso(),
        }, ensure_ascii=False, indent=2) + "\n")
    except Exception:
        pass


def _prep_session_id() -> str:
    """The journal id named by this worktree's prep marker, or '' when there is none.
    Read in the FOREGROUND by `supervise` before it detaches, because adoption consumes
    the marker moments later — a watcher that deferred this read would race the runtime
    it is supposed to be watching."""
    try:
        rec = json.loads(_prep_marker().read_text(encoding="utf-8"))
        return (rec.get("session_id") or "").strip()
    except Exception:
        return ""


SESSION_CONTEXT_NAME = "session-context.md"

# The embed cap, and why it is a fixed number rather than runtime arithmetic (WI-0324).
#
# The payload rides to a hookless runtime inside the opening prompt, which is an `exec`
# argv element, so the ceiling is ARG_MAX. MEASURED by bisecting a
# real `exec`: the largest single argv string that actually launched was **1,044,434
# bytes**, against a `getconf ARG_MAX` of 1,048,576 — so the configured constant is NOT
# the true limit and arithmetic against it would be arithmetic against the wrong number.
# The environment shares that budget and its size is not knowable from here.
#
# 256 KiB is therefore a floor-of-safety, not an estimate: it is ~3x the largest payload
# ever observed (81 KB, `lanes.py` / WI-0105) and leaves >760 KB of the measured ceiling
# unused. Above it delivery degrades to pointing and SAYS SO — a cap that fails silently
# just re-breaks on the next entry, which is the lesson `PROFILE_INJECT_CAP` above was
# raised to record.
SESSION_CONTEXT_EMBED_CAP = 262144

# The reading rule (WI-0324 / R4.2 of the 2026-09-07 consultant brief).
#
# Bounded by BYTES, not lines, and the reason is measurable HERE, today: the longest
# line in `federation-arch.md` is 6,763 characters and 9 of its lines exceed 2,000, so
# "read lines 1-200" is not a bound on anything. (The brief's 332 KB / 65-long-line
# figure was the file BEFORE WI-0284 split the changelog out; the role doc is 104,738 B
# now and `federation-arch-CHANGELOG.md` holds 316,532 B. The split shrank the number
# without changing the argument — 104 KB still overruns a 12k-token output cap.)
# This ships in the payload rather than in STANDARD.md because it is a property of
# runtimes that read files through a capped exec channel, not of every Architect —
# Claude's file tools bound themselves.
SESSION_CONTEXT_READING_RULE = """\
## How to read large files here — a rule, not a suggestion

Your shell tool truncates its own output at a token cap, and a truncated read looks
exactly like a complete one. That is the whole problem: the tail is gone and nothing
says so, so the usual recovery — re-reading the same file in guessed ranges — pays for
the same bytes two and three times over.

- **Never open a role doc, a registry, or a generated view with a whole-file read.**
  `cat federation-arch.md` emits 104,738 bytes, `cat habits/master.md` 126,051, and
  `cat session-handoff.md` 147,806 — each returns you a silently truncated prefix.
- **Ask for a section by heading**, which is cheaper than any arithmetic you could do:
  `python3 session.py show <file> --sections` lists every heading with its byte range,
  and `python3 session.py show <file> --section "<heading>"` prints just that one.
  Both refuse to exceed a byte budget and tell you what they held back.
- **Or ask for a byte-bounded chunk**: `python3 session.py show <file> --bytes 0-40000`.
  It reports the file's total size, so the next chunk's start is given to you rather
  than guessed.
- **Raise your own output cap to match the chunk.** Your exec tool's output limit is
  something you choose per call, not a fixed ceiling — measured across this machine's
  transcripts, the figure asked for ranges from 100 to 20,000 tokens with a median
  around 2,000. A 40,000-byte chunk is roughly 10,000 tokens, so asking for it under a
  2,000-token cap truncates it just the same and you have bought nothing. Pair them:
  request the bytes AND the tokens to hold them, or ask for fewer bytes.
- **Do not overlap.** Start the next chunk where the last one ended — the command
  prints that offset for exactly this reason. Re-reading a range you already hold buys
  nothing and costs it twice.

You do not need a separate sizing call before a small read. The rule binds the large
files above, which are the ones that have actually cost a session its context window.
"""

SESSION_CONTEXT_HEADER = """\
# Session start context

**Read this first.** This is your session-start orientation, the principles and
universal habits you inherit (not negotiate), and the standard session rituals.
Generated fresh each session; do not edit.

**How you got this.** Your runtime has no SessionStart hook to inject into, so the
launcher delivers this payload in your opening prompt and keeps this file as the same
bytes on disk (ADR-0082 D5, amended by WI-0324). If you are reading the file, you are
either recovering a prompt you lost or the payload was too large to embed — in which
case the launcher said so on stderr. Either way you already have everything below; you
do not need to read it twice.
"""


def _write_session_context(context: str) -> str:
    """Write the start payload where a hookless runtime can read it; return its
    repo-relative path (ADR-0082 D5).

    Canon delivery degrades **embed → point**, never → nothing. Where the runtime has a
    hook surface the payload rides in as `additionalContext`; where it does not, the
    launcher embeds these same bytes in the opening prompt, and only where THAT will not
    fit does it fall back to naming this path. The alternative to all three is that the
    agent simply never receives its principles. An Architect running without canon is not
    bound by it, which makes the lane a member in name only — so the file is not a
    convenience, it is the durable half of the delivery mechanism.

    WI-0324 moved the first rung from *point* to *embed*, and the reason is measured, not
    preferred: a pointer costs a tool call whose output is truncated at the runtime's cap,
    and across the Codex transcripts measured, **nearly all hit a truncated read inside
    their first ten tool calls** and about half re-read this very file several times
    recovering from it. An embedded payload costs no tool call and cannot be truncated — an 85,056-byte
    opening prompt was measured reaching the model byte-complete.

    Why not the runtime's own auto-loaded instruction file: `codex debug prompt-input`
    shows Codex does load `AGENTS.md` from the cwd, but it truncates it at exactly 32,768
    bytes with no marker the model can see, and this payload is 41-81 KB. `AGENTS.md` is
    also a committed, public, human-authored front door (WI-0383) — writing per-session
    lane state into it breaks [P13](principles/master.md#p13--single-writer-per-state) and
    [P3](principles/master.md#p3--data-system-separation) at once. `AGENTS.override.md`
    was measured to REPLACE `AGENTS.md` rather than stack with it, so using it would
    silently suppress that front door.

    Deliberately NOT a hand-maintained per-runtime copy of canon: the payload is the same
    generated text the hook path injects, produced once by the same start
    ([`single-source-and-deliver`](habits/master.md#single-source-and-deliver)). It lands
    in the gitignored `.session-state/` because it is ephemeral per-session data, not
    system state ([P3](principles/master.md#p3--data-system-separation))."""
    SESSION_STATE_DIR.mkdir(exist_ok=True)
    p = SESSION_STATE_DIR / SESSION_CONTEXT_NAME
    atomic_write(p, SESSION_CONTEXT_HEADER + "\n" + SESSION_CONTEXT_READING_RULE
                 + "\n" + context.rstrip("\n") + "\n")
    try:
        return str(p.relative_to(ROOT))
    except Exception:
        return str(p)



# --- `session.py show` — bounded reads for a runtime with a capped output channel -----
#
# WI-0324 / R4.2. The rule this serves is in SESSION_CONTEXT_READING_RULE above; this is
# the half that makes the rule cheap to follow. A runtime that must obey a byte budget
# should not have to do the arithmetic itself — doing it here costs no model cycle, and
# an agent that has to compute an offset will guess one and overlap.

# ~10,000 tokens of text. Chosen against what the calling runtime actually asks for:
# across the 1,213 capped exec calls in this machine's Codex transcripts the requested
# output limit runs 100-20,000 tokens, median ~2,000. So this budget is NOT a promise
# the output survives - the caller's own cap is the other half, and the reading rule
# above says to raise it to match. What the budget guarantees is that `show` never
# hands back more than was asked for without naming the offset to continue from.
SHOW_DEFAULT_BUDGET = 40000


def _md_section_spans(data: bytes):
    """Heading spans of a markdown document, in BYTES, closing at same-or-shallower.

    Returns `[{level, heading, start, end}]` where `start` is the heading line's first
    byte and `end` is one past the section's last byte.

    Two things here are the whole reason this is a function and not a regex:

    **A section closes at the next heading of the same or a SHALLOWER level**, never at
    the next heading of any level. Stopping at any heading silently drops every
    subsection, which makes a parent section report the size of its own preamble — it
    once inverted which section of a document was largest.

    **Fenced code blocks are not scanned.** A `#` at column zero inside a fence is a
    shell comment or a Python comment, not a heading, and treating it as one invents
    sections that cut real ones short.
    """
    spans, fence = [], None
    off = 0
    for raw in data.split(b"\n"):
        line = raw.rstrip(b"\r")
        stripped = line.lstrip()
        if fence is not None:
            if stripped.startswith(fence):
                fence = None
        elif stripped.startswith(b"```") or stripped.startswith(b"~~~"):
            fence = stripped[:3]
        elif line.startswith(b"#"):
            hashes = len(line) - len(line.lstrip(b"#"))
            if 1 <= hashes <= 6 and line[hashes:hashes + 1] in (b" ", b"\t"):
                try:
                    heading = line[hashes:].strip().decode("utf-8", "replace")
                except Exception:              # pragma: no cover - decode is lenient
                    heading = ""
                spans.append({"level": hashes, "heading": heading,
                              "start": off, "end": None})
        off += len(raw) + 1
    total = len(data)
    for i, sp in enumerate(spans):
        sp["end"] = total
        for nxt in spans[i + 1:]:
            if nxt["level"] <= sp["level"]:
                sp["end"] = nxt["start"]
                break
    return spans


def _show_match(spans, wanted: str):
    """Resolve a `--section` argument to exactly one span, or raise saying why not.

    Exact match first, then a unique case-insensitive containment match. An ambiguous
    request is REFUSED with the candidates named rather than resolved to the first hit:
    silently picking one is how a caller ends up reading a section it did not ask for and
    never learns it happened.
    """
    exact = [s for s in spans if s["heading"] == wanted]
    if len(exact) == 1:
        return exact[0]
    if len(exact) > 1:
        raise ValueError(
            f"{len(exact)} sections are titled {wanted!r}; ask by byte range instead "
            f"(--bytes {exact[0]['start']}-{exact[0]['end']} for the first)")
    low = wanted.lower()
    near = [s for s in spans if low in s["heading"].lower()]
    if len(near) == 1:
        return near[0]
    if not near:
        raise ValueError(f"no section matches {wanted!r}; --sections lists them")
    names = ", ".join(repr(s["heading"]) for s in near[:6])
    raise ValueError(f"{len(near)} sections match {wanted!r}: {names}"
                     + (", ..." if len(near) > 6 else ""))


def _parse_byte_range(spec: str, total: int):
    """`A-B`, `A-`, or `-B` to a concrete (start, end). Raises on anything else."""
    text = (spec or "").strip()
    if "-" not in text:
        raise ValueError(f"--bytes wants START-END (got {spec!r})")
    a, _, b = text.partition("-")
    try:
        start = int(a) if a.strip() else 0
        end = int(b) if b.strip() else total
    except ValueError:
        raise ValueError(f"--bytes wants whole numbers (got {spec!r})") from None
    if start < 0 or end < 0:
        raise ValueError("--bytes offsets are not negative")
    if end < start:
        raise ValueError(f"--bytes end {end} precedes start {start}")
    return start, end


def render_show(path, section=None, byte_range=None, sections=False,
                budget: int = SHOW_DEFAULT_BUDGET) -> str:
    """Render a bounded view of `path`, with a footer that states its own limits.

    Every return path ends in a receipt naming the file's total size, the byte span
    actually shown, and — when the budget cut it short — the exact offset the next chunk
    starts at. That last number is the point of the whole verb: an agent handed the next
    offset does not guess one, and two chunks that do not overlap cost what one truncated
    read plus its recovery reads cost today.

    The budget is enforced on BYTES, because the files this exists for are the ones whose
    lines are long — `federation-arch.md`'s longest line is 6,763 characters — so a line
    range is not a bound on anything.
    """
    p = Path(path)
    if not p.is_absolute():
        p = ROOT / p
    if not p.is_file():
        raise ValueError(f"not a file: {path}")
    data = p.read_bytes()
    total = len(data)
    if budget is not None and budget <= 0:
        raise ValueError("--budget is a positive number of bytes")

    if sections:
        spans = _md_section_spans(data)
        if not spans:
            return (f"{path}: no markdown headings ({total} bytes). "
                    f"Read it with --bytes 0-{min(total, budget)}.")
        out = [f"{path} — {len(spans)} sections, {total} bytes total",
               "level  bytes  range            heading"]
        for s in spans:
            out.append(f"{'#' * s['level']:<6} {s['end'] - s['start']:>6}  "
                       f"{s['start']}-{s['end']:<10} {s['heading']}")
        out.append("")
        out.append("Ask for one with --section '<heading>', or a span with --bytes A-B.")
        return "\n".join(out)

    label = f"0-{total}"
    if section is not None:
        span = _show_match(_md_section_spans(data), section)
        start, end = span["start"], span["end"]
        label = f"section {span['heading']!r}"
    elif byte_range is not None:
        start, end = _parse_byte_range(byte_range, total)
        label = "byte range"
    else:
        start, end = 0, total
        label = "whole file"

    start = max(0, min(start, total))
    end = max(start, min(end, total))
    asked = end - start
    cut = budget is not None and asked > budget
    stop = start + budget if cut else end
    body = data[start:stop].decode("utf-8", "replace")

    foot = [f"--- {p.name}: {label}, bytes {start}-{stop} of {total} ---"]
    if cut:
        foot.append(f"HELD BACK {end - stop} bytes of this request by the {budget}-byte "
                    f"budget. NEXT CHUNK STARTS AT {stop} — continue with "
                    f"`--bytes {stop}-{end}`; do not re-read from {start}.")
    elif end < total:
        foot.append(f"This is not the whole file. The rest is bytes {end}-{total}.")
    else:
        foot.append("This is the end of the file.")
    return body.rstrip("\n") + "\n\n" + "\n".join(foot)

SUPERVISE_INTERVAL_SEC = 60


def _process_alive(pid: int) -> bool:
    """Is `pid` still running?

    `os.kill(pid, 0)` raises ESRCH when the process is gone and EPERM when it exists but
    is not ours. The second case still means ALIVE — a blanket `except OSError: return
    False` gets it backwards and would report a living session dead, which is the one
    error that costs real work here (a false reap)."""
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except Exception:
        return False


def _write_gone_marker(key: str, pid: int) -> None:
    """Record that the watcher SAW the watched process disappear (ADR-0082 D7).

    Deliberately NOT `.ended`. That marker means a *clean* exit, written by a runtime's
    own SessionEnd binding, and it is the discriminator the reaper uses to tell a tidy
    close from a crash. A pid watch cannot make that distinction — it knows the process
    is gone and nothing about how — so it writes its own marker and claims only what it
    saw.

    What it buys is the grace. `REAP_CRASH_GRACE_MIN` exists because SILENCE is
    ambiguous: a quiet session may be idle-open rather than dead, so the reaper waits
    before believing it. A watcher that observed the exit removes that ambiguity, so a
    supervised lane can be closed at the next start instead of two days later."""
    try:
        SESSION_STATE_DIR.mkdir(exist_ok=True)
        atomic_write(SESSION_STATE_DIR / f"{key}.gone",
                     json.dumps({"gone": _now_iso(), "pid": pid}, ensure_ascii=False,
                                indent=2) + "\n")
    except Exception:
        pass


def _sidecar_evidence(n) -> dict:
    """Evidence about session number `n` from the sidecar: whether a `.live`
    exists (and how fresh its heartbeat), whether a `.ended` marker exists, and
    the owning session_id + machine. All-empty when there is no sidecar (the
    legacy / pre-rollout case). Never raises."""
    ev = {"has_live": False, "session_id": None, "machine": None,
          "beat_age_min": None, "has_ended": False, "ended_at": None, "last_beat": None}
    try:
        if not SESSION_STATE_DIR.is_dir():
            return ev
        for p in sorted(SESSION_STATE_DIR.glob("*.live")):
            data = json.loads(p.read_text(encoding="utf-8"))
            if str(data.get("session_n")) != str(n):
                continue
            beat = data.get("last_beat") or data.get("started")
            ev.update(has_live=True, session_id=p.stem, machine=data.get("machine"),
                      last_beat=beat, beat_age_min=_iso_age_min(beat))
            ended = SESSION_STATE_DIR / f"{p.stem}.ended"
            if ended.is_file():
                ev["has_ended"] = True
                ev["ended_at"] = json.loads(ended.read_text(encoding="utf-8")).get("ended")
            break
    except Exception:
        pass
    return ev


def _sidecar_evidence_by_csid(csid: str, state_dir: Path | None = None) -> dict:
    """Liveness evidence for an ephemeral claude-session-id (the sidecar filename stem):
    is there a `.live` (and how fresh its heartbeat), a `.ended` clean-exit marker, and
    their timestamps. All-empty when no sidecar exists. The journal-model twin of
    `_sidecar_evidence` (which keys on the legacy session number). Never raises.

    `state_dir` overrides which `.session-state` is read, defaulting to THIS worktree's.
    The sidecar is per-worktree and gitignored, so a sibling lane's evidence is only ever
    readable at its own path — `recover-lanes` (WI-0122) passes it to judge whether the
    session that owned a stranded lane is dead. One parser, two callers (P16): the rules
    that decide "dead" must not fork between the session reading its own sidecar and the
    verb reading someone else's, or the two would disagree about the same lane."""
    ev = {"has_live": False, "beat_age_min": None, "last_beat": None,
          "has_ended": False, "ended_at": None, "has_gone": False, "gone_at": None,
          "beat_source": "", "beat_pid": None, "beat_machine": ""}
    state = SESSION_STATE_DIR if state_dir is None else state_dir
    try:
        if not csid or not state.is_dir():
            return ev
        live = state / f"{csid}.live"
        if live.is_file():
            data = json.loads(live.read_text(encoding="utf-8"))
            beat = data.get("last_beat") or data.get("started")
            ev.update(has_live=True, last_beat=beat, beat_age_min=_iso_age_min(beat))
            # A beat's PROVENANCE and its subject. Absent on a hook beat, which is the
            # pre-ADR-0082 shape and reads as "" — so an older sidecar degrades to the
            # hook rules rather than to a crash.
            ev["beat_source"] = (data.get("beat_source") or "").strip()
            ev["beat_machine"] = (data.get("beat_machine") or "").strip()
            try:
                ev["beat_pid"] = int(data.get("beat_pid")) if data.get("beat_pid") else None
            except Exception:
                ev["beat_pid"] = None
        ended = state / f"{csid}.ended"
        if ended.is_file():
            ev["has_ended"] = True
            ev["ended_at"] = json.loads(ended.read_text(encoding="utf-8")).get("ended")
        # ADR-0082 D7: the wrapper's watcher SAW the process go. Distinct from `.ended`
        # (a clean exit) because a pid watch cannot tell clean from crashed — it reports
        # only what it observed, and the reaper decides what that is worth.
        gone = state / f"{csid}.gone"
        if gone.is_file():
            ev["has_gone"] = True
            ev["gone_at"] = json.loads(gone.read_text(encoding="utf-8")).get("gone")
    except Exception:
        pass
    return ev


def _crash_grace_min(ev: dict) -> int:
    """How long SILENCE must last before it reads as death, for THIS kind of beat.

    A hook beat gets the full 48 h because an idle-open session legitimately emits none.
    A supervisor beat gets `REAP_SUPERVISED_GRACE_MIN`, because it is emitted by a timer
    that does not care whether anyone is typing — so its silence means the watcher stopped,
    not that the user went to lunch."""
    return (REAP_SUPERVISED_GRACE_MIN
            if (ev.get("beat_source") or "") == "supervisor" else REAP_CRASH_GRACE_MIN)


# How long a silent sibling's files stay protected from another session's close.
# Deliberately NOT HEARTBEAT_STALE_MIN (15m, which only ever proves life, never death —
# a session idle between turns goes quiet and is very much alive) and deliberately NOT
# REAP_CRASH_GRACE_MIN (48h — a crashed session's files would be excluded from every
# later close for two days, so its debris would never get committed by anyone). 2h
# presumes a silent session abandoned for ATTRIBUTION purposes only; its journal still
# gets the full reaper grace, because closing a narrative is the destructive call and
# demands more certainty than declining to commit someone's file.
LAND_DEFER_GRACE_MIN = 120


def _live_sibling_csids(current_csid: str | None) -> list[str]:
    """Other sessions that may still be working in this tree — the set whose in-flight
    files this close must NOT commit.

    Under ADR-0057 this also gated landing; ADR-0058 retired that (waiting on a sibling
    froze the trunk and, with it, the compiled views). The liveness read survives for
    attribution alone: whose files to leave alone, never whether to land.

    Keyed on OPEN JOURNALS, not on heartbeat freshness. A fresh beat proves life, but a
    stale one proves nothing (the ADR-0054 lesson), so inferring "not fresh, not live"
    would let one session commit another's half-written files the moment that session
    sat idle between turns. A sibling is therefore counted as live unless it is
    *provably* gone:

      * a clean-exit marker as the latest signal — it exited, no grace needed; or
      * silence past LAND_DEFER_GRACE_MIN — presumed abandoned, so its debris becomes
        committable by whoever closes next rather than being orphaned forever.

    Everything else — including an idle session and a recent crash — counts as live and
    keeps its files. That is the safe direction: excluding a file costs one uncommitted
    path, committing someone's half-finished work costs their work.

    Scope is per-TREE, because the sidecars live under `ROOT/.session-state`
    (ADR-0057 D3 deferred): sessions in different worktrees cannot see each other.
    That is exactly the bug's scope, so nothing regresses. Best-effort; never raises."""
    out: list[str] = []
    try:
        for p in _open_journal_paths():
            fm, _body = parse_journal(p.read_text(encoding="utf-8"))
            csid = fm.get("claude-session-id")
            if not csid or csid == current_csid:
                continue
            ev = _sidecar_evidence_by_csid(csid)
            beat, ended = _parse_iso(ev["last_beat"]), _parse_iso(ev["ended_at"])
            if ended is not None and (beat is None or ended >= beat):
                continue                  # clean exit is the latest signal — gone
            age = ev["beat_age_min"]
            if age is not None and age > LAND_DEFER_GRACE_MIN:
                continue                  # silent past the grace — presumed abandoned
            out.append(csid)
    except Exception:
        pass
    return out


def _live_same_tree_siblings(current_csid: str | None) -> list[str]:
    """Csids of OTHER sessions PROVABLY live in THIS working tree right now — the
    app-surface concurrency signal for the ADR-0059 detect-and-refuse guard.

    Reads ONLY the per-worktree sidecar `.live` files (SESSION_STATE_DIR = ROOT/.session-
    state; each git worktree has its own), never the shared journal dir — so an intentional
    poga LANE, isolated in its own worktree with its own sidecar, is never counted as a
    same-tree sibling. Unlike the END-side attribution read (`_live_sibling_csids`), which
    errs toward protecting a quiet sibling's files, this START read wants HIGH CONFIDENCE
    that another session is actively here: it counts only a sibling whose heartbeat is
    fresher than HEARTBEAT_STALE_MIN (a beat that young proves life) and that left no
    clean-exit marker — so stale `.live` debris from a crash cannot trigger a false refusal.
    Never raises."""
    out: list[str] = []
    try:
        if not SESSION_STATE_DIR.is_dir():
            return out
        for p in sorted(SESSION_STATE_DIR.glob("*.live")):
            csid = p.stem
            if not csid or csid == (current_csid or ""):
                continue
            if (SESSION_STATE_DIR / f"{csid}.ended").is_file():
                continue                                   # cleanly exited — gone
            data = json.loads(p.read_text(encoding="utf-8"))
            age = _iso_age_min(data.get("last_beat") or data.get("started"))
            if age is not None and age <= HEARTBEAT_STALE_MIN:
                out.append(csid)                           # proven live, here, now
    except Exception:
        pass
    return out


# The tools whose input names the file they are about to write. Attribution is EXACT
# for these (ADR-0057 D1); `Bash` can write files this hook cannot see from the call
# (a script regenerating CANON.md), which is what the close-time sweep covers.
_TOUCH_TOOLS = {"Write", "Edit", "MultiEdit", "NotebookEdit"}


def _record_touch(sid: str, tool_name: str, tool_input: dict) -> None:
    """Record the repo-relative path a file-editing tool call is about to write into
    this session's attribution set (ADR-0057 D1). Hot path — runs on every tool call,
    so it skips the write when the path is already recorded, and FAILS OPEN on
    anything unexpected (a tool call must never be blocked by bookkeeping). Paths
    outside the repo are ignored — not ours to commit."""
    try:
        if tool_name not in _TOUCH_TOOLS:
            return
        ti = tool_input or {}
        fp = ti.get("file_path") or ti.get("notebook_path")
        if not fp:
            return
        try:
            # Resolve BOTH sides: a repo reached through a symlink (macOS /var ->
            # /private/var, or a symlinked home) makes the resolved file path
            # non-relative to an unresolved ROOT, silently attributing nothing.
            rel = str(Path(fp).resolve().relative_to(ROOT.resolve()))
        except Exception:
            return
        cur = _touched_paths(sid)
        if rel in cur:
            return                        # already attributed — skip the write
        _sidecar_write(sid, "touched", {"paths": cur + [rel]})
    except Exception:
        pass


def _record_store_write(rel_paths: list[str]) -> None:
    """Attribute store files this process just wrote to the CURRENT session (WI-0081).

    The ADR-0057 recorder is a `PreToolUse` hook and therefore only ever sees the four
    file-editing TOOLS. A work-item or ops-item write is not one of them — it is
    `session.py` writing a file itself — so the entire store was invisible to
    attribution, and `wi-commit` consequently had nothing to distinguish its own residue
    from a concurrent lane's in-flight item. It swept whatever was dirty.

    Same sidecar, same shape, same reader as `_record_touch`: attribution has one home,
    and a second parallel ledger for the store would be the duplication
    [P16](principles/master.md#p16--avoid-duplication) exists to stop.

    Fails open and silently. This is bookkeeping attached to a write that has already
    happened; it must never be the thing that turns a successful store write into an
    error."""
    try:
        sid = _claude_session_id()
        if not sid:
            return                       # no session identity — nothing to attribute to
        cur = _touched_paths(sid)
        new = [p for p in rel_paths if p and p not in set(cur)]
        if new:
            _sidecar_write(sid, "touched", {"paths": cur + new})
    except Exception:
        pass


def _touched_paths(csid: str | None) -> list[str]:
    """The repo-relative paths a session has been recorded as writing. Empty when the
    session predates attribution or only ever wrote through Bash. Never raises."""
    try:
        if not csid:
            return []
        p = SESSION_STATE_DIR / f"{csid}.touched"
        if not p.is_file():
            return []
        return [str(x) for x in json.loads(p.read_text(encoding="utf-8")).get("paths", [])]
    except Exception:
        return []


def _changed_paths() -> list[str]:
    """Every path git reports as changed in the working tree — modified, staged,
    untracked, deleted, renamed (both sides). NUL-delimited so paths with spaces or
    quotes parse correctly. Never raises; an empty list on any failure."""
    paths: list[str] = []
    try:
        r = sh(["git", "status", "--porcelain", "-z"], check=False)
        if r.returncode != 0:
            return paths
        items = r.stdout.split("\0")
        i = 0
        while i < len(items):
            ent = items[i]
            i += 1
            if len(ent) < 4:
                continue
            xy, p = ent[:2], ent[3:]
            if "R" in xy or "C" in xy:
                if i < len(items):        # rename/copy: the next item is the source
                    paths.append(items[i])
                    i += 1
            paths.append(p)
    except Exception:
        pass
    return [p for p in paths if p]


def _attributed_paths(csid: str | None, siblings: list[str]) -> tuple[list[str], int, int]:
    """The paths THIS session may commit (ADR-0057 D1, carried into ADR-0058).

    Two buckets: the changed paths this session is recorded as having written (exact),
    and any other changed path no live sibling is recorded as having written (the sweep
    — Bash-generated residue, which the hook cannot see). A path a live sibling touched
    is deliberately excluded: committing it would sweep their in-flight work into this
    session's close, which is the bug ADR-0057 was written to fix.

    Returns (paths, exact_count, swept_count). Nothing is staged — ADR-0058 D3 builds
    the commit through a private index, so the shared index is never touched."""
    mine = set(_touched_paths(csid))
    theirs: set[str] = set()
    for s in siblings:
        theirs.update(_touched_paths(s))
    changed = _changed_paths()
    exact = sorted(p for p in changed if p in mine)
    swept = sorted(p for p in changed if p not in mine and p not in theirs)
    return exact + swept, len(exact), len(swept)


# --- user-visible session banner (start + end stamp) ------------------------
#
# The banner is the one thing operator must SEE every session boundary. `start`
# stages it (below), the `announce` hook prints it. `end` prints its own end
# banner directly (it runs as an Architect Bash command, so its stdout is
# already visible). Same one-line shape at both boundaries so the pair reads
# consistently: "Session N start · <arch> v<ver> · <machine> · <stamp>".
BANNER_RULE = "─" * 4


def _commits_since(start_dt: datetime | None) -> list[str]:
    """One-line commits since a datetime (`git log --since`). Empty on any error.
    The git-evidence half of orphan triage — a Start-no-End entry with commits
    after its start stamp is almost certainly a REAL session (session-46 lesson:
    an empty-body orphan that had done v2.14→v2.15.1 of committed work was nearly
    mis-marked NC). P18 verify-everything applied to the orphan decision."""
    if start_dt is None:
        return []
    since = start_dt.strftime("%Y-%m-%d %H:%M:%S")
    r = sh(["git", "log", f"--since={since}", "--pretty=format:%h %s", "-n", "20"],
           check=False)
    if r.returncode != 0:
        return []
    return [l for l in r.stdout.splitlines() if l.strip()]


def _synth_end(text: str, prev: dict, end_dt: datetime | None) -> str:
    """Insert a synthetic End stamp on the (topmost) orphan entry `prev`, filling
    its prose header + SESSION LOG row title if still '(in progress)'. Returns the
    updated text. Shared by auto-triage (start) and `resolve-orphan --keep` — the
    surgery is CODE, never LLM text-editing of the machine-parsed handoff."""
    lines = text.splitlines()
    i = prev["header_index"]
    start_idx = start_dt = None
    for j in range(i + 1, len(lines)):
        if ENTRY_RE.match(lines[j]):
            break
        if lines[j].startswith("**Start:**"):
            start_idx, start_dt = j, parse_start_dt(lines[j])
            break
    if start_idx is None:
        return text
    if end_dt is None:
        end_dt = start_dt or datetime.now(CFG["tz"])
    if start_dt is None:
        start_dt = end_dt
    dur = format_duration(start_dt, end_dt)
    end_stamp = end_dt.astimezone(CFG["tz"]).strftime("%Y-%m-%d %H:%M %Z")
    end_line = (f"**End:**   {CFG['architect_name']} v{role_doc_version()} · "
                f"{detect_machine()} · {end_stamp} · {dur} · (auto-closed at start)")
    lines.insert(start_idx + 1, end_line)
    lines[i] = re.sub(r"— \(in progress\)$", "— (auto-closed — orphan)", lines[i])
    num = prev["number"]
    for k, line in enumerate(lines):
        rm = ROW_RE.match(line)
        if rm and rm.group(1) == num and not rm.group(2):
            lines[k] = re.sub(r"\(in progress\)", "(auto-closed — orphan)", line, count=1)
            break
    return "\n".join(lines) + "\n"


# --- ADR-0051 Phase 1: per-session journals (C1 identity + C2 own-journal writes) --
#
# Each session appends ONLY to its own journal `sessions/journal/<durable-id>.md`,
# created from turn 1 — so the narrative exists before any close, and an abandoned
# session's journal simply ends (the "orphan with no writeup" class dies at the source).
# The durable id is `<utc-compact>-<machine>-<short-random>` — no allocator, no order
# (the monotonic counter is an implicit master; ADR-0051 C1). The human-facing ordinal
# survives as a DERIVED label the compactor assigns, not one claimed at birth.
#
# THIS phase (1a) writes the journal ADDITIVELY, best-effort, alongside the existing
# shared handoff — same fail-open discipline as the liveness sidecar (a journal-write
# failure must never break the start/end it rides on). The compactor that makes
# `session-handoff.md` a GENERATED view from these journals + the frozen pre-journal
# archive, and moves the narrative fully off the shared doc, is the next increment
# (Phase 1b) — it rewrites the live start/end path and lands as its own careful session
# per the partition brief's "harness runs alone" rule.
JOURNAL_DIR = ROOT / layout_of(CFG_RAW, "journal_dir")
#: The journal directory of the checkout this process was actually launched in, captured
#: once at import. A test fixture rebinds `JOURNAL_DIR` to its temp repo; this never
#: moves, so the two compared together answer "is a machine-close about to write into a
#: REAL, tracked journal?" — the question WI-0146 needed and nothing could ask.
_LAUNCH_JOURNAL_DIR = JOURNAL_DIR
# Frontmatter key order is fixed so a journal renders deterministically (the compactor
# depends on byte-stable output; ADR-0051 Consequences).
JOURNAL_FM_KEYS = ["session-id", "ordinal", "title", "machine", "runtime",
                   "role-doc-version", "base-commit", "started", "ended",
                   "claude-session-id"]
# The default journal body (authored in the handoff-entry SUB-format, `###`, no H1 —
# the compactor supplies the heading). A journal still carrying exactly this at close
# never did any work — the reaper uses that to tell a phantom from a real short session.
_STUB_BODY = "### What happened\n\n- Session opened.\n\n### State at close\n\n### Parked question\n\n### Notes filed\n"
# WI-0137. The placeholder a journal is BORN with. It is the honest answer only while
# `ended` is empty; once a journal is closed it is a claim that the session is still
# running, and the machine closers (reaper, janitor, lane recovery) could not previously
# replace it — a title is judgment and they had none to offer. The result was a row that
# read `(in progress)` for a session that had been over for a month, with no mechanism
# that would ever correct it. Thirteen such rows had accumulated by session ~149.
JOURNAL_STUB_TITLE = "(in progress)"
# What a machine closer CAN say honestly: not what the session was about, but on what
# evidence it was declared over. Each label names the proof the close rested on, so the
# row states a fact the closer actually held ([`no-fabricated-data`](habits/master.md#no-fabricated-data))
# and stays visibly distinct from a title an Architect authored. `close-confirm` is
# deliberately untouched by all of this — nobody confirmed these closes, and that
# emptiness is the receipt ([`a-close-is-the-banner-not-the-sentence`](habits/master.md#a-close-is-the-banner-not-the-sentence)).
MACHINE_CLOSE_REASONS = {
    "exit-marker":  "dropped — closed at its exit marker",
    "process-gone": "dropped — closed when its process was seen gone",
    "silent":       "dropped — closed at its last heartbeat, silent past the grace",
    "no-evidence":  "dropped — closed with no evidence, aged out",
    # WI-0118. The worktree being GONE is itself the proof: a session cannot still be
    # running in a directory that no longer exists. Distinct from the four above because
    # the evidence is structural rather than temporal — it does not wait out a grace and
    # it does not need a sidecar to have survived. The board already computed and
    # displayed this ("lane gone" / "lane torn down" on the same row) while neither the
    # reaper nor the janitor consulted it, so the journal aged out over 7 days for a fact
    # already on screen.
    "lane-torn-down": "dropped — closed when its lane worktree was torn down",
    # WI-0391. Structural like `lane-torn-down` rather than temporal, and the evidence is
    # named exactly as narrow as it is: a new session was launched into the lane holding
    # this journal. That is NOT a claim the session died — nobody proved it — which is why
    # the label says what happened to the LANE and the `superseded-by` pointer says where
    # the lane's narrative continued. The alternative the harness shipped until now was to
    # ADOPT the journal and write a stranger's narrative into it, so a close that keeps its
    # hands off the body is strictly the smaller act on a record it does not own.
    "lane-reassigned": "dropped — closed when a new session opened in its lane",
}
# The label for a journal closed by a machine BEFORE the above shipped: it carries no
# reason, and inventing one now would be fabrication. "Dropped session" is the whole of
# what the record supports — the session ended without its close ritual running.
MACHINE_CLOSE_LEGACY = "(auto-closed — dropped session)"
# WI-0170. The title `resolve-orphan --bad` leaves. Distinct from the reaper's
# MACHINE_CLOSE_LEGACY: that one means "the machine could not tell what this was",
# this one means "a human looked and judged the record unusable".
RESOLVE_BAD_TITLE = "(resolved — corrupt session)"


def machine_close_title(reason: str) -> str:
    """The `title` a machine close writes, from the death class it proved."""
    return f"(auto-closed — {MACHINE_CLOSE_REASONS.get(reason, 'dropped session')})"


def _display_title(fm: dict) -> str:
    """The title a compiled view shows for one journal.

    Two facts decide it, and they are different questions: is this journal CLOSED, and
    does it carry a title. A closed journal still holding the birth placeholder was
    closed by a machine that had no title to give — rendering the placeholder verbatim
    republishes "still running" about a session that is over, which is the WI-0137 harm.

    This is a RENDERING rule, and it is what repairs the rows that already exist: the
    thirteen historical journals are not rewritten (their text is evidence of the defect,
    and hand-editing them would be the cleanup pass operator declined in favour of the
    mechanism). Anything closed from here on carries its own reason in frontmatter and
    never reaches the fallback."""
    title = (fm.get("title") or "").strip()
    if not (fm.get("ended") or "").strip():
        return title or JOURNAL_STUB_TITLE      # genuinely open — the placeholder is true
    if title and title != JOURNAL_STUB_TITLE:
        return title                            # an authored title always wins
    return MACHINE_CLOSE_LEGACY


def durable_session_id(machine: str, now: datetime, rand: str | None = None) -> str:
    """ADR-0051 C1 durable session id: `<utc-compact>-<machine>-<short-random>`.
    Nothing allocates order. `now`/`rand` are injectable for deterministic tests; the
    default random is 4 hex chars. Machine is slugged (lowercase, alnum) so the id is
    filename- and grep-safe. Extensible to `…-<person>-<random>` (multi-person layer)
    without a schema change."""
    ts = now.astimezone(timezone.utc).strftime("%Y%m%dT%H%MZ")
    mach = re.sub(r"[^a-z0-9]+", "", machine.lower()) or "unknown"
    r = rand if rand is not None else secrets.token_hex(2)
    return f"{ts}-{mach}-{r}"


def _base_commit() -> str:
    """The commit this session cuts from (ADR-0051 C1 causality-as-fact). HEAD at start
    is the base; the session branch (ADR-0056) is cut from it. '' on any git error."""
    r = sh(["git", "rev-parse", "HEAD"], check=False)
    return r.stdout.strip()[:12] if r.returncode == 0 else ""


def _current_branch() -> str:
    r = sh(["git", "rev-parse", "--abbrev-ref", "HEAD"], check=False)
    return r.stdout.strip() if r.returncode == 0 else ""


def _session_branch(session_id: str) -> str:
    return f"session/{session_id}"


def _on_session_branch() -> bool:
    return _current_branch().startswith("session/")


def _running_against_fixture() -> bool:
    """True when the harness is operating on a TEST FIXTURE rather than a real repo.

    The tell is a HALF-PATCHED module: `JOURNAL_DIR` moved to a temp dir while `ROOT`
    still points at the live checkout. A properly-built fixture repo patches both to
    the same temp tree (`tests/test_session_branch.py` does), and reads as real —
    correctly, because its git operations land in the temp repo where they belong.

    WI-0035. Session ~102 proved this is not hypothetical: a unit test overrode the
    `CfgPatchTest` lane pin, called `cmd_end` without `--dry-run`, and the harness ran
    `git commit` against the LIVE federation repo — sweeping the working tree into a
    commit titled `docs(handoff): close 20260718T1200Z-laptop-aa11 — x` before hanging
    on the network step. That fixture pins `_on_worktree_lane()` false precisely to
    prevent this, which means the only thing standing between the suite and the real
    repo was every future test remembering not to override it. That is discipline where
    `add-structural-guard-on-recurrence` says to put code."""
    try:
        JOURNAL_DIR.resolve().relative_to(ROOT.resolve())
        return False
    except Exception:
        return True


def _refuse_git_on_fixture(op: str) -> None:
    """Hard-stop before any git MUTATION when running against a fixture (WI-0035).

    Deliberately NOT fail-open, unlike the PreToolUse guards: those protect a live
    session and bricking the tool is worse than missing a case, whereas here the
    failure mode is writing to the operator's real repository from a test. A loud
    refusal in a test run costs one red test; a silent commit costs history."""
    if _running_against_fixture():
        raise SystemExit(
            f"session.py {op}: refused — running against a test fixture "
            f"(JOURNAL_DIR={JOURNAL_DIR} is outside ROOT={ROOT}), so this would run git "
            f"against the REAL repo. A test exercising the close must either patch ROOT "
            f"to its temp repo as well (see tests/test_session_branch.py) or pass "
            f"--dry-run. WI-0035.")


# WI-0068 — the MIRROR of the guard above, and its blind spot. `_running_against_fixture`
# keys on a `JOURNAL_DIR` that has moved OUT of `ROOT`, so it cannot see the opposite
# mistake: a test that patches `CFG` (a fake role doc, a temp handoff) and never patches
# `JOURNAL_DIR` at all. That fixture reads as a REAL repo — the journal dir genuinely is
# inside `ROOT` — so nothing refuses and the write lands in the operator's live checkout.
#
# It happened, session ~113 (2026-08-01): a run wrote `20260801T1200Z-unknown-913e` into
# the real `sessions/journal/`, already holding ordinal 114 — the next real session's
# number — and the lane's merge committed and pushed it. Every field said fixture
# (`role-doc-version: v1.0.0` is StampTest's fake role doc, `machine: UNKNOWN` is
# detection failing under a patched `sh`, `runtime: external` is the no-runtime default)
# and nothing objected, because the one thing the test did NOT fake was where the file
# went. Caught only because `git status` showed a `D` for a journal nobody wrote.
_REAL_JOURNAL_DIR = JOURNAL_DIR      # snapshot at import — immune to later patching


LANE_ORDINAL_NOTE = "lane — final number assigned at land"
#: The same disclosure for a session that is NOT on a lane (WI-0152). The trunk is
#: a concurrent writer too: `render_handoff` assigns over `_load_journals`' `started`
#: order, and an in-flight lane's journal lives on its own branch where the trunk
#: cannot see it, so a lane that started earlier and lands later is inserted AHEAD
#: and shifts this number up.
#: Off a lane the wait is on the compile rather than on a land, so the note names
#: the compile; both notes say the same thing about the same number.
START_ORDINAL_NOTE = "provisional — final number assigned by the trunk compile"


def _session_surface() -> tuple[str, str]:
    """(orientation line, short banner tag) naming which concurrency SURFACE this session
    runs on. The two-surface model — a plain `claude` on the trunk (the app surface, where
    concurrent sessions share one working tree) vs an isolated `poga` worktree lane — is
    otherwise invisible at the command line, and conflating them is exactly what turned the
    session-83 drill's first runs into accidental app-surface sessions (item 7)."""
    branch = _current_branch()
    if _on_worktree_lane():
        return (f"poga lane · {branch} (isolated worktree; lands by CAS)", f"lane {branch}")
    if _on_session_branch():
        return (f"session branch · {branch}", f"branch {branch}")
    return (f"app surface · {_trunk()} checkout (plain claude — run `poga` for an "
            f"isolated concurrent lane)", "app surface")


# ── Cross-lane coordination substrate (ADR-0051 C4/C5) ──────────────────────────
# Isolation (ADR-0060 worktree lanes) made `.session-state/` deliberately PER-TREE: a
# lane cannot see a sibling lane's liveness sidecar (see _count_other_live_sessions,
# "each git worktree has its own"). Coordination needs the OPPOSITE — a store EVERY
# concurrent lane sees — so it cannot live in a worktree's own tree, nor on a branch (a
# claim you must LAND to advertise is useless). The shared home is the git COMMON dir:
# every linked worktree of one repo shares `--git-common-dir` (the main `.git`), so
# `<common>/poga-coord/<kind>/` resolves to the SAME physical directory from every lane
# AND the main checkout, sits outside every working tree (never committed, no .gitignore
# needed), and is naturally ephemeral. This realizes the cross-tree visibility ADR-0057
# D3 deferred. Each record carries its OWN epoch TTL that a live session refreshes on
# every heartbeat, so cross-tree liveness rides in the record itself — not the per-tree
# sidecar a sibling lane cannot read. An expired record is reclaimable; correctness does
# not depend on the reaper (read-time expiry is authoritative), the reaper only tidies.
#
# The one load-bearing atomicity guarantee is O_EXCL on an AVAILABLE name: two lanes that
# both claim a free item at the same instant — exactly one wins the create, the other is
# refused and shown the holder. The expired-reclaim path has a benign last-writer race
# (two reclaimers of the SAME already-dead record); harmless at POGA's minutes-to-days
# collaboration granularity (ADR-0051 alt D), and it never lets two sessions hold a
# genuinely-available resource.

COORD_DIRNAME = "poga-coord"
# TTL a live session refreshes on every heartbeat (Stop + all-tools PreToolUse). It only
# has to outlast the gap between a live session's heartbeats plus margin; expiry frees a
# crashed session's hold. Claims: long enough to survive normal idle, short enough that a
# dead session frees the item within a work sitting. Leases: shorter — exclusive-resource
# ops (gen_settings / push-substrate) are quick, and a stuck holder should free fast.
CLAIM_TTL_SECONDS = 8 * 3600
LEASE_TTL_SECONDS = 30 * 60
# The land gate (WI-0267). Two records, two lifetimes, and the difference is the point.
# The HOLD outlives one land — a full gate run takes minutes even uncontended, and a
# land that also pushes and recompiles is longer — so it is generous; a holder that dies
# costs the queue this long, once, and every waiter says so while it waits. The TICKET is
# short, because a lane that dies WAITING must stop holding up the line quickly: its
# ticket is refreshed on every poll, so only a dead waiter's ever expires.
LAND_LOCK_TTL_SECONDS = 45 * 60
LAND_QUEUE_TTL_SECONDS = 10 * 60
# The CAS retry budget (WI-0266). Derived from what a retry COSTS, never a constant
# standing beside a cost that moves: the gate IS the CAS window, so every test added to
# the suite widens the window a retry has to survive, while a hardcoded `attempts=3`
# beside it does not move at all. One work item's worth of new tests can widen the
# same gate by several percent in a day, so a fixed attempt count is sized for no
# particular gate duration.
#
# The budget is wall-clock because the lane holds the land gate (ADR-0114 D1) for every
# one of these attempts: seconds spent retrying are seconds the queue behind us waits. It
# sits well under LAND_LOCK_TTL_SECONDS so a retrying lane can never be reclaimed as a
# dead holder mid-land. MIN is the old fixed 3, kept as a floor so this is never worse
# than what it replaces; MAX is the P19 runaway cap for a member whose gate is fast
# enough that the wall-clock allowance alone would permit hundreds.
LAND_CAS_MIN_ATTEMPTS = 3
LAND_CAS_MAX_ATTEMPTS = 12
LAND_CAS_BUDGET_SECONDS = 20 * 60
ADR_ALLOC_TTL_SECONDS = 8 * 3600
WI_ALLOC_TTL_SECONDS = 8 * 3600
OPS_ALLOC_TTL_SECONDS = 8 * 3600
# Every coordination kind that is a HOLD — something one session takes, that expires, that
# a dead lane's teardown must let go of, and that `release` must be able to clear. This one
# tuple drives all five of those surfaces (`_coord_reap`, `_coord_release_dead_lanes`,
# `_lane_exit_release`, `release --kind`, and the `coord` dump), which is what makes a
# newly added kind defended everywhere at once instead of in four places someone remembers.
#
# WI-0182 added `attention` and `ops-alloc`, and the gap was the same one twice: a kind that
# writes records into the store but is absent HERE is invisible to every one of those five.
# `ops-alloc` had a TTL constant and no reaper to honour it. `attention` had neither a
# release path nor a teardown release, so a stale record naming a lane that no longer
# existed could only be waited out (24h) or hand-edited under `.git/` — WI-0164's exact
# shape, one kind further on, and the `coord` dump that should have shown it silently
# skipped it too because it iterates this same tuple while its docstring says "all kinds".
#
# `dispatch` and `dispatch-spawn` stay OUT, on the reason stated at `_dispatch_dir`: a
# dispatch plan is not a hold. It must survive the TTL reaper and lane teardown — the lane
# that dies is often the one that just landed an item the queue still needs — and it has its
# own retirement verb (`dispatch-cancel`). Excluded by argument, not by omission.
#
# `land-gate` and `land-queue` (WI-0267) are both holds and both belong here: the gate is
# the one-at-a-time land token, the queue is a waiter's ticket in line for it. A dead lane's
# teardown must let go of BOTH — a corpse holding the gate stops every land on the machine,
# and a corpse at the head of the queue stops every land behind it, which is the same
# outage wearing a different hat.
# `trunk-lock` (WI-0293) is the third hold and belongs here for the same reason as the
# other two, one step sharper: it is taken by `poga work`, a verb that runs for
# milliseconds and can be killed between any two syscalls. A corpse holding it blocks
# every land AND every store write in the repo. It is the shortest-lived record here
# and therefore the most likely to be orphaned, which is exactly why omitting it would
# be WI-0182's bug for the third time.
COORD_KINDS = ("claims", "leases", "adr-alloc", "wi-alloc", "ops-alloc", "attention",
               "lane-alloc", "land-gate", "land-queue", "trunk-lock")
# Where a released record's tombstone lives, under each kind (WI-0074), and how long it
# survives. Same order as the claim TTL: long enough that someone reconstructing a bad
# night still sees the release, short enough that the directory is self-limiting.
COORD_RELEASED_DIRNAME = "released"
COORD_TOMBSTONE_TTL_SECONDS = CLAIM_TTL_SECONDS


def _git_dir() -> Path | None:
    """THIS worktree's own git directory, or None when it cannot be named with certainty.

    Distinct from `_git_common_dir`, and the difference is the whole reason this exists:
    per-worktree state — `MERGE_HEAD`, `REBASE_HEAD`, `HEAD` itself — lives in
    `.git/worktrees/<name>/`, while the common dir is the shared one. A merge in progress
    in a lane is invisible from the common dir, and a lane is where this substrate does
    almost all of its work.

    Absolute or nothing, for ADR-0114 D9's reason: a relative answer resolved against the
    process CWD produces a plausible path INSIDE the working tree, and a plausible wrong
    path is the one failure none of the callers can detect."""
    try:
        r = sh(["git", "rev-parse", "--absolute-git-dir"], check=False)
        p = (r.stdout or "").strip()
        if r.returncode != 0 or not p or not Path(p).is_absolute():
            return None
        return Path(p)
    except Exception:
        return None


def _git_common_dir() -> Path | None:
    """Absolute path to the shared git common dir (the main `.git`) — the same physical
    directory from every worktree lane and the main checkout. None on any git error, so a
    caller degrades coordination to a no-op (isolation still holds) rather than bricking."""
    r = sh(["git", "rev-parse", "--path-format=absolute", "--git-common-dir"], check=False)
    if r.returncode != 0 or not r.stdout.strip():
        return None
    out = Path(r.stdout.strip())
    # WI-0267: the answer must be ABSOLUTE, because that is what was asked for. Anything
    # relative is not this question's answer, and `.resolve()` would silently turn it into
    # one by anchoring on the process CWD — which is the repo root, so the "shared
    # coordination store" becomes a directory inside the working tree. Caught for real:
    # serializing the land made the land paths write coordination records for the first
    # time, and a fixture that stubs `sh` so every `rev-parse` returns a fixed short sha
    # created `beef9999/poga-coord/` in the checkout, which a `git add -A` then committed.
    # Absence of a common dir is a case every caller already handles (fail-open); a
    # plausible WRONG path is one none of them can detect.
    if not out.is_absolute():
        return None
    return out.resolve()


# Cached per ROOT, not globally. The git common dir is fixed for the life of a real
# process, so in production this is resolved exactly once — but ROOT is a module global
# that the test suite repoints between cases, and a cache keyed on nothing then serves one
# fixture's main checkout to the next. That is not merely a test artifact: it is a cache
# whose key was implicit, and an implicit key is one nobody can check. Keyed on the value
# it actually depends on, it is correct in both worlds and still one git call in the one
# that matters.
_SHARED_WORK_ROOT: tuple[Path, Path] | None = None


def _shared_work_root() -> Path:
    """The MAIN checkout's working-tree root — where GITIGNORED working state physically
    lives (the receipt-ritual inbox, machine-local `.local` config).

    In the main checkout this is ROOT. In a worktree lane it is NOT: a lane's checkout
    contains only TRACKED files, so gitignored state is simply absent there — which is why
    a lane's inbox always read empty and auto-adopt silently no-opped at every lane start
    (session 90). Resolved the same way the coordination store resolves: the git COMMON dir
    is shared by every lane, so its parent is the main working tree. Falls back to ROOT on
    any git error, so a non-git or odd layout degrades to today's behaviour rather than
    breaking.

    MEMOIZED per process (WI-0102). It shells out to git, and that subprocess is
    essentially the whole cost of an inbox lookup: the directory read itself is
    hundreds of times cheaper. The
    docstring used to say "never on the heartbeat path" for exactly that reason — but the
    answer cannot change inside one process (the git common dir is fixed once the process
    starts), so the honest fix is to pay it once rather than to keep the inbox off the
    hot path forever. After the first call the lookup is a dict hit."""
    global _SHARED_WORK_ROOT
    if _SHARED_WORK_ROOT is not None and _SHARED_WORK_ROOT[0] == ROOT:
        return _SHARED_WORK_ROOT[1]
    common = _git_common_dir()
    if common is None:
        return ROOT                    # NOT cached: a transient git failure must not pin
    parent = common.parent
    resolved = parent if (parent / ".git").exists() else ROOT
    _SHARED_WORK_ROOT = (ROOT, resolved)
    return resolved


# ── Is the store's checkout current? (WI-0222) ───────────────────────────────────
# WI-0188 gave `attach` a staleness line and stopped there; WI-0155 covers `dispatch`.
# `poga work` was the THIRD surface of ONE fact — the checkout that owns the store is
# behind its remote — and the class was being fixed one verb at a time, which is exactly
# what `add-structural-guard-on-recurrence` says to stop doing. So the probe lives here,
# once, and its two callers differ only in what they DO with the answer.
#
# REPORT vs REFUSE, and why they are not the same. A stale LISTING is misleading; a stale
# DRAW is corrupting. `poga work list` off an old checkout shows old numbers and the
# operator can at least see them. `poga work new` off an old checkout draws a number that
# ALREADY EXISTS on the trunk: a main sitting far enough behind can re-issue an id like
# WI-0188 — an id whose own title is "The operator machine's
# checkout goes stale silently" — and nothing surfaces that until the land. So reading
# reports, and drawing refuses.
#
# THE REF IS THE TRUNK, NOT `HEAD`. The question is "is the checkout that owns the store
# behind its remote", and in a lane `HEAD` is `worktree-poga-N`, which tracks nothing — so
# asking about HEAD there answers CANNOT TELL forever and the check degrades to noise.
# Refs are shared across every worktree (they live in the common git dir), so asking about
# the trunk gives the same definite answer from a lane as from the main checkout.
#
# IT NEVER PULLS. Pulling under an operator mid-fan-out is the surprise WI-0188 explicitly
# rejected, and nothing since has given a reason to overturn it.
CHECKOUT_FETCH_TTL_SECONDS = 600            # 10 minutes (the operator's ruling, session ~187)

# How long we will WAIT for a refresh before calling it CANNOT TELL. Short on purpose: the
# healthy case measured under a second, and the sick case measured 75 s — an unreachable
# remote — so a generous timeout buys nothing on a good network and is the entire
# cost on a bad one. Paired with the attempt-throttle in `_fetch_ages`, a machine that is
# offline pays this once per TTL rather than once per command.
CHECKOUT_FETCH_TIMEOUT_SECONDS = 5

# Verbs that must never print the staleness line. A DENYLIST, deliberately, not an
# allowlist. `ship-the-detector-with-the-capability` is about a capability that ships with
# no marker and therefore reads as absent to the surface that should show it — and an
# allowlist reproduces that exactly: the next store verb someone adds would silently have
# no check, and nothing would say so. Default-on means a new verb inherits the check, and
# opting one out is a visible edit right here.
#
# What is opted out, and why: every hook-invoked verb (a line printed into a hook's output
# lands in a channel nobody chose to read, and `start` already diagnoses its own sync state
# — a second opinion there is duplication, not defence), the machine-to-machine allocation
# and coordination verbs, and `test`, whose output the suite itself parses.
CHECKOUT_QUIET_VERBS = frozenset({
    "announce", "apply-briefs", "auto-adopts", "check-bash", "check-question", "end",
    "heartbeat", "hooks", "record-end", "start", "worktree-remove",
    "lane-alloc", "coord", "lease", "unlease", "journal-title", "wi-feed", "test",
    # `interpreter` answers one question in a fixed shape and a test parses it; a
    # staleness line in the middle of that is noise in a machine-read channel.
    "interpreter",
    # `lane-identity` (WI-0157) is the same shape with a sharper reason. `poga lanes`
    # shells out to it for the LANE column, and `poga lanes` was a pure LOCAL ref walk
    # before that — so leaving it off this list would make a listing verb reach the
    # NETWORK, paying a fetch (0.81s measured here, up to the fetch timeout when the
    # network is down) for a staleness line the caller discards. A display column must
    # not buy a fetch.
    "lane-identity",
})


def _fetch_ages(root: Path, upstream: str) -> tuple[float | None, float | None]:
    """`(since_success, since_attempt)` in seconds, either None for "no idea".

    TWO CLOCKS, and conflating them is a real bug I shipped and caught by running the real
    path (WI-0222). `since_success` is how old the remote-tracking refs are, and it is what
    an answer's freshness must be reported against. `since_attempt` is how long ago we last
    TRIED, and it is what throttling must key on — because if a failed attempt leaves no
    trace, a machine that cannot reach its remote retries on every single invocation and
    pays the full timeout each time. Measured here: with the remote unreachable a fetch
    took 75 s to fail, so keying the throttle on success alone turned a 0.15 s verb into a
    30 s one, every time, for as long as the network stayed down.

    Unreadable, absent and corrupt all answer None, and None means GO AND LOOK — the safe
    direction, since the worst case is one redundant fetch where the opposite mistake is
    trusting refs nobody refreshed."""
    try:
        rec = json.loads(_fetch_stamp_path(root).read_text(encoding="utf-8"))
        entry = rec.get(upstream, {})
        at, tried = float(entry.get("at", 0)), float(entry.get("tried", 0))
    except Exception:
        return None, None
    now = time.time()

    def _age(t: float) -> float | None:
        if t <= 0:
            return None
        age = now - t
        return age if age >= 0 else None    # a clock that moved backwards is "no idea"

    return _age(at), _age(tried)


def _staleness_as_of(age: float | None) -> str:
    """How old the knowledge is, in words.

    Empty ONLY when we just looked — the freshest answer needs no qualifier, and
    qualifying it anyway would train the reader to skip the phrase on the one occasion it
    is load-bearing. `None` is not freshness: it means nothing here has ever refreshed
    successfully, so it says so rather than rendering identically to "just checked"."""
    if age is None:
        return " (freshness UNKNOWN — nothing here has refreshed successfully)"
    if age < 60:
        return ""
    return f" (as of a refresh {int(age // 60)} min ago)"


# --- remote-ref provenance (WI-0283) -----------------------------------------
#
# `_checkout_staleness` above answers "how far behind is this checkout, and may I
# trust the answer" for ONE ref, and pays a fetch to do it. This answers a smaller,
# cheaper and more widely-needed question: given a remote-tracking ref someone is
# about to compare against, WHEN was it last confirmed against the remote, and WHAT
# put it where it is. It never fetches, so any caller can afford it.
#
# `origin/<branch>` is neither of the two sources ADR-0108 taught us to name. It is
# not the remote — it is a local ref as old as the last SUCCESSFUL fetch, and a fetch
# that fails leaves it UNCHANGED rather than unreadable, so probes keep answering in
# the old shape with no error. And it is not your tree either — the lanes share one
# git common dir (ADR-0060/0062), so a SIBLING's push moves it underneath you and it
# can be FRESHER than anything you did. Its freshness is therefore uncorrelated with
# your own connectivity in both directions, which is why a comparison against it is
# not a measurement unless it carries its own date.
#
# THE FEDERATION COPY IS `curate/common.py:remote_provenance`, and the two are pinned
# equal by `tests/test_remote_provenance.py`. `session.py` ships to every member and
# cannot import federation-only `curate/`, the same reason `atomic_write` is
# duplicated a few hundred lines above. Change one, change both, or the test fails.

_REFLOG_FMT = "%H%x1f%gs%x1f%ct"


def _short_remote_ref(ref: str) -> str:
    """`refs/remotes/origin/main` and `origin/main` are one ref under two names, and
    the fetch stamp is keyed by the SHORT one. Normalising here means a caller may
    pass either spelling and still get a freshness answer instead of silently None."""
    ref = str(ref)
    return ref[len("refs/remotes/"):] if ref.startswith("refs/remotes/") else ref


def _ref_last_move(root: Path, ref: str) -> tuple[str | None, float | None]:
    """`(kind, unix_time)` of the ref's last movement — `fetch`, `push`, `other`, or
    `(None, None)` when nothing can be told.

    Reflogs for `refs/remotes/*` are on by default in a non-bare repo but are NOT
    guaranteed: a fresh clone, an expired or pruned log, or a `git gc` can leave none.
    Absence means "I cannot tell what moved it", never "nothing moved it"."""
    try:
        r = sh(["git", "reflog", "show", "--format=" + _REFLOG_FMT, "-n", "1", str(ref)],
               check=False, cwd=root)
    except Exception:
        return None, None            # git absent or unrunnable is "cannot tell", not a crash
    if r.returncode != 0 or not (r.stdout or "").strip():
        return None, None
    parts = r.stdout.strip().split("\x1f")
    if len(parts) != 3:
        return None, None
    subject = (parts[1] or "").strip().lower()
    try:
        when = float(parts[2])
    except ValueError:
        when = None
    if not subject:
        kind = None
    elif "push" in subject:
        kind = "push"
    elif (subject.startswith("fetch") or subject.startswith("pull")
          or "storing head" in subject):
        kind = "fetch"
    else:
        kind = "other"
    return kind, when


def _remote_provenance(ref: str, root: Path | None = None,
                       ttl: int = CHECKOUT_FETCH_TTL_SECONDS) -> dict:
    """WHEN a remote-tracking ref was last confirmed against its remote, and by WHAT.

    THREE OUTCOMES, NEVER TWO (ADR-0108 D1), and the third is the whole point:

      readable=False              the ref is not there; there is no reading at all
      readable=True, fresh=True   contact within `ttl`; `confirmed_by` says how
      readable=True, fresh=False  the ref reads fine and its freshness is CANNOT TELL

    READ-ONLY AND FREE. It never fetches, never writes a stamp and never moves a ref,
    so it is safe in a hook, offline, or in a loop. Refreshing is a separate decision
    with a separate price (0.81s against a 0.15s verb, WI-0222) and it already has an
    owner in `_checkout_staleness`.

    `{"ref", "sha", "readable", "fresh", "age", "confirmed_by", "fetch_age",
    "moved_by", "moved_age"}`."""
    out = {"ref": _short_remote_ref(ref), "sha": None, "readable": False,
           "fresh": False, "age": None, "confirmed_by": None, "fetch_age": None,
           "moved_by": None, "moved_age": None}
    try:
        return _remote_provenance_read(ref, root, ttl, out)
    except Exception:
        # CANNOT RAISE, AND THE GUARANTEE IS STATED ONCE, HERE. A caller annotating a
        # verdict with provenance must never LOSE that verdict because the annotation
        # failed. Found the hard way (WI-0283): the first version guarded each `sh()`
        # and still died in `root or _shared_work_root()`, which shells out before any
        # of those guards is reached — guarding the calls you thought of is the same
        # mistake one level down. `_wi_missing_numbers` reports a missing work item
        # even when git cannot run at all, and `test_claims` mocks git into raising to
        # prove it; a dead git is simply the UNREADABLE outcome, which `out` already is.
        return out


def _remote_provenance_read(ref: str, root: Path | None, ttl: int, out: dict) -> dict:
    """The body of `_remote_provenance`, which owns the never-raises guarantee. Split
    out so that guarantee wraps EVERY statement including the root resolution, rather
    than only the calls someone remembered to wrap."""
    root = root or _shared_work_root()
    r = sh(["git", "rev-parse", "--verify", "--quiet", str(ref)], check=False, cwd=root)
    if r.returncode != 0 or not (r.stdout or "").strip():
        return out
    out["sha"], out["readable"] = r.stdout.strip(), True
    out["fetch_age"] = _fetch_ages(root, out["ref"])[0]

    kind, when = _ref_last_move(root, ref)
    out["moved_by"] = kind
    if when is not None:
        moved = time.time() - when
        out["moved_age"] = moved if moved >= 0 else None

    # TWO INDEPENDENT WITNESSES TO CONTACT, and both err safely. The STAMP is exact
    # but exists only where `session.py` runs. The REFLOG exists everywhere and
    # under-claims by construction — a fetch that finds nothing new moves no ref, so
    # the log is at least as old as the true last contact. Take the most recent.
    #
    # A push counts. A push that succeeded reached the remote and the remote accepted
    # that sha; what differs from a fetch is whose act it was and what it proves, not
    # whether contact happened — so `confirmed_by` names the act rather than ranking it.
    #
    # A move we cannot classify (`other`, or no reflog) is NOT contact: it may have been
    # a local `update-ref` that never left the machine, and guessing generously here is
    # exactly the false all-clear this exists to prevent.
    moved_age = out["moved_age"] if out["moved_by"] in ("fetch", "push") else None
    seen = [(a, k) for a, k in ((out["fetch_age"], "fetch"), (moved_age, out["moved_by"]))
            if a is not None]
    if seen:
        out["age"], out["confirmed_by"] = min(seen)
    out["fresh"] = out["age"] is not None and out["age"] < ttl
    return out


def _remote_clause(ref: str, root: Path | None = None,
                   ttl: int = CHECKOUT_FETCH_TTL_SECONDS) -> str:
    """`_remote_provenance` rendered as the clause a verdict carries (ADR-0108 D1).

    A FRAGMENT, so a caller appends it to its own number rather than emitting a second
    line the reader has to join up — and NEVER empty, unlike `provenance_clause`,
    because the defect being fixed is a comparison that renders as a bare measurement.
    `0 behind origin/main` a minute after a fetch and `0 behind origin/main` when
    nobody has reached the remote all week are the same characters today."""
    return _remote_clause_of(_remote_provenance(ref, root=root, ttl=ttl))


def _remote_clause_of(p: dict) -> str:
    """Render a provenance record someone ALREADY HOLDS.

    Split from the probe because a caller that decided something from a record must
    quote THAT record, not a fresh one: with concurrent lanes a sibling's push can move the ref
    between two probes, so a re-probing renderer can contradict the verdict it is
    attached to inside one sentence. It is also half the git calls on a banner path."""
    if not p["readable"]:
        return f"{p['ref']} UNREADABLE (no such ref here)"
    where = f"per {p['ref']} at {p['sha'][:7]}"
    if p["fresh"]:
        mins = int(p["age"] // 60)
        when = "just now" if mins < 1 else f"{mins} min ago"
        if p["confirmed_by"] == "push":
            return f"{where}, last confirmed {when} by a local push, not a fetch"
        return f"{where}, fetched {when}"
    if p["age"] is None:
        why = "nothing here has ever reached the remote successfully"
    else:
        why = (f"the last contact with the remote was {int(p['age'] // 60)} min ago "
               f"({p['confirmed_by']})")
    if p["moved_by"] is None:
        why += ", and no reflog survives to say what last moved the ref"
    elif p["moved_by"] == "push" and p["confirmed_by"] != "push":
        why += ", and the ref last moved by a local push rather than a fetch"
    return f"{where} — freshness CANNOT TELL ({why})"


def _refuse_stale_draw(label: str, draw_cmd: str, behind: int, upstream: str,
                       root: Path) -> None:
    """The allocator half — and the half that REFUSES rather than reports (WI-0222).

    Drawing from a checkout provably behind its remote is never correct: the highest
    number it can SEE is not the highest number that EXISTS, so the draw re-issues a
    landed id and the collision stays invisible until the land.
    `numbers-are-drawn-never-picked` already argues that a mechanism which is merely
    available gets bypassed exactly when it matters — a warning here would be that bypass
    with extra steps.

    Exits 3, matching `_refuse_undrawn`, so a caller can tell "could not draw" from
    argparse's "you used it wrong". Nothing on stdout: a capture must come back EMPTY
    rather than holding a number nobody can trust."""
    print(f"{draw_cmd}: REFUSING to issue an {label} number — {root} is {behind} "
          f"commit(s) behind {upstream}, so the highest number it can SEE is not the "
          f"highest number that EXISTS.\n"
          f"          Drawing here re-issues an id that already landed on the trunk. "
          f"A main far enough behind can hand back an existing id a second time, "
          f"and nothing says so until the land.\n"
          f"          Pull in {root}, then draw again. Nothing was reserved.",
          file=sys.stderr)
    sys.exit(3)


#: The notice `curate/push-substrate.py` leaves in a member it just refreshed (WI-0131).
#: Gitignored sidecar, never substrate — a marker that dirtied the target's tree would be
#: a worse version of the tree-noise it exists to replace.
SUBSTRATE_PUSH_MARKER = "substrate-push.json"


# ── WI-0023: the permission pile is visible, not just large ─────────────────────
#: Where Claude Code accumulates a project's granted permissions. Every "yes, allow
#: that" lands here and NOTHING ever removes one, so the file is a monotonic record of
#: every one-off a session ever needed. Machine-local and gitignored by design.
PERMISSION_PILE = ".claude/settings.local.json"

#: Print the pile only once it is worth a person's attention. A line on every start in
#: every member forever is how a signal trains its reader to skip it — the pile grows
#: slowly and reviewing it is never urgent, so the line has to be RARE to be read.
#: Overridable per system via `permission_pile.rules` / `.bytes` in session.config.json.
PERMISSION_PILE_RULES = 100
PERMISSION_PILE_BYTES = 32 * 1024


def _permission_pile_thresholds() -> tuple[int, int]:
    """(rules, bytes) at which the pile becomes worth announcing."""
    cfg = (CFG.get("permission_pile") if CFG else None) or {}
    if not isinstance(cfg, dict):
        cfg = {}

    def _n(key: str, default: int) -> int:
        try:
            v = int(cfg.get(key, default))
            return v if v > 0 else default
        except Exception:
            return default

    return _n("rules", PERMISSION_PILE_RULES), _n("bytes", PERMISSION_PILE_BYTES)


def _permission_pile_stats(path=None) -> dict | None:
    """Measure this repo's permission pile, or None when there is nothing to measure.

    THREE outcomes, never two ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)):
    the file is ABSENT (nothing has accumulated here — a real, clean answer), it is
    UNREADABLE (present but unparseable, which must not read as clean), or it is
    measurable. Returning `None` for absent and a `readable: False` record for
    unreadable is what keeps "I could not look" out of the same channel as "I looked
    and it is small."

    `exact` counts rules carrying no wildcard — `Bash(git status)` matches exactly one
    invocation forever, where `Bash(git status:*)` is a real standing grant. That ratio
    is the reviewable signal: a pile that is mostly exact-path entries is a heap of dead
    one-offs, not a permission posture anyone chose.

    NOT REPORTED, deliberately: the age of the oldest ENTRY. The file is a bare list of
    strings with no timestamps, so per-entry age does not exist to be read and computing
    one would be a fabricated measurement
    ([`no-fabricated-data`](habits/master.md#no-fabricated-data)). The file's own mtime
    is a real and different fact — when the pile last GREW — and is reported as that,
    under its own name."""
    p = Path(path) if path else (ROOT / PERMISSION_PILE)
    try:
        if not p.is_file():
            return None
    except Exception:
        return None
    try:
        raw = p.read_text(encoding="utf-8")
        size = len(raw.encode("utf-8"))
        mtime = p.stat().st_mtime
    except Exception:
        return {"readable": False, "path": str(p), "size": None, "mtime": None}
    try:
        doc = json.loads(raw)
        perms = doc.get("permissions") if isinstance(doc, dict) else None
        if not isinstance(perms, dict):
            perms = {}
    except Exception:
        return {"readable": False, "path": str(p), "size": size, "mtime": mtime}
    buckets: dict[str, list[str]] = {}
    for key in ("allow", "deny", "ask"):
        v = perms.get(key)
        buckets[key] = [r for r in v if isinstance(r, str)] if isinstance(v, list) else []
    rules = [r for v in buckets.values() for r in v]
    return {
        "readable": True,
        "path": str(p),
        "size": size,
        "mtime": mtime,
        "total": len(rules),
        "exact": len([r for r in rules if "*" not in r]),
        "allow": len(buckets["allow"]),
        "deny": len(buckets["deny"]),
        "ask": len(buckets["ask"]),
    }


def _permission_pile_line(now: float | None = None) -> str:
    """One banner line when the pile has grown past review-worthy, else "" (WI-0023).

    One member's pile has grown into the tens of kilobytes, and nobody has ever read one — the pile is
    invisible precisely because nothing reports it, and each individual "allow" was
    locally reasonable. This is the review MOMENT, not an enforcement: the operator's original
    framing was a 30-day auto-flush, argued against in the item on two grounds that both
    still hold — the entries carry no timestamps so only a wholesale wipe is
    implementable, and the unattended adoption runner would meet a flushed file at 03:15
    and fail silently rather than prompt anybody. Visibility buys the review without the
    breakage; an expiry ceiling is the right answer only once a genuinely broad grant
    wants a guaranteed lifetime."""
    stats = _permission_pile_stats()
    if stats is None:
        return ""                    # absent: nothing has accumulated. Silent, and true.
    if not stats.get("readable"):
        return (f"perms:   {PERMISSION_PILE} is present but UNREADABLE — its size and "
                f"contents CANNOT be measured (this is not the same as small)")
    rule_max, byte_max = _permission_pile_thresholds()
    if stats["total"] < rule_max and (stats["size"] or 0) < byte_max:
        return ""                    # small enough that saying so would be noise
    grew = ""
    try:
        days = int(((now if now is not None else time.time()) - stats["mtime"]) // 86400)
        grew = f", last grew {days}d ago" if days >= 1 else ", grew today"
    except Exception:
        pass
    return (f"perms:   {stats['total']} accumulated rule(s) in {PERMISSION_PILE} "
            f"({(stats['size'] or 0) / 1024.0:.0f} KB{grew}) — {stats['exact']} are "
            f"exact-path one-offs that can never match again. Nothing is owed; review "
            f"when you want the pile smaller. (No per-entry ages exist to report — the "
            f"file carries none.)")


def _harvest_session_work_items(journal_id: str) -> list[str] | None:
    """ADR-0093 D1: the work-item ids this session held, for its journal to keep.

    Why the CLOSE and why at all: the binding between a session and its work already
    exists — a claim record carries the owning `journal`, and every release/reclaim/
    teardown leaves a tombstone (WI-0074) — but all of it is EPHEMERAL, pruned at the 8h
    `CLAIM_TTL_SECONDS`, while the journal that git keeps forever never learns any of it.
    So "what did this session do?" was answerable for eight hours and then never, which is
    exactly why reconstructing session ~109 missed its largest deliverable: the evidence
    had already been collected, not never recorded. The close is the one moment both facts
    are true at once — the store still holds this session's claims and its unexpired
    tombstones, and the journal is open for its stamp.

    Live claims AND tombstones, because a session that claimed an item and released it
    mid-session did that work just as much as one still holding at close.

    Returns `None` — meaning WRITE NO KEY — when the coordination store cannot be read at
    all. That is a third state, distinct from `[]` ("held nothing", an honest and common
    answer): this field exists to be counted (D5), and folding "could not tell" into
    "nothing" would put a miscount into the record as fact
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
    Never raises — a harvest must not be able to fail a close."""
    if not journal_id:
        return None
    try:
        if _coord_dir("claims") is None:
            return None
        ids = {name for name, rec in _coord_list("claims").items()
               if rec.get("journal") == journal_id}
        ids |= {name for name, rec in _coord_tombstones("claims").items()
                if rec.get("journal") == journal_id}
        # WI-0174: a drill claims through the production path, so its synthetic id
        # arrives here like any other. Session ~173's journal landed carrying
        # `work-items: DRILL-1` — a permanent record of an item that never existed.
        # Dropping them here rather than at the claim keeps the rehearsal exercising
        # the real code, which is the only reason the drill is worth running.
        return sorted(i for i in ids if not _is_drill_item(i))
    except Exception:
        return None


def _invoked_session_key() -> str:
    """A per-session ownership key for a session whose runtime supplies no session id, or
    '' when the caller is not standing in a lane.

    Two tiers, most authoritative first. The lane's **prep marker** names the durable
    journal id `poga` created for it — unique by construction, written for every
    poga-launched lane, and the same id the journal itself carries, so a record and a
    journal can be joined. Failing that, the lane **path** (`.claude/worktrees/<lane>`)
    yields the branch name that a lane-local caller would have used, which keeps the two
    routes to the same lane agreeing. Read from the invoking checkout's own
    `.session-state/`, never `SESSION_STATE_DIR`, which under the anchored front door
    points at main."""
    d = _invoked_checkout()
    try:
        rec = json.loads((d / ".session-state" / "prep.json").read_text(encoding="utf-8"))
        sid = (rec.get("session_id") or "").strip()
        if sid:
            return sid
    except Exception:
        pass
    try:
        parts = d.parts
        if len(parts) >= 2 and parts[-2] == "worktrees":
            return f"worktree-{parts[-1]}"
    except Exception:
        pass
    return ""


LANE_ALLOC_KIND = "lane-alloc"
# Long enough to cover `git worktree add` plus a runtime boot on a cold machine, short
# enough that a crashed launcher's reservation frees itself rather than needing a verb.
# It is only ever load-bearing for the seconds between drawing a lane and the worktree
# existing — after that `_lane_taken` sees the directory and the reservation is redundant.
LANE_ALLOC_TTL_SECONDS = 5 * 60


def _launch_left_nothing(lane_dir: Path, branch: str) -> tuple[bool, str]:
    """Can this lane be rolled back with certainty that nothing is lost? (WI-0105)

    Returns (safe, why-not). The predicate carries the safety argument, exactly as
    `discard-phantom-lanes` does: a rollback is a destructive act on a worktree and a
    branch, so it must be reachable ONLY where it is provably a non-event. The failure
    this exists for leaves a worktree, a branch, a `.live` marker, a prep marker naming a
    session that will never start, and an 81k `session-context.md` — and no agent behind
    any of it.

    Four things must all hold, and each rules out a way of being wrong:

      * NO COMMITS AHEAD BY CONTENT. `_lane_work_is_on_trunk` rather than an ancestor
        test, for the WI-0147 reason — a lane whose work landed from a sibling carries
        different SHAs for identical patches.
      * NO LIVE HEARTBEAT. If something is beating in there, the launch did not fail; a
        rollback would delete a working session's tree.
      * NO JOURNAL WITH REAL NARRATIVE. A failed launch writes none — the ADR-0055 lazy
        rule means the journal materialises at the first tool call, which never came. A
        journal carrying anything but a stub means an agent ran and wrote, so this is
        not the case this verb is for.
      * NO UNCOMMITTED AUTHORED FILES. Everything prep writes is known and enumerable;
        anything else in the tree came from somewhere this verb cannot account for.

    Every error path answers "not safe". An unreadable lane is never a rollback
    candidate — the direction that keeps a tree rather than deleting one."""
    try:
        if not lane_dir.is_dir():
            return False, "no such lane directory"
        if _tree_has_live_session(lane_dir):
            return False, ("a session is LIVE in this lane — its launch did not fail")
        if branch and not _lane_work_is_on_trunk(branch, _trunk()):
            return False, (f"branch {branch} holds commits that are not on {_trunk()} "
                           f"by content — land it, never roll it back")
        jdir = layout_of(CFG_RAW, "journal_dir")
        cleared_journals: set[str] = set()
        for p in (lane_dir / jdir).glob("*.md"):
            try:
                fm, body = parse_journal(p.read_text(encoding="utf-8"))
            except Exception:
                return False, f"journal {p.name} could not be read"
            if not _journal_is_unauthored(body):
                return False, (f"journal {p.name} carries real narrative — an agent ran "
                               f"here, so this is not a failed launch")
            cleared_journals.add(f"{jdir}/{p.name}")
        r = sh(["git", "-C", str(lane_dir), "status", "--porcelain", "-uall"], check=False)
        if r.returncode != 0:
            return False, "the lane's git status could not be read"
        stray = [ln[3:].strip() for ln in (r.stdout or "").splitlines() if ln.strip()]
        # `session-context.md` is prep's own payload and `.session-state/` its sidecars —
        # the only things a launch that never started can legitimately have left. A stub
        # journal is exempt too, but only because the loop ABOVE already read it and
        # proved it is a stub: the exemption is granted per-file by that check, never by
        # the path pattern, or "it lives in the journal dir" would wave through the one
        # file class that can carry real authored work.
        stray = [s for s in stray
                 if not s.startswith(".session-state/")
                 and _basename_of(s) != "session-context.md"
                 and s.strip('"') not in cleared_journals]
        if stray:
            return False, (f"the lane holds {len(stray)} uncommitted file(s) this verb "
                           f"cannot account for (first: {stray[0]})")
        return True, ""
    except Exception as e:
        return False, f"could not establish safety ({type(e).__name__})"


def _basename_of(rel: str) -> str:
    """The basename of a repo-relative path, quote-tolerant."""
    return rel.strip('"').rsplit("/", 1)[-1]


# WI-0164: the coordination kinds that are NUMBER RESERVATIONS. These get the stronger
# death test below; claims deliberately do not. A number reservation protects a name in a
# namespace, and freeing one that no live lane is using costs nothing while holding one
# hostage blocks a land. A CLAIM is the opposite trade: freeing one under a lane that is
# briefly between heartbeats — or that has not written its first beat yet — hands its item
# to a sibling while it is still working. Same evidence, different cost, so a different
# threshold. Claims keep the branch-gone proof, the 8h TTL and the teardown release.
COORD_ALLOC_KINDS = ("adr-alloc", "wi-alloc", "ops-alloc", "lane-alloc")


# ── C5 leases: single-writer exclusion for the few genuinely-exclusive resources ─
# Almost nothing qualifies (ADR-0051 C5 — "leasing broadly is Option A returning"). The
# enumerated set for the federation is the gen_settings / push-substrate file-set: the one
# operation two otherwise-disjoint lanes both plausibly run that mutates state OUTSIDE
# their own worktree (push-substrate writes every reachable member repo; worktree isolation does NOT cover that — the target repos are shared). A lease is
# a coord record `leases/<name>.json` with a short TTL (exclusive ops are quick), held by
# the running lane and released on block exit. `gen_settings`' STANDALONE own-file write is
# NOT leased on purpose: it writes this worktree's own `.claude/settings.json`, so two lanes
# writing their own files never collide and a lease there would only false-block a sibling.

LEASE_NAMES = ("gen_settings", "push-substrate")  # the enumerated single-writer set


# ── WI-0267: the land gate is serialized — one land at a time, the rest queue ────
#
# MEASURED, NOT ASSUMED. One `ps` sample taken during a large lane fan-out caught
# several concurrent `session.py merge` processes and several concurrent
# `python3 -m unittest discover -s tests` runs on one machine; the two oldest merges had
# been running several times as long as an uncontended full suite on that same box —
# so a contended land cost a multiple of the uncontended cost of the one thing it was
# waiting for.
#
# THE PART THAT MATTERS IS THAT IT FEEDS ITSELF, and that is why "make the gate faster"
# is not the fix. Every land attempt re-runs the ENTIRE suite in a scratch worktree. N
# suites competing for the same cores makes each one slower; a slower gate widens the
# window in which a sibling can CAS the trunk first; losing the CAS forces a rebase and a
# retry; the retry starts ANOTHER full suite. Contention therefore MULTIPLIES latency
# instead of adding to it — the more lanes are landing, the longer each land takes, which
# makes collisions MORE likely rather than less. A positive feedback loop has no stable
# operating point, so the only fix is to remove the concurrency.
#
# THE CRITICAL SECTION IS rebase -> gate -> CAS, NOT THE GATE ALONE. Serializing only the
# gate does nothing: lane B rebases onto the pre-A trunk, waits its turn, gates, and then
# loses the CAS to A anyway — the same multiplication, one step further down. The lock has
# to span the window in which the trunk tip the lane built on must stay put.
#
# SCOPE IS THE REPO, NOT THE MACHINE, deliberately. The coordination store lives in the
# git COMMON dir, shared by every worktree of one repo and by nothing else, so this
# serializes every lane of one Architect. The measured storm was fifteen lanes of ONE
# repo, so that is the storm covered. A truly machine-global lock (a path under
# `~/.local/state`) would let one wedged lane in one Architect's repo block every other
# Architect on the box — trading a latency problem for an availability one, on a machine
# where the repos genuinely do not compete at this scale. Stated so nobody re-opens it as
# an oversight.
#
# WHY NOT `lease()`. `_lease_try` delegates to `_coord_try_acquire`, which reclaims a
# record `_coord_mine` judges as already ours — and `_coord_mine` matches on the ambient
# JOURNAL when the session id is shared. Dispatched lanes are exactly that case:
# `tmux new-session` hands each child the dispatcher's environment, so siblings inherit
# one `CLAUDE_CODE_SESSION_ID` and one journal, and BOTH would take the gate. That is not
# hypothetical — ten racers were once measured all drawing lane `poga-2` through the same
# hole, which is why `_lane_reserve` exists. Dispatched lanes are also precisely the
# population that storms the gate, so a lock they can walk through is no lock at all. The
# acquire below is modelled on `_lane_reserve`: exclusive create, or lose.
#
# FAIL-OPEN ON THREE INDEPENDENT PATHS, because a gate nobody can enter is worse than a
# gate two lanes enter — a stuck lock would strand every land on the machine, which is a
# far worse failure than the slow one it replaces:
#   1. No coordination dir (no git common dir) -> land unserialized, saying so.
#   2. A holder that died holding the gate -> its record expires and the next waiter
#      reclaims it; lane teardown and the dead-lane sweep also release it, because both
#      new kinds are in COORD_KINDS.
#   3. Waited past the cap -> land unserialized, saying so. The cap is the backstop for
#      the case none of the above covers: a holder that is alive but wedged.
#
# The one thing this does NOT do is fail closed. Nothing in this file does, and this is
# not the place to start.

LAND_LOCK_KIND = "land-gate"
LAND_QUEUE_KIND = "land-queue"
LAND_LOCK_NAME = "trunk"
# Poll interval while queued, how often a waiting lane re-states its position, and the
# longest it waits before landing unserialized. The cap is deliberately generous: fifteen
# lanes at ~4 minutes of serialized land each is an hour, so a cap much below this would
# fire during exactly the storm the lock exists for and put every lane back in it.
LAND_WAIT_POLL_SECONDS = 5.0
LAND_WAIT_REPORT_SECONDS = 60.0
LAND_WAIT_MAX_SECONDS = 90 * 60
# WI-0298. How often the HOLDER renews its own grip from inside the landing process, and
# how long without a renewal before an off-host holder reads as dead.
#
# The pair is what turns `LAND_LOCK_TTL_SECONDS` from a CAP ON A RUNNING LAND into a
# DEAD-HOLDER DETECTOR. Before this, the TTL was the only thing that ever freed the gate,
# so it had to be long enough for the slowest honest land (45m) — which is also how long a
# CRASHED land wedged every other lane. Now a live holder refreshes and never lapses
# however long it takes, so lapsing means something: nobody is renewing it. The heartbeat
# is far shorter than the dead-after window on purpose — several renewals must be missed
# before a holder is called dead, so one slow write can never evict a live land.
LAND_LOCK_HEARTBEAT_SECONDS = 60.0
LAND_LOCK_DEAD_AFTER_SECONDS = 10 * 60

# ── The land receipt, and the budget it is measured against (WI-0329 / ADR-0124) ────
#
# ADR-0114 D2 put validation inside the lock, so the serialized section was as long as
# the suite and the queue drained at one land per suite. Measured 2026-09-10 on the
# WI-0325 land: derive 271 s + gate 58 s inside the lock, against a merge of 0.060 s and
# a push of 1.7 s. Five lanes serialized behind that took about an hour to land ten
# minutes of work. ADR-0124 moves validation OUT of the lock; what is left inside is the
# advance and its publication, and this budget is what says whether that stayed true.
#
# WHY A RECEIPT FILE AND NOT THE TOMBSTONE. `poga-coord/land-gate/released/trunk.json` is
# one file per NAME, and the name is `trunk` — so every land overwrites the last one's
# times. "No land in the window held the lock over 30 s" is a claim about a POPULATION,
# and a surface that keeps one sample cannot answer it. The receipt is append-only, one
# line per land, and the scoreboard reads the window off it.
#
# LOCAL, NEVER TRACKED, and that is not a shortcut: a tracked receipt would be rewritten
# by every land, which is a merge hotspot on the one file every concurrent lane touches —
# the exact shape ADR-0119 D5 exists to keep off the trunk. Lands are per-machine events
# and the git common dir is per-machine state, so the receipt lives beside the
# coordination store it describes.
LAND_RECEIPTS_NAME = "land-receipts.jsonl"
# `retention-enforced-by-code`: trimmed on every append, so the file cannot grow without
# bound whatever anyone remembers to do. Comfortably longer than the scoreboard's
# 14-day window, so a trim can never eat evidence the board still needs.
LAND_RECEIPT_RETENTION_DAYS = 45
# The number FL7 is red above. the operator's ruling, 2026-09-10: "a finish-line test goes red
# whenever any land holds the lock longer than 30 seconds; lands still complete." It is a
# budget on the SERIALIZED section only — queueing and validation are outside it by
# construction now, and neither is bounded by this.
LAND_LOCK_HOLD_BUDGET_SECONDS = 30.0
# WI-0355. The push is a STEP OF THE LAND now rather than a flag, which puts the network on
# the critical path of every land — so it needs a bound, and `sh` has none.
#
# MEASURED, from this repo's own land receipts (91 receipts, 16 carrying a push stage):
# a healthy push is min 1.26s, median 1.44s, p90 2.56s. The one outlier is the fault this
# item was written around — 2026-09-12T11:38, `push 75.013s` followed by `integrate
# 75.024s`, a 151.4s lock hold on a land whose work was already on the trunk. Neither half
# of that 150 seconds bought anything: 75s is ssh's own TCP timeout on a flaky network
# route to the remote, and the integrate that followed re-paid it on a fetch that could
# not succeed either.
#
# Derived from the hold budget rather than written as a second literal, because it is the
# same constraint said once: a push still running when the time for the WHOLE serialized
# section is spent is not going to finish, and it is holding the land gate against every
# queued lane while it fails. ~12x the measured p90, so no healthy push is near it.
LAND_PUSH_TIMEOUT_SECONDS = LAND_LOCK_HOLD_BUDGET_SECONDS
# WI-0378. The push was bounded and the FETCH BESIDE IT WAS NOT, which is the same hazard
# with the same blast radius: `_integrate_trunk_with_remote`'s first act is
# `git fetch origin`, through bare `sh`, which passes no timeout. The receipt ADR-0134 D4
# was written around proves it costs exactly what an unbounded push costs — 2026-09-12T11:38
# paid `push 75.013s` AND `integrate 75.024s`, and the second 75 seconds was that fetch
# going down the same dead route to the remote to return the OFFLINE line it was always
# going to return. D5 stopped the land from BUYING that fetch on a positively-identified
# unreachable push; it did not bound the fetch, so every other path to it — the standalone
# verb, a rejected push this classifier cannot read — still hangs for as long as the kernel
# allows while holding nothing back but everyone else's land.
#
# Same derivation as the push above, for the same reason: one constraint said once. A fetch
# still running when the whole serialized section's allowance is spent is not going to
# finish. Measured healthy fetches on this repo are sub-second; this is not near them.
LAND_FETCH_TIMEOUT_SECONDS = LAND_LOCK_HOLD_BUDGET_SECONDS

# ── What a land costs the person waiting for it (WI-0349) ──────────────────────────
#
# THE BUDGET ABOVE IS ON THE LOCK, deliberately, because the lock is what OTHER lanes
# queue behind. It says nothing about how long your own land takes, and for two days
# that was the only land number anything kept: we measured the thing that protects
# everyone else and kept no number on the one operator actually feels.
#
# the operator's ruling, both halves binding: a land should finish in under a minute, AND no
# stage may be dropped to get there. So this is a GOAL, NEVER A GATE. Nothing
# reads it to refuse a land, nothing sheds a stage to get under it, and no stage is
# skipped to flatter it — a land that skips its recompile is not fast, it is
# incomplete, and the debt lands in someone else's session. An earlier proposal to let
# a breach shed optional stages was put to operator and WITHDRAWN on his correction (it
# would have made the land incomplete). Do not reintroduce stage-shedding under any
# name.
#
# THE CLOCK STARTS WHEN A LANE IS READY TO LAND AND STOPS WHEN THE WORK IS ON THE
# TRUNK. That boundary is the operator's ruling: time spent waiting to land counts as part of the
# land. Any wait — queue, freeze, retry, re-gate after a lost CAS — is INSIDE
# the number. Excluding it would park the real cost just outside the metric.
LAND_DURATION_GOAL_SECONDS = 60.0
# TRACK THE DISTRIBUTION, NOT THE WORST CASE — the opposite call from the lock budget,
# and for the opposite reason. The lock budget polices a shared resource, where one
# four-minute hold is four minutes everyone else queues and ninety-nine quick lands do
# not excuse it. This one describes an experience: the question is whether landing is
# USUALLY over a minute, not whether it was once. One slow land is noise; a median over
# a minute is the problem he described.
LAND_DURATION_RED_QUANTILE = 0.9
# ADR-0148 D7 (WI-0427) moved this from the median to the p90, over 7 days rather than
# 14: "FL7 = total_seconds p90 over the last 7 days <= 60 s, split by code/bookkeeping".
# A median hid that one land in ten took over eleven minutes; the p90 is what a person
# landing several times a day actually meets.
# The window the distribution is read over. 14 days deliberately — the same window the
# finish-line board uses (`curate/finish_line.py` WINDOW_DAYS), so the session-start line
# and the scoreboard row can never disagree about a "red week" while both being right.
# Comfortably inside LAND_RECEIPT_RETENTION_DAYS, so a trim cannot eat what this reads.
LAND_DURATION_WINDOW_DAYS = 7.0
# ADR-0148 D7: the bookkeeping-only target. Such a land runs no suite at all, so it
# has no business taking the code land's minute (acceptance 1 of WI-0427).
LAND_BOOKKEEPING_GOAL_SECONDS = 30.0


# ── The trunk lock: one writer of the trunk REF, for milliseconds (WI-0293) ─────────
#
# THE DEFECT THIS CLOSES, stated as the asymmetry it actually is. Two things advance
# `refs/heads/<trunk>` in this repo, and until now they played by different rules:
#
#   * a LAND advances it with a compare-and-swap - `update-ref <ref> <new> <old>` - which
#     is honest and can FAIL;
#   * a STORE WRITE (`poga work` / `poga ops` -> `_store_autocommit`) advances it with a
#     plain `git commit`, which takes no lock, does no CAS, and CANNOT fail.
#
# In a race the writer that cannot fail always wins, so the land is the only one that ever
# loses - and it loses AFTER paying for a full gate run. WI-0272 observed this live while
# landing ADR-0114 itself: the gate held perfectly, no sibling land ran beside it, and the
# CAS lost anyway to a `poga work` commit. That is the theft. It is not a bug in the land
# gate; the land gate serialises LANDS, and a store write is not a land.
#
# WHY NOT JUST PUT STORE WRITES BEHIND THE LAND GATE. Because it would be a worse system,
# and WI-0272 says so in its own text before recommending anything: a `poga work` write
# would then block for MINUTES behind a suite run, turning the cheapest verb in the system
# into the most expensive, and serialising a write that cannot break anything against one
# that can. The property wanted is narrower than "the trunk never moves during a land".
#
# WHAT THIS LOCK IS, THEREFORE: a second door on the same ref, held for the duration of a
# ref update and nothing else. The land takes it around its final tip-read + `update-ref`;
# the store write takes it around its own `add`/`commit`. Both holds are milliseconds. A
# `poga work` write waits for a land's SWAP, never for a land's GATE.
#
# WHAT IT DOES NOT DO, SAID PLAINLY SO NOBODY READS THE STRONGER SENTENCE. It does NOT
# stop a store write that arrives DURING the gate run from moving the trunk and costing
# that land a re-gate. Closing that needs the gate-neutral classification of ADR-0114 D7's
# exception, which is deliberately out of scope (see ADR-0116). What it closes is the
# check-then-act hole: once a land has read the tip under this lock, no store write can
# slip in before its `update-ref`, so a swap that was going to succeed cannot be stolen
# between the deciding and the doing.
#
# WHY NOT `_coord_try_acquire`, AGAIN. Same reason the land gate does not use it, and the
# reason is worth restating rather than cross-referencing because this lock has a caller
# the land gate does not: `_coord_try_acquire` reclaims a record `_coord_mine` judges as
# ours, and `_coord_mine` matches on the ambient JOURNAL. Dispatched siblings share one.
# But note the sharper case here - a lane running `session.py wi-new` directly and a land
# in that SAME lane share not just a journal but a session id, so a reclaim-if-mine lock
# would let a process walk straight through its own hold. Exclusive-create-or-lose, with
# an explicit process-local re-entrancy counter, is the only shape that is honest for both.
#
# FAIL-OPEN, on every path, because a trunk nobody can write is a repo nobody can use:
#   1. No coordination dir -> proceed unlocked, saying so.
#   2. A holder that died holding it -> a 120s TTL, short because every legitimate hold is
#      milliseconds; the next contender reclaims the corpse.
#   3. Waited past the cap -> proceed unlocked, saying so, and name the holder.
TRUNK_LOCK_KIND = "trunk-lock"
TRUNK_LOCK_NAME = "trunk"
# A legitimate hold is a `git commit` or an `update-ref` - milliseconds. The TTL is three
# orders of magnitude larger than that so a slow disk is never mistaken for a corpse, and
# still small enough that a real corpse is cleared before anyone files a bug about it.
TRUNK_LOCK_TTL_SECONDS = 120
TRUNK_LOCK_POLL_SECONDS = 0.02
# The cap is 30s rather than the land gate's 90 MINUTES, and the difference is the whole
# point of having two locks: nothing that legitimately holds this takes longer than a
# commit, so a 30s wait already means something is wrong and the honest move is to proceed
# and say so rather than to keep a `poga work` write hanging.
TRUNK_LOCK_MAX_WAIT_SECONDS = 30.0
_TRUNK_LOCK_DEPTH = 0


# ── ONE allocator, many counters (ADR-0076 D2) ───────────────────────────────────
# There were two hand-written allocators here — ADR numbers (ADR-0069, session 93) and
# WI numbers (ADR-0073, session ~101, built by "mirroring the ADR allocator exactly").
# Mirroring was defensible at the time (copy proven safety code rather than refactor it
# mid-build), but the result was two independent implementations of one three-layer
# mechanism, measured at 51% textual similarity in the land gate and 40% in the reserve
# step. The land gate IS the safety mechanism; separately-maintained copies of it drift,
# and a fix applied to one and not the other is silent. A THIRD copy — for the OPS
# counter (ADR-0076) — is where that stops being untidy and becomes the risk ADR-0069
# exists to prevent, which is why the extraction is a PREREQUISITE of the ops kind
# rather than a follow-up: once other code depends on a third copy it cannot be undone.
#
# So the mechanism is written once and the counters become DATA. Everything that differs
# between them is a field below; the mechanism — propose a candidate from the landed
# files plus sibling lane tips plus held reservations, claim it atomically against the
# reservation ledger, refuse at the land gate if it was not drawn or is contested — is
# one implementation.
#
# Two consequences beyond removing the duplication:
#   * A new counter is gated BY CONSTRUCTION. The land gate iterates the registry, so an
#     ungated namespace cannot be shipped by forgetting to wire one in — there is no step
#     to forget (`ship-the-detector-with-the-capability`).
#   * The canon claim in `numbers-are-drawn-never-picked` — that a number comes from "a
#     single allocator" — becomes true in code rather than only in spirit.
#
# The per-counter `_adr_*` / `_wi_*` functions below are kept as thin delegations rather
# than renamed: they are the surface the allocation-gate tests drive directly, so the
# existing suite exercises the extracted mechanism unchanged. That is deliberate — the
# net for a refactor of live safety code is worth more than a tidier call graph.


class _Counter:
    """One row of the counter registry: everything that differs between the ADR, WI and
    OPS sequences. `dirname` is a callable, not a string, because a member's ADR
    directory is configurable and tests repoint the module at a lane between calls —
    resolving it once at import would freeze a stale path. `basename_re` takes a callable
    for the same reason since WI-0128: the ADR FILENAME shape is configurable too, and
    the two facts have to travel together or a member declares half its arrangement."""

    def __init__(self, key, label, draw_cmd, namespace, ttl, dirname, glob,
                 basename_re, renumber_hint="", redraw_hint="", renumberer=None,
                 noun="", filename_for=None, parse_text=None, render_item=None,
                 remap_edges=None, claimed=False, hole_index=None):
        self.key = key
        self.label = label              # how the number is NAMED in a blocked-land message
        self.noun = noun or label       # how the THING is named in prose ("work-item")
        self.draw_cmd = draw_cmd        # the verb that draws one
        self.namespace = namespace      # coord-store reservation namespace
        self.ttl = ttl
        self.dirname = dirname          # () -> str, relative to ROOT
        self.glob = glob                # on-disk scan pattern
        self._basename_re = basename_re  # compiled pattern, or () -> one
        self.renumber_hint = renumber_hint  # trunk-duplicate message tail
        self.redraw_hint = redraw_hint      # held-reservation message tail
        # WI-0379: where this counter DECLARES the numbers that were drawn and never
        # spent — `() -> Path`, or None for a counter that declares none. A row-level
        # capability for the same reason `renumberer` is one: the mechanism reads the
        # declaration, so a counter that grows a hole table is defended by adding one
        # line here rather than by a branch inside the allocator and a second inside the
        # land gate. Resolved per call, never at import, because the directory it lives
        # in is configurable and the tests repoint ROOT between calls.
        self.hole_index = hole_index
        # WI-0245: the STORE SHAPE a renumber has to move, declared per row rather than
        # branched on inside the renumberer. A counter whose store answers these four is
        # renumberable by `_store_renumber_batch` with no code that knows which store it
        # is looking at; `adr` answers none of them and stays refused (see below).
        #   filename_for  id -> the on-disk name it currently carries, or None
        #   parse_text    (id, text) -> the item dict
        #   render_item   item -> its full file text
        #   remap_edges   optional: follow this store's machine-validated cross-references
        #   claimed       whether ids in this store can hold a coordination claim
        self.filename_for = filename_for
        self.parse_text = parse_text
        self.render_item = render_item
        self.remap_edges = remap_edges
        self.claimed = claimed
        # WI-0169: how this counter remaps a colliding id, or None if it cannot.
        # A ROW-LEVEL capability rather than a branch inside the land, so a counter that
        # gains a renumberer is auto-remapped by construction and one that has none still
        # refuses honestly — the same by-construction property the registry was extracted
        # for. Bound to the row here so the registry declares a CAPABILITY rather than
        # wiring up a partial at each call site.
        #
        # `wi` and `ops` have one (WI-0169, then WI-0245 — ops is the same store shape
        # with two fewer moving parts: no `blocked-by` edges and no claims, both of which
        # this row simply declines to declare). `adr` has one too since WI-0290, but NOT
        # this one: an ADR cites its own number inside its own body AND in the
        # `adr/README.md` index, a landed ADR is immutable, and it carries no fielded
        # store to parse and re-render. ADR-0120 settled the doctrine, and
        # `_adr_renumber_batch` does it as its own job, with the same contract.
        self.renumberer = (functools.partial(renumberer, self) if renumberer else None)

    @property
    def basename_re(self):
        """group(1) = the number. Resolved per access when the row supplies a callable,
        so a configurable pattern is not frozen by the registry's own caching."""
        r = self._basename_re
        return r() if callable(r) else r


_COUNTERS: dict[str, _Counter] = {}


def _counters() -> dict[str, _Counter]:
    """The counter registry, built on first use. Lazy because the WI constants are
    defined further down this file than the ADR allocator that first needs the registry;
    an import-time dict literal would forward-reference them."""
    if not _COUNTERS:
        _COUNTERS.update({c.key: c for c in (
            _Counter(
                key="adr", label="ADR", draw_cmd="session.py adr-next",
                namespace="adr-alloc", ttl=ADR_ALLOC_TTL_SECONDS,
                dirname=_adr_dir, glob="*.md", basename_re=_adr_num_re,
                # WI-0379. `adr/README.md` is the one index in this repo that already
                # states its own holes, in a section a reader is pointed at from the
                # top of the file. The allocator reads the same table the reader does,
                # so the two cannot disagree about which numbers are spent.
                hole_index=lambda: ROOT / _adr_dir() / COUNTER_HOLE_INDEX,
                # An ADR cites its own number in its body, so a renumber is not just a
                # file rename — the land message has always said so and still must.
                renumber_hint="update the file's self-references, ",
                redraw_hint="renumber, ",
                # WI-0290 / ADR-0120. Its OWN renumberer, not `_store_renumber_batch`:
                # an ADR is prose with no store hooks to declare, it names itself in
                # its body, and a landed one is never renumbered. The row still answers
                # none of the four store hooks — that is what keeps it off the store path.
                renumberer=_adr_renumber_batch,
            ),
            _Counter(
                key="wi", label="WI", draw_cmd="session.py wi-next", noun="work-item",
                namespace="wi-alloc", ttl=WI_ALLOC_TTL_SECONDS,
                dirname=lambda: WI_DIRNAME, glob="WI-*.md",
                basename_re=WI_FILENAME_RE,
                # WI-0169. Resolved at call time (`_counters()` is lazy), so the
                # renumberer may live beside the store it rewrites rather than being
                # hoisted above the registry.
                filename_for=lambda i: _wi_filename_for(i),
                parse_text=lambda i, t: _wi_parse_text(i, t),
                render_item=lambda it: _wi_render_item(it),
                remap_edges=lambda o, n: _wi_remap_edges(o, n),
                claimed=True,
                renumberer=_store_renumber_batch,
            ),
            # ADR-0076 D2's ops counter — the row this whole extraction existed to make
            # cheap. Adding it gates `ops-items/` at all three land paths with no other
            # edit anywhere, which is the by-construction property the registry buys.
            _Counter(
                key="ops", label="OPS", draw_cmd="session.py ops-next",
                noun="obligation",
                namespace="ops-alloc", ttl=OPS_ALLOC_TTL_SECONDS,
                dirname=lambda: OPS_DIRNAME, glob="OPS-*.md",
                basename_re=OPS_FILENAME_RE,
                # WI-0245. The same four store hooks as `wi`, and the two it does NOT
                # declare are the whole difference: ops items carry no `blocked-by` edge
                # (see `_ops_render_item`) and are not claimable (`_wi_claimable_items`
                # reads the WI store plus live drills — an OPS id can never hold a claim
                # record), so a renumber has two fewer things to move rather than two
                # things to skip. Declaring `remap_edges=None` and `claimed=False` is how
                # the row says that, instead of the renumberer testing `if key == "ops"`.
                filename_for=lambda i: _ops_filename_for(i),
                parse_text=lambda i, t: _ops_parse_text(i, t),
                render_item=lambda it: _ops_render_item(it),
                claimed=False,
                renumberer=_store_renumber_batch,
            ),
        )})
    return _COUNTERS


def _counter(key: str) -> _Counter:
    return _counters()[key]


def _counter_by_namespace(namespace: str) -> _Counter | None:
    """The counter row owning a coord-store reservation namespace, or None when the kind
    is not a file-backed counter (WI-0244).

    Keyed on `namespace` rather than `key` because the coordination store speaks in kinds
    (`adr-alloc`) while the registry is keyed by counter (`adr`), and the mapping between
    them is already declared once, on the row. Deriving it here rather than restating it
    means a counter whose namespace is renamed cannot go half-renamed
    ([P16](principles/master.md#p16--avoid-duplication)).

    None is a real answer, not a failure: `lane-alloc` is an allocator kind with no
    counter and no file, so trunk visibility does not describe it."""
    for c in _counters().values():
        if c.namespace == namespace:
            return c
    return None


def _counter_num_in_path(c: _Counter, path: str) -> int | None:
    """The counter's number in a git-reported path, or None. Verifies BOTH the directory
    prefix and the filename shape. The two-place check is the ADR allocator's own hard-won
    defense (see `_adr_dir`): a member's ritual once filtered a diff to `adr/` by pathspec while
    matching a pattern that assumed a different layout, so both layers went blind on one
    assumption and neither could catch the other."""
    d = c.dirname()
    if not path.startswith(f"{d}/"):
        return None
    m = c.basename_re.match(path[len(d) + 1:])
    return int(m.group(1)) if m else None


def _counter_existing_max(c: _Counter) -> int:
    """Highest number among the counter's landed files on disk; 0 if none."""
    mx = 0
    try:
        for p in (ROOT / c.dirname()).glob(c.glob):
            m = c.basename_re.match(p.name)
            if m:
                mx = max(mx, int(m.group(1)))
    except Exception:
        pass
    return mx


# ── WI-0379: a burned number is not a free one ───────────────────────────────────
# `_counter_existing_max` scans the counter's DIRECTORY, so a number that was drawn and
# then never spent leaves a hole indistinguishable from a number nobody has reached yet.
# The moment its reservation lapses out of the coordination store, the allocator's floor
# steps straight back onto it. Measured, not reasoned: ADR-0138 was drawn 2026-09-13,
# left to expire, and handed out AGAIN on 2026-09-17 to a different session four days
# later — caught only because `adr/README.md`'s own table said the number was spent and a
# person happened to read it. The holes are self-refilling, so 0072, 0083, 0086, 0121 and
# 0138 were each queued to recur.
#
# The table is the AUTHORITY (`derive-a-checks-subjects-from-the-authority`): the hole
# list is already maintained where a reader looks for it, and the allocator's floor now
# reads it rather than re-deriving "free" from a directory that cannot express "burned".
#: The `##` section of a counter's index that lists its permanently-unused numbers.
COUNTER_HOLE_SECTION = "Unused numbers"
#: The index file, inside the counter's own directory, that carries that section.
COUNTER_HOLE_INDEX = "README.md"
#: `_declared_holes` outcomes. Named rather than inferred from an empty dict, because the
#: two callers hold DIFFERENT policies on the same answer and only one of them is wrong to
#: be quiet: the fleet-shipped allocator must treat a member with no table as declaring no
#: holes, while this repo's own doc check must treat a missing table as a finding. One
#: reader, one set of distinguishable answers, two policies — the alternative is two
#: parsers of one table, which is what this repo already had
#: ([P16](principles/master.md#p16--avoid-duplication)).
HOLES_OK = "ok"                    # a section holding a table — possibly an empty one
HOLES_NO_INDEX = "no-index"        # no such file
HOLES_NO_SECTION = "no-section"    # the file is there; the section is not
HOLES_UNREADABLE = "unreadable"    # a section with no table in it at all — the reformat case


def _declared_holes(index_path: Path, heading: str = COUNTER_HOLE_SECTION,
                    text: str | None = None) -> tuple[dict[int, str], str, str]:
    """({number: when it was drawn}, problem, state) from a declared-hole table.

    The shape read is the one `adr/README.md` already carries: a `## <heading>` section
    holding a markdown table whose first cell is the number and whose second is when it
    was drawn. The third column is prose for a human and is deliberately not parsed.

    FOUR ANSWERS, NEVER TWO (`declare-what-a-check-assumes`). `state` is one of the
    `HOLES_*` constants above and `problem` is a sentence only where the caller could not
    have worked the trouble out for itself — the reformat case, where a section exists and
    holds no table at all. Folding that into "no holes" is exactly how a check goes quiet
    and keeps certifying, and the federation's own table is additionally pinned non-empty
    by a test, so losing it turns the suite red rather than the allocator silent.

    AN EMPTY TABLE IS NOT A BROKEN ONE, and the first cut of this got that wrong: it read
    "zero numbers parsed" as the reformat case, which turned a member that has the heading
    and has burned nothing yet — a real and correct state — into a check that refuses to
    run. The discriminator is whether the section contains a markdown table AT ALL: a
    header and separator with no data rows is a table saying "none", while prose with no
    pipe in it is a section whose rows went somewhere this cannot follow. Caught by the
    doc check's own fixture, which builds exactly the empty-table case.

    A section closes at the next heading of the SAME OR SHALLOWER level, never at a
    heading of any level — stopping at the first `###` inside it would silently truncate
    the table and under-report the holes, which is the direction that costs a number."""
    if text is None:
        try:
            text = index_path.read_text(encoding="utf-8")
        except Exception:
            return {}, "", HOLES_NO_INDEX
    lines = text.splitlines()
    want = heading.strip().lower()
    start = depth = None
    for i, ln in enumerate(lines):
        m = re.match(r"^(#{1,6})\s+(.*?)\s*$", ln)
        if m and m.group(2).strip().lower() == want:
            start, depth = i + 1, len(m.group(1))
            break
    if start is None:
        return {}, "", HOLES_NO_SECTION
    holes: dict[int, str] = {}
    saw_a_table = False
    for ln in lines[start:]:
        h = re.match(r"^(#{1,6})\s", ln)
        if h and len(h.group(1)) <= depth:
            break
        if ln.lstrip().startswith("|"):
            saw_a_table = True
        row = re.match(r"^\|\s*(\d{3,5})\s*\|([^|]*)\|", ln)
        if row:
            holes[int(row.group(1))] = " ".join(row.group(2).split())
    if not saw_a_table:
        return {}, (f"{index_path} declares a '{heading}' section with no table in it — "
                    f"declared holes were NOT consulted"), HOLES_UNREADABLE
    return holes, "", HOLES_OK


def _counter_holes(c: _Counter) -> tuple[dict[int, str], str, str]:
    """(holes, problem, the source that declared them) for one counter.

    ({}, "", "") for a counter that declares no hole index — `wi` and `ops` have none,
    and a store whose numbers have never been burned is not a store with an empty table.
    A read that RAISES degrades to no-holes but NAMES itself: an allocator that bricks on
    an unreadable index would be a worse defect than the one this closes, and a silent
    degrade would be the same defect wearing the fix's badge."""
    if c.hole_index is None:
        return {}, "", ""
    try:
        path = c.hole_index()
    except Exception as e:
        return {}, f"could not locate the {c.label} declared-hole index ({e})", ""
    try:
        holes, problem, _state = _declared_holes(path)
    except Exception as e:
        return {}, f"could not read {path} ({e})", str(path)
    return holes, problem, str(path)


def _skip_declared_holes(c: _Counter, n: int, holes: dict[int, str], source: str,
                         announced: set[int]) -> int:
    """The first number at or above `n` that is not a declared hole, saying so on stderr.

    REPORTED, NEVER SILENT. A skipped number is the allocator declining to hand out one
    the index says was already spent; an invisible skip would leave the next reader with
    the same ungrounded gap the table exists to explain. Announced once per draw, because
    `_counter_reserve_next` retries on a lost race and the same hole would otherwise be
    narrated on every pass through the loop."""
    while n in holes:
        if n not in announced:
            announced.add(n)
            drawn = holes[n] or "not recorded"
            print(f"{c.draw_cmd}: {c.label} {n:04d} is RESERVED — {source} declares it "
                  f"permanently unused (drawn {drawn}). A drawn number is never reused; "
                  f"skipping it.", file=sys.stderr)
        n += 1
    return n


def _tracked_paths_among(root: Path, specs: list[str]) -> list[str]:
    """Which of `specs` git actually TRACKS in `root` — the difference between "these
    paths are clean" and "git matched none of these paths", which `status --porcelain`
    reports identically (both are empty output). Empty list on any error, so a question
    git could not answer never reads as a yes."""
    r = sh(["git", "-C", str(root), "ls-files", "--", *specs], check=False)
    if r.returncode != 0:
        return []
    known = {ln.strip().strip('"') for ln in (r.stdout or "").splitlines() if ln.strip()}
    return [s for s in specs if s in known]


def _counter_reserve_next(c: _Counter, identity: str | None = None,
                          tries: int = 64) -> int | None:
    """Atomically reserve the next free number across landed files, sibling lane tips
    (R5c), AND held reservations (Rule 3 — two lanes never grab the same number). Returns
    the reserved int, or None if the coord store is unavailable (caller falls back to an
    unguarded max+1). Retries on a lost race: a sibling that took the candidate number
    just moves this reservation to the next one."""
    ident = identity or _coord_identity()
    if _coord_dir(c.namespace, create=True) is None:
        return None
    # WI-0222. ONE place, not one per verb: every counter — wi, adr, ops — draws through
    # here, which is why the guard belongs here and not in `cmd_wi_new`. The three inputs
    # below (landed files, sibling lane tips, held reservations) are all LOCAL, so a
    # checkout behind its remote under-counts every one of them and the max is a lie.
    #
    # ONLY `provably behind` refuses. CANNOT TELL proceeds, deliberately: refusing to draw
    # a number because the network is down would be a worse bug than the one this prevents,
    # and it would arrive on exactly the day someone is working offline.
    stale_root = _shared_work_root()
    behind, upstream, _why, _age = _checkout_staleness(ref=_trunk(), root=stale_root)
    if behind is not None and behind > 0:
        _refuse_stale_draw(c.label, c.draw_cmd, behind, upstream, stale_root)
    # WI-0379: the FOURTH input, and the only one that is not derived from what exists.
    # The other three answer "what is taken"; a burned number is taken and has nothing on
    # disk, in a lane tip or in the ledger to say so — its only record is the declaration.
    holes, hole_problem, hole_src = _counter_holes(c)
    if hole_problem:
        print(f"{c.draw_cmd}: WARNING — {hole_problem}.", file=sys.stderr)
    announced: set[int] = set()
    for _ in range(tries):
        reserved = {int(k) for k in _counter_alloc_holds(c) if k.isdigit()}
        n = max([_counter_existing_max(c), _counter_lane_tips_max(c),
                 _counter_trunk_max(c)] + list(reserved)) + 1
        n = _skip_declared_holes(c, n, holes, hole_src, announced)
        ok, _holder = _coord_try_acquire(c.namespace, f"{n:04d}", ident, c.ttl)
        if ok:
            return n
    return None


def _auto_renumber_collisions(tip: str, parent: str) -> tuple[str | None, list[str]]:
    """Remap every trunk-colliding number this land introduces, for each counter that
    knows how. Returns (the new tip after the remap commit, report lines).

    RUNS BEFORE THE GATE, NEVER INSTEAD OF IT. The gate keeps the final say, so a remap
    that failed to clear a collision refuses the land exactly as it did before. That
    ordering is the whole reason this is safe to run automatically: the automatic path
    can only remove refusals it has ACTUALLY fixed, and can never assert that it did.

    Only trunk duplicates are remapped. A number held by a live sibling's reservation is
    left to refuse, because that sibling may still land it — redrawing around a live
    reservation is a guess about someone else's unfinished work, while a number already
    on the trunk is a settled fact."""
    report: list[str] = []
    remapped = False
    for c in _counters().values():
        if c.renumberer is None:
            continue
        collisions = _counter_trunk_collisions(c, tip, parent)
        if not collisions:
            continue
        pairs: list[tuple[str, int]] = []
        for n, name in collisions:
            drawn = _counter_reserve_next(c)
            if drawn is None:
                # The one case that must NOT proceed: with no allocator we would be
                # picking, which is the exact thing the gate exists to prevent. Refuse
                # the remap and let the gate refuse the land, rather than inventing a
                # number to get past our own check.
                report.append(f"land:    could not DRAW a replacement {c.label} number "
                              f"for {name} — the coordination store is unreachable. "
                              f"Nothing was renumbered; picking one here is the very "
                              f"thing the gate exists to stop.")
                return None, report
            pairs.append((f"{c.label}-{n:04d}", drawn))
        report.append(f"land:    {len(pairs)} {c.label} number(s) collide with the trunk "
                      f"— remapping (numbers DRAWN, never picked):")
        mapping, rep = c.renumberer(pairs, parent)
        report += rep
        remapped = remapped or bool(mapping)
    if not remapped:
        return None, report
    newtip = sh(["git", "rev-parse", "HEAD"], check=False).stdout.strip()
    return (newtip or None), report


# ── Rule 3: ADR-number allocation (ADR-0051 C4 / partition-plan Rule 3) ──────────
# Two lanes each drafting an ADR would both compute "max in adr/ + 1" and grab the SAME
# number. `adr-next` reserves the next free number atomically in the shared coord store,
# counting BOTH the numbers already used by adr/*.md files AND live reservations, so a
# sibling lane that just reserved 0062 pushes this one to 0063. A reservation TTLs out /
# is reaped like any coord record; once the ADR file exists its number is permanently
# accounted for by the file scan, so it is never reused even after the reservation lapses.
#
# The mechanism now lives in the counter registry above; what remains here is the `adr`
# row's identity plus thin delegations that keep the tested surface stable.

_ADR_NUM_RE = re.compile(r"^(\d{4})-")


def _refuse_undrawn(label: str, draw_cmd: str, dirname: str) -> None:
    """WI-0057 option (a): REFUSE to issue a number that carries no arbitration.

    Every draw used to fall back to an unguarded `max+1` over landed files plus sibling
    lane tips and warn on **stderr** — the one channel the caller provably does not read,
    because `adr-next` deliberately puts the number on stdout and everything else on
    stderr so `N=$(session.py adr-next)` captures cleanly. A script capturing the number
    therefore never saw the warning, and in a hook context stderr is usually discarded
    outright. That is the exact shape of the session-93 five-way ADR collision the draw
    discipline exists to prevent: two lanes that both cannot reach the store both compute
    the same `max+1`, confidently.

    The item filed this as a decision needing operator, on the premise that failing closed
    trades away availability whenever "the shared volume is down". Its own correction
    withdrew that, and the code agrees: the coord store is `<git-common-dir>/poga-coord/`
    (ADR-0062) — inside the repo's own `.git`, not on the shared volume. `_coord_dir`
    returns None only when git cannot resolve the common dir or the mkdir fails, both of
    which are already-broken states in which the repo itself is unusable; and the
    allocator's other None is 64 consecutive lost races, which is not a state to paper
    over either. So the operation this denies is narrow, the state it denies it in is rare
    and already degraded, and every other verb — editing, committing, running the suite —
    keeps working. There is no availability trade left to make, so there was no question
    to ask ([`no-question-without-a-tradeoff`](habits/master.md#no-question-without-a-tradeoff)).

    Exits 3, distinct from the argparse 2, so a caller can tell "could not draw" from
    "you used it wrong". Nothing is printed on stdout: a capture must come back EMPTY
    rather than holding a number nobody arbitrated."""
    print(f"{draw_cmd}: REFUSING to issue an {label} number — the coordination store is "
          f"unreachable, so nothing can reserve this number against a concurrent lane.\n"
          f"          The old behaviour here was to hand back `{dirname}/` max+1 and warn "
          f"on stderr, which is how two lanes that both cannot reach the store both "
          f"compute the SAME number (the session-93 collision).\n"
          f"          The store is <git-common-dir>/poga-coord/ — inside this repo's own "
          f".git, not a shared volume — so this means git cannot resolve the common dir, "
          f"or it is not writable. Fix that and draw again; every other verb still works.",
          file=sys.stderr)
    sys.exit(3)


def _ref_exists(ref: str) -> bool:
    return sh(["git", "rev-parse", "--verify", "--quiet", ref], check=False).returncode == 0


# ── Work-item store (ADR-0073) ───────────────────────────────────────────────────
# A canonical, machine-readable work list — durable `WI-NNNN` ids drawn by the SAME
# discipline as ADR numbers (ADR-0069): reserved in the coord store, defended at the
# land gate, never hand-picked. ONE FILE PER ITEM under `work-items/`, deliberately
# mirroring `adr/NNNN-*.md` — not one shared growing file: two lanes each appending an
# item to a single file conflict at the git-rebase level before any land-gate logic
# ever runs (proven live while building this), exactly the class of collision the
# per-file ADR layout was already built to avoid. The coordination store stays the
# SOLE owner of claims (P13 — nothing here writes a claim record). ROADMAP.md's
# Next/Backlog sections are a rendered JOIN over this directory + live claims
# (`session.py wi-render`) — nothing parses ROADMAP prose as data anymore.

WI_DIRNAME = layout_of(CFG_RAW, "work_items")
# Filename is `WI-NNNN-slug.md` — the slug rides along for readability (`git log`,
# directory listings) exactly like `adr/NNNN-slug.md`, but the NUMBER is identity;
# the slug is regenerated from the title on every write and the stale file removed,
# so a title edit never leaves two files for one id.
WI_FILENAME_RE = re.compile(r"^WI-(\d{4})-[a-z0-9-]*\.md$")
# `DRILL-N` is admitted here so a synthetic drill item parses its title through the
# SAME function a real one does. Nothing else widens: `WI_FILENAME_RE` still gates
# what `_wi_parse` will read out of `work-items/`, so a file named `DRILL-…` in the
# tracked store is still ignored by every backlog reader.
WI_TITLE_RE = re.compile(r"^# (WI-\d{4}|DRILL-\d+): (.*)$")
WI_FIELD_RE = re.compile(
    r"^- (status|section|blocked-by|group|source|impact|migration|scope|waiting-on"
    r"|version|probed"
    r"):\s?(.*)$")
# `superseded` (session ~103, the operator's ruling: the store is one list, and nothing is ever
# removed from it — items are only marked finished) is the honest terminal state for an item absorbed into another — `done`
# would claim work that never happened, and DELETING it leaves a hole. WI-0022 was deleted
# when it was folded into WI-0012, which left a number missing from the sequence and a
# dangling `WI-0022` reference in WI-0012's own notes pointing at nothing. An id is a
# permanent handle: once drawn it always resolves.
WI_STATUSES = ("open", "in-progress", "done", "held", "superseded")
WI_TERMINAL = ("done", "superseded")
WI_SECTIONS = ("next", "backlog")
# ── impact + migration + version ─────────────────────────────────────────────────
# `impact` makes the SMALL numbers derived rather than argued about: a release's bump is
# the max impact it carries (any `feature` → minor, else patch). That moves the argument
# down to a cheap concrete question per item — "is this a fix or a feature?" — instead of
# an abstract one per release.
#
# THE BIG NUMBER IS NOT HERE, and cannot be (ADR-0081). `breaking` used to be a third
# value that derived a major, and operator removed it, ruling that a major change is one that
# fundamentally alters the system — which may break it, or may only add capabilities on top.
# Fundamental alteration is a judgment about SIGNIFICANCE, and significance is not a
# property any per-item label carries nor a thing `max()` can compute — so a major is
# declared by a human, never derived ([P15](principles/master.md#p15--code-for-mechanism-not-judgment):
# judgment does not belong in code). The old label also mismeasured our own history:
# 6.0.0 (lanes become fleet substrate) was recorded as a "thin" major because it broke
# almost nothing, when it was a whole capability arriving on top — exactly the case the
# breakage axis cannot see.
WI_IMPACTS = ("fix", "feature")
# ORTHOGONAL to impact, and the useful half of what `breaking` used to conflate: does
# shipping this force the other members to go and edit their own files? It feeds NO
# version number — it is a deployment warning, so a release can say "these repos need
# editing" and so the work is visible before the ship rather than after. The two axes
# genuinely come apart in both directions: moving a file to fix a small bug forces edits
# and is nobody's major; adding lanes fleet-wide was a major that forced almost none.
#
# Absent means "no migration required" — deliberately two states, not three. The usual
# `declare-what-a-check-assumes` objection (never fold "unknown" into "no") is aimed at
# DETECTORS reading someone else's subject; this is authored data set by the same hand
# that sets `impact`, and a mandatory third judgment on every item buys a nag nobody
# asked for. Revisit if a migration is ever missed because nobody was prompted.
WI_MIGRATION_VALUES = ("yes", "no")
# UNSET IS ITS OWN STATE, deliberately — the brief floats defaulting to `feature`, and
# that default would quietly certify what it never checked (`declare-what-a-check-assumes`):
# an unlabelled item would count toward a minor nobody classified it into, and the release
# would look computed when it was guessed. Unset instead stays empty, `wi-check` reports it,
# and the bump computation must refuse rather than assume. A default is only safe where
# being wrong is visible; here it is invisible by construction.
WI_IMPACT_UNSET = ""
# Stamped BY the release step, never by hand — the release is the single writer of the
# fact "this shipped in X" (P13). Empty means "closed but not yet released", which is a
# real and common state, not a missing value.
WI_VERSION_UNSET = ""

# ── scope (WI-0323, R4 of the 2026-09-07 consultant brief) ───────────────────────
# WHAT KIND OF WORK IS THIS? Authored at creation, and defined by the CAPABILITY being
# changed — never by the path the diff happens to touch:
#
#   * `harness`  — shared session lifecycle, coordination, bootstrap, recovery, delivery,
#                  or agent-operating infrastructure. A shared-substrate defect REPORTED
#                  FROM a product repository is still harness work; where the bug was
#                  observed says nothing about which capability it lives in.
#   * `product`  — domain behaviour, or an outcome of the member application itself.
#   * `mixed`    — materially both. Split when splitting helps planning; never split only
#                  to improve a count.
#
# WHY IT IS NOT DERIVED FROM PATHS. `curate/finish_line.py`'s `_SUBSTRATE_WORDS` is the
# existing answer to this question and it is a filename-keyword regex — it matches product
# titles containing ordinary words like "landing". WI-0287's own closing note ruled on
# exactly that: *"Do not enforce a freeze with that regex. It is fine for a trend, not for
# a gate."* So path hints may SUGGEST a value to whoever is authoring the item; they never
# set it and never gate on it ([P15](principles/master.md#p15--code-for-mechanism-not-judgment):
# the classification is a judgment, and judgment does not belong in code).
WI_SCOPES = ("harness", "product", "mixed")
# UNSET IS A VALID STORED VALUE, and this is the one place the field DIVERGES from
# `impact` on purpose. `impact` reports every unlabelled item as a problem, which is how
# it reached 366-of-367 labelled — but it could afford that nag because it arrived when
# the store was small. `scope` arrives to a store of 367 items, and `_wi_validate` is what
# the LAND GATE runs: a missing-scope problem per legacy item is 367 problems, i.e. a
# permanently red trunk until a 367-file backfill lands, and that backfill would collide
# with every item in flight.
#
# So the brief's own alternative is taken: unset is valid for items that predate the
# field, the count of unset items is SHOWN (`curate/finish_line.py`'s exit-1 evidence
# splits it out as its own bucket), and the count falls as items are touched. What keeps
# the field from staying empty forever is not a nag but `cmd_wi_new`, which REFUSES to
# mint an item without one — the authored-at-creation half of R4, enforced at the single
# moment the author has the context to answer.
#
# The invariant the brief actually asks for is that unset items stay VISIBLE and are never
# silently counted as product. A fourth enum value meaning "not classified" would satisfy
# neither half — it would read as a classification in every count that groups by scope,
# which is the `ship-the-detector-with-the-capability` failure: a not-applicable branch
# that reads as a pass does not merely miss a gap, it certifies one.
WI_SCOPE_UNSET = ""

# ── waiting-on (WI-0408, from a member's brief) ─────────────────────────────────────
# WHO IS THIS ITEM WAITING ON? An ACTOR token — `operator`, a role, whoever the answer is
# owed by — never an item id. It is the schema-legal home for the marker a member
# originally asked to put in `blocked-by`, and the reason it is a field of its own rather
# than a widened `blocked-by` is worth keeping where the next person will read it:
#
#   `blocked-by` is the store's ONE machine-validated cross-reference. `_wi_validate`
#   resolves every token in it against the store and `poga work check` exits 1 on a
#   dangling one — which is exactly why an actor token cannot live there. Loosening it to
#   admit actor-shaped tokens would buy one field at the price of making every future
#   reading of `blocked-by` ambiguous: every reader would have to classify each token
#   before it could trust it. The requesting member found this by trying it on its own
#   store and withdrew its own request. That withdrawal is the negative control on this item.
#
# The two fields therefore refuse each other's values, in both directions and on purpose:
# `blocked-by` refuses `operator` because it is not a known id, and `waiting-on` refuses
# `WI-0007` because of the shape below. Neither can silently absorb the other's meaning.
#
# UNSET IS A REAL ANSWER — "nobody is waiting on a human here" — unlike `scope`, where
# unset is a gap to close. So the line is written only when set (see `_wi_render_item`),
# 400-odd existing item files are unchanged by this field arriving, and no member edits
# anything. What unset does NOT answer is whether this member writes the marker at all;
# that question is answered once, at feed level, by `WI_FEED_WRITES_WAITING_MARKER`.
#
#: An actor token: lowercase, starts with a letter, no spaces. Deliberately not an enum —
#: the bound user differs per member, and a fleet-wide allowlist of people is a list that
#: is wrong the first time a member has a different operator.
WI_WAITING_ON_RE = re.compile(r"^[a-z][a-z0-9._-]{0,31}$")
#: The one shape that is refused with its own sentence rather than the generic one: an
#: item id in `waiting-on` is the exact confusion this field exists to prevent, so the
#: refusal names `blocked-by` instead of leaving the operator to work out where it goes.
WI_WAITING_ON_ID_RE = re.compile(r"^(?:WI|OPS|DRILL)-\d+$", re.IGNORECASE)
WI_WAITING_ON_UNSET = ""

#: WI-0408 half two, and the half that is easy to drop. Published at the TOP of the feed,
#: beside the item list: this member's harness writes the waiting marker.
#:
#: WHY A DECLARATION AND NOT AN INFERENCE. Without it, "no item in this feed names a
#: person" and "this member does not write the marker" are the same empty list, and a
#: consumer must render `cannot tell` for the whole portfolio (ADR-0101's three-state
#: rule, `declare-what-a-check-assumes`). Inferring participation from the presence of a
#: marker is worse than it looks: it reads as a fact while it is evidence, and it flips
#: back to `cannot tell` the moment a member clears its last waiting item — a pane that
#: goes blind as a side effect of good news.
#:
#: It is a CONSTANT, never derived from the item set, for that same reason: it declares
#: what the WRITER can do, not what the data happens to contain today. A feed built by
#: this code always supports the field, so the declaration is true by construction —
#: `ship-the-detector-with-the-capability`.
#:
#: The feed schema is deliberately NOT bumped (same call as `scope`, WI-0323): a consumer
#: that does not know the key ignores it, and an ABSENT declaration already reads as
#: exactly the honest answer for an older feed — "this member does not write the marker".
#: Bumping would force every consumer to re-verify against a new schema number in order
#: to learn one boolean it can read directly.
WI_FEED_WRITES_WAITING_MARKER = True


def _store_autocommit(dirname: str, names: list[str], subject: str,
                      retry_verb: str) -> None:
    """Commit exactly the named store files (WI-0056). Never `add -A`.

    Parametrised on the store DIRECTORY in WI-0125, because `ops-items/` had none of
    this. The two namespaces render in the same chart, the same startup view and the same
    feed, so ops read as a peer of work-items everywhere a user looks — and diverged at
    the one point nobody can see: a `wi` write saved itself and an `ops` write did not.
    OPS-0005 sat uncommitted in the main checkout because of it, where the next session
    would have met it as authored dirt and had to ask about it. One implementation, both
    callers ([P16](principles/master.md#p16--avoid-duplication)); `retry_verb` is the only
    other thing that differs, and it is in the message because a retry hint naming the
    wrong verb is worse than none.

    The whole defect this closes is that the store's write and the store's SAVE were
    different operations owned by different actors: `poga work` writes the file and
    reports success, and committing it was left to whoever noticed. From a lane there
    was ultimately no route at all — the runtime's worktree-isolation guard denies the
    `git -C <main>` redirect that used to stand in for mechanism — so an item could be
    written and then be uncommittable, with the tool's success message and git's view
    of the world disagreeing (hit in sessions ~107, ~109, and ~118, where it blocked a
    land outright).

    Why this can simply run git here, when a lane cannot: `poga work` cd's to the MAIN
    checkout and execs THAT copy of session.py (`require_repo work`), so this process is
    already standing in the checkout that owns the store. There is no cross-checkout
    redirect to be denied. The lane never needed a way to reach main; the tool that was
    already there needed to finish its job.

    Three safety properties, each load-bearing:

      * **Explicit pathspecs, never `-A`.** A concurrent lane may have its own store
        writes in flight in this same tree; sweeping them into our commit would attribute
        another session's work to this one.
      * **`git commit -- <paths>` rather than a bare commit.** A pathspec-limited commit
        takes the working-tree state of exactly those paths and IGNORES the rest of the
        index, so a session that has staged other things in the main checkout keeps them
        staged and uncommitted. We cannot capture what we did not write.
      * **Fail-open, and say so.** The file is already written when we get here. A git
        failure must never turn a successful store write into an error — it reports on
        stderr that the save did not happen and leaves the file for `wi-commit`.

    Skipped entirely under the test suite: `wi-new`/`wi-status` run in dozens of tests,
    and committing the operator's real repo from a test is precisely WI-0068's class."""
    if _under_test():
        return
    specs = [f"{dirname}/{n}" for n in names if n]
    if not specs:
        return
    # WI-0081: claim these paths in this session's attribution set BEFORE attempting the
    # commit. The ADR-0057 recorder only sees Write/Edit/MultiEdit/NotebookEdit tool
    # calls, and a store write is none of those — it is this function writing a file
    # directly — so every item file was invisible to attribution and `wi-commit` had no
    # way to tell its own residue from a sibling's. Recorded on the WRITE, not on the
    # commit, because the case that matters is precisely the one where the commit below
    # FAILS: that is the residue `wi-commit` exists to sweep, and it must be sweepable
    # as ours rather than as anonymous dirt.
    _record_store_write(specs)
    root = ROOT
    try:
        if sh(["git", "-C", str(root), "rev-parse", "--git-dir"],
              check=False).returncode != 0:
            return                              # not a git repo — the write still stands
        # `add` first: a pathspec-limited commit cannot match a file git has never seen,
        # so a brand-new item needs to be known before it can be committed. This also
        # records the deletion side of a title-driven rename.
        sh(["git", "-C", str(root), "add", "--", *specs], check=False)
        st = sh(["git", "-C", str(root), "status", "--porcelain", "--", *specs],
                check=False)
        if not (st.stdout or "").strip():
            # Nothing actually changed — no empty commit. The paths are already at HEAD,
            # which is the condition the reservation was being held against, so their
            # numbers are released here too.
            #
            # AN EMPTY STATUS IS NOT BY ITSELF PROOF OF THAT, which is why the release
            # asks a second question rather than reusing this one. `status --porcelain`
            # over a pathspec that matches NOTHING is also empty — a file outside this
            # root, a bad path, a git that errored — and those are the cases where the
            # file is not committed anywhere and its number is still doing real work.
            # Releasing on an unmatched pathspec would free a live number on the strength
            # of a question git declined to answer, which is the
            # [`declare-what-a-check-assumes`] collapse in its most expensive form.
            if st.returncode == 0:
                _release_committed_numbers(_tracked_paths_among(root, specs))
            return
        # WI-0293: the one step here that advances the trunk goes under the trunk lock,
        # so this write cannot land inside a concurrent land's swap.
        #
        # SCOPED TO THE COMMIT, deliberately, and not widened to the `add` above. The
        # `add` writes this repo's INDEX, which no land touches — a land moves refs and
        # syncs the main checkout's working tree, and `git commit -- <pathspec>` takes the
        # working-tree state of exactly these paths and ignores the rest of the index
        # anyway (the property the docstring above calls load-bearing). Locking it would
        # buy nothing and would widen a hold whose whole justification is that it is too
        # short to be worth queueing for.
        #
        # This is the other half of the asymmetry described on `trunk_lock`: until now
        # this line was the writer that could not fail, so it always won and the land
        # always paid. It can still not fail — it just waits its turn first, for the
        # duration of somebody's `update-ref`.
        with trunk_lock():
            c = sh(["git", "-C", str(root), "commit", "-m", subject]
                   + _grant_trailer_args(verb="note") + ["--", *specs], check=False)
        if c.returncode != 0:
            print(f"note: {dirname}/ written but NOT committed — "
                  f"{(c.stderr or c.stdout).strip()[:160]}  (retry: `{retry_verb}`)",
                  file=sys.stderr)
            return                              # NOT released — an uncommitted file is
            # invisible to every scan a sibling lane's draw makes (its own working tree,
            # the lane tips, the trunk), so its number is still doing real work. The
            # reservation is freed by the `wi-commit` retry path when the file is saved.
        # WI-0237: the commit is what ends the reservation's job, so the release rides it
        # here rather than in each of `wi-new`/`wi-status`/`wi-move`/`ops-new` — the same
        # one-hook-point argument that put the auto-commit itself in this function. A verb
        # added tomorrow cannot forget a step that is not its to remember.
        _release_committed_numbers(specs)
        # SAY SO. This used to succeed in silence, which is the whole defect: the commit
        # lands in the MAIN checkout, so a lane that goes looking for it in its own
        # `git status` finds nothing and concludes the edit was stranded. It then hands
        # the operator a git command to run by hand — for work that is already committed,
        # in a checkout that is already clean. Observed on another member and hit first-hand
        # in the federation the same day; the receipt existed and was invisible, so every
        # reader guessed, and the pessimistic guess is the one that generates a chore for
        # a human ([`a-close-is-the-banner-not-the-sentence`] — a ritual with no visible
        # receipt is indistinguishable from one that never ran).
        head = sh(["git", "-C", str(root), "rev-parse", "--short", "HEAD"],
                  check=False).stdout.strip() or "(unknown)"
        # WHERE it committed is a FACT to read, not a constant to assert. This message
        # used to state "it lives in the main checkout" unconditionally — true on the
        # `poga work` path (which anchors on the main checkout by design) and false
        # whenever `session.py` drives the store from inside a lane, where `root` IS this
        # tree. Cutting 7.0.0 from a lane printed it 26 times, each naming the lane path
        # in the same breath as the claim that the commit was somewhere else. A receipt
        # that misreports its own location is worse than a silent one: it tells the reader
        # not to look in the only place the commit actually is.
        #
        print(f"committed {head} in {root} — the store is SAVED. "
              f"{_wi_receipt_where(root, _main_checkout(root))}")
    except Exception as e:
        print(f"note: {dirname}/ written but NOT committed ({type(e).__name__}) — "
              f"retry with `{retry_verb}`.", file=sys.stderr)


# ── WI-0181: an append-only note is a RECORD, never a longer string ─────────────────
#
# THE COLLISION, and why it is not a disagreement. Two machines each appended a paragraph
# to the same item's notes field. Neither edited what the other wrote; both simply added at
# the end of one growing string, with an empty common base for the added region — so git
# had no way to order two appends and produced a conflict with no mechanical answer. That
# stopped a trunk reconcile dead and is what WI-0153/ADR-0102 was chasing when it was found.
#
# ADR-0102 made that class RESOLVABLE. This makes it IMPOSSIBLE, which is the better fix and
# the one the shape actually calls for: a field that is append-only BY CONSTRUCTION should
# not be a merge hotspot at all. One note per FILE, named with the same
# `<utc-compact>-<machine>-<rand>` durable id the session journals use — collision-free
# across machines by construction, and filename order IS time order. Two machines appending
# then produce two DIFFERENT files, which git takes as two adds. The conflict is not
# resolved; it never occurs.
#
# ONE IMPLEMENTATION, BOTH STORES ([P16](principles/master.md#p16--avoid-duplication)), for
# the reason `_store_autocommit` was parametrised the same way in WI-0125: `ops-items/` has
# the identical shape and would otherwise be the identical bug found again later. THREE
# append sites existed — `wi-edit --append-notes`, `ops-edit --append-notes`, and
# `ops-ran --notes`, which appends a run receipt and is the most purely append-only of them.
#
# NOTHING IS MIGRATED, deliberately. An item's existing notes stay in its file as the
# authored BODY; records are the append log, and a reader sees body-then-records compiled in
# order. That keeps every existing file byte-identical, needs no migration step to go wrong,
# and is a truer model anyway: the body is the description, the records are what happened.
# The invariant that makes it safe is that `_wi_render_item` writes the BODY and never the
# compiled view — writing the compiled view back would duplicate every record into the file
# and rebuild the very hotspot this removes. That one is pinned by its own test.

NOTES_DIRNAME = "notes"
# A note is one paragraph, not a document. Bounded so a runaway caller cannot write an
# unbounded file into the store ([P19](principles/master.md#p19--cap-what-can-run-away)).
NOTE_MAX_CHARS = 20000


def _notes_dir(store: str, item_id: str, base: Path | None = None,
               create: bool = False) -> Path:
    """`<store>/notes/<ID>/` — one directory per item, holding its immutable note records."""
    d = (base or ROOT) / store / NOTES_DIRNAME / item_id
    if create:
        with contextlib.suppress(Exception):
            d.mkdir(parents=True, exist_ok=True)
    return d


def _note_id(machine: str, now: datetime, rand: str | None = None) -> str:
    """`<utc-compact-to-the-microsecond>-<machine>-<rand>` — one note record's filename.

    THE SAME SHAPE as `durable_session_id` and deliberately NOT the same function, which is
    the opposite of the usual call. A journal id is minute-granular, and that is right for
    journals: one session per machine per minute is already generous. For notes it is
    wrong, and wrong in a way that looks fine — two notes appended in the same minute sort
    by their RANDOM suffix, so the log renders out of order roughly half the time. Caught
    by the ordering test, not by review.

    Microseconds make filename order equal time order, which is what lets the reader sort
    with no field inside the record to trust or keep in sync. Across machines that ordering
    is only as good as their clocks — stated because it is a real limit, and an acceptable
    one: two notes on two machines within microseconds of each other have no meaningful
    order to get wrong."""
    ts = now.astimezone(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    mach = re.sub(r"[^a-z0-9]+", "", machine.lower()) or "unknown"
    return f"{ts}-{mach}-{rand if rand is not None else secrets.token_hex(2)}"


def _note_write(store: str, item_id: str, text: str) -> str | None:
    """Write one note record for `item_id`. Returns the store-relative name. NO commit.

    Split out of `_note_append` for the BATCH case (WI-0169's renumber writes a
    provenance record onto every item it moves): committing per note would turn one
    remap of nine items into nine commits in the middle of a land. `_note_append` is
    this plus the commit, so there is still exactly one implementation of what a note
    record IS ([P16](principles/master.md#p16--avoid-duplication)).

    NEVER touches the item file — that is the entire point. An append that rewrites the
    item file is an append that can conflict with another machine's append.

    Fail-open like every other store write: a note that cannot be written reports and
    returns None; it must not turn the verb that carried it into an error."""
    body = (text or "").strip()
    if not body:
        return None
    if len(body) > NOTE_MAX_CHARS:
        body = body[:NOTE_MAX_CHARS].rstrip() + "\n\n[truncated]"
    try:
        machine = detect_machine() if CFG else ""
    except Exception:
        machine = ""
    d = _notes_dir(store, item_id, create=True)
    p = None
    for _ in range(8):
        cand = d / f"{_note_id(machine or 'unknown', datetime.now(timezone.utc))}.md"
        if not cand.exists():
            p = cand
            break
    if p is None:
        print(f"note: could not allocate a note id for {item_id} — nothing written.",
              file=sys.stderr)
        return None
    try:
        atomic_write(p, body.rstrip() + "\n")
    except Exception as e:
        print(f"note: could not write the note for {item_id} ({type(e).__name__}).",
              file=sys.stderr)
        return None
    return f"{NOTES_DIRNAME}/{item_id}/{p.name}"


def _note_append(store: str, item_id: str, text: str, retry_verb: str) -> str | None:
    """Write one note record AND commit it — the single-note path every verb uses."""
    rel = _note_write(store, item_id, text)
    if rel:
        _store_autocommit(store, [rel],
                          f"chore({store}): note on {item_id}", retry_verb)
    return rel


def _notes_records(store: str, item_id: str, base: Path | None = None) -> list[str]:
    """Every note record for `item_id`, OLDEST FIRST. Never raises.

    Filename order is time order by construction — the id leads with a UTC compact stamp —
    so no field inside the record has to be trusted, or kept in sync, to sort them."""
    out: list[str] = []
    try:
        for p in sorted(_notes_dir(store, item_id, base).glob("*.md")):
            with contextlib.suppress(Exception):
                t = p.read_text(encoding="utf-8").strip()
                if t:
                    out.append(t)
    except Exception:
        pass
    return out


# ── WI-0169: a colliding number is REMAPPED, never handed back as an errand ─────────
#
# THE GATE IS RIGHT AND IS NOT SOFTENED HERE. A number drawn inside a lane cannot see
# what a peer lands between the draw and the land, so the counter gate catching the
# collision at the land is the design working, not failing. What was missing was the
# REMEDY: the gate named `wi-next`, which hands you a number and leaves the rename, the
# H1, the notes directory, the claim record, the `blocked-by` edges and every citation
# to you by hand. Done three times, most expensively in session ~174, where nine
# colliding ids cost nine sequential land attempts and a script written for the occasion.
#
# WHY IT IS AUTOMATIC RATHER THAN A VERB YOU RUN. A fix that ends in "and then run X"
# leaves X as the remaining defect. The land has everything it needs at the moment it
# refuses — the colliding set, the trunk tip, a working tree that matches the tip, and an
# allocator — so the refusal was never a lack of information, only a lack of nerve. It is
# not silent: every rename, every rewritten citation and every deliberate non-rewrite is
# printed, and `--no-renumber` restores the refusal for anyone who wants to look first.
#
# WHAT MOVES, and why each one is load-bearing rather than tidy:
#   * the file and its H1  — the H1 is the ONLY place the id appears inside the file, and
#     `_wi_parse_text` reads the title from it.
#   * `work-items/notes/<ID>/` — 52 directories and 68 records exist today. Notes left
#     behind do not error; they vanish from the compiled view, which is worse.
#   * `blocked-by:` edges in other items — the only MACHINE-VALIDATED cross-reference in
#     the store. Miss it and `wi-check` goes red on a store the renumber just "fixed".
#   * the coordination claim record — claims are keyed by WI id (`claims/WI-0169.json`),
#     so a renumber without it orphans the claim and the item reads unclaimed to every
#     sibling lane while someone is actively working it.
#   * the old number's reservation — released only if it is OURS, so a renumber can never
#     free the number a different lane is still holding.
#   * a provenance record — without it a reader arriving from a journal that cites the old
#     number lands on a DIFFERENT REAL ITEM and has no way to tell.
#
# THE CITATION RULE, which is the part that has to be got right rather than merely done.
# After a remap the old number still names a real item on the trunk, so a blanket
# find-and-replace is wrong in BOTH directions: it repoints citations that were already
# correct, and it confidently rewrites references to the trunk's item. WI-0190 names the
# mechanical separator and this uses exactly it — a citation on a line THIS LANE ADDED
# relative to the trunk means the lane's numbering; a line that already existed on the
# trunk means the trunk's item and is not touched. Line-level, not file-level: a lane that
# appended one paragraph to an old item must not have that item's existing prose rewritten
# underneath it.
#
# IMMUTABLE HISTORY IS REPORTED, NEVER REWRITTEN. Journals, the compiled handoff, release
# records and audits are record rather than guidance; the provenance note is what lets a
# reader arriving from them resolve the number. They are counted and named in the output
# so the operator sees what was deliberately left alone rather than assuming it was missed.

RENUMBER_NOTE = (
    "RENUMBERED {old} -> {new} at the land on {when}. This item was FILED as {old}. "
    "{old} names a DIFFERENT item on the trunk — so any text written before this line "
    "that cites {old} and means this work means {new}. The remap happened because two "
    "lanes drew {old} independently: a number drawn inside a lane cannot see what a peer "
    "lands between the draw and the land, which is why the collision surfaces at the land."
)

# WI-0307. The body of the tombstone left at a number a renumber VACATES. Its wording is
# lifted from the three written by hand in session ~241 (WI-0018, WI-0047, WI-0269) so the
# generated ones and the hand-repaired ones read as the same artifact — a reader arriving
# at a dead number should not have to work out which era produced the file.
#
# It exists because an id is a permanent handle: other items' `blocked-by` edges cite it,
# commits cite it, journals cite it. A number whose file is simply gone turns every one of
# those into a dangling reference, which is what `_wi_missing_numbers` refuses and what
# refused the trunk after the session ~241 land.
RENUMBER_TOMBSTONE = (
    "SUPERSEDED BY {new} at the land on {when}. This id was not abandoned and no work was "
    "dropped -- the item MOVED to {new}, and this file exists so {old} still resolves "
    "rather than reading as a deletion. An id is never deleted, which is what `wi-check` "
    "enforces.\n\n"
    "Read {new} for the item, its status and its acceptance criteria. Anything written "
    "before this line that cites {old} and means this work means {new}."
)

# Record, not guidance — see the citation rule above. Counted and named, never rewritten.
# Store-neutral on purpose: a journal citing an old OPS number is record for exactly the
# same reason a journal citing an old WI number is.
RENUMBER_HISTORY = ("sessions/", "session-handoff.md", "session-handoff-archive/",
                    "releases/", "audits/")


def _remap_citations(mapping: dict[str, str],
                     parent: str) -> tuple[list[str], list[str]]:
    """Rewrite citations of the remapped ids on lines this lane authored. See the block
    comment above for why this is line-scoped rather than a tree-wide replace.

    Returns (repo-relative paths changed, report lines)."""
    changed: list[str] = []
    report: list[str] = []
    if not mapping:
        return changed, report
    r = sh(["git", "diff", "--name-only", parent, "--"], check=False)
    if r.returncode != 0:
        report.append("           citations: could not diff against the trunk — NONE were "
                      "rewritten and none were checked.")
        return changed, report
    pat = re.compile("|".join(re.escape(k) for k in sorted(mapping, reverse=True)))
    history: list[str] = []
    rewritten = 0
    for rel in sorted(set((r.stdout or "").split())):
        p = ROOT / rel
        if not p.is_file():
            continue                                   # deleted by the rename — nothing to do
        try:
            text = p.read_text(encoding="utf-8")
        except Exception:
            continue                                   # binary or unreadable — never guess
        if not pat.search(text):
            continue
        if rel.startswith(RENUMBER_HISTORY):
            history.append(rel)
            continue
        added = _lane_added_lines(parent, rel)
        if added is None:
            report.append(f"           citations: {rel} cites a remapped id but its diff "
                          f"was unreadable — LEFT ALONE, check it by hand.")
            continue
        lines = text.splitlines(keepends=True)
        hits = 0
        for i, line in enumerate(lines, 1):
            if i in added and pat.search(line):
                lines[i - 1] = pat.sub(lambda m: mapping[m.group(0)], line)
                hits += 1
        if hits:
            try:
                atomic_write(p, "".join(lines))
            except Exception:
                report.append(f"           citations: could not rewrite {rel} — left alone.")
                continue
            changed.append(rel)
            rewritten += hits
            report.append(f"           citations: {rel} — {hits} line(s) rewritten "
                          f"(lane-authored)")
    if rewritten:
        report.append(f"           citations: {rewritten} line(s) across "
                      f"{len(changed)} file(s) followed the remap.")
    if history:
        report.append(f"           citations: {len(history)} history file(s) cite an old "
                      f"number and were deliberately NOT rewritten "
                      f"({', '.join(history[:4])}"
                      f"{', …' if len(history) > 4 else ''}) — they are record, not "
                      f"guidance, and each item now carries a provenance note that "
                      f"resolves the old number.")
    return changed, report


def _store_renumber_one(c: _Counter, old_id: str, new_id: str,
                        parent: str | None = None) -> tuple[list[str], list[str]]:
    """Move ONE item's whole identity, for any counter whose row declares its store
    shape. Returns (repo-relative paths changed, report).

    WI-0245 generalised this off the WI store. Nothing below asks which store it is
    holding: the file, the H1 and the notes directory are the same three artifacts in
    both, and the two that differ — `blocked-by` edges and the coordination claim — are
    row-declared hooks that `ops` simply does not supply. That is the point. A branch on
    `c.key` would have put the knowledge of which stores have claims inside the
    renumberer, where the next store to be added cannot see it."""
    changed: list[str] = []
    report: list[str] = []
    dirname = c.dirname()
    old_name = c.filename_for(old_id)
    if not old_name:
        return [], [f"           {old_id}: no file in {dirname}/ — nothing renumbered."]
    if c.filename_for(new_id):
        return [], [f"           {old_id}: {new_id} already has a file — refusing to "
                    f"renumber onto a live id."]
    d = ROOT / dirname
    try:
        item = c.parse_text(old_id, (d / old_name).read_text(encoding="utf-8"))
    except Exception as e:
        return [], [f"           {old_id}: could not read its file ({type(e).__name__}) "
                    f"— nothing renumbered."]
    old_title = item.get("title") or old_id
    tomb = dict(item)                       # captured BEFORE the id is rewritten
    item["id"] = new_id
    new_name = f"{new_id}-{_wi_slug(item['title'])}.md"
    atomic_write(d / new_name, c.render_item(item))
    (d / old_name).unlink(missing_ok=True)
    changed += [f"{dirname}/{new_name}", f"{dirname}/{old_name}"]
    report.append(f"           {old_id} -> {new_id}   {old_name} -> {new_name}")
    # WI-0307 — AN ID IS NEVER DELETED. The unlink above used to be the end of it, and
    # that is how WI-0018, WI-0047 and WI-0269 left the store entirely.
    #
    # ONLY WHEN THE NUMBER IS ACTUALLY VACATED, which is the half that is easy to get
    # backwards, and it takes TWO questions rather than one.
    #
    # `filename_for` is re-read AFTER the unlink, so the first question is precisely
    # "would this id now resolve to nothing here?" rather than anything inferred about
    # why we are here.
    #
    # THE TRUNK IS THE SECOND QUESTION, and it is a SUPPRESSOR. In a genuine collision
    # the trunk's own item is still sitting on this number — that is why the land
    # renumbered at all — so a tombstone would put a second file on it and re-create the
    # collision the remap had just resolved. The lane's working tree cannot answer that
    # on its own before a rebase, because a lane that branched earlier simply never had
    # the trunk's file; asking the trunk directly is what makes the answer the same on
    # both sides of the rebase.
    #
    # This is only SAFE because of part two of WI-0307. Suppressing on "the trunk holds
    # this number" would have suppressed the session ~241 tombstones too — those were
    # classified as trunk collisions, wrongly, because a retitle regenerates a filename.
    # A retitle no longer reaches this function at all (`_counter_retitled`), so every
    # renumber that still gets here with the trunk holding the number is a real
    # collision, where the id keeps resolving without our help.
    trunk_holds = False
    if parent:
        counts = _counter_file_counts(c, parent)
        # None (unreadable ref) must not read as "the trunk does not have it" — that is
        # the direction that writes a colliding tombstone. Unknown suppresses.
        trunk_holds = counts is None or counts.get(int(old_id.split("-")[-1]), 0) > 0
    if c.filename_for(old_id) is None and not trunk_holds:
        when = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        tomb.update({
            "id": old_id,
            "title": f"{old_title} (superseded by {new_id})",
            "status": "superseded",
            "notes_body": RENUMBER_TOMBSTONE.format(old=old_id, new=new_id, when=when),
            "notes": "",
        })
        # A tombstone is not queued work and blocks nothing; the live item at the new
        # number carries the edges. Each key is set only where the store HAS it, so the
        # renumberer stays store-neutral (WI-0245) rather than learning the WI schema.
        for key, blank in (("section", "backlog"), ("blocked_by", []), ("group", ""),
                           ("cadence", ""), ("last_completed", ""), ("due", ""),
                           ("version", "")):
            if key in tomb:
                tomb[key] = blank
        atomic_write(d / old_name, c.render_item(tomb))
        report.append(f"             tombstone left at {old_id} — the id still "
                      f"resolves, and points at {new_id}.")
    # The notes directory travels with the id, or the records silently leave the view.
    # Both stores keep theirs under `<store>/notes/<ID>/` (WI-0181), so this is one code
    # path rather than two that have to agree.
    old_notes = _notes_dir(dirname, old_id)
    new_notes = _notes_dir(dirname, new_id)
    if old_notes.is_dir():
        moved = 0
        with contextlib.suppress(Exception):
            new_notes.mkdir(parents=True, exist_ok=True)
        for p in sorted(old_notes.glob("*.md")):
            try:
                p.replace(new_notes / p.name)
            except Exception:
                continue
            changed += [f"{dirname}/{NOTES_DIRNAME}/{new_id}/{p.name}",
                        f"{dirname}/{NOTES_DIRNAME}/{old_id}/{p.name}"]
            moved += 1
        with contextlib.suppress(Exception):
            old_notes.rmdir()
        if moved:
            report.append(f"             {moved} note record(s) moved "
                          f"{NOTES_DIRNAME}/{old_id}/ -> {NOTES_DIRNAME}/{new_id}/")
    if c.remap_edges:
        ch, rep = c.remap_edges(old_id, new_id)
        changed += ch
        report += rep
    identity = _coord_identity()
    # The claim follows the id, or the item reads unclaimed while someone is working it.
    # Guarded by the ROW rather than by a try/except: a store with no claims must not
    # merely survive this block, it must be seen not to need it.
    if c.claimed:
        held = _coord_list("claims", include_expired=True).get(old_id)
        if held:
            if _coord_mine(held, identity, _coord_my_journal()):
                _coord_try_acquire("claims", new_id, identity, CLAIM_TTL_SECONDS,
                                   title=held.get("title", "") or item.get("title", ""))
                _coord_release("claims", old_id, identity, reason="renumbered")
                report.append(f"             claim moved claims/{old_id} -> "
                              f"claims/{new_id}")
            else:
                who = held.get("branch") or held.get("session_id", "?")
                report.append(f"             claims/{old_id} is held by {who} — LEFT "
                              f"ALONE (a renumber never touches another lane's claim).")
    # Release our hold on the number we are giving up. Never forced: if the record is not
    # ours, the number belongs to whoever drew it and this must not free it.
    num = old_id.split("-", 1)[1] if "-" in old_id else ""
    if num and _coord_release(c.namespace, num, identity, reason="renumbered"):
        report.append(f"             released this lane's reservation on "
                      f"{c.namespace}/{num}")
    return changed, report


def _renumber_commit(paths: list[str], subject: str) -> str | None:
    """Commit exactly `paths` (repo-relative) in ROOT; the short sha, or None.

    The same three safety properties as `_store_autocommit` — explicit pathspecs never
    `add -A`, a pathspec-limited commit so another session's staged work stays staged,
    and fail-open with a note rather than turning a completed rewrite into an error — but
    over the WHOLE tree rather than one store directory, because a renumber reaches
    outside `work-items/`: an ADR header, a test fixture and a proposal can each carry a
    citation the remap just rewrote."""
    if _under_test():
        return None
    specs = sorted({p for p in paths if p})
    if not specs:
        return None
    _record_store_write(specs)
    try:
        if sh(["git", "-C", str(ROOT), "rev-parse", "--git-dir"],
              check=False).returncode != 0:
            return None
        sh(["git", "-C", str(ROOT), "add", "--", *specs], check=False)
        if not sh(["git", "-C", str(ROOT), "status", "--porcelain", "--", *specs],
                  check=False).stdout.strip():
            return None
        c = sh(["git", "-C", str(ROOT), "commit", "-m", subject, "--", *specs],
               check=False)
        if c.returncode != 0:
            print(f"note: the renumber is written but NOT committed — "
                  f"{(c.stderr or c.stdout).strip()[:160]}", file=sys.stderr)
            return None
        return (sh(["git", "-C", str(ROOT), "rev-parse", "--short", "HEAD"],
                   check=False).stdout.strip() or "(unknown)")
    except Exception as e:
        print(f"note: the renumber is written but NOT committed "
              f"({type(e).__name__}).", file=sys.stderr)
        return None


def _store_renumber_batch(c: _Counter, pairs: list[tuple[str, int]],
                          parent: str | None = None,
                          commit: bool = True) -> tuple[dict[str, str], list[str]]:
    """Remap every `(old_id, new_number)` as ONE operation. Returns (mapping, report).

    Bound to its row by `_Counter.__init__`, so callers reach it as
    `c.renumberer(pairs, parent)` and a row without one is `None` — the refusal stays a
    property of the registry rather than a check anyone has to remember to write.

    One operation is the point: nine items remapped one verb-call at a time is nine
    commits and nine chances to stop halfway, and a half-applied renumber is strictly
    worse than none — it leaves the store in a state no reader can interpret."""
    mapping: dict[str, str] = {}
    changed: list[str] = []
    report: list[str] = []
    renamed: list[tuple[str, str]] = []
    dirname = c.dirname()
    for old_id, new_num in pairs:
        new_id = f"{c.label}-{new_num:04d}"
        ch, rep = _store_renumber_one(c, old_id, new_id, parent)
        report += rep
        if not ch:
            continue
        mapping[old_id] = new_id
        changed += ch
        renamed.append((old_id, new_id))
    if not mapping:
        return mapping, report
    # The citation pass is store-neutral and deliberately runs over the WHOLE tree: a
    # remapped OPS number is cited from work items, ADRs and ROADMAP.md exactly as a WI
    # number is, and scoping it to one store directory would follow half the citations.
    if parent:
        ch, rep = _remap_citations(mapping, parent)
        changed += ch
        report += rep
    else:
        report.append("           citations: no trunk ref to compare against, so they "
                      "were LEFT — not checked, and not silently assumed clean.")
    # Provenance LAST, deliberately. The record names the OLD id and the citation pass
    # rewrites old ids on every line this lane authored — a record written before that
    # pass would rewrite itself into "RENUMBERED WI-0250 -> WI-0250" and destroy the one
    # artifact whose entire job is to survive the renumber.
    when = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    for old_id, new_id in renamed:
        rel = _note_write(dirname, new_id,
                          RENUMBER_NOTE.format(old=old_id, new=new_id, when=when))
        if rel:
            changed.append(f"{dirname}/{rel}")
    report.append(f"           provenance: {len(renamed)} item(s) now record what they "
                  f"were filed as.")
    _wi_feed_write()          # WI and OPS rows are both rows in the one feed
    if commit:
        sha = _renumber_commit(
            changed,
            f"fix({dirname}): renumber "
            + ", ".join(f"{o}->{n}" for o, n in renamed)[:120])
        if sha:
            report.append(f"           committed {sha} — the remap is SAVED.")
    return mapping, report


def _counter_holds_id(c: _Counter, iid: str) -> bool:
    """Whether `iid` has a file under its counter. Through the row's `filename_for` when
    it declares one; otherwise by the row's own filename pattern (WI-0290: the `adr` row
    declares no store hooks, and must not be given one just to answer this)."""
    if c.filename_for:
        return bool(c.filename_for(iid))
    try:
        n = int(iid.rsplit("-", 1)[-1])
    except ValueError:
        return False
    try:
        for p in (ROOT / c.dirname()).glob(c.glob):
            m = c.basename_re.match(p.name)
            if m and int(m.group(1)) == n:
                return True
    except Exception:
        pass
    return False


def _cmd_store_renumber(c: _Counter, args: argparse.Namespace) -> None:
    """Renumber colliding items in one counter's store — the verb behind the land's
    automatic remap, for any row that declares a renumberer.

    Normally you never type this: a land remaps its own collisions and says what it did.
    It exists for the case the land cannot serve — inspecting a remap before taking it
    (`--dry-run`), repairing a lane that was landed with `--no-renumber`, or moving a
    specific id on purpose.

    WI-0245 lifted this off `wi-renumber` unchanged in behaviour. The refusal for a row
    with no renumberer is stated HERE rather than left to an AttributeError, because the
    honest answer for such a row is a sentence about why, not a traceback. (`adr` was
    that row until WI-0290 gave it its own renumberer.)"""
    verb = f"{c.key}-renumber"
    if c.renumberer is None:
        print(f"{verb}: the {c.label} counter has no renumberer — its numbers must be "
              f"redrawn with `{c.draw_cmd}` by hand ({c.renumber_hint}then re-land).")
        sys.exit(2)
    parent = _trunk_tip()
    if not parent:
        print(f"{verb}: cannot resolve the trunk tip — nothing to compare against.")
        sys.exit(1)
    pairs: list[tuple[str, int]] = []
    if args.all:
        tip = sh(["git", "rev-parse", "HEAD"], check=False).stdout.strip()
        if not tip:
            print(f"{verb}: cannot resolve HEAD.")
            sys.exit(1)
        collisions = _counter_trunk_collisions(c, tip, parent)
        if not collisions:
            print(f"{verb}: no {c.label} number this branch adds collides with the "
                  f"trunk — nothing to do.")
            return
        ids = [f"{c.label}-{n:04d}" for n, _name in collisions]
    else:
        ids = []
        for raw in args.ids:
            for part in raw.replace(",", " ").split():
                ids.append(part if part.upper().startswith(f"{c.label}-")
                           else f"{c.label}-{int(part):04d}")
        if not ids:
            print(f"{verb}: name at least one id, or pass --all.")
            sys.exit(2)
    # Refuse the whole batch on an unknown id rather than half-applying it — the same
    # all-or-nothing precondition `wi-move` uses, and for a stronger reason here: a
    # half-finished renumber leaves the store in a state no reader can interpret.
    missing = [i for i in ids if not _counter_holds_id(c, i)]
    if missing:
        print(f"{verb}: unknown id(s): {', '.join(missing)} — nothing changed.")
        sys.exit(1)
    if args.dry_run:
        print(f"--- {verb} (dry-run) --- would draw a new number for "
              f"{len(ids)} item(s): {', '.join(ids)}")
        print("            (a dry run draws nothing — the numbers are allocated only "
              "when the remap actually runs.)")
        return
    for iid in ids:
        drawn = _counter_reserve_next(c)
        if drawn is None:
            _refuse_undrawn(c.noun, verb, c.dirname())
        pairs.append((iid, drawn))
    mapping, report = c.renumberer(pairs, parent)
    for line in report:
        print(line)
    if not mapping:
        print(f"{verb}: nothing was renumbered.")
        sys.exit(1)
    print(f"{verb}: {len(mapping)} item(s) remapped — "
          + ", ".join(f"{o}->{n}" for o, n in mapping.items()))


# ── staleness of an item's own notes (WI-0095) ───────────────────────────────────

# A backticked code symbol in an item's notes: `_stamp_status`, `wi-render`,
# `cmd_release`. The backticks are load-bearing — they are what the author used to
# mark "this is a thing in the code", and prose has no shortage of English words that
# would otherwise resolve to nothing and be reported as deleted.
WI_CITED_SYMBOL_RE = re.compile(r"`([A-Za-z_][A-Za-z0-9_]{3,})`")
# The idiom this store actually uses. Measured before designing for it: 53 backticked
# hyphenated tokens across the live items, against 115 python-style ones of which most
# were English words. Notes cite the CLI (`wi-render`, `reap-lanes`, `adr-next`), so a
# symbol-only reader was nearly inert on the very store it was built for.
#
# Habit and principle names share the shape exactly (`declare-what-a-check-assumes`),
# and the `cmd_` prefix is what separates them without a hand-kept exclusion list: a
# verb resolves because `cmd_wi_render` is a real definition, and a habit name does not
# because `cmd_declare_what_a_check_assumes` is not.
WI_CITED_VERB_RE = re.compile(r"`([a-z][a-z0-9]*(?:-[a-z0-9]+)+)`")
WI_STALE_SYMBOL_CAP = 12      # P19: bound the git work per item, not per repo
WI_STALE_ITEM_CAP = 200

# ── the other three premise classes (WI-0308) ────────────────────────────────────
# Code citations were only ever ONE of the load-bearing premises in an item body, and
# session 241 measured which ones actually rot: of eighteen items re-probed by hand, four
# changed answer, and not one of the four was a code citation. WI-0296 was already fixed
# by another item; WI-0286's quoted count was 4 of 6, not 3; WI-0217 named a blocker that
# had been renumbered out from under it. Those are cited items, quoted counts and blocker
# status — the three the symbol probe is structurally blind to, plus cited ADRs, which
# carry a decision an item is premised on and flip status without touching the item.
#
# NO BACKTICKS REQUIRED, unlike the symbol patterns above, and that is not an oversight:
# `ADR-0021` and `WI-0217` are unambiguous by shape, so there is no English-word trap for
# the backticks to protect against, and the store writes them bare far more often than
# not. Measured over the live store (310 item files + 178 note dirs): 689 ADR citations
# across 98 distinct ADRs, 1646 WI citations across 266 distinct ids, 24 OPS citations.
WI_CITED_ADR_RE = re.compile(r"\bADR-(\d{3,4})\b")
WI_CITED_ID_RE = re.compile(r"\b((?:WI|OPS)-\d{3,4})\b")
# A QUOTED MEASUREMENT — "84 of 104", "three of six". Deliberately this shape and no
# other. The generic "<number> <word>" shape was measured first and is unusable: 2322
# occurrences across the same corpus, 1855 distinct, overwhelmingly dates, id fragments
# and design parameters ("3 attempts", "14 days"). The ratio shape is 37 occurrences —
# roughly one per thirteen items — and is the shape an author reaches for precisely when
# they are quoting something they counted, which is the premise that goes stale.
_WI_NUMWORD = ("one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|"
               "thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty")
WI_QUOTED_COUNT_RE = re.compile(
    rf"\b(?:\d+|{_WI_NUMWORD})\s+(?:of|out of)\s+(?:\d+|{_WI_NUMWORD})\b", re.I)
# How many quoted measurements to name per item. There is no AGE threshold here, and the
# absence is deliberate — a 30-day gate was written first and measured before shipping:
# the oldest watermark among the 78 live items was 4.0 days, because a bulk triage sweep
# rewrites every item's notes at once and resets the lot. The gate would have fired on
# zero of the seven items that actually quote a measurement, which is not a quiet
# detector, it is an absent one wearing a detector's name
# ([`ship-the-detector-with-the-capability`]).
WI_COUNT_CAP = 6
WI_STALE_ADR_CAP = 12         # P19, same bound and same reason as the symbol cap
WI_STALE_ID_CAP = 16


# ── releases (WI-0044; ADR-0078 / ADR-0080 / ADR-0081) ───────────────────────────
# A RELEASE is harvested, a SET is planned, and they are different objects (ADR-0078 D1).
# Nothing here gates a cut on a plan: `release-cut` takes whatever actually landed —
# every closed item not yet stamped with a version — computes the small-number bump from
# the impact labels, and writes an immutable record. An item that slipped does not hold
# the release; it simply is not in it, and D5 makes the record say so out loud.
#
# THE MAJOR IS NOT COMPUTED HERE (ADR-0081). `_wi_derive_bump` cannot return "major" at
# all. A major exists because a human declared a milestone — `release-declare` writes its
# manifest up front — and the cut then honours that declaration. This is the whole reason
# the two verbs are separate: a plan is written before the work, a record after it.
RELEASES_DIRNAME = "releases"
# A version's three parts, and the seed the federation's own history starts from
# (ADR-0080: 6.0.0, reconstructed from the record rather than started fresh at 1.0.0).
SEMVER_RE = re.compile(r"^(\d+)\.(\d+)\.(\d+)$")


def _rel_project() -> str:
    """The project this repo releases — `federation-arch` → `federation` (ADR-0006).

    Derived from `architect_id` rather than configured separately, for the same reason
    the session-picker label is (ADR-0032): a hand-set second copy of an identity is a
    copy that can disagree with the first.
    """
    aid = CFG.get("architect_id", "") or ""
    return aid[:-5] if aid.endswith("-arch") else (aid or "project")


def _rel_dir() -> Path:
    return ROOT / RELEASES_DIRNAME / _rel_project()


def _rel_parse_version(name: str) -> tuple[int, int, int] | None:
    m = SEMVER_RE.match(name)
    return (int(m.group(1)), int(m.group(2)), int(m.group(3))) if m else None


def _rel_records() -> list[tuple[tuple[int, int, int], Path]]:
    """Every release record on disk, oldest first. Manifests are NOT records — a
    declared major that has not shipped must never be mistaken for a shipped version."""
    d = _rel_dir()
    if not d.is_dir():
        return []
    out = []
    for p in sorted(d.glob("*.md")):
        if p.stem.endswith("-manifest"):
            continue
        v = _rel_parse_version(p.stem)
        if v:
            out.append((v, p))
    return sorted(out)


def _rel_current() -> tuple[int, int, int] | None:
    """The highest SHIPPED version, or None when nothing has ever been cut.

    None is deliberately distinct from `(0,0,0)`: "no releases yet" and "released 0.0.0"
    are different facts, and folding them would let a first cut silently compute a bump
    against a version nobody declared
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
    """
    recs = _rel_records()
    return recs[-1][0] if recs else None


def _rel_apply_bump(cur: tuple[int, int, int], bump: str) -> str:
    major, minor, patch = cur
    if bump == "major":
        return f"{major + 1}.0.0"
    if bump == "minor":
        return f"{major}.{minor + 1}.0"
    return f"{major}.{minor}.{patch + 1}"


def _rel_manifest_path(version: str) -> Path:
    return _rel_dir() / f"{version}-manifest.md"


def _rel_parse_manifest(path: Path) -> dict:
    """A declared major's manifest: its theme, its ruled-in ids, and its ship target.

    Parsed rather than trusted from memory because the manifest is the *promise*, and the
    cut has to be checkable against it (D5 — what slipped).
    """
    text = path.read_text(encoding="utf-8")
    theme, target, ids = "", "", []
    for line in text.splitlines():
        if line.startswith("- theme:"):
            theme = line.split(":", 1)[1].strip()
        elif line.startswith("- target:"):
            target = line.split(":", 1)[1].strip()
        elif line.startswith("- items:"):
            ids = [x.strip() for x in line.split(":", 1)[1].split(",") if x.strip()]
    return {"theme": theme, "target": target, "items": ids, "path": path}


def _rel_declared_major() -> dict | None:
    """The in-flight major manifest, if one is declared and not yet shipped."""
    d = _rel_dir()
    if not d.is_dir():
        return None
    shipped = {p.stem for _v, p in _rel_records()}
    for p in sorted(d.glob("*-manifest.md")):
        version = p.stem[: -len("-manifest")]
        if version not in shipped:
            man = _rel_parse_manifest(p)
            man["version"] = version
            return man
    return None


def _rel_harvest() -> list[dict]:
    """Everything that shipped and has not been recorded: closed, and carrying no version.

    `superseded` work never shipped, so it is excluded — including it would let cancelled
    work inflate a release and, worse, drag its impact label into the bump.
    """
    return [it for it in _wi_parse()
            if it.get("status") == "done" and not it.get("version")]


def _rel_titles(base: Path | None = None) -> dict[str, str]:
    """`{id: title}` for the whole store, read at render time — never stored.

    THE TENSION THIS RESOLVES, because the next person to touch it will hit it too.
    [ADR-0073](adr/0073-work-item-store.md) D3 makes the item file the single writer of a
    title, which is why the release record carried bare ids for its first eight versions:
    restating a title looks like the hand-maintained duplicate `single-source-and-deliver`
    forbids. It is not one. That habit names three sanctioned deliveries, and a record is
    the third — build-assemble: one authority composed into an artifact at write time. The
    discriminator is whether the copy has to be KEPT IN SYNC by somebody. A release record
    is immutable by construction (`release-cut` refuses an existing record), so its titles
    are a snapshot of what the store said on the day the version shipped — a receipt, not
    a second copy that can drift out of agreement with the item. Nothing reads a title back
    out of a record, and nothing may: the item file stays the only place a title is stored.

    A missing title reads as the id itself (`_wi_parse_text` defaults it), and callers drop
    that case rather than rendering `WI-0001 — WI-0001`.
    """
    return {it["id"]: (it.get("title") or "").strip() for it in _wi_parse(base)}


def _rel_title_suffix(wid: str, titles: dict[str, str]) -> str:
    """` — Its title`, or `""` when there is no title worth appending.

    ONE definition of "worth appending", used by every section of the record. Most bullets
    want it straight after the id (`_rel_titled`); `## Previously shipped in this promise`
    wants it after the VERSION, because the id and the number it went out under are the
    accounting for a promise and a free-text field must not sit between them. Both call
    this rather than each restating the rule, so a title can never render in one section
    and go missing in another.
    """
    t = (titles.get(wid) or "").strip()
    return f" — {t}" if t and t != wid else ""


def _rel_titled(wid: str, titles: dict[str, str]) -> str:
    """`WI-0001 — Its title`, or the bare id when there is no title worth appending.

    The id stays FIRST and the separator is a spaced em dash, so anything reading ids out
    of a record by matching the id at the head of the bullet is unaffected by it.
    """
    return f"{wid}{_rel_title_suffix(wid, titles)}"


def _rel_summary(shipped: list[dict]) -> str:
    """One line answering "what is in this release?" without opening a single item file.

    WI-0065. A major gets a `theme` because a human declared a milestone and wrote one; a
    minor gets nothing, so the version that ships most of the work was the one with no
    statement of what it did — 6.1.0's record is thirteen bare ids, and "what's new?" meant
    opening thirteen files. This is the minor's equivalent, and it is DERIVED rather than
    asked for: a summary the operator has to type at cut time is a summary that will be
    typed badly at 2am or skipped with an empty string, and `release-cut` is meant to run
    unattended on the landed trunk.

    Shape: `N items — <impact mix>; <where they landed>`. Two facts, both already in the
    store and both load-bearing at a glance — how big the release is, and what area it
    touched. The impact mix is safe to lean on because the cut REFUSES an unlabelled item,
    so it is complete by the time this runs.

    The group clause never picks a winner out of a tie. Sorting the tied names and taking
    the first would read as a finding while being an artefact of the alphabet, so a tie is
    reported as a tie. A leader also has to clear a floor before it is named at all (see
    below) — a group holding a twelfth of the harvest is not what the release was about.
    When no item carries a group the clause says so rather than going quiet: a summary that
    silently drops half its sentence is indistinguishable from one that found nothing to
    say ([`declare-what-a-check-assumes`]).
    """
    n = len(shipped)
    noun = "item" if n == 1 else "items"
    impacts: dict[str, int] = {}
    for it in shipped:
        label = (it.get("impact") or "").strip() or "unlabelled"
        impacts[label] = impacts.get(label, 0) + 1
    mix = ", ".join(f"{c} {label}" for label, c in
                    sorted(impacts.items(), key=lambda kv: (-kv[1], kv[0])))
    groups: dict[str, int] = {}
    for it in shipped:
        g = (it.get("group") or "").strip()
        if g:
            groups[g] = groups.get(g, 0) + 1
    if not groups:
        where = "no group recorded on any of them"
    else:
        top = max(groups.values())
        leaders = sorted(g for g, c in groups.items() if c == top)
        # A LEADER HAS TO ACTUALLY LEAD, and this floor was put here by the real store
        # rather than by taste. Dry-run against the federation's own 25-item backlog the
        # day this shipped, the first draft produced: "led by Federation production state
        # and mail and Public cut (WI-0020) (2 each of 25)" — true, unreadable, and empty.
        # Naming a leader that holds a twelfth of the release is WORSE than admitting the
        # release had no centre of gravity, because a named leader reads as a finding. So
        # below a quarter of the harvest, or past three tied names, report the SPREAD,
        # which is itself the honest answer to "what's in this one?" — it says the release
        # was maintenance across the board rather than a push on one area.
        if top * 4 < n or len(leaders) > 3:
            # Say how many of the N this clause is even ABOUT. "spread across 4 groups"
            # over a 25-item harvest reads as 25 items in 4 groups; the measured shape
            # that day was 6 grouped and 19 carrying no group at all, which is a different
            # release. A clause that quietly changes denominators is the same collapse
            # as one that goes silent ([`declare-what-a-check-assumes`]).
            where = (f"no dominant group ({sum(groups.values())} of {n} grouped, "
                     f"across {len(groups)})")
        elif len(leaders) == 1 and top == n:
            where = f"all in {leaders[0]}"
        elif len(leaders) == 1:
            where = f"mostly {leaders[0]} ({top} of {n})"
        else:
            # Comma-joined, never "A and B": group names in this repo contain the word
            # `and` ("Federation production state and mail"), so an "and" separator makes
            # two names unparseable as two.
            where = f"led by {', '.join(leaders)} ({top} each of {n})"
    return f"{n} {noun} — {mix}; {where}"


def _rel_promise_state(manifest: dict, shipping_ids: set[str]) -> dict:
    """Is a declared major's promise complete, and where did each ruled-in item ship?

    ADR-0084 D1: the major fires when EVERY ruled-in item has shipped — counted, not
    declared. ADR-0081 D1 is untouched by this: code still cannot judge whether a chapter
    is significant, it just counts to nine.

    Returns `complete` plus the two lists the record needs (D4):
      `prior`       [(id, version)] — ruled in, shipped under an EARLIER number. Without
                    this the major's record would only ever contain whatever happened to
                    be unstamped on the day it completed, so every milestone would report
                    fewer items than it promised.
      `outstanding` ids not shipped at all. Non-empty ⇒ not complete.
      `absent`      id → why it is not in this tree's store at all (WI-0239). A subset of
                    `outstanding`, and the one the reader cannot infer: an id held by an
                    unlanded lane yielded `it = {}`, no version, and landed in
                    `outstanding` indistinguishable from work nobody has started. That is
                    the SILENT member of this defect class — the counter reads a stranded
                    lane as incomplete and says nothing about which kind of incomplete it
                    is. `complete` is unchanged by it: lane-held work has not shipped.

    A `superseded` ruled-in item counts as OUTSTANDING, not shipped: cancelled work never
    shipped, so treating it as kept would let a promise complete itself by abandonment.
    The way out is D5 — amend the manifest and say why — which is exactly the record we
    want in that case, so the stall is the feature.
    """
    by_id = {it["id"]: it for it in _wi_parse()}
    prior, outstanding, cancelled = [], [], []
    for wid in manifest.get("items", []):
        if wid in shipping_ids:
            continue
        it = by_id.get(wid) or {}
        ver = (it.get("version") or "").strip()
        if ver and it.get("status") != "superseded":
            prior.append((wid, ver))
            continue
        outstanding.append(wid)
        if it.get("status") == "superseded":
            cancelled.append(wid)
    return {"complete": not outstanding, "prior": prior,
            "outstanding": outstanding, "cancelled": cancelled,
            "absent": _wi_absent_cause([w for w in outstanding if w not in by_id])}


def _rel_commit_record(path: Path, version: str) -> None:
    """Commit the release record that `release-cut` just wrote.

    Same three safety properties as `_wi_autocommit`, for the same reasons: an explicit
    pathspec (never `-A`, so a concurrent lane's in-flight work is never swept into this
    commit), a pathspec-limited `commit --` (so anything else already staged in this tree
    stays staged and uncommitted), and FAIL-OPEN — the record is already written when we
    get here, so a git failure reports on stderr and leaves the file rather than turning a
    successful cut into an error.

    Skipped under the test suite, like every other auto-commit path: committing the
    operator's real repo from a test is WI-0068's class."""
    if _under_test():
        return
    root = path.parent
    while root != root.parent and not (root / ".git").exists():
        root = root.parent
    spec = str(path.resolve())
    try:
        if sh(["git", "-C", str(root), "rev-parse", "--git-dir"],
              check=False).returncode != 0:
            return                              # not a git repo — the write still stands
        sh(["git", "-C", str(root), "add", "--", spec], check=False)
        if not sh(["git", "-C", str(root), "status", "--porcelain", "--", spec],
                  check=False).stdout.strip():
            return                              # already committed — no empty commit
        subject = f"feat(releases): cut {_rel_project()} {version}"
        c = sh(["git", "-C", str(root), "commit", "-m", subject, "--", spec], check=False)
        if c.returncode != 0:
            print(f"note: {path.name} written but NOT committed — "
                  f"{(c.stderr or c.stdout).strip()[:160]}  "
                  f"(commit it by hand before the items are stamped)", file=sys.stderr)
            return
        head = sh(["git", "-C", str(root), "rev-parse", "--short", "HEAD"],
                  check=False).stdout.strip() or "(unknown)"
        print(f"committed {head} — {path.name} is SAVED.")
    except Exception as e:
        print(f"note: {path.name} written but NOT committed ({type(e).__name__}) — "
              f"commit it by hand before the items are stamped.", file=sys.stderr)


# ── WI-0303 (b): a declared set rots by SLIPPAGE, so the nagging comes from code ──
# ADR-0084 D1 made a major ship when its promise is complete, which removed every way a
# milestone can quietly shrink except one: an item nobody drops and nobody finishes. The
# promise then stays formally intact and indefinitely unmet, and the only thing standing
# between that and a de-scope is somebody remembering to look.
#
# WHY THIS IS A SIBLING OF `wi-stale` AND NOT A MODE ON IT. Both report staleness and
# neither ever acts, and that shared shape is the whole of what they share. `wi-stale`
# asks whether an item's CITED PREMISES still hold, and answers by running git per
# citation; this asks whether a RULED-IN item has moved lately, and answers from file
# reads. Three concrete consequences decided it, rather than taste:
#   1. `_WI_PREMISE_KEYS` couples "any finding" to "not clean" to "not stamped". A
#      manifest-staleness finding folded in there would suppress the `probed:` receipt on
#      an item whose citations are all fine — a live regression in an unrelated field.
#   2. `wi-stale` is on-demand-only BECAUSE it shells out. This check is
#      file reads, which is what lets it ride the startup surface — and riding the startup
#      surface is the entire point of the item, whose acceptance is that the nagging must
#      not come from anyone's memory. Folding it in would forfeit exactly the property
#      that makes it work.
#   3. `wi-stale` sits in `LANE_STRANDED_STORE_VERBS` (exit 4 from a lane) solely because
#      it writes `probed:`. A pure reporter has nothing to write and no reason to inherit
#      that refusal.
# `curate/check_citations.py`'s docstring already draws this line for the repo: a premise
# that can age for honest reasons reports beside `wi-stale`. The reuse P16 asks for here
# is of the settled SHAPE — flag and propose, never act; a distinct third answer for
# "could not tell" — not of a function that reads a different store.

# How long a ruled-in item may sit with no dated movement before the report proposes
# de-scoping it. Fourteen days is the operator's ruled acceptance (session ~241), kept as the default rather than quietly retuned here.
#
# MEASURED BEFORE SHIPPING, because this repo has already shipped one unmeasured age gate
# and found it fired on nothing (see `WI_COUNT_CAP` above, which records the same lesson).
# Three measurements, all taken 2026-09-18:
#   - The movement clock across the 40 live items: median 7 days, MAXIMUM 11. A 14-day
#     flag fires on zero of them today, and the cause is the one `WI_COUNT_CAP` already
#     names — a bulk triage sweep writes a note onto every item at once and resets the lot.
#   - 7.0.0, the only major this project has ever declared, ran from `declared: 2026-07-30`
#     to `shipped: 2026-08-09`. TEN DAYS. The threshold is longer than the entire milestone
#     it was written for, so it could not have fired once during the only flight there has
#     ever been.
#   - AND THE REPLAY OVER THAT FLIGHT PROVES NOTHING EITHER WAY, which is the measurement
#     worth carrying. Replaying this clock across all ten days for all nine ruled-in items
#     flags zero — but not because they were moving. None of the nine has a dated note at
#     all: the earliest note record anywhere in the store is 2026-08-23, fourteen days
#     AFTER that major shipped, because the note mechanism did not exist during its flight.
#     So every row lands in `unknown`, and the honest reading is that the only real subject
#     available cannot confirm or falsify this number. Said out loud rather than reported
#     as a clean replay, which is what it would look like from the exit code
#     ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
#     Going forward the clock is adequate — 35 of the 40 live items carry one — so the
#     thinness is historical, not structural.
# All three say the same thing: this flag is expected to be QUIET. That is why the report
# prints the oldest idle age and every per-item age whether or not anything trips, and why
# the threshold is a flag rather than a constant no reader can see. A detector whose only
# output is silence is indistinguishable from one that never ran
# ([`ship-the-detector-with-the-capability`](habits/master.md#ship-the-detector-with-the-capability)),
# and the fix for that is to report the measurement — never to lower the number until it
# says something.
REL_STALE_DAYS = 14

# A note record's filename leads with `YYYYMMDDTHHMMSS<micros>Z` (`_note_id`), which is
# what makes the NAME readable as a date without opening the file — the property that
# keeps this whole check on the file-read side of the startup rule.
REL_NOTE_STAMP_RE = re.compile(r"^(\d{4})(\d{2})(\d{2})T\d{6}")
REL_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _rel_manifest_declared(manifest: dict) -> str:
    """The manifest's `- declared:` date, or `""`.

    Written by `release-declare` into every manifest since the first one, and never read
    back until now. Parsed here rather than added to `_rel_parse_manifest`'s return
    because that dict is consumed by `release-cut`, and a cut must not start depending on
    a field that a hand-written or older manifest may not carry.
    """
    try:
        for line in manifest["path"].read_text(encoding="utf-8").splitlines():
            if line.startswith("- declared:"):
                return line.split(":", 1)[1].strip()
    except Exception:
        pass
    return ""


def _rel_item_movement(wid: str, item: dict,
                       base: Path | None = None) -> tuple[str, str]:
    """The most recent dated evidence that `wid` moved — `(YYYY-MM-DD, source)`, or
    `("", "")` when this store holds none.

    FILE READS ONLY, and the constraint is load-bearing rather than incidental: it is what
    lets the caller run on the startup path at all. The obvious richer clock
    — `git log -1 -- <item file>` — is the one `wi-stale` uses, and is exactly why
    `wi-stale` may never be a startup hook.

    Two sources, newest wins:
      - the newest NOTE RECORD, dated by its own filename. `_note_id` leads every record
        with a UTC compact stamp precisely so that filename order is time order with no
        field inside to trust, which is what makes the name readable as data.
      - the item's `probed:` receipt, whose first field is a UTC date.

    `("", "")` is a REAL THIRD ANSWER and callers must keep it apart from "moved recently"
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
    Five of the forty live items carried no dated evidence at all when this was written;
    folding them into either verdict would invent a finding or hide one.
    """
    best, source = "", ""
    try:
        for p in _notes_dir(WI_DIRNAME, wid, base).glob("*.md"):
            m = REL_NOTE_STAMP_RE.match(p.name)
            if not m:
                continue
            day = f"{m.group(1)}-{m.group(2)}-{m.group(3)}"
            if day > best:
                best, source = day, "note"
    except Exception:
        pass
    probed = ((item or {}).get("probed") or "").split(" ")[0].strip()
    if REL_DATE_RE.match(probed) and probed > best:
        best, source = probed, "probe"
    return best, source


def _rel_days_since(day: str, today: str) -> int | None:
    """Whole days from `day` to `today`; None when either is not a date we can read."""
    try:
        d0 = datetime.strptime(day, "%Y-%m-%d").date()
        d1 = datetime.strptime(today, "%Y-%m-%d").date()
    except Exception:
        return None
    return (d1 - d0).days


def _rel_stale_report(manifest: dict, today: str = "",
                      stale_days: int = REL_STALE_DAYS) -> dict:
    """Which of a declared major's ruled-in items have gone quiet, and for how long.

    Reads the store under `ROOT`, and takes NO `base` argument although its helpers do.
    `_rel_promise_state` — the authority this defers to for the shipped/outstanding split —
    reads `ROOT` unconditionally, so a `base` here would be honoured by half the
    computation and silently ignored by the other half. A parameter that reads as
    supported and is not is worse than its absence; tests swap `ROOT` instead, as the
    rest of this suite already does.

    Reports; never acts — and it could not act even if it were allowed to, because the
    remedy is an AMENDMENT, which ADR-0084 D5 deliberately left as a written act with a
    reason in it rather than a flag. There is no verb here for a reporter to have called.

    The subjects are the OUTSTANDING items only: an item that already shipped cannot rot,
    and `_rel_promise_state` is the single authority on which is which, so this asks it
    rather than re-deriving the split beside it.

    Every row lands in exactly one of four states, and the last two are the ones a careless
    version of this would have collapsed into the first:
      `stale`     — idle at least `stale_days`. The de-scope proposal.
      `fresh`     — dated movement more recently than that.
      `unknown`   — no dated movement evidence in this store AT ALL. Not a finding about
                    the item; a finding about the evidence.
      `cancelled` — superseded while ruled in. The strongest de-scope case there is: under
                    ADR-0084 D1 the promise can never complete while it is in the set, so
                    this is not "consider dropping it", it is "the milestone is stuck".
    """
    today = today or datetime.now(timezone.utc).date().isoformat()
    by_id = {it["id"]: it for it in _wi_parse()}
    state = _rel_promise_state(manifest, set())
    cancelled = set(state.get("cancelled") or [])
    rows: list[dict] = []
    for wid in state.get("outstanding") or []:
        item = by_id.get(wid)
        day, source = _rel_item_movement(wid, item or {})
        days = _rel_days_since(day, today) if day else None
        if wid in cancelled:
            verdict = "cancelled"
        elif days is None:
            verdict = "unknown"
        elif days >= stale_days:
            verdict = "stale"
        else:
            verdict = "fresh"
        rows.append({"id": wid, "title": (item or {}).get("title") or "",
                     "in_store": item is not None, "moved": day,
                     "source": source, "days": days, "state": verdict})
    aged = [r["days"] for r in rows if r["days"] is not None]
    return {"version": manifest.get("version", ""),
            "declared": _rel_manifest_declared(manifest),
            "target": manifest.get("target", ""),
            "stale_days": stale_days, "today": today,
            "ruled_in": len(manifest.get("items") or []),
            "prior": state.get("prior") or [], "rows": rows,
            "oldest": max(aged) if aged else None,
            "absent": state.get("absent") or {}}


def _rel_stale_row(r: dict) -> str:
    """One item's line. The clock's SOURCE is named on every row, because `note` and
    `probe` are different strengths of evidence: a note is somebody writing about the
    work, while a `probed:` stamp records only the mechanical citation check `wi-stale`
    ran, and its own writer says out loud that it does not mean anyone re-read anything."""
    title = (r.get("title") or "").strip()
    head = _rel_titled(r["id"], {r["id"]: title}) if title else r["id"]
    if r["days"] is None:
        return f"{head} — no dated movement in this store"
    return f"{head} — idle {r['days']}d (last {r['source']} {r['moved']})"


def _rel_stale_lines(rep: dict) -> list[str]:
    """The report as text. Split from the printer so the startup one-liner, the full verb
    and the tests all read one computation instead of three of them."""
    out: list[str] = []
    rows = rep["rows"]
    if not rows:
        out.append(f"  every ruled-in item of {rep['version']} has shipped — the promise "
                   f"is complete, and the next cut carries the major.")
        return out
    buckets = {k: [r for r in rows if r["state"] == k]
               for k in ("cancelled", "stale", "unknown", "fresh")}
    # The ages print whether or not anything trips. A flag that speaks only when it fires
    # cannot be told apart from one that is broken, and this one is MEASURED to be quiet
    # (see `REL_STALE_DAYS`) — so the always-on line is what makes an empty finding list
    # readable as a negative result rather than as silence.
    oldest = (f"oldest idle {rep['oldest']}d" if rep["oldest"] is not None
              else "no dated movement on any of them")
    out.append(f"  {len(rows)} of {rep['ruled_in']} ruled-in item(s) outstanding; "
               f"{oldest}; threshold {rep['stale_days']}d.")
    if rep["declared"]:
        age = _rel_days_since(rep["declared"], rep["today"])
        out.append(f"  declared {rep['declared']}"
                   + (f" — the promise is {age}d old" if age is not None else "")
                   + (f"; target {rep['target']}" if rep["target"] else ""))
    # ONE BUCKET, ONE REMEDY SENTENCE. WI-0191/WI-0240's lesson, recorded in
    # `cmd_inbox_check`: a shared header can only ever be right for one shape of finding,
    # and these four want four different things from whoever reads them.
    if buckets["cancelled"]:
        out.append(f"\n  SUPERSEDED WHILE RULED IN ({len(buckets['cancelled'])}) — "
                   f"cancelled work never ships, so {rep['version']} can NEVER complete "
                   f"while these are in the set (ADR-0084 D1). Amend the manifest to drop "
                   f"them, or reinstate the work:")
        out.extend(f"    {_rel_stale_row(r)}" for r in buckets["cancelled"])
    if buckets["stale"]:
        out.append(f"\n  IDLE {rep['stale_days']}d OR MORE ({len(buckets['stale'])}) — "
                   f"propose dropping these, or record on the item why they are still "
                   f"owed. Amending is loud on purpose (ADR-0084 D5): append a dated "
                   f"section with a written reason to "
                   f"{RELEASES_DIRNAME}/{_rel_project()}/{rep['version']}-manifest.md, "
                   f"keeping the original verbatim. Nothing here drops anything:")
        out.extend(f"    {_rel_stale_row(r)}" for r in buckets["stale"])
    if buckets["unknown"]:
        out.append(f"\n  NO MOVEMENT EVIDENCE ({len(buckets['unknown'])}) — this store "
                   f"holds no dated note and no `probed:` receipt for these, so they are "
                   f"neither idle nor fresh HERE. That is a statement about the evidence "
                   f"and not about the work, and it is not a de-scope proposal:")
        out.extend(f"    {_rel_stale_row(r)}" for r in buckets["unknown"])
    if buckets["fresh"]:
        out.append(f"\n  moved within {rep['stale_days']}d ({len(buckets['fresh'])}): "
                   + ", ".join(f"{r['id']} ({r['days']}d)" for r in buckets["fresh"]))
    if rep["absent"]:
        out.append(f"\n  NOT IN THIS STORE ({len(rep['absent'])}) — ruled in, but this "
                   f"tree cannot resolve the id, so the age above is unmeasurable for it:")
        out.extend(f"    {wid} — {why}" for wid, why in rep["absent"].items())
    return out


# ── WI-0039: the startup chart has to be READABLE ────────────────────────────────
# Learned across five rejected attempts (session ~103), and the lesson is a shape, not a preference: **completeness is about ROWS, readability
# is about COLUMNS.** The first cut printed every field, producing 1,200-character note
# cells — an unreadable wall of text; the correction over-rotated and filtered rows
# out. Both fail. So: every row always, but only scannable cells — identifier, state,
# section, a truncated one-line title. Long free text is never a column; `poga work show
# <id>` is the detail path.
#
# COLOUR CARRIES STATE, on the text itself (coloured dots were offered and rejected).
# Terminal rows are de-emphasised rather than dropped.
#
# COLOUR VOCABULARY — the operator's ruling, session ~105: **green = finished, red = in flight.**
# The ruling was given in a peer lane against the *conversation* chart (`poga work chart`,
# built there the same session); this is the *startup* surface, and the two shipped with
# different vocabularies for the same states because neither lane knew about the other.
# Aligning the two is applying his existing ruling to a second surface, not a new call.
# Finished rows are DIM green — green per the ruling, dim because closed rows are
# de-emphasised rather than dropped (`show-the-whole-list`). Blocked keeps yellow: the
# ruling covers finished-vs-in-flight and says nothing about work that cannot start.
WI_ANSI = {
    "dim_green": "\033[2;32m", "red": "\033[31m", "yellow": "\033[33m",
    "reset": "\033[0m",
}


def _set_terminal_title(title: str) -> None:
    """OSC-0 — name the terminal after its lane and topic (WI-0031 Part A).

    Only when stderr is a real terminal; piped or captured, the escape is literal garbage
    in someone's log. Written to stderr because stdout carries the command's own output,
    which a caller may be parsing. Never raises — a cosmetic title must not fail a claim."""
    try:
        if sys.stderr.isatty() and not os.environ.get("NO_COLOR"):
            sys.stderr.write(f"\033]0;{title}\007")
            sys.stderr.flush()
    except Exception:
        pass


# ── wi-feed: the published surface a board renders ───────────────────────────
# The board once parsed the raw store and broke SILENTLY at a format change — the
# `work-items.md` → directory move read back as "no open items" over five live claims —
# so the boundary is a generated, schema-versioned file, never shared internals (the
# ADR-0021 STATUS.md move, applied to the store). Regenerated best-effort by every
# mutation of what a viewer should see: the two sole-writer item paths and every claim
# acquire/release/tombstone. A feed failure never fails the write it rides on (the
# WI-0056 autocommit posture). Always built from the MAIN checkout's stores plus the
# shared claim records: a lane's claim path publishing its own frozen store copy would
# hand the board a stale item set (the two-stores split, WI-0061's lesson).
WI_FEED_SCHEMA = 1
WI_FEED_NAME = "wi-feed.json"
# The board's own status file — board-authored, single-writer (P13), the one file the
# startup gate reads (a file read, never HTTP, on the startup path). The
# path is a CONTRACT constant shared with the board; env override for tests.
BOARD_STATUS_ENV = "POGA_BOARD_STATUS"
# Floor for the two freshness windows when the board declares no/absurd poll_seconds —
# generous enough to absorb a slow poll loop, tight enough that a dead board's file
# goes stale within two minutes.
BOARD_FRESH_FLOOR_SECONDS = 120


def _system_id() -> str:
    """ADR-0006: the system id is `architect_id` minus `-arch` — derived, never a
    hand-set display field (`_lane_label`'s reasoning). Repo directory name when no
    config is readable, so a mid-bootstrap repo still publishes an identifiable feed."""
    sysid = ""
    with contextlib.suppress(Exception):
        if CFG:
            sysid = (CFG.get("architect_id") or "").strip()
            if sysid.endswith("-arch"):
                sysid = sysid[: -len("-arch")]
    if not sysid:
        with contextlib.suppress(Exception):
            sysid = ROOT.name
    return sysid


# ── Operational items (ADR-0076) ─────────────────────────────────────────────────
# Operational work is its own KIND, not a fourth impact label. The property that matters
# is that it RECURS, and three things follow:
#
#   * `done` is the wrong end state. Marking the quarterly drill done is false — it will
#     be owed again in three months. Leaving it open is also false: it reads as stalled.
#     Whichever you pick, the item is permanently misfiled.
#   * Staleness alarms point the wrong way. A dev item open three months means nobody
#     picked it up; an ops item open three months may be exactly on schedule.
#   * The useful fact is a DATE, not a state. "Drill #2 done" says nothing without *when*.
#
# So an ops item carries a `cadence` (optional — absent means one-time), a
# `last-completed` stamp, a DERIVED `due`, and a `last-result`. It carries NO `impact`
# and NO `version`: operational work has no release impact, and overloading `impact` so
# one of its values means "this field does not apply" is the shape
# `ship-the-detector-with-the-capability` names — a not-applicable branch that reads as a
# pass does not merely fail to detect a gap, it certifies one (ADR-0076 D1).
#
# ON `kind` AS A FIELD (a judgment this build had to make): D1 names `kind: dev | ops` a
# first-class field, and D2 then gives ops its own counter and directory — which makes a
# literal `kind:` line in the file redundant with the id that already carries it. Writing
# it anyway would be a second copy of one fact, free to drift (P16). So `kind` is REAL
# but DERIVED from the namespace, and it renders as a column wherever items are shown.
# D1's argument is preserved intact: its point is that kind is orthogonal to `impact`,
# not that it must be stored twice.

OPS_DIRNAME = "ops-items"
OPS_FILENAME_RE = re.compile(r"^OPS-(\d{4})-[a-z0-9-]*\.md$")
OPS_TITLE_RE = re.compile(r"^# (OPS-\d{4}): (.*)$")
OPS_FIELD_RE = re.compile(
    r"^- (status|cadence|last-completed|last-result|due|group|source):\s?(.*)$")
OPS_STATUSES = ("open", "in-progress", "held", "done", "superseded")
OPS_TERMINAL = ("done", "superseded")
# `findings` is DISTINCT from `fail` deliberately (ADR-0076 D4). A drill can run clean as
# an exercise and still surface a serious gap — the kind of finding that produces new work
# items. It did not fail; it succeeded at telling us something bad.
# A store that renders that identically to an uneventful drill records the wrong fact
# about the most valuable thing it did.
OPS_RESULTS = ("pass", "fail", "findings")
OPS_RESULT_UNSET = ""
# Deliberately small. A cadence vocabulary calcifies once items carry it, so this starts
# with the three the live items actually need rather than inventing a scheduling grammar
# nobody asked for (ADR-0076 "Bad, and accepted").
#
# `weekly` joined them 2026-09-06, on a live item rather than a hypothetical: the operator's
# Group C ruling puts the findings review on a weekly cadence. The alternative was to record
# a standing weekly obligation as a ONE-TIME item with a typed due date, which is the
# failure D3 names — the date would need pushing forward by hand every week, so the
# review that exists to stop chores lapsing would itself lapse silently.
#
# TWO MAPS, not one. A week is a fixed 7 days; a month is not a fixed number of days, and
# folding either into the other would make one of them wrong. `_ops_derive_due` reads the
# day map first and falls through to the month map, so the clamping that keeps a monthly
# obligation off 2026-02-31 is untouched by a cadence that never needed it.
#
# `daily` added by WI-0329 (ADR-0124 D3): the gate-input derive leaves the land path and
# becomes a nightly obligation, and there was no cadence short enough to express it. It
# goes in the DAY map for the same reason `weekly` does — a day is a fixed number of days.
OPS_CADENCES = ("daily", "weekly", "monthly", "quarterly", "annual")
OPS_CADENCE_MONTHS = {"monthly": 1, "quarterly": 3, "annual": 12}
OPS_CADENCE_DAYS = {"daily": 1, "weekly": 7}
OPS_CADENCE_UNSET = ""


def _today() -> str:
    """Today in the member's configured timezone. A due date or a ship date is a local
    calendar fact — stamping it in UTC would move a run near midnight onto the wrong day.

    Was `_ops_today`; renamed when releases needed the same fact (WI-0044). A second copy
    would have been the [P16](principles/master.md#p16--avoid-duplication) hand-maintained
    duplicate, and the two would have drifted the first time either grew a fallback.
    """
    try:
        return datetime.now(CFG["tz"]).strftime("%Y-%m-%d")
    except Exception:
        return datetime.now().strftime("%Y-%m-%d")


# ── The chart (`wi-chart`) ───────────────────────────────────────────────────────
# The SHAPE the user asked to see when he asks for the whole list, as code rather
# than as each session's re-invention (P15 — a fixed format given fixed inputs is
# mechanism, not judgment). Before this existed, every session that was asked for the
# list hand-rolled a renderer from scratch: several round-trips to re-derive column
# widths and wrapping, and a slightly different chart each time. That is the drift
# `single-source-and-deliver` names, showing up as *display* rather than storage.
#
# The format is the user's, approved 2026-07-29 (`show-the-whole-list` in the user
# profile), and every rule in it is load-bearing:
#   * EVERY row, always — no filtering by status, section, or recency. Completeness is
#     about rows. A `--section`/`--status` filter is deliberately NOT offered here;
#     the whole point of the chart is that it is the whole list.
#   * Readability is about COLUMNS — id, state, section, and a one-line label. Long
#     free-text (notes, blockers, source briefs) is not a column; it wrapped to
#     1,200-character cells the first time and read as "an unreadable wall of text."
#     `wi-show <id>` is the full record.
#   * A bordered grid, a separator between every item, and long titles WRAPPED inside
#     the cell rather than truncated — truncation would silently drop content, which
#     is the completeness rule failing in a different direction.
#   * Colour carries state via a diff fence: `+` (green) closed, `-` (red) in-progress,
#     plain open. Markdown tables carry neither borders nor colour, so they are not an
#     option; coloured dots were tried and rejected.
#
# It emits the ```diff fence itself: the chart reaches the user only by the Architect
# reproducing it in chat (this harness's stdout does not reliably render to him), so
# the fence is part of the artifact, not decoration the Architect adds by judgment.
# ADR-0076 D6: identity splits, visibility does NOT — one chart, both namespaces. Ops
# work is never given its own view: a standing obligation that lives on a surface nobody
# visits is exactly how a quarterly drill quietly becomes an annual one.
#
# NO `kind` COLUMN. D6 names one, and the build shipped one; operator removed it (session
# ~109), ruling that the id already carries the kind. That is right, and it is the same argument that kept `kind` from being STORED — a column that
# restates the id is a second copy of one fact, and it read `dev` on forty-one
# consecutive rows while `SECTION` sat empty on every ops row. Eleven columns spent on
# cells that never varied. D6's requirement is *visibility of both kinds in one view*,
# which the `WI-`/`OPS-` prefix already delivers.
#
# `DEPS` replaces it, because the chart could not show what it most needed to: an item
# blocked by another rendered as plain `open`, so WI-0046 waiting on WI-0044 was
# invisible here while the startup list showed it as `blocked`. Two surfaces over one
# store disagreeing about whether work is actionable is worse than either answer.
WI_CHART_COLS = (("ID", 8), ("STATUS", 14), ("SECTION", 7), ("DEPS", 9), ("VER", 5))
WI_CHART_TITLE_W = 54


def _chart_rows(base: Path | None = None) -> list[dict]:
    """Both namespaces as one ordered row set (ADR-0076 D6) — dev items first, then ops.

    Each row carries `kind` and a `state` (what a reader needs to decide whether to act).
    For a dev item `state` is just its status; for an ops item it is the DATE-derived
    answer — `overdue`, `never run`, or `due YYYY-MM-DD` — because "is anyone working on
    this?" is the wrong question to ask a standing obligation.

    Ops rows carry no `section`: `next`/`backlog` is a dev-planning axis, and an
    obligation is not planned, it is owed. The cell is left empty rather than filled with
    a lookalike value.

    `base` selects which checkout's stores to read (see `_wi_dir`) — the feed builder
    passes `_shared_work_root()` so a lane never publishes its frozen copy."""
    today = _today()
    rows: list[dict] = []
    for it in _wi_parse(base):
        rows.append({**it, "kind": "dev", "state": it.get("status", "open")})
    for it in _ops_parse(base):
        # `blocked_by` is defaulted rather than omitted: every consumer of this row set
        # reads it, and an ops row missing the key would KeyError the shared renderers.
        # An obligation has no dependencies — it is owed on a date, not unblocked by work.
        rows.append({**it, "kind": "ops", "section": "", "blocked_by": [],
                     "state": _ops_state(it, today)})
    return rows


# ── ROADMAP.md Next/Backlog render (ADR-0073 D6) ─────────────────────────────────
# Recently-shipped stays hand-authored prose (outcome-framing needs a human); Next and
# Backlog are, structurally, nothing but a work-item list, so they render FROM the
# store between a pair of GENERATED markers per section — the same "generated, do not
# hand-edit" contract as CANON.md/STANDARD.md. `wi-render` refuses outright if the
# marker pairs aren't present rather than guessing where to splice.

WI_GEN_BEGIN = "<!-- BEGIN GENERATED: session.py wi-render — do not hand-edit between these markers -->"
WI_GEN_END = "<!-- END GENERATED -->"


# ── ADR-0105: the outcome paragraph lives in the journal, not in ROADMAP.md ──────
#: The journal section carrying this session's one-paragraph outcome. A journal is a
#: per-session file, so two sessions writing outcomes cannot collide however concurrent
#: they are — which is the entire point, since `ROADMAP.md` collided by construction.
#: Journal sections are `###` in the house format (`### What happened`, `### Notes filed`), so
#: this is too — and the extractor accepts either level, because getting this wrong is
#: SILENT: the region would read "no outcomes yet" forever while every session dutifully
#: wrote one, and nothing would error. Found by writing this session's own outcome and
#: watching it not appear ([`verify-in-the-created-configuration`]).
JOURNAL_OUTCOME_HEADING = "### Outcome"

#: How many outcomes ROADMAP's Recently-shipped carries. Smaller than HANDOFF_KEEP on
#: purpose: the handoff is the blow-by-blow record and wants depth, while this is the
#: human-facing "what changed lately" and stops being that once it needs scrolling.
ROADMAP_OUTCOME_KEEP = 8


# ── WI-0285: the finish-line board's verdict is the roadmap's first line ─────
#: The federation-only board whose one-line verdict fills the generated region under
#: `## Now`. Declared as a repo-relative PATH, not an import, because `sessionlib` is
#: byte-identical fleet substrate and `curate/` is not shipped to members: a member that
#: never adds the markers never calls the producer, and one that does gets told the board
#: is absent rather than an ImportError during its close.
FINISH_LINE_SCRIPT = "curate/finish_line.py"

#: A wall-clock cap the board itself does not have. `finish_line.py` bounds each git call
#: at 30s and makes no promise about the TOTAL — it shells git once per fleet member — and
#: this producer runs inside `run_compile`, which every land calls on the trunk. An
#: unbounded probe there would turn a slow fleet walk into a slow land, which is the exact
#: number the board's own FL8 row measures.
#:
#: WI-0357 — DERIVED FROM THE LAND BUDGET NOW, and the literal it replaces was wrong in the
#: one way a ceiling can be: it was equal to the whole thing it was supposed to protect.
#: `run_compile` is called from inside the land's serialized section, so this producer
#: spends the section's allowance — and at 30 it could spend ALL of it, on one region of
#: one generated view, before the land had merged anything. A ceiling that permits a
#: total breach of the budget it sits inside is not a ceiling.
#:
#: THE MEASUREMENT, because the old comment's was true when written and is not now —
#: `measured-small-is-not-structurally-zero`, and the reason a number in a comment needs a
#: date. WI-0285 measured `--status` at ~2.1s warm on an idle machine and reasonably read
#: 30 as unreachable. From this repo's own land receipts, the recompile stage either side
#: of the commit that wired this producer in (`3c0fd1ac`, 2026-09-13):
#:
#:     before  12 recompiles that did work   median 0.552s   max  2.010s
#:     after   24 recompiles that did work   median 3.050s   max 30.109s
#:
#: A 5.5x step in the median at that commit, and re-measured directly under
#: heavy load the board takes 7.9s / 10.4s / 22.7s (min / median / max over five runs).
#: 30 is reachable in ordinary operation on a busy machine, not a stall ceiling.
#:
#: A THIRD of the budget, not all of it: the section also has to merge, sync and push, and
#: no single producer inside it may spend more than a third of what every other lane is
#: queueing behind. Derived rather than written as a second literal for the same reason
#: `LAND_PUSH_TIMEOUT_SECONDS` above is — it is one constraint said once, so a change to
#: the budget cannot leave a stale ceiling above it. A board that does not answer inside
#: this keeps its previous verdict (`_render_finish_line`), which is why the cap can be
#: tight without costing the region anything.
FINISH_LINE_TIMEOUT_S = LAND_LOCK_HOLD_BUDGET_SECONDS / 3


def _strip_generated_regions(text: str) -> str:
    """`text` with everything between each GENERATED marker pair removed — i.e. only the
    hand-authored remainder."""
    out: list[str] = []
    inside = False
    for tok in re.split(f"({re.escape(WI_GEN_BEGIN)}|{re.escape(WI_GEN_END)})", text):
        if tok == WI_GEN_BEGIN:
            inside = True
            continue
        if tok == WI_GEN_END:
            inside = False
            continue
        if not inside:
            out.append(tok)
    return "".join(out)


def _has_staged_changes() -> bool:
    """True iff the index has changes to commit (git diff --cached is non-empty)."""
    return sh(["git", "diff", "--cached", "--quiet"], check=False).returncode != 0


def _cut_session_branch(session_id: str) -> str | None:
    """Cut+checkout session/<id> from the trunk at first activity (ADR-0056 D1).
    Fail-open: only auto-branches from a clean-enough TRUNK checkout; on any git
    error stays put and returns None (degraded to Phase-1 behaviour, never bricked).
    Idempotent — already on this session's branch is a no-op; a session already on
    another non-trunk branch (a worktree / hand-cut branch) keeps it as its session
    branch. Never raises."""
    # ADR-0058: DEFAULT OFF. Branches are no longer load-bearing for isolation —
    # attribution (D1) plus the isolated gate (D4) do that job, and two sessions in one
    # tree cannot have separate branches anyway (one tree, one HEAD), which is exactly
    # how the shared-branch bug arose. Kept behind the flag for the future
    # worktree-lane world, where each session genuinely has its own tree.
    try:
        if CFG is None or not CFG.get("branch_sessions", False):
            return None
        branch = _session_branch(session_id)
        cur = _current_branch()
        if cur == branch:
            return branch
        if cur != _trunk():
            # On a worktree / hand-cut branch already — that IS the session branch.
            return branch if cur.startswith("session/") else None
        exists = _ref_exists(f"refs/heads/{branch}")
        flag = [] if exists else ["-b"]
        r = sh(["git", "checkout", *flag, branch], check=False)
        return branch if r.returncode == 0 else None
    except Exception:
        return None


#: ADR-0148 D3 (WI-0427): the paths a land may change WITHOUT a suite verdict. A diff
#: every one of whose paths is here is bookkeeping — the record of work, never the
#: work — and lands on the cheap checks alone.
#:
#: DECLARED, NOT MEASURED, and that is the reversal of ADR-0117 D1. The measured set
#: depended on a nightly serial derive, and the record went stale every night that
#: derive was red — so the skip it licensed fired ZERO times between WI-0329 and this
#: item, while 75 of 231 lands (32%) changed nothing but these paths and paid a median
#: 193 s of suite each. What makes a declared list SAFE is the other half of D3: the
#: suite may not read any of these paths under the real root, and `curate/store_guard.py`
#: fails the test that does. A path goes on this list only together with that guard.
#:
#: Directories end in "/" and match by prefix; bare names match one top-level file.
BOOKKEEPING_PATHS = (
    "work-items/", "sessions/", "ops-items/", "proposed-edits/", "comms/",
    "outbox/", "releases/",
    "ROADMAP.md", "STATUS.md", "session-handoff.md", "gate-inputs.json",
)


def _is_bookkeeping_path(rel: str) -> bool:
    """Is one repo-relative path bookkeeping under ADR-0148 D3?"""
    rel = rel.strip()
    if rel.startswith("./"):
        rel = rel[2:]
    return bool(rel) and any(rel.startswith(p) if p.endswith("/") else rel == p
               for p in BOOKKEEPING_PATHS)


#: The measured input set the gate-neutral classifier reads (WI-0294). Written by
#: `curate/gate_inputs.py --derive`, which runs the suite under an `sys.addaudithook`
#: and records every repo-relative path it actually opened. Committed data, so a lane
#: and the trunk classify against the same measurement.
GATE_INPUTS_RECORD = "gate-inputs.json"

#: Record schema this code understands. A record announcing anything else is not a
#: measurement this version can read, and the land gates.
#:
#: 2 — WI-0337. Schema-1 records were derived by a probe that hooked only its own
#: interpreter, so every repo path the suite's subprocesses read was measured by
#: nothing. That under-reports the input set, and under-reporting is what licenses a
#: gate-neutral SKIP, so the whole generation is retired at once by the bump rather
#: than aged out one nightly derive at a time.
#:
#: 3 — WI-0347. Schema-2 records carry ONE input set, measured from one command, and
#: the land applied it to the whole `gate` list — seven commands here, of which the
#: measured one (`unittest discover -s tests`) was not among them. The bump is again
#: the point: a schema-2 record cannot say which command read what, so there is no way
#: to read one conservatively. Every record now carries a per-command `commands` block,
#: and a command the record does not cover runs unconditionally.
GATE_INPUTS_SCHEMA = 3


def _roledoc_version_at(rev: str, role_doc_rel: str) -> str | None:
    """The `**Version:**` value the declared role doc carried AT `rev`, tolerant of
    the same variants `role_doc_version()` parses. None if the file didn't exist at
    `rev`, or carried no parseable Version line, so the caller degrades to no signal
    rather than a false positive."""
    show = sh(["git", "show", f"{rev}:{role_doc_rel}"], check=False)
    if show.returncode != 0:
        return None
    for line in show.stdout.splitlines():
        m = re.match(r"\*\*Version:?\*\*:? *`?v?([0-9]+\.[0-9]+\.[0-9]+)", line)
        if m:
            return m.group(1)
    return None


def _new_roledoc_violation(parent: str, tip: str) -> str | None:
    """WARN (never block) — the ADR-0053 R3 `versioned-role-doc-and-changelog`
    conformance miner, folded into the land per the roadmap's `phase2-followons`
    item, scoped to *newly-introduced* exceptions only: violations already sitting
    on the trunk are this land's inheritance, not its fault, and re-flagging them on
    every unrelated land would make the signal noise. Scoping the mine to exactly
    `parent..tip` — this lane's own new commits — makes 'new vs pre-existing'
    unambiguous without needing a separate baseline snapshot: a commit that isn't in
    this range didn't happen in this land. Fail-open on any git error (a broken diff
    must never block or falsely warn); returns None when the role doc wasn't
    touched, when either endpoint's Version can't be read, or when the version did
    change."""
    role_doc_rel = (CFG or {}).get("role_doc_rel")
    if not role_doc_rel:
        return None
    touched = sh(["git", "log", "--format=%H", f"{parent}..{tip}", "--", role_doc_rel],
                 check=False)
    if touched.returncode != 0 or not touched.stdout.strip():
        return None
    shas = touched.stdout.split()
    before, after = _roledoc_version_at(parent, role_doc_rel), _roledoc_version_at(tip, role_doc_rel)
    if before is None or after is None or before != after:
        return None
    return (f"warn:    {role_doc_rel} changed in {len(shas)} commit(s) "
            f"({shas[-1][:8]}..{shas[0][:8]}) with no **Version:** bump "
            f"(versioned-role-doc-and-changelog) — landing anyway, not blocked.")


def _candidate_commit(paths: list[str], msg: str, parent: str) -> str | None:
    """Build a commit containing `paths` on top of `parent` WITHOUT touching the shared
    index or HEAD (ADR-0058 D3).

    Two sessions in one working tree share both, so neither may be mutated to stage a
    commit — a `git add` from one session would corrupt the other's staging. Instead we
    point GIT_INDEX_FILE at a private temp index, seed it from the parent tree, apply
    only our attributed paths, and write the tree + commit with plumbing. Nothing about
    the shared checkout changes. Returns the new commit sha, or None on any failure."""
    tmp = tempfile.mkdtemp(prefix="fed-index-")
    try:
        env = {**os.environ, "GIT_INDEX_FILE": str(Path(tmp) / "index")}
        if sh(["git", "read-tree", parent], check=False, env=env).returncode != 0:
            return None
        for p in paths:
            # A path that no longer exists is a deletion — record it as one.
            op = (["--add"] if (ROOT / p).exists() else ["--force-remove"])
            if sh(["git", "update-index", *op, "--", p],
                  check=False, env=env).returncode != 0:
                return None
        tree = sh(["git", "write-tree"], check=False, env=env)
        if tree.returncode != 0 or not tree.stdout.strip():
            return None
        made = sh(["git", "commit-tree", tree.stdout.strip(), "-p", parent, "-m", msg],
                  check=False, env=env)
        if made.returncode != 0 or not made.stdout.strip():
            return None
        return made.stdout.strip()
    except Exception:
        return None
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


# Prefix of the throwaway directory `_gate_commit` stages its scratch worktree in. Named
# once (P16) because the REAPER matches on it too — WI-0063: the cleanup below runs in a
# `finally`, so any gate whose process dies first (kill -9, crash, knocked offline) leaves
# a REGISTERED worktree behind permanently. Eleven accumulated in one four-minute burst of
# concurrent land attempts on 2026-07-28 and had to be removed by hand.
GATE_WORKTREE_PREFIX = "fed-gate-"

#: Set to "1" in the environment of every suite the gate runs (ADR-0119 D4). It is the
#: only thing that distinguishes "this suite is deciding whether a commit may enter the
#: trunk" from "somebody is running the tests", and the five machine-scoped probes below
#: key on it.
GATE_ENV_VAR = "POGA_GATE"

#: The programs a gate-run suite must not reach. Not a documentation list — the detector
#: `tests/test_gate_snapshot.CompletenessTest` reads it and fails on any harness function
#: that spawns one without consulting `_under_gate()`.
GATE_FORBIDDEN_PROGRAMS = ("lsof", "ps", "tmux", "claude")


def _under_gate() -> bool:
    """True when this process is (or descends from) a suite the land gate is running.

    ADR-0058 D4 promises the gate sees *"exactly what the trunk would become — no in-flight
    noise from anyone."* WI-0271 measured that and it was false: the suite shelled out to
    the machine's `lsof`, `ps`, `tmux` and `claude`, so the verdict on a commit was partly
    a reading of the operator's box. That is not a flaw in those probes — they exist to
    read the real machine and are right to — it is that a GATE has no business asking.

    The guard lives here rather than in the tests because this is the third instance of the
    class (`coord_fixture`, the dispatch-env vars, now this), and a rule each test module
    has to remember is a rule that gets forgotten — `add-structural-guard-on-recurrence`.
    Under the gate each probe returns the CANNOT-TELL answer it already returns when the
    machine will not answer; none of them gains a fabricated one.

    Inherited by children, deliberately: a test that shells out to `session.py` gets a
    process that is bound by the same variable. Its limit is stated in
    `tests/test_gate_snapshot.py` — a child that clears its environment is not bound, and
    that is CANNOT TELL rather than covered."""
    return os.environ.get(GATE_ENV_VAR) == "1"


# ── WI-0143 / ADR-0097: integrating the trunk with its remote, from a lane ──────
#
# THE GAP, hit live at session ~157/158 with the work already gate-green. A lane lands
# by CAS: it advances the LOCAL `refs/heads/<trunk>` with `update-ref` and checks
# nothing out, which is exactly what makes the land cheap and lockless. The push that
# follows is a plain fast-forward — and a peer session that pushed while we were landing
# makes it non-ff. From a lane there was then NO path at all. A ff push needs
# `origin/<trunk>` to be an ANCESTOR of local `<trunk>`, which means replaying our
# commits on top of theirs — i.e. operating on the trunk — and the trunk is checked out
# in the MAIN checkout, which the runtime's worktree-isolation guard correctly refuses
# to reach into.
# Cherry-picking their commit onto our side does not help (a copy has a new sha, so
# origin is still not an ancestor), and force-pushing is forbidden ([P9](principles/master.md#p9--destructive-ops-confirmed)).
# So the work landed locally and simply could not leave the machine, and the land's own
# advice — "run `git push`" — was an instruction to a human that could not succeed.
#
# THE FIX is a verb whose predicate carries the safety argument, never an exception to
# the guard: reconcile the two trunks IN A THROWAWAY WORKTREE (the same primitive the gate
# already uses — nothing checked out that another worktree holds), re-gate the result, CAS
# the trunk forward to it, bring the main checkout's tree along, recompile the views, then
# push. It REFUSES rather than guesses when the reconciliation conflicts, and never forces.
#
# WI-0153 / ADR-0102 CORRECTED HOW that reconciliation is built. The first cut REPLAYED our
# unpushed trunk commits onto origin's tip — rebase semantics — and that is wrong for two
# trunks that both advanced, for a reason that only shows up on the second machine:
#
#   * **a replay rewrites our side.** Every local commit gets a new sha. Anything else that
#     referenced the old ones — the peer's clone, a parked ref, a lane branched from the
#     trunk — is now diverged from a trunk it used to be part of, so the machines take turns
#     rewriting each other and never converge. WI-0153's acceptance names this directly:
#     *nothing rewritten*.
#   * **a replay conflicts far more than a merge does**, because a cherry-pick's base is one
#     commit's parent rather than the true merge base. Two sides that each edited a
#     different region of the same file merge cleanly and replay badly, and a commit that
#     touched a file and a later one that reverted it conflicts on the way through even
#     though the net trees agree.
#
# A MERGE COMMIT is the operation that actually resolves a divergence: it has both tips as
# parents, so `origin/<trunk>` becomes an ANCESTOR of the result — which is the exact
# predicate a fast-forward push needs — while both sides' commits keep their shas. That is
# the one thing neither `integrate`'s replay nor `merge`'s lane rebase could produce, and
# the reason an operator had to hand-build the merge in a lane (WI-0153, session ~161).


# The named conflict classes BOTH reconciliations resolve under — the integrate's merge
# (`_merge_onto`) and the land's rebase (`_resolve_rebase_conflict`). One vocabulary for one
# rule ([P16](principles/master.md#p16--avoid-duplication)): `generated` resolves a conflict
# confined to this member's derived views and refuses on anything else; `none` resolves
# nothing. A policy is a NAME with an argument behind it, never "files that look mergeable".
RESOLVE_POLICIES = ("generated", "none")


def _trunk_only_views() -> tuple[str, ...]:
    """Repo-relative paths of every view ONLY the trunk may author — the compiled handoff,
    `STATUS.md` (which carries the census in its frontmatter) and `ROADMAP.md`.

    THE ONE LIST, and it exists because there were four
    ([ADR-0119](adr/0119-the-gates-three-side-doors-are-shut.md) D5). `_generated_view_names`
    named two of them, `_harness_owned` named three inline, `_recompile_main_checkout`
    re-derived two of its own, and `LAYOUT_DEFAULTS` declared all three — so *"is the
    roadmap generated?"* had a different answer depending on which one you asked, which is
    exactly how WI-0262 arrived (the resolve policy said no) and WI-0260 landed (the dirt
    classifier said yes and nothing stopped the write). One list, read by the land's
    restore step, the resolve policy and the dirt classifier alike ([P16](principles/master.md#p16--avoid-duplication)).

    Repo-relative strings, resolved through `layout_of` so a member whose views live
    elsewhere is named correctly rather than being silently absent from the guard — the
    `declare-what-a-check-assumes` failure this substrate has already paid for twice.
    Order is handoff, status, roadmap; callers that care about identity match on the value,
    never the position."""
    out: list[str] = []
    for key in ("handoff", "status_file", "roadmap"):
        try:
            rel = layout_of(CFG_RAW, key)
        except Exception:                            # pragma: no cover - defensive
            rel = ""
        if rel and rel not in out:
            out.append(rel)
    return tuple(out)


def _conflict_is_resolvable(rel: str, policy: str = "generated",
                            cwd: Path | None = None) -> bool:
    """True iff `policy` may take the trunk/ours side of this conflicted path.

    ONE VOCABULARY, TWO MEMBERSHIPS. A wholly generated view — the compiled handoff,
    `STATUS.md` — qualifies UNCONDITIONALLY: every byte is re-derived by the recompile at
    the end of the very land this unblocks, so whichever side is taken is overwritten
    before anyone reads it. `ROADMAP.md` qualifies CONDITIONALLY, because it is generated
    in regions rather than in whole, and `_roadmap_side_is_render_only` is the condition.

    WHY THE ROADMAP IS IN THE CLASS AT ALL, having been excluded by
    [ADR-0098](adr/0098-a-lane-repairs-main-and-clears-its-own-blocked-rebase.md) D7: that
    exclusion rested on *"it is authored prose with one writer per lane"*, and
    [ADR-0105](adr/0105-roadmap-is-a-compiled-trunk-only-view.md) D4 reversed the premise
    eight days later — lanes never write `ROADMAP.md`, `STANDARD.md` says so in as many
    words, and the last hand-edit-shaped commit to it predates that ADR. D7's reason
    stopped being true and nothing re-read it. Meanwhile a lane's roadmap divergence
    became almost always the harness's OWN re-render — which is exactly the shape D7
    refuses on — so the refusal turned into close to the default outcome of landing behind
    another lane, and routed a mechanical, argued no-op to a human every time (WI-0252).

    A policy other than `generated` resolves nothing, and is answered here rather than by
    handing this function an empty set: an empty set would still have let the roadmap
    branch fire under `none`."""
    if policy != "generated":
        return False
    name = Path(rel).name
    if name in _generated_view_names():
        return True
    if name == _roadmap_name():
        return _roadmap_side_is_render_only(rel, cwd)
    return False


# ── WI-0109 / ADR-0098: a blocked rebase has a next verb ────────────────────────
#
# `merge` rebases the lane onto the trunk, hits a conflict, aborts cleanly and reports
# BLOCKED. That is correct — it never leaves a half-state — but there was no NEXT verb.
# The banner and the merge output both said "resolve it in the lane", which means opening
# a session in that lane: precisely the manual step the lane substrate exists to avoid,
# and what left poga-2 unmerged after poga-1 and poga-3 landed (session ~129).
#
# The rule this follows is the one WI-0097 and WI-0143 followed before it: when a guard
# correctly refuses a hand-run, the answer is a substrate verb whose PREDICATE carries the
# safety argument, never an exception to the guard. Here the predicate is a NAMED, bounded
# conflict class — files this member declares GENERATED — where the trunk side wins and
# nothing durable is lost, because the land regenerates both files minutes later. Anything
# outside that class still refuses, loudly, by name.

# One conflicted commit may resolve into another; the loop is bounded so a pathological
# rebase can never spin ([P19](principles/master.md#p19--cap-what-can-run-away)). A lane
# with more conflicted commits than this has a problem no policy should be papering over.
REBASE_RESOLVE_MAX_STEPS = 50


# --- ADR-0051 Phase 1b: the compactor -----------------------------------------
#
# `session-handoff.md` (and STATUS.md's census line) become GENERATED views compiled
# from the per-session journals + the frozen `sessions/pre-journal-archive.md`. No
# session edits the shared handoff any more — each owns its journal, and `compile`
# (run by every start and end) regenerates the view. The counter contention and the
# "orphan with no writeup" class die here: nothing is allocated, and an abandoned
# session is just a journal with no `ended`.
#
# The render is DETERMINISTIC + IDEMPOTENT: same journals + archive -> byte-identical
# output (ADR-0051 Consequences). Ordinals are DERIVED by the compactor (the historian),
# never claimed at birth: journals sort by `started`, and ordinals continue from the
# frozen historical max. The pure renderer (`render_handoff`) takes every input as an
# argument so it is testable without the filesystem; thin fs-reading glue wraps it.
ARCHIVE = ROOT / "sessions" / "pre-journal-archive.md"
HANDOFF_KEEP = 10   # newest journal prose entries inlined; older stay in sessions/journal/
# The handoff title falls back to this ONLY when the member declares no `architect_name`
# (WI-0404). The heading used to be this literal unconditionally, so every member's own
# record spoke as the federation — the `stay-in-role` boundary breached by the substrate
# that ships it. Keeping the old literal as the no-key fallback means an undeclared member
# is unchanged rather than titled with an empty string; a declared one gets its own name.
HANDOFF_TITLE_FALLBACK = "Federation Architect"


def _strip_h1(body: str) -> str:
    """Drop a leading `# ...` H1 (+ following blank) from a journal body — the compactor
    supplies the `## DATE — Session N — title` heading, so a body-level H1 would double
    it. Tolerates bodies authored with or without one."""
    lines = body.lstrip("\n").splitlines()
    if lines and lines[0].startswith("# "):
        lines = lines[1:]
        while lines and not lines[0].strip():
            lines = lines[1:]
    return "\n".join(lines)


def _migrate_freeze() -> None:
    """Self-triggering one-time migration for the fleet rollout (ADR-0051): a member that
    gets the new harness but has no `pre-journal-archive.md` yet has its existing
    HAND-WRITTEN `session-handoff.md` frozen into the archive BEFORE the first compile —
    so the compactor composes onto real history instead of clobbering the handoff with an
    empty view. Idempotent: a no-op once the archive exists or the handoff is already
    generated. The federation froze manually (session 70); every other member self-migrates
    here on first run — no per-member manual step (the 'fix the engine' rule)."""
    if ARCHIVE.exists():
        return
    handoff = CFG.get("handoff") if CFG else None
    if not handoff or not handoff.is_file():
        return
    cur = handoff.read_text(encoding="utf-8")
    if not cur.strip() or "GENERATED — do not edit" in cur:
        return   # empty, or already a generated view — nothing to freeze
    lines = cur.splitlines()
    hdr = next((i for i, l in enumerate(lines) if l.startswith("| # | Date |")), None)
    if hdr is None:
        return   # unrecognized handoff shape — skip; compile proceeds without an archive
    end = hdr + 1
    if end < len(lines) and lines[end].startswith("|---"):
        end += 1
    while end < len(lines) and lines[end].startswith("|"):
        end += 1
    table = "\n".join(lines[hdr:end])
    prose = "\n".join(lines[end:]).strip("\n")
    frozen = (
        f"# Pre-journal archive — {CFG['architect_name']}\n\n"
        "> **Frozen — do not edit.** Auto-captured at the Phase 1b cutover "
        "([ADR-0051](adr/0051-multi-session-concurrency-retire-the-master-session.md) C2) "
        "the first time this member ran the journal-compiling harness. Verbatim pre-journal "
        "SESSION LOG rows + prose; from here on each session owns its journal and "
        "`session-handoff.md` is compiled.\n\n"
        "## SESSION LOG (archived)\n\n" + table + "\n\n## Prose (archived)\n\n" + prose + "\n"
    )
    ARCHIVE.parent.mkdir(parents=True, exist_ok=True)
    atomic_write(ARCHIVE, frozen)


# A reaped journal that never left the stub body and lived less than this is a PHANTOM —
# an accidental SessionStart (a background `claude -p` firing this repo's hook, the
# session-15/68 class), not a real session. Deleted rather than kept, so it consumes no
# ordinal — the journal-native form of the retired "NC doesn't burn the counter" rule.
REAP_PHANTOM_MAX_SEC = 120


def _is_stub_body(body: str) -> bool:
    """True when a journal body is BYTE-FOR-BYTE the opening stub.

    **Not a question any caller should ask directly** (WI-0377). It is the exact-match
    core `_journal_is_unauthored` is built on, and nothing else: the harness itself
    writes into the body of a running session, so byte-exactness answers False for a
    journal no Architect ever touched, and every caller that asked it got the wrong
    answer on the machine the defect was found on. `test_no_second_caller_of_is_stub_body`
    holds that boundary structurally — the predicate was re-acquiring call sites faster
    than they were being corrected, which is the `add-structural-guard-on-recurrence`
    trigger."""
    return body.strip() == _STUB_BODY.strip()


#: The only body section the HARNESS itself writes into. `_journal_note` files its lines
#: under this heading and nowhere else, so every section above it is Architect-authored
#: or empty. Named here rather than spelled again, because the whole point of
#: `_journal_is_unauthored` is that this boundary is exact.
JOURNAL_HARNESS_SECTION = "### Notes filed"


def _journal_is_unauthored(body: str) -> bool:
    """True when nothing but the HARNESS has written into this journal body.

    `_is_stub_body` asks the stricter question — byte-for-byte the opening stub — and
    **this is the only place that asks it** (WI-0377). When this predicate shipped, the
    four callers that delete a journal or a lane were left on the strict form, on the
    argument that a deleter wants the conservative question. That argument was wrong in
    the one direction nobody checks: the strict predicate is conservative about
    *deleting*, so those callers never fired at all, and an empty lane carrying one
    machine-written line read as real work forever while nothing reaped it. Being too
    slow to delete debris is a failure too — it just produces a growing pool of stranded
    lanes instead of a lost file. The harness writes into the body while the session is
    running: `_journal_note` files a line under
    `### Notes filed` during lazy start, and a checkout whose main tree holds authored
    work gets one on every session it opens. MEASURED on this repo (WI-0340): the two
    journals opened here on 2026-09-12 each carry exactly that one machine-filed line and
    no narrative, and `_is_stub_body` returns False for both — so a close-time stub guard
    built on it would never have fired on the machine where the defect was found.

    The question is therefore narrowed to the sections the harness does not write. Built
    ON `_is_stub_body` rather than beside it, so the opening stub keeps exactly one
    definition and the two predicates cannot drift apart
    ([P16](principles/master.md#p16--avoid-duplication)). Strictly the weaker of the two:
    everything `_is_stub_body` calls a stub, this does too."""
    head, sep, _filed = body.partition(JOURNAL_HARNESS_SECTION)
    return _is_stub_body(f"{head}{JOURNAL_HARNESS_SECTION}\n" if sep else body)


def _machine_close_would_hit_the_real_repo() -> bool:
    """Refuse a machine-close that a TEST RUN is about to aim at real, tracked journals.

    MEASURED (WI-0146, devbox 2026-08-22): running the suite closed
    `sessions/journal/20260814T1200Z-runner-5599.md` in the ambient checkout — a tracked
    file — stamping it `closed-by: janitor`. A fresh clone then passed 1956 tests and the
    SECOND run in that same clone failed six, all in `test_claims`, because those tests
    read the ANCHORED checkout and now found a journal the first run had mutated. It hid
    for months because every Runner run was from a lane, where the anchored checkout and
    the ambient one are different files; on a machine that works in its main checkout
    they are the same file. The land gate runs the raw suite, so the consequence was that
    the second land in a row failed for a reason naming neither the change nor the cause.

    The guard is here, at the write, rather than in each fixture's setUp: a fixture that
    forgets is invisible, and this is the one place the damage happens. A test that has
    rebound `JOURNAL_DIR` — which every janitor and reaper test already does — is
    unaffected, because then the two directories differ."""
    if not _test_suite_is_running():
        return False
    try:
        return JOURNAL_DIR.resolve() == _LAUNCH_JOURNAL_DIR.resolve()
    except (OSError, ValueError):
        return False


# ---------------------------------------------------------------- janitor
# The reaper above closes a session it can PROVE is dead, from the liveness sidecar.
# The janitor handles the two cases it structurally cannot, both of which accumulate
# forever and both of which are litter rather than news:
#
#   1. A journal whose evidence NO LONGER EXISTS. The record is durable (tracked in git,
#      visible from both machines); the evidence is a gitignored scratch file, per-tree
#      and per-machine, deleted with the lane worktree that held it. When the evidence
#      dies first, the reaper's "no evidence -> leave open" rule means the journal can
#      never be closed by anything, ever. Federation carried three such journals for
#      14-17 days as of session ~118; nothing was ever going to resolve them.
#   2. Sidecar files for sessions that are long over. Nothing has ever deleted one —
#      one member's `.session-state/` held well over a hundred files, most of them
#      belonging to sessions that closed perfectly
#      ([`retention-enforced-by-code`](habits/master.md#retention-enforced-by-code):
#      a lifecycle policy that lives only in prose is a chore that silently lapses).
#
# WHAT THIS IS NOT. It is not a way to stop seeing problems (the operator's ruling, session ~118:
# the fix is a system that does not produce the problems, not a cleanup process). It sweeps only
# the two classes above — residue with no news in it — and every sweep is APPENDED TO A LOG
# rather than performed silently, because a janitor that quietly closes a fifth of one
# member's sessions every week is hiding a defect, not fixing one. The log is what makes a
# rising sweep rate visible as the signal it is.
JANITOR_AGED_DAYS = 7          # an EVIDENCE-LESS journal is over once it is this old
JANITOR_SIDECAR_KEEP_DAYS = 14  # residue for a session that is over is dropped after this
# Sidecar suffixes keyed by a session id, and therefore prunable once that session is over.
# The SHARED `.jsonl` logs are deliberately absent — `guard-firings`, `janitor`,
# `startup-timing`, `notify-payloads` are append-only records with their own lifecycle, not
# per-session residue, and sweeping them would delete the audit trail.
#
# `.escalations.jsonl` (WI-0278) is on the list anyway, and the distinction is the stem
# rather than the extension: it is keyed by ONE session and its durable copy is the tracked
# journal that `end` folds it into, so what is left here after that close is residue in
# exactly the sense the two classes above are not. Without a line here it would be the one
# per-session sidecar nothing ever drops — `retention-enforced-by-code` failing by
# inheriting a rule written about a different class of file. It follows `.end-ran`'s
# precedent in the other respect too: both are stemmed by the DURABLE session id rather
# than the claude-session-id, so neither is matched by the `open_csids` guard and both rest
# on the age cutoff, which is sized for exactly that.
JANITOR_SIDECAR_SUFFIXES = (".live", ".ended", ".gone", ".touched", ".end-ran",
                            f".{ESCALATION_LOG_SUFFIX}")
#: The subset of the above that `_lane_death_verdict` and `_sidecar_evidence_by_csid`
#: actually READ to decide whether a session is over — and therefore the only suffixes
#: where a stem naming no session does harm rather than merely taking up space. A forged
#: `.live` holds a dead lane against `recover`; a forged `.ended` or `.gone` would retire a
#: live one. `.touched` and `.end-ran` are attribution and telemetry: no verdict reads
#: them, so they stay on the age rule alone.
#:
#: THE SCOPE IS THE POINT, and it was nearly wrong. WI-0270's first cut applied the shape
#: rule to everything the janitor recognises, which swept `wi-snapshot-<sid>.json` in with
#: it — and `<sid>` there falls back to the literal `"app"` for any runtime with no
#: `CLAUDE_CODE_SESSION_ID` (store.py, and lanes.py reads it back to resolve "items 1-10").
#: That is a real, load-bearing key for a plain terminal `poga`, not a fixture's leavings,
#: and pruning it would have silently broken item-range resolution for exactly the
#: sessions least able to notice. The shape survey behind `SIDECAR_STEM_RE` enumerated the
#: liveness suffixes only; applying its answer to a class it never looked at is
#: [`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes) failing
#: at the consuming end, which is the failure this substrate keeps re-buying.
LIVENESS_SUFFIXES = (".live", ".ended", ".gone")


def _emit_already_open(fm: dict) -> None:
    """Idempotent re-run output (ADR-0051): this session's journal is already open.
    Tell the Architect not to re-run and where its journal is; no new stamp, no JSON."""
    sid = fm.get("session-id", "")
    # WI-0152: still a START-TIME ordinal — the compile that settles it has not run over
    # the landed union yet, and the fallback here is the frontmatter's own advisory
    # estimate. Rendered as such rather than asserted.
    n = compiled_ordinal(sid) or fm.get("ordinal") or "?"
    print("\n".join([
        "=== SESSION START (already open) ===",
        f"session: {_display_ordinal(n)}  (journal {sid})",
        "stamp:   already open this session — do NOT re-run `session.py start`.",
        f"journal: sessions/journal/{sid}.md — write your session narrative there.",
        "note:    Orient from the hook's original block; nothing to do here.",
    ]))


# --------------------------------------------------------------------------------
# Runtime registry — ADR-0082 D3
# --------------------------------------------------------------------------------
# One ROW per runtime, never an `if` per agent inside poga's cmd_session. Four
# branches become five become six, and they drift apart; adding a runtime here is
# data. The table lives in Python rather than in poga's bash for one reason: the
# `tests/` suite is the gate `curate/push-substrate.py` refuses to push without, and
# it cannot reach bash. poga owns the exec and asks this for the row.
#
#   id             canonical runtime id — the value written to a journal's `runtime:`
#   alias          short form for `poga -r <alias>` (D2). DECLARED, never inferred, so
#                  `--list` can print it: an abbreviation that only works if you already
#                  know it is worse than no abbreviation.
#   command        the executable to launch. None = no launch command known yet, which
#                  D4 turns into a refusal BY NAME rather than a raw exec failure.
#   worktree_flag  the runtime's OWN native worktree flag, if it has one. Claude Code
#                  takes `--worktree <lane>` and lands inside the worktree itself. A
#                  runtime with none gets the lane created for it and is launched with
#                  that directory as cwd — which is the path the off-repo launch
#                  pad already walks (poga:164-177), so the non-Claude launch is mostly
#                  written already.
#   model_flag     D2's SECOND AXIS, reserved and unused in Phase 1: which model INSIDE
#                  the runtime (Opus vs Fable, and each runtime's equivalent). Recorded
#                  now so filling it later is data, not a schema change.
#   argv_shape     D3's argv-shape column (WI-0096): how an opening prompt is passed
#                  to the runtime (antigravity: -i; claude-code and codex: positional).
#   guards         D6: what this runtime can actually enforce. `native` = the PreToolUse
#                  guards apply. Anything else is declared per ADR-0041's vocabulary and
#                  REPORTED by the start banner — an unguarded lane that looks identical
#                  to a guarded one is the precise failure D6 exists to prevent.
RUNTIMES = (
    {"id": "claude-code", "alias": "c",  "command": "claude",
     "worktree_flag": "--worktree", "model_flag": "--model", "guards": "native",
     "argv_shape": "positional", "prompt_shape": "positional"},
    # NO `chatgpt` ROW. The opening roster (ADR-0082 D2) carried one as a placeholder
    # with no launch command. Removed on the operator's correction, session ~111: ChatGPT cannot
    # be run bare in a terminal at all — the only way to reach it is by invoking `codex`,
    # which is already its own row. So `chatgpt` was never a runtime this registry could
    # launch; it was a product name in a column of executables. A placeholder row implies
    # "not wired up yet" and would have left someone waiting for a command that is never
    # coming, which is worse than its absence.
    {"id": "codex",       "alias": "cx", "command": "codex",
     "worktree_flag": None,         "model_flag": None,      "guards": "undeclared",
     "argv_shape": "positional", "prompt_shape": "positional"},
    # NO `gemini` ROW. Removed session ~125 on the operator's ruling that the Gemini CLI is
    # superseded by Antigravity. Google's terminal agent is now Antigravity, and the
    # `gemini` binary is a command whose product is going away. A row that resolves to a binary
    # nobody should be starting new work in is worse than no row: it launches, so nothing
    # tells you it was the wrong choice. This is the `chatgpt` removal's rule applied to a
    # row that CAN launch — the test is whether it SHOULD.
    #
    # The alias `g` is deliberately NOT reused for antigravity. Muscle memory would send
    # `-r g` to a different product and get a working session, which is the "wrong answer
    # shaped like a right one" class; leaving `g` unclaimed makes it refuse by name and
    # print the roster, which is how someone learns the CLI changed.
    #
    # BINARY IS `agy`, NOT `antigravity` — the product's CLI package installs its
    # executable as `agy`, so the product name and the executable differ. Do not
    # "correct" this to the product name; D4 would then refuse every launch as not-installed.
    {"id": "antigravity", "alias": "ag", "command": "agy",
     "worktree_flag": None,         "model_flag": "--model", "guards": "undeclared",
     "argv_shape": "-i", "prompt_shape": "-i"},
)

RUNTIME_DEFAULT = "claude-code"


def _runtime_row(key: str) -> dict | None:
    """Resolve a runtime id OR its short alias to its row. None when unknown.

    Both forms are first-class (D2): `-r c` and `-r claude-code` are the same request.
    Returns a copy so a caller cannot mutate the registry."""
    k = (key or "").strip()
    if not k:
        return None
    for row in RUNTIMES:
        if k == row["id"] or k == row["alias"]:
            return dict(row)
    return None


def _runtime_roster() -> str:
    """The declared roster, one line each — what `--list` prints and what a refusal
    shows, so an operator who typed a wrong alias sees the real ones immediately."""
    out = []
    for row in RUNTIMES:
        cmd = row["command"] or "(no launch command configured)"
        out.append(f"  {row['alias']:<3} {row['id']:<12} {cmd}")
    return "\n".join(out)


def _claude_session_id() -> str:
    """The ephemeral Claude-Code session id from the environment — the concurrency-safe
    key by which `end` (a plain Bash command, not a hook) identifies its OWN journal,
    matched against the journal's `claude-session-id` frontmatter. No shared pointer
    file (which two sessions would clobber); the env var is per-session by construction."""
    return os.environ.get("CLAUDE_CODE_SESSION_ID", "")


# --- handoff rotation --------------------------------------------------------
#
# The handoff grows without bound (~6KB/session) and is read + rewritten in full
# at every session boundary. Rotation moves the OLD prose entries — verbatim,
# never summarized — into session-handoff-archive/, keeping the newest KEEP in
# the live file. The SESSION LOG table is the permanent index and never moves.
# Deliberately a separate explicit subcommand, not an automatic side effect of
# `end`: the close ritual stays single-purpose, and `end` just prints a hint
# when the entry count passes ROTATE_HINT_AT.
ROTATE_KEEP_DEFAULT = 10
ROTATE_HINT_AT = 15


# --- liveness hooks + orphan surgery (ADR-0036) ------------------------------


def _sweep_stale_pending(keep: Path | None) -> None:
    """Remove OTHER sessions' leftover `.pending-start` markers (ADR-0055):
    phantom debris (its `.ended` exists — the session died without ever becoming
    real) immediately, anything else past the crash grace. A young marker with no
    exit evidence is a concurrent session still in its first turn — kept.
    Best-effort; never raises."""
    try:
        for p in SESSION_STATE_DIR.glob("*.pending-start"):
            if keep is not None and p == keep:
                continue
            other = p.name[: -len(".pending-start")]
            if _sidecar_evidence_by_csid(other)["has_ended"]:
                p.unlink(missing_ok=True)
                continue
            try:
                started = json.loads(p.read_text(encoding="utf-8")).get("started")
            except Exception:
                started = None
            age = _iso_age_min(started)
            if age is None or age > REAP_CRASH_GRACE_MIN:
                p.unlink(missing_ok=True)
    except Exception:
        pass


def _complete_lazy_start(sid: str | None) -> None:
    """Materialize a lazily-started session (ADR-0055) — the mutating half of
    `start`, run at the FIRST heartbeat (tool call or Stop): freeze-migrate, reap,
    write this session's journal (backdated to the recorded start), recompile the
    handoff/STATUS views, and perform the deferred auto-push. The heartbeat is the
    signal a phantom SessionStart never produces, so this running at all is the
    proof of a real session. Idempotent under concurrent duplicate fire (atomic
    writes; the journal write is skipped if the file exists — which also protects
    a narrative the Architect already wrote there) and the marker is consumed
    LAST, so a failed attempt retries on the next beat. Never raises."""
    # Per-step wall-clock, written once at the end (see `_startup_timing_log`). This
    # path is the only mutating work between the operator's prompt and the session's
    # first action, and every step but one is local disk — `push` is network, so it is
    # the only step whose cost can vary by orders of magnitude. Measuring beats
    # inferring: a guess about which step is slow is exactly the kind of confident
    # unverified claim P18 exists to stop.
    t0 = time.monotonic()
    steps: dict[str, float] = {}
    ok = True

    def _step(label: str, fn, *a, **kw):
        """Time one step and RE-RAISE. The timing must not change control flow: a step
        that fails still has to abort the rest and leave the marker unconsumed, so the
        next beat retries. `finally` records the failing step's duration too."""
        s = time.monotonic()
        try:
            return fn(*a, **kw)
        finally:
            steps[label] = round(time.monotonic() - s, 3)

    try:
        if not sid or CFG is None:
            return
        marker = _pending_marker(sid)
        if not marker.is_file():
            return
        data = json.loads(marker.read_text(encoding="utf-8"))
        did = data.get("session_id")
        if did:
            _step("freeze", _migrate_freeze)
            _step("reap_journals", _reap_dead_journals, sid)
            _step("reap_lanes", _auto_reap_lanes)      # ADR-0060 Q5: sweep crashed poga lanes
            _step("link_shared", _link_shared_data)    # a lane must see the inbox/profile/mirrors (session 90)
            _step("coord_reap", _coord_reap)           # ADR-0051 C4/C5: sweep expired claims/leases/adr reservations
            if not journal_path(did).is_file():
                _step("journal", write_start_journal, did, {
                    "session-id": did,
                    "ordinal": data.get("ordinal") or _next_ordinal(),
                    "title": "(in progress)",
                    "machine": data.get("machine") or detect_machine(),
                    "runtime": CLAUDE_RUNTIME,
                    "role-doc-version": data.get("role_doc_version") or f"v{role_doc_version()}",
                    "base-commit": data.get("base_commit") or _base_commit(),
                    "started": data.get("started") or _now_iso(), "ended": "",
                    "claude-session-id": sid,
                })
            # Push any prior session's unpushed TRUNK commits BEFORE branching away —
            # a fresh session branch has no upstream, so the deferred push (ADR-0055)
            # must run while still on the trunk.
            _step("push", _push_if_ahead)
            # the stale-materialization deadlock: bring the main checkout to the trunk tip when it provably holds
            # nothing of its own — the repair for a checkout a declined land-sync left
            # behind. BEFORE the sweep, and that order is the fix rather than a tidiness:
            # the sweep refuses on a non-empty index, and a stale materialization IS a
            # non-empty index, so the sweep could not run until this had.
            _step("main_materialize", _materialize_main_auto)
            # ADR-0091 D3: sweep harness-written records left in the main checkout by
            # prior lane activity. After `push` (so this session's push behaviour is
            # unchanged — the swept commit rides the next land's trunk push), before
            # branching. No-ops everywhere but a lane looking at an idle, on-trunk main.
            _step("main_sweep", _main_harness_sweep_auto)
            # ADR-0056: isolate this session on its branch, then compile — which now
            # no-ops on the branch (D2). If branching is off/failed we stay on the
            # trunk and compile there as before.
            _step("branch", _cut_session_branch, did)
            _step("compile", run_compile, CFG["tz"])
            # WI-0131: the start banner has already shown the substrate-push notice by
            # the time a beat happens, so consume it here. A session that never beats
            # never delivered the notice to anyone and correctly re-announces.
            _step("push_notice", _mark_substrate_push_announced)
        _sweep_stale_pending(keep=marker)
        marker.unlink(missing_ok=True)
    except Exception:
        ok = False
    finally:
        # Empty on every beat but the materializing one — the early returns above fire
        # before any `_step`, so the hot path logs nothing at all. `ok` records whether
        # the marker was consumed, so a retry loop is visible as repeated failed rows
        # rather than as silence.
        if steps:
            _startup_timing_log({
                "at": _now_iso(), "session": sid,
                "total_s": round(time.monotonic() - t0, 3),
                "ok": ok, "steps": steps,
            })


# ── Resident-runtime launch pads ───────────────────────────────────────────────
# A RESIDENT-RUNTIME member's repo hosts two roles: another agent that owns the repo
# root and the Architect that builds it. Its Architect cannot
# launch from the repo root — Claude Code would auto-load that agent's `CLAUDE.md`
# and the Architect doc would be absorbed into it. So the Architect launches from a
# PAD outside the repo.
#
# That makes lanes structurally impossible without help: a lane worktree is a CHECKOUT
# of the repo, so the `CLAUDE.md` and settings inside it are the RUNTIME's, and the
# main pad's `../architect/` resolves, from inside a lane, to a path that does not
# exist. `poga session` there would boot the resident agent under its own permission
# posture while the Architect's hooks silently never fired.
#
# The fix is a PER-LANE pad: generated, disposable, and outside the repo — so the
# ADR-0027 boundary holds in every lane, not merely in the main checkout.

PAD_ANCHOR = '"$CLAUDE_PROJECT_DIR/'


def _pad_dir_rel() -> str | None:
    """Repo-relative path to the Architect's launch pad (e.g. `../architect`), or None
    for an ordinary member that launches from its repo root."""
    v = (CFG or {}).get("pad_dir")
    return v.strip().rstrip("/") if isinstance(v, str) and v.strip() else None


def _harness_dir_rel() -> str:
    """Path from the Architect's launch cwd to the harness — the prefix `gen_settings`
    stamped into this member's hook commands, and therefore the prefix a lane's settings
    must have REWRITTEN to reach the lane's own harness.

    Declared, not inferred. It cannot be derived from `pad_dir`: inverting the pad path
    needs the repo's own directory name, which no config records, and a guess would
    produce hooks that point nowhere."""
    explicit = (CFG or {}).get("harness_dir")
    if isinstance(explicit, str) and explicit.strip():
        return explicit.strip().rstrip("/")
    # No declaration: fall back to computing it from the real paths on disk, which IS
    # available here (unlike in the generator, which renders for remote targets).
    pad, main = _main_pad(), _main_checkout()
    if pad is None or main is None:
        return "."
    return os.path.relpath(main, pad)


def _main_pad() -> Path | None:
    """The operator's real launch pad, anchored on the MAIN checkout so it resolves to
    the same place whether called from there or from inside a lane."""
    rel = _pad_dir_rel()
    main = _main_checkout()
    if not rel or main is None:
        return None
    return (main / rel).resolve()


def _settings_rel() -> str | None:
    """Repo-relative path of the Architect's settings file, same precedence the
    capability detectors use: the generated `settings_path` first, then the read-side
    `architect_settings_path`. Only an IN-REPO path can serve a lane — a pad-relative
    one (`../architect/...`) names the main pad, which no lane may point at."""
    for key in ("settings_path", "architect_settings_path"):
        v = (CFG or {}).get(key)
        if isinstance(v, str) and v.strip() and not v.strip().startswith(".."):
            return v.strip()
    return None


def _relink(link: Path, target: Path) -> None:
    """Point `link` at `target` by a RELATIVE symlink, replacing whatever is there."""
    with contextlib.suppress(OSError):
        if link.is_symlink() or link.exists():
            link.unlink()
    link.parent.mkdir(parents=True, exist_ok=True)
    link.symlink_to(os.path.relpath(target, link.parent))


def orphan_pads() -> list[Path]:
    """Every generated pad whose lane worktree is gone — the PREDICATE, with no removal.

    The two teardown paths (the WorktreeRemove hook, the reaper) each clean the pad of
    a lane they are retiring — but a worktree can also vanish by routes neither sees: a
    bare `git worktree remove`, a `poga lanes --clean`, a manual `rm -rf`. The pad left
    behind is not inert: it is a fully-formed Architect launch surface aimed at a
    directory that no longer exists. Sweeping by ABSENCE OF THE LANE rather than by
    teardown event catches every route at once, including the ones not yet invented.

    Separated from the sweep for WI-0291, so a caller that must only REPORT (a dry run)
    answers from the same predicate the sweep acts on instead of from a second copy of
    it. A dry run reporting a set the real run would not touch — or vice versa — is the
    same class of defect as the one that split them
    ([P16](principles/master.md#p16--avoid-duplication))."""
    found: list[Path] = []
    main_pad, main = _main_pad(), _main_checkout()
    if main_pad is None or main is None:
        return found
    prefix = f"{main_pad.name}-"
    with contextlib.suppress(OSError):
        for cand in sorted(main_pad.parent.iterdir()):
            if not cand.is_dir() or not cand.name.startswith(prefix):
                continue
            lane = cand.name[len(prefix):]
            if not lane or (main / ".claude" / "worktrees" / lane).is_dir():
                continue
            found.append(cand)
    return found


def sweep_orphan_pads() -> list[str]:
    """Remove every pad `orphan_pads` names. Returns what it ACTUALLY removed.

    `rmtree(ignore_errors=True)` swallows a failure, so appending unconditionally would
    print `removed orphaned lane pad X` about a pad still sitting on disk — the WI-0038
    shape, where a run that failed every operation and a run that worked print the same
    sentence. The existence check costs one stat and makes the line true; a pad that
    could not be removed is simply reported again by the next sweep."""
    removed: list[str] = []
    for pad in orphan_pads():
        shutil.rmtree(pad, ignore_errors=True)
        if not pad.exists():
            removed.append(pad.name)
    return removed


# ── Crash-safety reaper for orphaned terminal poga lanes (ADR-0060 Q5) ──────────
# A `poga` session runs alone in a linked worktree at `.claude/worktrees/<name>` on a
# `worktree-<name>` branch (Claude Code's older native worktrees used `claude/<name>`).
# When such a session dies mid-run — the crash class — it leaves an orphaned worktree
# dir + branch behind that no clean `WorktreeRemove` ever swept. `reap-lanes` is the
# sweep counterpart to `cmd_worktree_remove`: it enumerates the whole lane pool and,
# for each orphan, REAPS it iff its branch is merged into the trunk (or it has no
# branch — pure dir residue), and otherwise SURFACES it loudly. It never auto-discards
# or auto-merges unmerged work (that is a human call), and it never touches a live lane.

_LOCK_PID_RE = re.compile(r"\bpid\s+(\d+)\b")


def _tree_has_live_session(tree: Path) -> bool:
    """True iff `tree` has a PROVABLY live session right now — a `.live` sidecar with a
    beat fresher than HEARTBEAT_STALE_MIN and no clean-exit marker. Same evidence rule as
    `_live_same_tree_siblings`, applied to another worktree's sidecar dir. Errs toward
    True on any read failure: an undeterminable answer must not license writing into a
    tree someone may be working in."""
    try:
        state = tree / ".session-state"
        if not state.is_dir():
            return False
        for p in sorted(state.glob("*.live")):
            csid = p.stem
            if not csid or (state / f"{csid}.ended").is_file():
                continue
            data = json.loads(p.read_text(encoding="utf-8"))
            age = _iso_age_min(data.get("last_beat") or data.get("started"))
            if age is not None and age <= HEARTBEAT_STALE_MIN:
                return True
        return False
    except Exception:
        return True


# How far back along the trunk to look for the commit a stale checkout actually sits at.
# Generous enough to cover a checkout missed for weeks (one member's fell several lands and
# many files behind), bounded because this runs at every land and an unbounded walk over a
# long history would be a cost paid forever to answer a question that is almost always
# "it sits at the parent" ([P19](principles/master.md#p19--cap-what-can-run-away)).
CHECKOUT_BASE_SEARCH = 200

# ── the stale-materialization deadlock (2026-09-06, journal 20260906T1200Z-devbox-4513): stop SEARCHING for where the main checkout sits, and write it down ──
#
# Everything below `_checkout_sync_base` re-derives one fact on every land: which commit
# the main checkout's tree was last materialized at. It is derived by walking history and
# comparing trees, it is bounded, and — the part that matters — it FAILS OPEN, returning
# `parent` whenever the answer is not exact. That fallback is correct for a checkout with
# real local edits and wrong for a checkout that is merely behind, and the two are
# indistinguishable from the outside.
#
# The consequence was a DEADLOCK, and it is worth stating precisely because both halves
# look like good behaviour on their own. After a declined sync, main's tree holds the
# pre-land content of every path the land touched — stale copies of committed versions,
# reported by `git status` as dirt. `main-restore` repairs the AUTHORED half and hands the
# harness-written half (`session-handoff.md`, `STATUS.md`, `ROADMAP.md`, the journals) to
# `main-sync` by name. `main-sync` then refuses before it looks, because `_index_is_empty`
# is false — and a stale materialization IS a non-empty index. Neither verb is wrong.
# `main-sync` must never commit those paths: committing a stale handoff commits a REVERT of
# the version the trunk already holds, which is WI-0040 firing again through a sanctioned
# path. The only correct answer for a stale copy was never "commit it" or "keep it" but
# MATERIALIZE it, and nothing in the substrate did that.
#
# It also compounds. A partial repair leaves the tree matching no commit at all, so the
# search below falls to `parent` forever and every later land's `read-tree -m -u` reads the
# un-materialized gap as content the checkout owns and carefully protects — the exact shape
# WI-0133 fixed for the index, reappearing one layer out.
#
# So the materialization point becomes a RECORD rather than an inference. With it written
# down, "does this tree hold anything of its own?" has a definite answer, and the answer
# licenses the repair structurally: a tree byte-identical to a commit we ourselves put
# there cannot lose anything by being brought forward, so P9's confirm is discharged by
# construction rather than by a human's judgement in the moment — the same argument
# `_sync_main_checkout` already makes for its own cross-tree write.
#
# Per-tree and gitignored, like every other `.session-state/` resident: it describes THIS
# machine's checkout and must never travel.
MAIN_MATERIALIZED_FILE = "materialized-at.json"


def _tree_equals(main: Path, commit: str) -> bool:
    """Is `main`'s working tree byte-for-byte `commit`, with nothing of its own anywhere?

    Three witnesses, because any one of them alone is a lie in this neighbourhood:
    the INDEX against the commit (nothing staged of its own), the WORKING TREE against the
    index (nothing modified of its own), and no untracked files (nothing new of its own).
    `git status` is deliberately not the test, for the reason `_sync_main_checkout` gives at
    length: in exactly the condition being repaired, HEAD resolves through the advanced ref
    while the tree sits behind it, so status is loud and "clean tree" would never fire on
    the case it exists to handle."""
    if sh(["git", "-C", str(main), "diff", "--cached", "--quiet", commit],
          check=False).returncode != 0:
        return False
    if sh(["git", "-C", str(main), "diff", "--quiet"], check=False).returncode != 0:
        return False
    unt = sh(["git", "-C", str(main), "ls-files", "--others", "--exclude-standard"],
             check=False)
    return unt.returncode == 0 and not unt.stdout.strip()


def _main_holds_nothing_of_its_own(main: Path) -> tuple[bool, str]:
    """May `main`'s working tree be brought to the trunk tip without losing anything?
    `(safe, why)`.

    Three routes to yes, in descending order of certainty, and every one of them is a PROOF
    rather than a heuristic — a `False` costs one report line, a wrong `True` destroys work.

      1. The tree is clean. It is materialized at HEAD by definition; there is nothing to
         bring forward and nothing to lose.
      2. The tree equals the RECORDED materialization commit. The substrate put it there
         and wrote that down, so every difference from HEAD is the gap since.
      3. No record (or the tree has moved off it), but EVERY dirty path is provably a
         superseded committed version of that path — `_main_restore_verdict`'s question,
         asked of the whole dirty set instead of one file. Slower, and it is what makes the
         repair engage on a checkout that has never been recorded, which today is all of
         them.

    Route 3 is the reason this is not gated on the record existing. A fix that only works
    once the record exists would need one clean land to reach the exact checkouts that are
    too stale to get one — `ship-the-detector-with-the-capability`, read from the other end.

    ROUTE 3 WIDENS A BLAST RADIUS, and that is stated here rather than discovered later.
    Its predicate is ADR-0098's, unchanged — but ADR-0098 applies it when a human TYPES
    `main-restore`, and this applies it unattended at every session start. The case it can
    get wrong is narrow and real: someone standing in the main checkout who deliberately
    reverts a file to an older committed version, and changes nothing else, has produced a
    tree every one of whose differences is "a superseded committed version", and this will
    carry it forward. What bounds the harm is the predicate itself — the discarded content
    is by construction still reachable in git, which is exactly why ADR-0098 chose it over
    the weaker subset test — plus the standing policy that no session runs in main, and the
    live-session check above for when one does. The alternative is worse: gating on the
    record leaves every checkout that is ALREADY deadlocked deadlocked, since the deadlock
    is precisely what prevents it earning a record.
    """
    r = sh(["git", "-C", str(main), "status", "--porcelain"], check=False)
    if r.returncode != 0:
        return False, "git would not report on the main checkout"
    dirty = [l for l in (r.stdout or "").splitlines() if l.strip()]
    if not dirty:
        return True, "clean — materialized at HEAD by definition"
    recorded = _main_materialized_at(main)
    if recorded and _tree_equals(main, recorded):
        return True, (f"byte-identical to {recorded[:7]}, where the substrate recorded "
                      f"materializing it")
    for line in dirty:
        rel = _porcelain_rel(line)
        if rel is None:
            return False, f"a path that cannot be named with certainty: {line.strip()}"
        ok, why = _main_restore_verdict(main, rel, untracked=line.startswith("??"))
        if not ok:
            return False, f"{rel} — {why}"
    return True, (f"every one of its {len(dirty)} differing path(s) is byte-identical to a "
                  f"committed version of that path")


def _pid_alive(pid: int) -> bool:
    """True iff a process with `pid` exists on THIS machine. `os.kill(pid, 0)` raises
    ProcessLookupError when the pid is dead and PermissionError when it is alive but
    owned by another user (still alive). A stale pid from another machine may
    coincidentally match a live local process — that only makes the reaper MORE cautious
    (it skips a real orphan), never less: a live lane's own pid is always alive here, so
    liveness can never be mis-read as death, and a live lane can never be reaped."""
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except (OverflowError, ValueError, OSError):
        return False


# A lane must have been quiet this long before an automatic sweep may reap it. Sized to
# dwarf the only window it has to cover — the seconds between `poga` creating a worktree
# and that session taking its lock — so the guard costs nothing in practice (an abandoned
# lane is reaped an hour later instead of instantly) while making the birth race
# structurally impossible rather than avoided-by-surface (session 90).
LANE_REAP_MIN_AGE_MIN = 60
# How long after a lane is CREATED its liveness evidence may still be absent — the birth
# window, below which "no holder" has not yet earned the reading "free to enter" (WI-0258).
#
# DELIBERATELY NOT `LANE_REAP_MIN_AGE_MIN`, and the item is explicit that one fix must not
# be assumed to serve both. That guard prevents a DELETE, so an hour of over-caution costs
# nothing (an abandoned lane is reaped later). This one prevents an ENTRY, and every second
# of it is a refusal an operator waits out — so it is sized to the evidence, not padded to
# the largest number that is obviously safe.
#
# MEASURED, not picked. Across every locked lane live on one machine on 2026-09-04, the gap
# between a lane's registration (`.git/worktrees/<name>/` birth) and its `git worktree lock`
# was min 0.07s, median 0.08s, max 0.22s — Claude creates and locks the worktree in one
# breath, so the native path's window is a fifth of a second, not the "seconds" WI-0258
# assumed. The slower path is the supervised one: `git worktree add`, then two `session.py`
# invocations (an interpreter start and parse each, a fraction of a second even under many
# concurrent lanes) plus prep's own work, before `_supervise_loop`'s first beat. Thirty seconds clears
# every measured component by two orders of magnitude and the reasoned one by ten.
#
# The cost of being wrong is bounded and self-clearing in BOTH directions, which is what
# makes this the safe shape: too short and a launch race is answered "free" (the defect);
# too long and an operator waits at most this many seconds before the same lane answers
# honestly either way.
LANE_ENTER_MIN_AGE_SEC = 30
# A gate run is minutes at most (the suite plus three `--check`s). An hour of no writes is
# far past any live run and matches the lane threshold, so there is one number to reason
# about rather than two.
GATE_REAP_MIN_AGE_MIN = 60

# How long a LIVE lane may go without a heartbeat before its unlanded commits are worth
# telling somebody about (WI-0172). ADVISORY ONLY — nothing acts on this number. It
# decides one thing: whether a lane appears on a list, never whether a verb touches it.
#
# THE STATE IT NAMES has no verb and, before this, no surface either. A lane whose claude
# process is alive but which has been sitting at a prompt for hours holds its committed
# work where nothing can reach it: `_scan_lanes` classifies it `live`, which is correct
# and which every consumer honours by leaving it alone, so `reap-lanes` printed
# "protected", `recover-lanes` printed "nothing stranded", and the startup banner dropped
# it entirely (it is not `unmerged`, not `dirty`, and `_tree_has_live_session` is false
# for it, so it is not even on the `active:` line). Observed on poga-2, 2026-09-05: two
# commits, 2h18m of silence, three surfaces reporting a non-event.
#
# NOT the three thresholds already here, and each for its own reason:
#   * HEARTBEAT_STALE_MIN (15m) only ever proves LIFE, never death. A session between
#     turns goes quiet, and advising on it would make the row noise within one workday.
#   * REAP_CRASH_GRACE_MIN (48h) is sized for a DESTRUCTIVE call. Waiting two days to
#     mention a lane leaves the invisibility this exists to remove almost entirely intact.
#   * LAND_DEFER_GRACE_MIN (120m) is the same number for a reason — "silent this long
#     presumes abandonment, for reporting purposes only" is exactly the claim made here —
#     but it is a claim about WHOSE FILES a close may commit. Aliasing the two would mean
#     a later retune of one silently retunes the other, on a different subject.
# A separate name, and the same 2h, so each can move without the other.
#
# THE COST OF BEING WRONG IS SYMMETRIC AND CHEAP, which is what licenses a guess where the
# constants above are measured: too short and a working session sees one extra advisory
# line naming its own unlanded commits (true, if premature); too long and the work stays
# invisible a while longer. Neither outcome deletes or lands anything.
LANE_IDLE_ADVISORY_MIN = 120


# ── ADR-0089: a lane checkpoints its own work ───────────────────────────────────
# `record-end` deliberately did no git, so a lane that stopped without landing left
# uncommitted edits outside git indefinitely (one member's went invisible for over a week). A lane
# branch is private scratch, so committing there destroys nothing (P9) and preserves
# everything. The marker is the commit SUBJECT PREFIX — the mechanism must be able to
# recognise its own commits later without a sidecar that can drift from the history it
# describes.
CHECKPOINT_PREFIX = "wip(checkpoint):"


def _head_is_checkpoint(cwd: Path | None = None) -> bool:
    """True iff HEAD is a commit THIS mechanism made. Anchored on the subject prefix, so
    a hand-written commit that merely looks similar is not silently rewritten: the reset
    below moves a commit off the branch, and it must only ever move one of ours."""
    r = sh(["git", "log", "-1", "--format=%s"], check=False, cwd=cwd)
    return r.returncode == 0 and r.stdout.strip().startswith(CHECKPOINT_PREFIX)


_LOCK_PID_RE = re.compile(r"\bpid\s+(\d+)\b")


# ── Stranded lane PROCESSES ────────────────────────────────────────────────────
# The lane machinery reaps directories, branches, pads and claims. Nothing has ever
# looked at the thing that was *running* in the lane. Session ~124 found four Claude
# sessions still alive in lanes that no longer existed — one up 7 days 17 hours,
# dispatched on an item that had shipped in 6.1.0 — and the harness permission classifier
# refuses a bare `kill` from inside a session, so clearing them fell to operator by hand.
#
# THE PREDICATE IS NOT "does the lane directory exist". Lane names are RECYCLED (poga-1
# is reused the moment the old one is reaped), so a nine-day-old process naming `poga-1`
# sits beside a live session naming the same lane. Comparing the process's age against the
# lane directory's BIRTH time is what separates them — a process that predates the
# directory it claims to be working in cannot be that lane's session.
#
# The grace margin is load-bearing and was found by probing rather than by reasoning: the
# process that CREATES a lane necessarily starts before the directory exists. Measured
# live, this session's own pid started **one second** before its lane directory — so a
# naive "older than the lane" test would have reported the session running it as stranded.
LANE_PROCESS_BIRTH_GRACE_MIN = 60


def _parse_etime(s: str) -> int | None:
    """Seconds from `ps -o etime` (`[[dd-]hh:]mm:ss`). None if unparseable.

    `etime` rather than `lstart` deliberately: `lstart` renders day and month NAMES, so it
    is locale-dependent and would silently stop parsing under a non-English locale —
    producing "no stranded processes" rather than an error
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes))."""
    s = s.strip()
    if not s:
        return None
    days = 0
    if "-" in s:
        d, _, s = s.partition("-")
        if not d.isdigit():
            return None
        days = int(d)
    parts = s.split(":")
    if not all(p.isdigit() for p in parts) or not 2 <= len(parts) <= 3:
        return None
    nums = [int(p) for p in parts]
    while len(nums) < 3:
        nums.insert(0, 0)
    return days * 86400 + nums[0] * 3600 + nums[1] * 60 + nums[2]


LANE_PROC_RE = re.compile(r"(?:^|\s)--worktree\s+(\S+)")

LANE_PROC_CWD_CAP = 32
PROC_CWD_TIMEOUT_SEC = 2.0


def _process_cwd(pid: int) -> str | None:
    """The absolute working directory of `pid`, or None where it cannot be read.

    **This is the repo identity of a lane process, and nothing else supplies it** (WI-0135).
    `--worktree poga-2` in a process's argv names a lane but not the repo the lane belongs
    to, and `poga-1`/`poga-2` are the most common lane names on the machine — so a match on
    the name alone is a match against every member at once. The launcher sets the lane
    directory as the process's cwd, so cwd is what says *whose* lane it is.

    Deleted directories still answer, which is the property the whole `lane-gone` proof
    depends on: a process whose lane was removed out from under it keeps reporting the old
    path (verified on macOS against a live process whose cwd was `rmtree`'d), so gaining a
    repo check does not cost the one proof that has to survive it.

    `/proc` first (Linux, free), `lsof` second (macOS). Timeout-bounded and fail-safe: any
    error, timeout, or unparseable answer returns None, which the caller must treat as
    *unprovable* rather than as either "mine" or "not mine".

    UNDER THE GATE it is unprovable by construction (ADR-0119 D4): the process table is the
    operator's machine, not the commit being gated, and the existing None contract already
    means exactly what is true there — we cannot tell."""
    if _under_gate():
        return None
    with contextlib.suppress(Exception):
        link = Path("/proc") / str(pid) / "cwd"
        if link.is_symlink():
            return os.readlink(str(link))
    with contextlib.suppress(Exception):
        r = subprocess.run(["lsof", "-a", "-d", "cwd", "-p", str(pid), "-Fn"],
                           capture_output=True, text=True, check=False,
                           timeout=PROC_CWD_TIMEOUT_SEC)
        for line in (r.stdout or "").splitlines():
            if line.startswith("n") and line[1:2] == "/":
                return line[1:]
    return None


def _path_within(child: str | Path, parent: Path) -> bool:
    """True iff `child` is `parent` or sits underneath it, decided on the path strings.

    Deliberately not `Path.resolve()`d and deliberately not a filesystem question: the
    paths this compares routinely name directories that have been deleted (that is the
    `lane-gone` case), and `resolve()` on a missing path cannot follow symlinks anyway, so
    touching the disk here would buy nothing and would make the answer depend on whether
    the lane still exists. Never raises."""
    with contextlib.suppress(Exception):
        c, p = Path(child).parts, parent.parts
        return len(c) >= len(p) and c[:len(p)] == p
    return False


MAIN_DIRT_REPORT_CAP = 8

# How much of a kept file's diff `main-restore --show` prints. Bounded because the point is
# to let the call be made from the lane, not to page a whole file into a session's context
# ([P19](principles/master.md#p19--cap-what-can-run-away)); the elision is always reported,
# never silent.
MAIN_RESTORE_DIFF_LINES = 60


# ------------------------------------------------- harness-written records (ADR-0091)
# The substrate has always had WRITE paths into trees it then never committed — a lane's
# post-land addendum in the main checkout, a fleet janitor's close in a parked member —
# and the conversation layer reported the resulting dirt to the user at every session
# start. ADR-0091's rule is one sentence: the harness commits what the harness writes,
# and a dirty-tree warning names only AUTHORED work. The classifier below is the single
# definition of "what the harness writes"; both committers (the janitor's, for its own
# repo, and `main-sync`, for a lane acting on main) and the warning share it.

def _porcelain_rel(line: str) -> str | None:
    """The repo-relative path in one `git status --porcelain` line, or None when it
    cannot be named with certainty (renames, quoted paths). None is the safe answer —
    an unnameable path is treated as authored, and the harness never commits it."""
    body = line[3:] if len(line) > 3 else ""
    if not body or " -> " in body or body.startswith('"'):
        return None
    return body.strip() or None


def _harness_owned(rel: str) -> bool:
    """True iff `rel` (repo-relative, as porcelain prints it) is a record the HARNESS
    itself writes: a session journal, the compiled handoff, `STATUS.md`, `ROADMAP.md`.
    Everything else — code, ADRs, registries, briefs — is authored work and is never
    committed by machinery. Deliberately a closed list, not a pattern: an unknown path
    defaulting to "harness-owned" would let the sweep commit exactly the files it must
    never touch."""
    try:
        if rel in _trunk_only_views():
            return True
        jdir = _journal_dir_rel().as_posix().rstrip("/") + "/"
        return rel.startswith(jdir) and rel.endswith(".md")
    except Exception:
        return False


def _classify_dirt(dirty: list[str]) -> tuple[list[str], list[str]]:
    """Split porcelain lines into (harness-owned paths, authored/unknown lines)."""
    harness, authored = [], []
    for line in dirty:
        rel = _porcelain_rel(line)
        if rel is not None and _harness_owned(rel):
            harness.append(rel)
        else:
            authored.append(line)
    return harness, authored


def _index_is_empty(tree: Path) -> bool:
    """True iff `tree`'s index holds nothing beyond its HEAD. Anything staged means the
    tree is mid-something — a stale checkout's phantom reversal (the c8edc02 defect: a
    bare commit shipped the whole index), or a human's half-staged work — and machinery
    must not commit there at all, pathspecs or no. Errs toward False on any failure."""
    r = sh(["git", "-C", str(tree), "diff", "--cached", "--quiet"], check=False)
    return r.returncode == 0


def _commit_harness_paths(tree: Path, paths: list[str], message: str) -> tuple[bool, str]:
    """Stage exactly `paths` in `tree` and commit the index. NOT a pathspec'd commit,
    deliberately: `git commit -- <path>` builds from the WORKTREE state of the named
    paths, so a path whose staged state is a deletion (the D1 `rm --cached` migration —
    the sidecar files still exist on disk, now ignored) would be quietly re-added by the
    very commit meant to untrack it (proven by test_untracks_the_sidecar_and_ignores_it
    against the pathspec form). Both callers verify the index is EMPTY before staging,
    so the index here holds only what this function put in it — and that is re-verified
    structurally below: every staged path must fall under `paths`, or nothing is
    committed. The add is per-path and tolerant: a path that will not stage (ignored
    after the migration; its removals are already in the index) must not abort the
    rest. Returns (committed, detail)."""
    for p in paths:
        sh(["git", "-C", str(tree), "add", "--", p], check=False)
    staged = sh(["git", "-C", str(tree), "diff", "--cached", "--name-only"], check=False)
    staged_paths = [l for l in (staged.stdout or "").splitlines() if l.strip()]
    if not staged_paths:
        return False, "nothing to commit"
    covered = tuple(p.rstrip("/") for p in paths)
    stray = [s for s in staged_paths
             if not any(s == c or s.startswith(c + "/") for c in covered)]
    if stray:
        return False, f"index holds paths outside the sweep set ({stray[0]}) — refusing"
    c = sh(["git", "-C", str(tree), "commit", "-m", message], check=False)
    if c.returncode != 0:
        return False, (c.stderr or c.stdout).strip()[:200]
    return True, ""


def _main_harness_sweep(dry_run: bool = False) -> dict:
    """From a lane, commit in the MAIN checkout exactly the harness-written records left
    there (ADR-0091 D3) — the sanctioned form of the repair that previously needed
    the operator's shell (WI-0097). Preconditions mirror the land path's cross-tree writes:
    main resolvable and not this tree, HEAD on the trunk, an empty index, and no
    provably-live session. Mixed dirt commits only the harness subset; authored files
    are left alone and stay the user-facing signal. Fail-open, never raises."""
    out = {"committed": [], "authored": [], "skipped": "", "dry_run": bool(dry_run)}
    try:
        if not _on_worktree_lane():
            out["skipped"] = "not on a worktree lane"
            return out
        main = _main_checkout()
        if main is None or main == ROOT.resolve() or not (main / ".git").exists():
            out["skipped"] = "main checkout not locatable from here"
            return out
        trunk = _trunk()
        head = sh(["git", "-C", str(main), "symbolic-ref", "--quiet", "HEAD"], check=False)
        if head.stdout.strip() != f"refs/heads/{trunk}":
            out["skipped"] = (f"main is on '{head.stdout.strip() or 'detached'}', "
                              f"not {trunk}")
            return out
        if _tree_has_live_session(main):
            out["skipped"] = "a session is live in the main checkout"
            return out
        if not _index_is_empty(main):
            out["skipped"] = ("main's index is not empty — mid-flight or stale state; "
                              "not committing anything there")
            return out
        r = sh(["git", "-C", str(main), "status", "--porcelain"], check=False)
        if r.returncode != 0:
            out["skipped"] = "git would not report main's status"
            return out
        dirty = [l for l in (r.stdout or "").splitlines() if l.strip()]
        harness, authored = _classify_dirt(dirty)
        out["authored"] = authored
        if not harness:
            return out
        if dry_run:
            out["committed"] = harness
            return out
        ok, detail = _commit_harness_paths(
            main, harness,
            "chore(session): sweep harness-written records left by lane activity "
            "(ADR-0091)")
        if not ok:
            out["skipped"] = detail
            return out
        out["committed"] = harness
        try:
            state = main / ".session-state"
            state.mkdir(exist_ok=True)
            with (state / "janitor.jsonl").open("a", encoding="utf-8") as fh:
                fh.write(json.dumps({"at": _now_iso(), "main_sweep": harness},
                                    ensure_ascii=False) + "\n")
        except Exception:
            pass
    except Exception as exc:
        out["skipped"] = f"{type(exc).__name__}: {exc}"
    return out


def _main_harness_sweep_auto() -> None:
    """The first-heartbeat caller (ADR-0091 D3) — the ADR-0055 materialization point, so
    a phantom SessionStart still writes nothing anywhere. Swallows everything: a sweep
    hiccup must never fail a session start."""
    try:
        _main_harness_sweep(dry_run=False)
    except Exception:
        pass


def _fs_birthtime(path: Path) -> float | None:
    """`st_birthtime` for `path`, or None where the platform does not expose it. A named
    function rather than an inline `getattr` so a test can simulate the Linux case, which
    is otherwise unreachable on the machine this is developed on — the gap that would
    otherwise ship untested to exactly the members it affects."""
    with contextlib.suppress(OSError):
        b = getattr(path.stat(), "st_birthtime", None)
        if b:
            return float(b)
    return None


def _stranded_process_lines() -> list[str]:
    """Orientation lines naming stranded lane processes. Reports; never kills — the sweep
    verb is `reap-lanes --processes`, run deliberately (P9)."""
    procs, unprovable = _classify_lane_processes()
    lines = []
    # Printed even when nothing is proven. A member whose filesystem answers no birth
    # question would otherwise read "no stranded processes" for the harder half of the
    # class forever — absence of a check rendering as absence of a problem. The two causes
    # get their own sentences: they are different ignorances, they were not checked to
    # different depths, and collapsing them would re-create the very thing
    # `declare-what-a-check-assumes` exists to stop.
    no_birth = [p for p in unprovable if p.get("unprovable_cause") != "repo-unknown"]
    no_repo = [p for p in unprovable if p.get("unprovable_cause") == "repo-unknown"]
    if no_birth:
        lines.append(f"stranded: {len(no_birth)} lane process(es) NOT CHECKED for the "
                     f"recycled-name case — no creation time available for their lanes "
                     f"(neither st_birthtime nor a git registration record). The "
                     f"lane-gone check still ran.")
    if no_repo:
        lines.append(f"stranded: {len(no_repo)} lane process(es) NOT CHECKED at all — "
                     f"their working directory could not be read, so it is unknown "
                     f"whether they belong to this repo. NEITHER check ran for them; "
                     f"they are not counted as stranded and will not be reaped.")
    if not procs:
        return lines
    for p in procs:
        why = ("its lane directory no longer exists" if p["reason"] == "lane-gone"
               else f"it predates the current {p['lane']} by more than "
                    f"{LANE_PROCESS_BIRTH_GRACE_MIN}m — an earlier lane of the same name")
        lines.append(f"stranded: pid {p['pid']} ({p['lane']}, up "
                     f"{p['age_sec'] // 3600}h{p['age_sec'] % 3600 // 60:02d}m) — {why}.")
    lines.append(f"stranded: {len(procs)} process(es) holding nothing reachable. "
                 f"Clear them: `python3 session.py reap-lanes --processes`.")
    return lines


PROC_SIGNAL_GRACE_SEC = 3.0


def _pid_alive(pid: int) -> bool:
    """Signal 0 asks the kernel whether the pid exists without delivering anything. A
    `PermissionError` means it exists and is not ours — alive, and honestly so."""
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True


# Gitignored paths a LANE must see the MAIN checkout's copy of. A git worktree
# materializes TRACKED files only, so everything here is simply absent in a lane
# (session 90: a lane opened announcing `inbox: (empty)` while two briefs were pending,
# one of them time-boxed — the harm was the silence, not the absence).
#
# Deliberately NOT here: `.session-state/`. That sidecar is per-tree BY DESIGN — it is
# what makes a lane invisible to its siblings, and ADR-0062 had to put coordination in
# the git common dir precisely because of it. Sharing it would break isolation.
# Also absent: derived/ephemeral output (`curate-runs/`, `EVIDENCE.md`, `__pycache__/`),
# which is correct to regenerate per lane.
SHARED_LANE_PATHS = [
    "proposed-edits",        # the receipt-ritual inbox — a brief applied in one lane is applied for all
    "users",                 # the user profile: behaviour-shaping, must not vary by lane
    "inputs",                # upstream mirrors of other systems
    "architect-learnings.md",  # the producer file (append-only)
    "reconcile-roots.local",   # machine-local config (P3)
    "repo-paths.local",
]


def _link_shared_data() -> None:
    """SYMLINK the shared gitignored data into this lane, so a lane sees one copy rather
    than none (session 90).

    Symlinks, not copies: a copy is a second source that drifts, which is the exact
    failure [P16](principles/master.md#p16--avoid-duplication) names. A link means reads
    AND writes reach the main checkout's single copy, so a brief filed `pending/` ->
    `applied/` from a lane is filed for everyone.

    Only links a path that EXISTS upstream and is ABSENT here — never replaces anything
    the lane already has, and never creates an empty shell for a path the system doesn't
    use (members carry different gitignored sets; a fresh Architect has no `inputs/`).
    Idempotent, no-ops outside a lane, and never raises: this rides the start hook, and a
    linking hiccup must not break the session it rides on.
    """
    try:
        if not _on_worktree_lane():
            return
        main = _main_checkout()
        if main is None or main == ROOT.resolve():
            return
        for rel in SHARED_LANE_PATHS:
            src, dst = main / rel, ROOT / rel
            if not src.exists() or dst.exists() or dst.is_symlink():
                continue
            try:
                dst.symlink_to(src, target_is_directory=src.is_dir())
            except OSError:
                continue                      # one bad link must not stop the rest
    except Exception:
        pass


def _mark_nc(text: str, prev: dict) -> str:
    """Tag the orphan entry CORRUPT and its SESSION LOG row `<n>NC` (NC does not
    burn the counter). The surgery is CODE, not LLM text-editing of the parsed
    handoff — the error class this harness exists to prevent (ADR-0036 / P15)."""
    lines = text.splitlines()
    i = prev["header_index"]
    num = prev["number"]
    lines[i] = re.sub(r"— Session " + re.escape(num) + r" —",
                      f"— Session {num}NC —", lines[i])
    for j in range(i + 1, len(lines)):
        if ENTRY_RE.match(lines[j]):
            break
        if lines[j].startswith("**Start:**"):
            lines.insert(j + 1, "**CORRUPT:** orphan — no end stamp; marked NC at start.")
            break
    for k, line in enumerate(lines):
        rm = ROW_RE.match(line)
        if rm and rm.group(1) == num and not rm.group(2):
            lines[k] = re.sub(r"^\| *" + re.escape(num) + r" ",
                              f"| {num}NC ", line, count=1)
            break
    return "\n".join(lines) + "\n"


# ── the test verdict, as a verb (WI-0139) ───────────────────────────────────────

# unittest writes its summary to STDERR. Every failure in this class began by losing
# that stream: capturing stdout only (~129), merging it into stdout through a pipe so
# the block-buffered stdout REORDERED around the unbuffered stderr (~134), or reading a
# pipeline's exit code — `tail`'s, not the suite's — as the verdict (~148). All three
# reported a suite green that had never reported at all.
#
# So: two separate FILES, no pipe, no merge. The verdict is parsed from stderr alone,
# where fixture stdout — which prints the substrate's own real banners from a temp repo
# and reads exactly like a live land — cannot reach it.
TEST_RAN_RE = re.compile(r"^Ran (\d+) tests? in .*$", re.M)
# The verdict shapes unittest actually emits — `OK`, `OK (skipped=2)`,
# `FAILED (failures=1, errors=2)` — and nothing else. Anchored whole-line so the
# fixture banner `OK — all 1 index(es) match ...` cannot be read as a verdict even
# if it landed in the one position where a verdict belongs.
TEST_OK_RE = re.compile(r"^OK(?: \([^)]*\))?$")
TEST_FAILED_RE = re.compile(r"^FAILED \([^)]*\)$")


# ── Machine preflight (WI-0149) ───────────────────────────────────────────────────
# A fresh machine does not fail once. It fails one precondition at a time, each one
# discovered by operator hitting it in his own terminal and the Architect diagnosing it
# afterward — four walls in one hour standing a machine up (session ~161), three of which
# ended with a command in his shell. That is the exact pattern the 2026-08-19 consultant
# brief says must stop being individually regrettable and start being structurally
# impossible.
#
# The walls, and why each is checkable BEFORE it is hit:
#   1. TERMINFO   — devbox had no entry for xterm-ghostty/kitty/wezterm/alacritty. The
#                   missing `kbs` meant backspace did nothing, and the absent width data
#                   made pastes RENDER truncated while the buffer was intact. Nothing
#                   errors; the terminal just lies to you.
#   2. TRUST      — poga delegates lane creation to `claude --worktree`, which refuses
#                   with "Workspace trust not yet accepted". Nothing checked it, so it
#                   surfaced as a failed poga launch rather than as the dialog it is.
#   3. ONBOARDING — `~/.claude.json` with `hasCompletedOnboarding` absent runs the
#                   first-run wizard, whose login step opens a browser on a headless host
#                   even when `claude auth status` already says loggedIn.
#   4. STRANDED   — a probe `claude auth login` outlived its TaskStop by 30 minutes,
#                   because killing the local ssh client does not kill the remote process.
#                   A second auth flow was open on the machine while operator started his own.
#
# TWO RULES THIS VERB IS BUILT AROUND.
#
# It never folds "could not check" into a pass. Every check returns one of OK / FAIL /
# UNKNOWN, and UNKNOWN prints its own sentence saying what it could not determine
# (`declare-what-a-check-assumes`). The failure this prevents is the one that made these
# four walls expensive in the first place: a not-applicable branch that reads as a pass
# does not merely fail to detect a gap, it certifies one.
#
# It is NOT on the startup path. operator vetoed network probes at session start,
# and two of these checks (auth, gate) are slow or reach the network. They belong behind
# an explicit verb, run when you are standing a machine up — not paid by every session.

PREFLIGHT_OK = "OK"
PREFLIGHT_FAIL = "FAIL"
PREFLIGHT_UNKNOWN = "UNKNOWN"
PREFLIGHT_SKIPPED = "SKIPPED"

# Capability names a terminfo entry must carry for the terminal to behave. `kbs` is the
# one that bit devbox (backspace). Checked BY NAME rather than by "does infocmp exit 0",
# because an entry can resolve and still be the wrong entry.
PREFLIGHT_TERM_CAPS = ("kbs",)

PREFLIGHT_AUTH_TIMEOUT = 20
PREFLIGHT_PS_TIMEOUT = 10

PREFLIGHT_BYPASS_ENV = "POGA_SKIP_PREFLIGHT"

# ── WI-0398: memory pressure — telling a THRASHING machine from a busy one ─────────
#
# THE FAILURE IT GUARDS (WI-0398). A long-running system daemon can grow to a large share
# of RAM at well over 100% CPU, with swap near its full size and almost no free pages.
# Every gate then pages to disk, the load average reads very high with a handful of
# processes, and a lane can sit unable to land for hours. A reboot clears it.
#
# LOAD AVERAGE DOES NOT DISCRIMINATE, and that is the whole reason this is a refusal
# rather than a dashboard. A machine at high load running several real suites and a
# machine at the same load thrashing behind a runaway daemon are the same reading, and only
# the second one is unfixable by waiting. Without this guard a session has no signal that
# says "stop, this is not your work queue".
#
# THE TWO READINGS THESE THRESHOLDS ARE DESIGNED TO SEPARATE, on one machine:
#
#   bad    swap used near all of RAM; one system daemon holding a large share of RAM.
#   good   swap used = 0%; worst system daemon = 1.2% of RAM; largest live session well
#          under 1% of RAM; moderate load with several live sessions and lanes working.
#
# The good reading IS the negative control, and note that it carries real load. An
# ordinarily busy machine must not be refused: this guard sits in front of every launch
# and every parallel wave, and one false refusal is how a guard gets deleted.
#
# BOTH THRESHOLDS ARE FRACTIONS OF PHYSICAL MEMORY, never absolute byte counts. The fleet
# runs on boxes of different sizes and a given amount of swap does not mean the same thing on each;
# a constant picked on this box would arrive on another as either a dead check or a false
# refusal. Each fraction sits an order of magnitude above the good reading and a factor of
# 2-4 below the bad one, so neither measurement is anywhere near the line.
SWAP_REFUSE_FRACTION = 0.25          # good 0% · bad 98%
DAEMON_RSS_FLOOR_FRACTION = 0.125    # healthy is a few percent

# The daemon clause is an AND, and the floor above is the half that keeps it honest. The
# item's rule is "a system daemon holds more RSS than the session would" — but on an idle
# machine with no session running, *every* comparison against a session is trivially won
# and a 300 MB indexer would be refused. So an offender must beat BOTH the largest live
# session on this machine AND the floor. A runaway daemon beats both the
# largest live session and the floor by a wide margin; the ordinary worst daemon beats
# neither.
#
# `sysctl` and `ps` are both local reads of this machine's own kernel state; expected to
# cost on the order of 10 ms for the pair, which is what earns this check a place in the
# launch-gate subset where auth (network, 20 s timeout) and the land gate (~90 s) are
# refused entry on cost.
PREFLIGHT_SYSCTL_TIMEOUT = 5

# ── Repair (WI-0150 / ADR-0109) ───────────────────────────────────────────────────
# ADR-0096 shipped the report and said so in its own Consequences: nothing fixes what it
# finds, and every remedy is still a command in the operator's terminal. His ruling closing that
# gap (2026-09-04) is broader than this verb — preflight, git and lane problems are fixed
# by the system and work carries on, rather than being reported to him — so preflight, repository
# state and lane state are the substrate's own housekeeping, repaired automatically as
# the DEFAULT with the cautious path as an opt-out. This file is the first build of that
# pattern and the one the rest of the class copies, so the shape matters more than the
# one check it currently repairs.
#
# THE SHAPE, in four rules:
#
#   1. REPAIR IS THE DEFAULT, never an opt-in. `--fix` as WI-0150 originally proposed it
#      is an opt-in, and an opt-in fix leaves the errand exactly where it was for anyone
#      who does not know to type it. The flags run the other way: `--no-repair` on the
#      verb, POGA_NO_PREFLIGHT_REPAIR=1 on the gate.
#   2. EVERY CHECK DECLARES ITS CLASS. A check with no entry in PREFLIGHT_REPAIRS is a
#      hard error at import, not a silent NONE — a repairable check that nobody wired up
#      would otherwise read as unrepairable forever, which is the same
#      absent-reads-as-answered failure the verdict split exists to prevent.
#   3. A REPAIR IS ONLY DONE WHEN THE CHECK RE-RUNS OK. `tic` exiting 0 having installed
#      a wrong entry is precisely the wrong-answer-shaped-like-a-right-one this verb
#      exists to stop, so the repair's own exit code is never the receipt
#      (`a-close-is-the-banner-not-the-sentence`).
#   4. ESCALATE ONLY AFTER TRYING. What reaches the operator is "I tried and could not,"
#      never "here is what I found" — so a residual remedy carries the attempt that
#      failed, not just the wall.

REPAIR_AUTO = "auto"        # the substrate performs it: local, non-destructive, verifiable.
REPAIR_GUIDED = "guided"    # another product's own interaction; we can only LAUNCH it.
REPAIR_NONE = "none"        # no repair exists at this layer, and the reason is stated.

PREFLIGHT_NO_REPAIR_ENV = "POGA_NO_PREFLIGHT_REPAIR"


def _terminfo_dest() -> Path:
    """Where `tic` will write. `$TERMINFO` wins if set — honouring it is what lets the
    tests exercise a real install without touching the developer's own database."""
    t = os.environ.get("TERMINFO", "").strip()
    return Path(t) if t else Path.home() / ".terminfo"


def _terminfo_source_dbs() -> list[Path]:
    """Local terminfo databases that might carry the missing entry, best-first.

    THE DESTINATION IS NEVER A SOURCE (ADR-0109 D4). `~/.terminfo` is where the repair
    writes, and the check only failed because what is there is absent or broken — so
    reading the entry back out of it would reinstall the broken entry and then confirm
    success. Excluded by resolved path, so a `$TERMINFO_DIRS` that names it under another
    spelling is excluded too.

    WI-0150 assumed this list had to be a REACHABLE PEER MACHINE. It does not, and on
    devbox it could not be: there is no ssh alias to a peer at all. The entry that
    actually bit devbox in session ~161 — `xterm-ghostty` — ships inside the terminal
    emulator's own app bundle, so the file the old remedy sent operator to another machine
    for was in /Applications on the machine he was standing at."""
    out: list[Path] = []
    for raw in (os.environ.get("TERMINFO_DIRS") or "").split(":"):
        if raw.strip():
            out.append(Path(raw.strip()))
    out += [Path("/opt/homebrew/opt/ncurses/share/terminfo"),
            Path("/usr/local/opt/ncurses/share/terminfo"),
            Path("/usr/share/terminfo"),
            Path("/usr/lib/terminfo")]
    # A terminal emulator ships the entry for its own $TERM; nothing else reliably does.
    out += sorted(Path("/Applications").glob("*.app/Contents/Resources/terminfo"))
    try:
        dest = _terminfo_dest().resolve()
    except Exception:
        dest = _terminfo_dest()
    seen: set[Path] = set()
    keep: list[Path] = []
    for p in out:
        try:
            rp = p.resolve()
        except Exception:
            continue
        if rp == dest or rp in seen or not p.is_dir():
            continue
        seen.add(rp)
        keep.append(p)
    return keep


# The GUIDED class. Workspace trust, onboarding and live auth are all `claude`'s own
# first-run state, and writing ~/.claude.json behind its back is forging another
# product's state file — a fix that works until the format changes. What we CAN do is
# stop printing the step and run it: all three are settled by one interactive `claude`
# in the main checkout, so the substrate spends the operator's attention once instead of
# handing back three commands across two machines.
PREFLIGHT_GUIDED_CHECKS = ("workspace-trust", "onboarding", "auth")


def _repair_claude_first_run(results: list[_PreflightResult]) -> tuple[bool, str]:
    """Hand the terminal to `claude` once, in the main checkout, so the dialog the
    operator would have been told to go and find appears in front of them instead.

    The MAIN checkout, not this lane: poga cds to the repo root and asks the runtime to
    make the worktree from there, so that is the path whose trust state decides whether a
    lane can be created (`_pf_workspace_trust` says the same about the check)."""
    if shutil.which("claude") is None:
        return False, "`claude` is not on PATH, so there is no first-run to complete"
    failed = {r.name for r in results
              if r.verdict == PREFLIGHT_FAIL and r.name in PREFLIGHT_GUIDED_CHECKS}
    if not failed:
        return False, "nothing in the guided class failed"
    root = str(_shared_work_root())
    # Auth alone is a login; trust or onboarding means the first-run wizard, which walks
    # the login step itself — so one invocation covers whichever combination failed.
    if failed == {"auth"}:
        argv, what = ["claude", "auth", "login"], "the login flow"
    else:
        argv, what = ["claude"], "the first-run/trust dialog"
    print(f"preflight: {', '.join(sorted(failed))} needs {what}; opening it in {root} "
          f"now. Answer it and quit `claude` to continue.", file=sys.stderr)
    try:
        subprocess.run(argv, cwd=root)
    except Exception as e:
        return False, f"could not launch `{argv[0]}` ({type(e).__name__})"
    return True, f"ran `{' '.join(argv)}` in {root}"


def _repair_kind(name: str) -> str:
    """The declared class, or REPAIR_NONE for a check nobody wired up. The narration says
    an undeclared check is a defect; this keeps the control flow from treating it as a
    repairable one on the strength of a missing entry."""
    spec = PREFLIGHT_REPAIRS.get(name)
    return spec.kind if spec else REPAIR_NONE


# ── WI-0100: post-close work has a verb, and the close stays irreversible ────────
#: Heading of an addendum block inside a closed journal. Stable and greppable — the
#: compiled handoff inlines the journal body verbatim, so this string is what a reader
#: (and a future miner) keys on to see that work continued after the close.
ADDENDUM_HEADING = "## Addendum"


def _resolve_orphan_candidates() -> list[tuple[Path, dict]]:
    """Every open journal that is NOT this session's own.

    The live session is excluded structurally rather than by care: `resolve-orphan`
    exists to close a session that is over, and the one journal guaranteed not to be
    over is the one this process is writing. Stamping it would publish an end for a
    session that then keeps working — the mirror of the falsehood `journal-title`
    already refuses in the other direction."""
    holder = _find_holder_journal()
    holder_id = (holder[1].get("session-id") or "") if holder else ""
    return [(p, fm) for p, fm in _open_journals_in(JOURNAL_DIR)
            if fm.get("session-id") != holder_id]

# --- no-compound-bash structural guard -------------------------------------
#
# Git subcommands that mutate repository state. The guard denies ALL top-level
# compounds; this set only refines the *message* — a chain that includes one of
# these gets the git-specific wording (git add / commit / push must be separate
# Bash calls), while other chains get the generic no-compound-bash message.
# Read-only subcommands (status, log, diff, show, branch-listing, …) are absent
# because they don't change the wording, NOT because such chains are allowed —
# `git status; git log` is still denied, just with the generic message.
GIT_MUTATING = frozenset({
    "add", "commit", "push", "pull", "fetch", "merge", "rebase", "reset",
    "checkout", "restore", "stash", "switch", "cherry-pick", "revert",
    "rm", "mv", "tag", "apply", "am", "clean", "branch",
})

# git global options that consume a following argument (so the subcommand token
# isn't mistaken for their value): `git -C path commit`, `git -c k=v push`, …
_GIT_OPTS_WITH_ARG = frozenset({
    "-C", "-c", "--git-dir", "--work-tree", "--namespace", "--exec-path",
})
# command prefixes that wrap the real command without changing its identity.
_CMD_PREFIXES = frozenset({"sudo", "command", "time", "nice", "env", "builtin", "exec"})
_ENV_ASSIGN_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=")


def top_level_segments(cmd: str) -> list[str]:
    """Split a shell command into its top-level segments.

    Splits on `;`, `&&`, `||`, `|` (and `|&`), and bare newlines, but ONLY when
    they sit at the top level — never inside single/double quotes, `$(...)` /
    backtick command substitution, `(...)` subshells, or heredoc bodies. This is
    what lets a commit message that itself contains `;`/`&&` (including a
    multi-line `"$(cat <<'EOF' … EOF)"`) stay a single segment.

    THE PIPE IS A SEPARATOR SINCE WI-0344, and it moved all four callers in the
    safe direction. A pipeline's later stages are now segments of their own, so
    `echo x | git -C /other reset --hard` reaches the destructive-git guard (it
    did not before — token 0 of the whole string was `echo`, so `git_argv`
    returned None and the reset was invisible), and `git status | sh` stops
    auto-approving as "a safe git op". `safe_git_auto_allow` carries the one
    allowance that keeps `<safe git> | head` on its fast path.

    Not a full shell parser. On malformed/ambiguous nesting it degrades toward
    *fewer* splits (one big segment), i.e. toward allowing — the safe direction
    for a guard that hard-denies, and still the safe direction for the pipe rule,
    where a missed split can only mean a missed deny.
    """
    return [seg for seg, _ in _split_top_level(cmd)]


def _split_top_level(cmd: str) -> list[tuple[str, str]]:
    """`top_level_segments`, but each segment paired with the SEPARATOR that
    follows it — one of `&&` `||` `;` `|` `|&` `\n`, or `""` for the last one.

    Three of the four guards want the flat view and get it from the wrapper
    above. The separator matters to exactly one of them, because whether a run's
    exit status survives depends entirely on what comes after it: `&&` preserves
    a failure (a non-zero left side short-circuits) while `|`, `;`, `||` and a
    newline all replace it with the next command's. See `false_green_violation`.
    """
    segs: list[tuple[str, str]] = []
    buf: list[str] = []
    stack: list[str] = []      # 'sq' | 'dq' | 'paren' | 'btick'
    heredocs: list[str] = []   # delimiters whose bodies are still to be consumed
    i, n = 0, len(cmd)

    def flush(sep: str = "") -> None:
        s = "".join(buf).strip()
        if s:
            segs.append((s, sep))
        buf.clear()

    while i < n:
        c = cmd[i]
        top = stack[-1] if stack else None

        # Single quotes: everything literal until the closing quote (no escapes).
        if top == "sq":
            buf.append(c)
            if c == "'":
                stack.pop()
            i += 1
            continue

        # Backslash escapes the next char everywhere except inside single quotes.
        if c == "\\" and i + 1 < n:
            buf.append(cmd[i:i + 2])
            i += 2
            continue

        # Double quotes: `"` closes; `` ` `` and `$(` still open nested contexts.
        if top == "dq":
            if c == '"':
                stack.pop()
            elif c == "`":
                stack.append("btick")
            elif c == "$" and i + 1 < n and cmd[i + 1] == "(":
                stack.append("paren")
                buf.append("$(")
                i += 2
                continue
            buf.append(c)
            i += 1
            continue

        # Backticks: literal until the closing backtick.
        if top == "btick":
            buf.append(c)
            if c == "`":
                stack.pop()
            i += 1
            continue

        # --- here we are at TOP level or inside a paren/$() subshell ---
        # Lexical openers/closers tracked in both contexts (nesting must balance).
        if c == "'":
            stack.append("sq")
            buf.append(c)
            i += 1
            continue
        if c == '"':
            stack.append("dq")
            buf.append(c)
            i += 1
            continue
        if c == "`":
            stack.append("btick")
            buf.append(c)
            i += 1
            continue
        if c == "$" and i + 1 < n and cmd[i + 1] == "(":
            stack.append("paren")
            buf.append("$(")
            i += 2
            continue
        if c == "(":
            stack.append("paren")
            buf.append(c)
            i += 1
            continue
        if c == ")":
            if stack and stack[-1] == "paren":
                stack.pop()
            buf.append(c)
            i += 1
            continue

        # Heredoc start (`<<WORD` / `<<-WORD` / `<<'WORD'`), top level only. A
        # `<<<` here-string is not a heredoc — consume all three chars, or the
        # trailing `<<` gets re-scanned as a heredoc opener and a quoted
        # here-string word (`<<<"a;b"`) false-splits on its own content.
        # Inside a subshell we don't track the body — that only risks a missed
        # split, never a false split.
        if not stack and cmd[i:i + 2] == "<<":
            if cmd[i:i + 3] == "<<<":
                buf.append("<<<")
                i += 3
                continue
            j = i + 2
            if j < n and cmd[j] == "-":
                j += 1
            while j < n and cmd[j] in " \t":
                j += 1
            quote = ""
            if j < n and cmd[j] in ("'", '"'):
                quote = cmd[j]
                j += 1
            ds = j
            while j < n and (cmd[j].isalnum() or cmd[j] in "_-."):
                j += 1
            delim = cmd[ds:j]
            if quote and j < n and cmd[j] == quote:
                j += 1
            if delim:
                heredocs.append(delim)
            buf.append(cmd[i:j])
            i = j
            continue

        # Newline at top level: if heredocs are pending, swallow their bodies
        # (everything up to and including each delimiter line) before treating a
        # later newline as a separator.
        if c == "\n" and not stack:
            if heredocs:
                buf.append(c)
                i += 1
                while heredocs:
                    delim = heredocs.pop(0)
                    while i < n:
                        nl = cmd.find("\n", i)
                        end = nl + 1 if nl != -1 else n
                        line = cmd[i:nl] if nl != -1 else cmd[i:]
                        buf.append(cmd[i:end])
                        i = end
                        if line.strip() == delim or nl == -1:
                            break
                continue
            flush("\n")
            i += 1
            continue

        # Separators at top level. `&&`/`||` are matched before the bare `|` or
        # the two-char `|&`, so the first `|` of an `||` is never eaten as a pipe.
        if not stack:
            if cmd[i:i + 2] in ("&&", "||"):
                flush(cmd[i:i + 2])
                i += 2
                continue
            if c == ";":
                flush(";")
                i += 1
                continue
            if cmd[i:i + 2] == "|&":
                flush("|&")
                i += 2
                continue
            if c == "|":
                flush("|")
                i += 1
                continue

        buf.append(c)
        i += 1

    flush()
    return segs


def git_subcommand(segment: str) -> str | None:
    """Return the git subcommand in a single segment, or None if it isn't a git
    invocation (or is a bare `git` with no subcommand)."""
    argv = git_argv(segment)
    return argv[0] if argv else None


# Destructive git operations, keyed by subcommand -> predicate over the tokens
# that FOLLOW the subcommand. Mirrors the settings.json deny-list, but classified
# after `git_argv` strips `-C <path>`/wrappers, so the guard catches the same
# operation regardless of a `git -C <repo> …` prefix. Predicates are total and
# side-effect-free. See confirm-destructive-ops (P9) / add-structural-guard-on-recurrence.
def _destructive_git_hit(sub: str, rest: list[str]) -> str | None:
    flags = set(rest)
    if sub == "push":
        if flags & {"--force", "-f", "--force-with-lease", "--mirror", "--delete"}:
            return "force / mirror / delete push"
        if any(a.startswith(":") for a in rest):
            return "ref-delete push (`push … :branch`)"
    elif sub == "reset":
        if flags & {"--hard", "--keep"}:
            return "reset --hard/--keep (discards working-tree/index state)"
    elif sub == "branch":
        if "-D" in flags or ("--force" in flags and (flags & {"-d", "--delete"})):
            return "force branch delete"
    elif sub == "rebase":
        if flags & {"-i", "--interactive", "--onto"}:
            return "interactive/onto rebase (history rewrite)"
    elif sub in ("filter-branch", "filter-repo"):
        return f"{sub} (history rewrite)"
    elif sub == "clean":
        if "--force" in flags or any(
            a.startswith("-") and not a.startswith("--") and "f" in a for a in rest
        ):
            return "clean -f (deletes untracked files)"
    elif sub == "update-ref":
        if "-d" in flags:
            return "update-ref -d (deletes a ref)"
    elif sub == "reflog":
        if "expire" in rest:
            return "reflog expire (drops reflog entries)"
    elif sub == "gc":
        if any(a.startswith("--prune=") and a != "--prune=never" for a in rest):
            return "gc --prune (drops unreachable objects)"
    return None


def destructive_git_violation(cmd: str) -> str | None:
    """Return a deny reason if any top-level segment is a DESTRUCTIVE git op, else
    None. Iterates EVERY top-level segment, so it covers compounds on its own — which
    matters since [ADR-0087] retired the compound deny and nothing is denied upstream
    anymore. This is the reliable, `-C`-aware backstop that lets
    `.claude/settings.json` blanket-allow `git -C:*` for the safe surface without
    ungating destructive `-C` forms — the prefix-anchored settings deny-list cannot
    match a path in the middle.

    UNCONDITIONAL, and deliberately so: this guard's motivation was never
    permission-prompt matching, it is the [P9](principles/master.md) no-work-destroyed
    floor. Under a harness that approves by judgment it matters MORE, not less."""
    for seg in top_level_segments(cmd):
        argv = git_argv(seg)
        if not argv:
            continue
        hit = _destructive_git_hit(argv[0], argv[1:])
        if hit:
            return (
                f"Blocked by the confirm-destructive-ops guard (P9): `{seg}` is a "
                f"destructive git operation ({hit}). Denied structurally — including "
                "the `git -C <path> …` forms the prefix-anchored settings deny-list "
                "can't see.\n"
                "DENIED: this exact destructive form. NOT denied: the sanctioned verb "
                "for what you are trying to do — try, in order:\n"
                "  • main's working tree is stale/dirty  -> `python3 session.py main-restore` "
                "(restores only what is provably a superseded ancestor blob; refuses a "
                "human's edit)\n"
                "  • local trunk behind origin           -> `python3 session.py integrate` "
                "(fast-forwards; refuses on conflict, never forces)\n"
                "  • local trunk DIVERGED from origin    -> `python3 session.py integrate` "
                "MERGES origin in (ADR-0102) — nothing on either side is rewritten. On a "
                "conflict it refuses inert and parks the tip at origin `parked/main-<sha>`; "
                "the way through is to land the reconciled content through a lane, and it "
                "must incorporate origin's side or the next merge conflicts identically\n"
                "  • a stranded sibling lane             -> `python3 session.py recover-lanes "
                "--lane <name>`, or `cd <lane> && python3 session.py <verb>` (the RUNTIME's "
                "worktree guard — not this one — refuses `git -C <lane>`; this "
                "form it allows)\n"
                "  • a rebase conflict in your own lane  -> `python3 session.py merge "
                "--resolve generated`, else resolve in-lane and re-run\n"
                "  • a park ref whose work has landed    -> `python3 session.py "
                "retire-parked` (deletes a `parked/*` / `landed/*` ref local AND on "
                "origin, but only where every commit on it is a trunk ancestor or "
                "already content-equivalent there; prints the per-commit verdict, and "
                "refuses with that same list)\n"
                "If none of those fit, there is no verb yet: park the work additively "
                "(commit in-lane, push to a `landed/<id>` ref) and file the work item for "
                "the missing verb — then retire that ref with the verb above once its "
                "content is on the trunk. Do NOT hand this command to the user — that is a "
                "substrate defect, not a resolution "
                "(habit `never-route-your-own-work-through-the-user`, ADR-0099)."
            )
    return None


# A lane pane is named `poga-D-<dispatch>-WI-<item>` by `_tmux_session_name`. That
# name is what makes a peer lane ADDRESSABLE by send-keys, so it is also the precise
# thing to guard: this pattern matches a dispatched Claude lane's pane and nothing
# else on the machine.
_LANE_PANE_RE = re.compile(r"^poga-D-[0-9a-fA-F]+-WI-\d+", re.I)

# Tmux key names, control sequences and repeat-counts. A relay is PROSE; unsticking a
# wedged TUI is KEYSTROKES, and the two deserve different answers. Session ~190 has a
# worked example of the legitimate case — a peer typed bare `0`s into a lane to dismiss
# a modal dialog, then had to explain in the NEXT relay that they were not an answer.
# Denying those too would push that case onto the operator with no verb at all, which
# is how a guard earns its way around itself.
_TMUX_KEYNAMES = frozenset({
    "enter", "escape", "esc", "space", "tab", "btab", "bspace", "backspace",
    "up", "down", "left", "right", "home", "end", "npage", "ppage", "pageup",
    "pagedown", "ic", "dc", "insert", "delete",
})


def _tmux_send_keys_target(argv: list[str]) -> tuple[str | None, list[str], bool, str]:
    """Pick apart a `tmux … send-keys …` argv: (target, payload args, literal, subcmd).

    Returns target=None when this is not a send-keys/paste-buffer at all. Tolerates
    the global options that may sit before the subcommand (`-S <socket>`, `-L <name>`,
    `-f <file>`), because `tmux -S /tmp/x send-keys -t pane …` is the same act as the
    bare form and a guard that only knows the bare form is decoration."""
    if not argv or os.path.basename(argv[0]) != "tmux":
        return None, [], False, ""
    i, sub = 1, None
    while i < len(argv):
        a = argv[i]
        if a in ("-S", "-L", "-f", "-c"):      # global opts that TAKE a value
            i += 2
            continue
        if a.startswith("-"):                   # valueless global opt
            i += 1
            continue
        sub = a
        i += 1
        break
    if sub not in ("send-keys", "send", "paste-buffer"):
        return None, [], False, ""
    target, literal, payload = None, False, []
    while i < len(argv):
        a = argv[i]
        if a == "-t" and i + 1 < len(argv):
            target = argv[i + 1]
            i += 2
            continue
        if a == "-l":
            literal = True
            i += 1
            continue
        if a.startswith("-"):
            i += 1
            continue
        payload.append(a)
        i += 1
    return target, payload, literal, sub


def peer_injection_violation(cmd: str) -> str | None:
    """Return a deny reason if a segment types PROSE into a peer lane's pane, else None.

    WI-0255, and the structural half of [ADR-0112](adr/0112-a-relayed-approval-cites-a-grant-not-a-peer.md).
    Measured in session ~202 across every lane transcript on this machine: all 46
    peer-lane relays sent this way recorded `origin={'kind':'human'}, promptSource='typed'`
    — BYTE-IDENTICAL to the operator's own typing, including to the hand-typed
    "operator HERE, this is not a relay" disclaimers written to work around it. tmux
    send-keys delivers keystrokes to a pty, so the runtime never observes an injection;
    it observes a person typing, because at the only layer it can see, that is what
    happened. The receiving lane therefore cannot tell a peer from its own user, and no
    marker poga writes into the TEXT can fix that — anything that can send-keys can
    write the marker too.

    So the guard is on the SENDER, which is the only side with the information. The
    sanctioned path already exists and is attributed by the runtime rather than by us:
    `SendMessage` (with `ListAgents` to find the address) wraps a peer message in an
    envelope the receiver gets and the sender cannot suppress — verified live in this
    session, where a subagent's send returned only `{"success":true,…}` while the
    receiver got the sender's identity and an explicit not-typed-by-your-user caution.

    NOT denied, deliberately: bare keystrokes (`Enter`, `Escape`, `C-c`, a repeat count).
    Unsticking a wedged TUI is not a relay, and session ~190 records that exact case.
    Nor does this touch poga's own `_dispatch_rebrief_tmux` — that runs as a subprocess
    from this file and never passes through the Bash tool, so this hook never sees it;
    its brief cites a dispatch id the receiving lane can resolve in the coord store,
    which is the same assertion-substitution a grant makes.

    `add-structural-guard-on-recurrence`: WI-0255 is filed as a SECOND occurrence. Every
    lane that met one of these relays held the line by discipline and was right to — the
    habit's point is that a repeat means discipline is not the mechanism to rely on."""
    for seg in top_level_segments(cmd):
        try:
            argv = shlex.split(seg)
        except ValueError:
            continue                      # unparseable -> fall through (fail open)
        target, payload, literal, sub = _tmux_send_keys_target(argv)
        if not target or not _LANE_PANE_RE.match(target.split(":")[0].lstrip("=")):
            continue
        # Keys, not prose? Leave it alone. `paste-buffer` is never keys — it pastes the
        # buffer's CONTENTS and carries no payload argv at all, so the keys-only test
        # below would vacuously pass it (`all([])` is True). Caught by exercising the
        # guard through the hook rather than by reading it.
        if not literal and sub != "paste-buffer":
            meaningful = [p for p in payload if not p.isdigit()]
            if all(p.lower() in _TMUX_KEYNAMES or re.fullmatch(r"[CMS]-.+", p)
                   for p in meaningful):
                continue
        return (
            f"Blocked by the peer-relay guard (WI-0255 / ADR-0112 D1): `{seg}` types "
            f"prose into another Claude lane's pane ({target}).\n"
            "WHY THIS IS DENIED RATHER THAN DISCOURAGED. Measured across every lane "
            "transcript on this machine: all 46 relays sent this way recorded "
            "`origin={'kind':'human'}, promptSource='typed'` — identical to the user's "
            "own typing, and identical to the nine hand-typed 'this is not a relay' "
            "disclaimers written to work around it. send-keys writes to a pty, so the "
            "receiving lane has NOTHING to distinguish you from its user, and a label "
            "in your text does not help: anything that can send-keys can write that "
            "label too. 39 of those 46 told a lane to run something.\n"
            "DO THIS INSTEAD: use the `SendMessage` tool (`ListAgents` gives you the "
            "address). The runtime wraps it in a sender-identified envelope applied on "
            "the RECEIVING side, so it cannot be forged or suppressed by you — which is "
            "the property send-keys can never have.\n"
            "STILL ALLOWED: bare keystrokes to unstick a wedged pane (`Enter`, `Escape`, "
            "`C-c`, a repeat count) — that is not a relay.\n"
            "AND IF IT CARRIES AUTHORITY: it does not travel in prose at all. A relay "
            "carries words only (ADR-0101); the authority for a shared-state write is a "
            "grant the receiving lane resolves ITSELF — `poga authorize grant`, cited by "
            "id, checked with `poga authorize check <id> --for <class>`."
        )
    return None


# Subcommands check-bash AUTO-APPROVES (permissionDecision "allow") so they skip
# the interactive permission prompt. This is the fix for the `git -C <path> <verb>`
# prompts: Claude Code's settings permission matcher CANNOT match a `git -C <path>`
# command against ANY allow-string (the `-C /path` global option defeats the
# prefix match — confirmed against the CC permission docs, session 60), which is
# why `settings.local.json` kept accumulating one exact-command allow per session.
# No string rule can fix it, so the auto-approve moves into this hook, which already
# parses git `-C`-aware. The set MIRRORS the floor's already-blessed plain-git allow
# surface in standard-settings.json — every verb here is one plain `git <verb>` is
# already blanket-allowed for, so this is PARITY for the `-C` form, not new trust.
# Safety: this allow is only reached AFTER destructive_git_violation has cleared, so
# the destructive forms (force/mirror/delete push, reset --hard/--keep, branch -D,
# rebase -i/--onto, filter-*, clean -f, update-ref -d, reflog expire, gc --prune)
# are DENIED first and never auto-approved; and per the CC deny-first precedence a
# hook "allow" can NEVER override a settings `deny` entry. Anything NOT listed here
# (git config writes, tag -d, reset, cherry-pick/revert, unknown subcommands, and
# every non-git command) falls through to the normal permission prompt — no
# regression. See P15 / add-structural-guard-on-recurrence (session 60).
_AUTO_ALLOW_GIT_SUB = frozenset({
    # read-only / inspection
    "status", "log", "diff", "show", "fetch", "pull", "remote", "branch",
    "ls-files", "ls-remote", "ls-tree", "rev-parse", "check-ignore", "describe",
    "worktree", "for-each-ref", "symbolic-ref", "show-ref", "merge-base",
    "name-rev", "blame", "shortlog", "rev-list", "cat-file", "count-objects",
    "var", "whatchanged",
    # safe / forward-only mutating (parity with the floor plain-git allow-list;
    # destructive variants are screened out upstream by destructive_git_violation)
    "add", "commit", "push", "merge", "restore", "checkout", "switch", "stash",
})


# Pipeline stages that only READ stdin and write to stdout. Needed because
# WI-0344 made `|` a segment boundary: without this, `git -C <path> log | head -20`
# stops auto-approving and the `-C` prompt-suppression this function exists for
# comes back for every piped read. Nothing listed can write a file or run a
# program — `tee`, `xargs`, `sed` and `awk` are deliberately absent, and so is
# `sh`, which is the case that makes the fail-closed split worth having on its
# own: `git status | sh` auto-approved as "a safe git op" before this change.
_AUTO_ALLOW_PIPE_READERS = frozenset({
    "head", "tail", "cat", "wc", "nl", "sort", "uniq", "cut", "tr", "rev",
    "column", "grep", "egrep", "fgrep", "less", "more",
})


def _is_inert_reader(segment: str) -> bool:
    """Is this pipeline stage a pure reader? A redirect makes it a WRITER, so the
    program name alone is never enough — `wc -l > /etc/hosts` is not inert."""
    try:
        toks = shlex.split(segment)
    except ValueError:
        return False
    if not toks or os.path.basename(toks[0]) not in _AUTO_ALLOW_PIPE_READERS:
        return False
    return not any(t.startswith(">") for t in toks)


def safe_git_auto_allow(cmd: str) -> str | None:
    """Return an auto-APPROVE reason if `cmd` is a safe git op that should skip the
    permission prompt, else None. Only reached AFTER destructive_git_violation has
    cleared (and the compound deny, where a system re-enabled it per [ADR-0087]), so
    every segment is non-destructive — post-0086 `cmd` may legitimately be a compound,
    which is why the check below is per-segment and fail-closed rather than assuming a
    single segment. Approves iff EVERY top-level segment is a git invocation whose
    subcommand is in _AUTO_ALLOW_GIT_SUB. Fail-closed: one unrecognized or non-git
    segment -> None (fall through to the normal prompt). This is the structural fix
    for the `git -C <path> <verb>` prompts the settings string-matcher can't suppress
    (P15 / add-structural-guard-on-recurrence, session 60)."""
    segs = top_level_segments(cmd)
    # The FIRST segment must be an allow-listed git op. Without that anchor the
    # reader allowance below would auto-approve a bare `head file` — every segment
    # of it is "inert", and none of it is git.
    if not segs or git_subcommand(segs[0]) not in _AUTO_ALLOW_GIT_SUB:
        return None
    for seg in segs[1:]:
        if git_subcommand(seg) in _AUTO_ALLOW_GIT_SUB or _is_inert_reader(seg):
            continue
        return None
    return (
        "Auto-approved by check-bash: safe git op (read-only / forward-only). "
        "The `git -C <path> …` form can't be matched by a settings allow-string, "
        "so the safe git surface is auto-approved here instead (session 60)."
    )


# --- false-green guard (WI-0344) --------------------------------------------
#
# A run whose EXIT CODE is the answer must be the last thing the command does.
# `pytest | tail -25` reports tail's status, so a red suite comes back exit 0 —
# and through a pipe it is worse than that: stdout is block-buffered while stderr
# is not, so unittest's `Ran N tests` / `OK` / `FAILED` summary can fall outside
# the last N lines entirely. The exit code and the text lie in the same direction
# at once, so the output is always a CONFIDENT WRONG ANSWER, never an error.
#
# EIGHT RECORDED OCCURRENCES, which is what moves this out of prose and into code
# (`add-structural-guard-on-recurrence`). Three catalogued by WI-0139 (sessions
# ~129 / ~134 / ~148 — the last reported a red suite green to operator), and five more
# found by WI-0344's sweep over every journal: 20260810T1200Z-runner-ef7a:94,
# 20260816T1200Z-runner-fd4d:81, 20260904T1200Z-devbox-059d:51,
# 20260904T1200Z-devbox-a5b4:77, 20260905T1200Z-devbox-ad61:71.
#
# `merge` IS RECOGNIZED BESIDE THE TEST RUNNERS, and that is the point of the
# name `false_green` rather than `piped_test`. 20260910T1200Z-devbox-3f22:202 is
# the identical shape around a land: `; echo EXIT=$?` reported success for a
# `session.py merge` that had exited 1 on a rebase conflict, so nothing landed and
# the session believed it had. The class is "a verb whose exit code is the
# verdict", not "a test", and closing only the reported site leaves every sibling
# of the same shape running the old answer (`retire-the-class-not-the-instance`).
#
# WI-0139 ALREADY BUILT THE HONEST VERB. `session.py test` runs the suite with
# stdout and stderr to separate FILES, never a pipe, and prints PASSED / FAILED /
# DID NOT REPORT. Prose told everyone to use it. Prose is what failed five more
# times after it shipped; this guard is the mechanism the prose stood in for.

_TEST_RUNNER_PROGRAMS = frozenset({"pytest", "py.test"})
_TEST_RUNNER_MODULES = frozenset({"unittest", "pytest"})

# The harness's own verbs whose EXIT CODE is the verdict, keyed by the script that
# carries them. Deliberately short. This feeds a hard deny that ships
# byte-identical to every member, so a verb nobody pipes for a real
# reason is pure false-deny surface with no matching defect behind it — and
# `poga work list | grep WI-03` is a LISTING that must keep working, which is why
# this is a verb allow-list and not "any call to poga".
_VERDICT_VERBS = {
    "session.py": frozenset({"test", "merge"}),
    "poga": frozenset({"test"}),
}
_VERDICT_SCRIPTS = frozenset({"run_suite.py"})

# Invocations with no verdict to lose. `pytest --collect-only | wc -l` counts
# collected tests; there is no pass/fail anywhere in it, and denying it would be a
# deny with nothing behind it.
_NO_VERDICT_FLAGS = frozenset({
    "--collect-only", "--co", "--fixtures", "--markers", "--version", "-h", "--help",
})

_PY_PROG_RE = re.compile(r"^python[0-9.]*$")

# Separator -> how the message names it. `&&` is absent ON PURPOSE: a non-zero
# left side short-circuits, so the failure still reaches the caller and
# `poga test && echo done` is honest. Denying it would be a deny this guard
# cannot justify, and not one of the eight recorded occurrences used it.
_STATUS_SWALLOWING = {
    "|": "a pipe", "|&": "a pipe", ";": "a `;` chain",
    "||": "an `||` fallback", "\n": "a newline chain",
}


def verdict_run_argv(segment: str) -> list[str] | None:
    """Tokens of a run whose EXIT CODE is the verdict, or None if this segment is
    not one. Normalized the way `git_argv` normalizes a git call — env
    assignments and wrapper prefixes (`sudo`, `env`, `time`, …) stripped — so
    `POGA_GATE=1 python3 -B session.py test` is recognized exactly like a bare
    `pytest`, which is the form the recorded occurrences actually used."""
    try:
        toks = shlex.split(segment)
    except ValueError:
        toks = segment.split()
    k = 0
    while k < len(toks) and (_ENV_ASSIGN_RE.match(toks[k]) or toks[k] in _CMD_PREFIXES):
        k += 1
    toks = toks[k:]
    if not toks or any(t in _NO_VERDICT_FLAGS for t in toks):
        return None
    words = [os.path.basename(t) for t in toks if not t.startswith("-")]
    if not words:
        return None
    if words[0] in _TEST_RUNNER_PROGRAMS:
        return toks
    if _PY_PROG_RE.match(words[0]):
        for idx, tok in enumerate(toks[:-1]):
            if tok == "-m":
                return toks if os.path.basename(toks[idx + 1]) in _TEST_RUNNER_MODULES \
                    else None
            if idx and not tok.startswith("-"):
                break            # the first non-flag argument is a script path
        words = words[1:]        # `python3 <script> <verb>` — classify the script
    if not words:
        return None
    if words[0] in _VERDICT_SCRIPTS:
        return toks
    verbs = _VERDICT_VERBS.get(words[0])
    if verbs and len(words) > 1 and words[1] in verbs:
        return toks
    return None


def false_green_violation(cmd: str) -> str | None:
    """Return a deny reason if a run whose exit code is the verdict has something
    running AFTER it in the same command, else None.

    The rule is one sentence, and it is the repo's own: **the run whose status you
    mean must be the last thing the command does.** Anything downstream — a pipe,
    a `;`, an `||`, a newline — replaces its exit code with the downstream
    command's, and a failing run then comes back exit 0. `&&` is exempt because a
    non-zero left side short-circuits and the failure survives.

    Position, not program, is what this classifies on. `cd <lane> && poga test` is
    allowed however long the chain before it, because the run is still the last
    thing that happens; `poga test | tail -5` is denied even though the same verb
    appears, because it is not. Fails toward ALLOWING, like the parser under it:
    text that does not split into recognizable segments produces no deny."""
    pairs = _split_top_level(cmd)
    for idx, (seg, sep) in enumerate(pairs):
        if idx == len(pairs) - 1:
            continue          # nothing runs after it — its status IS the command's
        if sep not in _STATUS_SWALLOWING:
            continue          # `&&`: a non-zero left side short-circuits
        if not verdict_run_argv(seg):
            continue
        after = pairs[idx + 1][0]
        after_prog = os.path.basename((shlex.split(after) or ["it"])[0])
        return (
            "Blocked by the false-green guard (WI-0344 / "
            "add-structural-guard-on-recurrence):\n"
            f"  {seg}\n"
            f"is a run whose EXIT CODE is the verdict, and {_STATUS_SWALLOWING[sep]} "
            f"puts `{after}` after it. What comes back is `{after_prog}`'s status, "
            "not the run's — so a FAILING run reports exit 0. Through a pipe it is "
            "worse: stdout is block-buffered and stderr is not, so unittest's "
            "`Ran N tests` / `OK` / `FAILED` summary can fall outside the last N "
            "lines entirely. The exit code and the text lie in the same direction at "
            "once, which is why this shape produces a confident wrong answer rather "
            "than an error.\n"
            "WHY A DENY AND NOT A WARNING: eight recorded times this repo has "
            "reported a suite green off a reading that never contained a verdict "
            "(WI-0139 sessions ~129/~134/~148, plus five more found by WI-0344's "
            "sweep), and once the same shape reported a land as successful that had "
            "exited 1 on a conflict. A purpose-built honest verb has existed since "
            "WI-0139 and prose pointing at it is what failed those five times.\n"
            "RUN THE VERB BARE:\n"
            "  python3 session.py test          (or `poga test`)\n"
            "It runs the suite with stdout and stderr to SEPARATE FILES, never a "
            "pipe, and prints its own verdict — PASSED / FAILED / DID NOT REPORT, "
            "exiting 0/1/2 to match. It prints both log paths; read them in a "
            "SEPARATE Bash call, which is the sanctioned way to see the output you "
            "were reaching for here. For any other verb, redirect to a file "
            "(`> out.log 2>&1`) and read the file in the next call.\n"
            "NOT DENIED: `<run> && <anything>` — a non-zero left side "
            "short-circuits, so the failure survives; a run that is the LAST thing "
            "in the command, however long the chain before it; and "
            "`--collect-only` / `--help` / `--version` invocations, which have no "
            "verdict to lose."
        )
    return None


def compound_violation(cmd: str) -> str | None:
    """Return a deny reason if `cmd` is a top-level compound (2+ segments joined
    by &&/||/;/|/newline), else None.

    WI-0344 made `|` a separator, so a pipeline is a compound to this check too.
    That only reaches a system that has set `compound_bash_guard: true`, and per
    [ADR-0087] none declares it — but a member that turns it back on now denies
    `ls | grep x`, which is a real widening and is stated here rather than
    discovered.

    RETIRED BY DEFAULT ([ADR-0087]) — reached only when `compound_guard_enabled()`
    is true. The policy it encodes is unchanged and absolute WHEN ON: one bash tool
    call = one operation, no &&/;/|| chaining regardless of what the segments do, so
    read-only and non-git chains (`cd x && find .`, `git status; git log`) deny too.
    A chain that includes a git mutating op gets a more specific message.

    Kept live and tested rather than deleted: the switch is only worth having if the
    code behind it stays green."""
    segs = top_level_segments(cmd)
    if len(segs) < 2:
        return None
    shown = "\n".join(f"  {idx + 1}. {s}" for idx, s in enumerate(segs))
    has_git_mutating = any(git_subcommand(s) in GIT_MUTATING for s in segs)
    if has_git_mutating:
        head = (
            "Blocked by the compound-bash guard (`compound_bash_guard: true` in "
            f"session.config.json): this is a top-level chain ({len(segs)} operations) "
            "and at least one is a git mutating op. Run each as its own Bash call — "
            "`git add`, `git commit`, `git push` are separate calls, never "
            "&&/;/||/|-chained."
        )
    else:
        head = (
            "Blocked by the compound-bash guard (`compound_bash_guard: true` in "
            "session.config.json): one bash tool call = one operation. This is a "
            f"top-level compound ({len(segs)} operations joined by "
            "&&/||/;/|/newline). "
            "Run each step as its own Bash call."
        )
    return head + "\nSegments detected:\n" + shown


def _emit_external_canon() -> None:
    """C1 canon-delivery for a NON-Claude runtime (symmetric multi-runtime).

    `start` injects CANON.md + STANDARD.md into a Claude session as `additionalContext`
    (a Claude-only channel). A non-Claude runtime has no such channel — so the external
    session-start ritual (a script of the member's own that prints
    `session.py stamp`'s stdout) is the delivery path: surface the inherited canon +
    standard as plain text and the ritual's output lands them in the agent's working
    context. This is the same C1 delivery guarantee `start` gives, on the same trigger
    as C2 (the shared-spine pattern) — so canon is present in EITHER runtime, not just
    Claude governance sessions.

    Best-effort: never raises, so it can never break the stamp. Emitted on EVERY `stamp`
    invocation (independent of whether that call bumps the session counter) — canon
    delivery is per session start, not per counter-bump; a same-day re-run that does not
    re-stamp must still land canon in a fresh agent context."""
    try:
        canon = _canon_block()
        standard = _standard_block()
    except Exception:
        return
    if not canon and not standard:
        return
    print("=== INHERITED CANON (C1 — delivered in every runtime) ===")
    if canon:
        print(canon)
    if standard:
        print("")
        print(standard)
    print("=== END INHERITED CANON ===")


def _emit_start(title: str, context: str, announce: str) -> None:
    """SessionStart hook output: set the session title, pass the orientation
    block as additionalContext, and emit the announce line as systemMessage, in
    one pure-JSON stdout write. `sessionTitle` is honored only on SessionStart.

    `systemMessage` is the intended deterministic hook→transcript channel — it
    would print the announce line straight to the user's screen with no model
    relay, closing the gap where the Architect skips or fabricates the announce
    (sessions 34/35). It does NOT render today: the field is broken upstream
    (anthropics/claude-code#9090, #50542; the related stdout regression is
    #24425). We wire the correct field anyway so it self-heals the day the bug is
    fixed — the parked-correct-code pattern (cf. auto-naming #55951) — at zero
    cost now (a broken field is silently ignored).

    The LIVE user-visible post no longer depends on it (or on the Architect
    relaying it): the second SessionStart 'startup' hook `session.py announce`
    prints the banner `start` staged, over plain stdout — the one SessionStart
    channel that renders to the user (session 57). This function keeps emitting
    the pure JSON `start` needs (title + additionalContext); the banner rides the
    sibling hook so this stdout stays parseable."""
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "SessionStart",
            "sessionTitle": title,
            "additionalContext": context,
            "systemMessage": announce,
        }
    }))


# ===================================================================================
# Appliable-brief auto-adopt (ADR-0039 / ADR-0029) — the `apply-briefs` subcommand.
#
# Fork A: the verified core, dogfooded federation-only as `curate/apply.py`, is lifted
# here into the shipped harness so EVERY Architect auto-adopts conforming briefs at
# startup with zero user turns (2026-07-14-zero-touch-adoption R1). It reads the
# repo-local inbox (`CFG["inbox"]`), APPLIES every brief matching the strict `Apply:
# auto` schema to a verified in-memory copy, atomically replaces the touched files, and
# files the brief `pending/` -> `applied/`. It makes NO judgment: a brief either matches
# the strict schema (applies literally) or it does not (surfaces). It never guesses,
# never partial-applies, and does NOT commit — the session-end close commits, so a bad
# apply shows in `git diff` first. Any error FAILS OPEN (applies nothing, exits 0) so it
# can never brick startup. A repo with no `inbox` configured no-ops silently.
#
# THE STRICT APPLIABLE-BRIEF SCHEMA (this block is the executable spec — ADR-0039):
# A brief is `Apply: auto` IFF it opens with YAML frontmatter (edit-id, target-file,
# expected-base-version, proposed-new-version, apply: auto) AND every mutation is one of
# four ops introduced by a `## op: <type>` heading, with TILDE-fenced payloads:
#   replace           — ~~~before (exactly-once anchor) + ~~~after
#   create-file       — Path: (must not exist) + ~~~content
#   version-bump      — no payload; specialised replace on the **Version:** line
#   changelog-prepend — After: (exactly-once anchor) + ~~~content inserted after it,
#                       into an optional `File:` (default: target-file). ADR-0123: a
#                       system may keep its role-doc changelog in a tracked sibling,
#                       which carries no **Version:** line and so can never be a second
#                       target-file. A File: leaving the repo is refused — an auto brief
#                       is applied unattended from a gitignored mailbox.
# Uniqueness is the anchor: 0 or >1 matches surface (never guess). Base version must
# equal expected-base-version (no apply on drift). Whole-brief atomicity: all ops verify
# against in-memory copies before any file is written.
# ===================================================================================

REQUIRED_BRIEF_HEADER = ("edit-id", "target-file", "expected-base-version",
                         "proposed-new-version")
OP_HEADING = re.compile(r"^##\s+op:\s*([a-z][a-z-]*)\s*$", re.IGNORECASE)
FENCE_OPEN = re.compile(r"^(~{3,})[ \t]*([A-Za-z][A-Za-z-]*)[ \t]*$")
FENCE_CLOSE = re.compile(r"^(~{3,})[ \t]*$")
BRIEF_FIELD = re.compile(r"^([A-Za-z][A-Za-z-]*):[ \t]?(.*)$")
# Tolerant of the same version-line variants `role_doc_version()` accepts, so the
# apply engine can verify/bump a differently-styled role doc (e.g. a non-Claude
# member's — `**Version**: `v0.1.7``): colon inside OR outside the bold, an
# optional backtick wrapper, an optional `v`. Three capture groups so `version-bump`
# rewrites style-preservingly: (1) prefix through the opening backtick/`v`, (2) the
# semver, (3) closing backtick + trailing whitespace. Anchored full-line so `findall`
# still counts occurrences for the exactly-one uniqueness rule.
VERSION_LINE = re.compile(r"(?m)^(\*\*Version:?\*\*:?[ \t]*`?v?)(\d+\.\d+\.\d+)(`?[ \t]*)$")


def parse_frontmatter(text):
    """(header_dict, body_text). header is {} if there is no leading `---` frontmatter."""
    if not text.startswith("---"):
        return {}, text
    end = text.find("\n---", 3)
    if end == -1:
        return {}, text
    header = {}
    for line in text[3:end].splitlines():
        if ":" in line and not line.strip().startswith("#"):
            k, _, v = line.partition(":")
            header[k.strip().lower()] = v.strip()
    nl = text.find("\n", end + 1)
    return header, (text[nl + 1:] if nl != -1 else "")


def split_op_sections(body):
    """(op_type, section_lines) pairs on `## op:` headings; preamble ignored. Surfaces
    if there are no operations."""
    sections, current = [], None
    for line in body.split("\n"):
        m = OP_HEADING.match(line)
        if m:
            current = (m.group(1).lower(), [])
            sections.append(current)
        elif current is not None:
            current[1].append(line)
    if not sections:
        raise SurfaceBrief("no `## op:` operations found")
    return sections


def _norm_version(v):
    return v.strip().lstrip("v").strip() if v else v


def current_version(text):
    """The single `**Version:** X.Y.Z` value in a role doc, or None if not exactly one."""
    matches = VERSION_LINE.findall(text)
    return matches[0][1] if len(matches) == 1 else None


def apply_replace(text, before, after):
    count = text.count(before)
    if count == 0:
        raise SurfaceBrief("replace: `before` block not found in target (0 matches)")
    if count > 1:
        raise SurfaceBrief(f"replace: `before` block is ambiguous ({count} matches) — never guess")
    return text.replace(before, after, 1)


def apply_version_bump(text, expected, proposed):
    matches = VERSION_LINE.findall(text)
    if len(matches) != 1:
        raise SurfaceBrief(f"version-bump: expected exactly one `**Version:**` line, found {len(matches)}")
    prefix, found, suffix = matches[0]
    if _norm_version(found) != _norm_version(expected):
        raise SurfaceBrief(f"version-bump: target version {found} != expected {_norm_version(expected)}")
    return VERSION_LINE.sub(lambda _m: f"{prefix}{_norm_version(proposed)}{suffix}", text, count=1)


class Plan:
    """The result of evaluating one brief: apply (with a file plan) or surface."""

    def __init__(self, brief_path, edit_id):
        self.brief_path = brief_path
        self.edit_id = edit_id
        self.action = None          # "apply" | "surface"
        self.reason = None
        self.touched = {}           # abs Path -> new text
        self.proposed_version = None


def commit_plan(plan, applied_dir, stamp):
    """Write every touched file atomically, then file the brief. Whole-brief atomic:
    all copies were verified in evaluate_brief before this is called."""
    for path, content in plan.touched.items():
        atomic_write(path, content)
    return file_applied_brief(plan, applied_dir, stamp)


# --- ADR-0074: triage debt ---------------------------------------------------
# The inbox is a MAILBOX (a delivery channel whose designed normal state is empty);
# `work-items/` is the BACKLOG. Triage is the bridge: a surfaced brief is triaged to
# one of three terminal states — `applied/` (already satisfied), `accepted/` (a work
# item was minted, carrying `source:` back to the brief), or `declined/` (won't do,
# with a reason). Nothing is left to re-surface forever.
#
# The guard exists because this is the SECOND time a second list describing the same
# work appeared (ROADMAP prose was the first, retired by ADR-0073 D6), and a repeat
# means discipline isn't enough ([`add-structural-guard-on-recurrence`]). A brief that
# sits in `pending/` past the grace period is untriaged debt, and an inbox that always
# shows N items has stopped being a signal.

TRIAGE_GRACE_DAYS = 3


def _applied_without_a_receipt(applied_dir: Path) -> list[str]:
    """WI-0041: an `applied/` brief that the apply engine never stamped.

    `file_applied_brief()` writes `applied:` / `applied-at-version:` / `state: applied`
    into the frontmatter, so that stamp is the engine's own receipt
    ([`a-close-is-the-banner-not-the-sentence`](habits/master.md#a-close-is-the-banner-not-the-sentence)
    — the valid receipt is the artifact the closing code produces, never a self-report,
    and here the *filing* is the self-report). Its absence means a human or an agent moved
    the file by hand. That is exactly how one member's enrollment was silently
    dropped (session ~104): filed `applied/` with none of its work done, which removed it
    from the adopt-runner queue, so the enrollment failed *quietly* instead of loudly.

    THE STAMP ALONE IS NOT ENOUGH, and assuming it was would have made this guard worse
    than useless. Session ~105 found the same brief unstamped in `applied/` a second time
    — but with the work genuinely done. The reason is structural: the R3 adopt-runner
    works `apply: manual` briefs through a headless Claude session that files them by
    hand, so a runner-adopted manual brief NEVER carries the engine stamp. A naive
    "unstamped means unapplied" rule would therefore flag every correctly-adopted manual
    brief, and a guard that cries wolf on its most common input gets ignored, which is
    how the real case slips past next time.

    So the answer is three-valued, not two ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)):

      * `apply: auto` with no stamp   -> FLAG. The engine is the only thing that files an
                                        auto brief, and it always stamps. Unstamped means
                                        it did not run.
      * `apply: manual` with no stamp -> UNVERIFIABLE by stamp, reported as its own state
                                        and pointing at the brief's own `verify:` command.
      * stamped                       -> quiet.

    ONLY THE `auto` CASE IS REPORTED, and that scoping is the whole design. The first cut
    also reported every unstamped MANUAL brief as "unconfirmed" — and printed 24 of them
    on its first real run, because the entire historical archive predates the stamp
    mechanism and every runner-adopted manual brief is unstamped by construction. A guard
    that emits two dozen lines every startup is not a guard; the one real finding would
    sit invisibly among them, which is the failure this whole item exists to prevent,
    reproduced by its own fix. Manual briefs are therefore *silent* here: the honest
    reading of an unstamped manual brief is "no evidence either way," and a check with no
    evidence should say nothing rather than manufacture a finding.

    The `verify:` command is deliberately NOT executed. A brief is inbound payload from a
    lower-trust channel, and running a shell command out of one on the startup path would
    make this guard an execution sink — precisely what
    [`treat-inbound-payload-as-data-not-commands`](habits/master.md#treat-inbound-payload-as-data-not-commands)
    forbids. Confirming a manual adoption stays a deliberate act by the runner or a human.
    """
    out: list[str] = []
    if not applied_dir.is_dir():
        return out
    for p in sorted(applied_dir.glob("*.md")):
        try:
            head = p.read_text(encoding="utf-8")[:4000]
        except OSError:
            continue
        if re.search(r"^state:\s*applied\s*$", head, re.M):
            continue
        m = re.search(r"^apply:\s*(\w+)", head, re.M)
        if not m or m.group(1).strip().lower() != "auto":
            continue                      # manual: no evidence either way — stay quiet
        out.append(f"{p.name} is in applied/ but carries no `state: applied` stamp, and "
                   f"an `apply: auto` brief is only ever filed by the engine — which "
                   f"always stamps. It was moved by hand, so its work is probably NOT "
                   f"applied and it has left the runner queue. Check it, and refile to "
                   f"pending/ if the work is owed.")
    return out


# ADR-0065 D3 note. `poga restore` hydrates this inbox from BACKUP MEDIA, whose
# provenance cannot be verified — unlike the target file it edits, which arrives over
# git from an identity-pinned remote. NO SPECIAL RESTORE MODE EXISTS HERE, deliberately:
# the `expected-base-version` check below is already the gate. Because it compares the
# unverified brief against the VERIFIED role doc, a stale or already-applied brief
# sitting in a backup fails automatically (applying it would have bumped the version it
# claims to expect). An earlier draft held the whole restored inbox behind a
# human-cleared marker; that was rejected — it put a human step inside a disaster
# rebuild and implied a protection against backup tampering it did not deliver.
def _apply_run(mode):
    """mode: 'apply' | 'dry-run' | 'status'. Returns (applied, surfaced) plan lists."""
    pending, applied_dir = inbox_dirs()
    # A CONFIGURED-but-unreadable inbox is reported, never silently treated as empty.
    if pending is not None and not inbox_visible(pending):
        print(f"Apply: inbox not readable at {pending} — applied nothing "
              f"(not the same as empty; nothing was inspected).")
        return [], []
    briefs = pending_briefs(pending)
    plans = [evaluate_brief(b) for b in briefs]
    applied = [p for p in plans if p.action == "apply"]
    surfaced = [p for p in plans if p.action == "surface"]

    if mode == "status":
        if not briefs:
            print("Apply: inbox empty.")
        elif applied:
            tail = f"; {len(surfaced)} to surface" if surfaced else ""
            print(f"Apply: {len(applied)} brief(s) ready to auto-apply at startup{tail}.")
        else:
            ids = ", ".join(p.edit_id for p in surfaced)
            print(f"Apply: 0 auto-appliable; {len(surfaced)} to surface ({ids}).")
        return applied, surfaced

    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    if mode == "apply":
        # Every lane now reads ONE shared inbox, so two lanes starting together could
        # otherwise both apply the same brief. Single-writer via the C5 lease (ADR-0062);
        # fail-open — no shared coord dir means no siblings to race.
        try:
            with lease("inbox-apply"):
                for p in applied:
                    commit_plan(p, applied_dir, stamp)
        except LeaseHeld as e:
            print(f"Apply: skipped — another session is adopting from this inbox ({e}). "
                  f"It will apply there; nothing was half-applied here.")
            return [], surfaced

    label = "DRY-RUN — nothing written" if mode == "dry-run" else "auto-adopt"
    if not briefs:
        print(f"Apply ({label}): inbox empty.")
        return applied, surfaced
    verb = "would apply" if mode == "dry-run" else "applied"
    print(f"Apply ({label}): {len(applied)} {verb}, {len(surfaced)} surfaced.")
    for p in applied:
        print(f"  [{verb}] {p.edit_id} — {p.reason}")
    for p in surfaced:
        print(f"  [surface] {p.edit_id} — {p.reason}")
    return applied, surfaced


# ---------------------------------------------------------------------------
# Relay-authorization grants (ADR-0112)
#
# A dispatched lane has no inbound channel (WI-0166), so an approval reaches it as a peer
# lane's prose and the lane cannot verify it. Six lanes on 2026-09-03 correctly refused to
# make shared-state writes on that authority, and had nothing to cite instead.
#
# THIS IS NOT SECURITY AND MUST NOT BE BUILT AS ONE (ADR-0112, the operator's reframe). Every
# process here runs as the user; a shared secret would be forgeable by any lane that saw
# it. What a grant changes is WHAT THE LANE HAS TO ASSERT: instead of "operator approved" — a
# claim about his state of mind it cannot check — it writes "authorized via G-xxxx", a
# claim about a record it read itself, which is true regardless of who wrote the record.
#
# THE DECLARED LIMIT (ADR-0112 D10): a grant proves INTENT AND TIME, NOT IDENTITY. Anything
# running as the user can write one. The win is auditability, not prevention — a forged
# grant becomes a specific, timestamped artifact in a channel the user can review, where
# relayed prose left no trace at all. Never cite this as an access control.
GRANTS_DIRNAME = "grants"
# D5 default: long enough to cover a working sitting, short enough that a forgotten grant
# does not authorize tomorrow's writes. One `poga authorize` clears a sitting's worth of
# routine relays; the alternative the user is living with is one message per lane per decision.
GRANT_TTL_SECONDS = 4 * 3600
# A ceiling, because the failure mode this whole design has to stay ahead of is the
# over-broad grant, and an unbounded --ttl is its sharpest form: `authorize --ttl 3650d`
# is a decade-long any-lane, any-item grant with nothing between it and the D6 carve-out.
# A week is well past any legitimate sitting and still expires. WI-0023 anticipated this
# ("revisit expiry if a genuinely broad grant is ever made and wants a guaranteed
# lifetime ceiling") — this is that ceiling, set before rather than after the incident.
GRANT_MAX_TTL_SECONDS = 7 * 24 * 3600
# D6. The routine set is what a bare `poga authorize` covers. The named set is deliberately
# NOT in the default: a write to the registries, to `standard-source.md`, or into another
# member's repo is slow and expensive to reverse, so it must be asked for by name. This is
# the carve-out that stops a wide default from ever reaching canon.
GRANT_ROUTINE_VERBS = ("close", "land", "note", "write")
GRANT_NAMED_VERBS = ("canon", "standard", "fleet")
GRANT_ALL_VERBS = GRANT_ROUTINE_VERBS + GRANT_NAMED_VERBS
GRANT_WILDCARD = "*"

# Resolver outcomes (D8). SIX answers, never two — `declare-what-a-check-assumes`. In
# particular CANNOT TELL is its own state and is treated as REFUSED, never folded into
# "fine": an unreadable store must not read as an authorization.
GRANT_GRANTED = "GRANTED"
GRANT_NO_SUCH = "NO SUCH GRANT"
GRANT_EXPIRED = "EXPIRED"
GRANT_OUT_OF_SCOPE = "OUT OF SCOPE"
GRANT_REVOKED = "REVOKED"
GRANT_CANNOT_TELL = "CANNOT TELL"


def _grant_dir(create: bool = False) -> Path | None:
    """`<git-common-dir>/poga-coord/grants` — the grant records.

    Deliberately NOT a COORD_KINDS member, for the reason stated at `_dispatch_dir`: a
    grant is not a hold. It must survive the TTL reaper and `_lane_exit_release` at
    lane teardown — outliving the session that minted it is the entire point, since the
    lane it authorizes is a DIFFERENT session — and it has its own retirement verb
    (`authorize-revoke`). Excluded by argument, not by omission."""
    common = _git_common_dir()
    if common is None:
        return None
    d = common / COORD_DIRNAME / GRANTS_DIRNAME
    if create:
        try:
            d.mkdir(parents=True, exist_ok=True)
        except Exception:
            return None
    return d


def _grant_origin() -> str:
    """D7. Whether this process is running inside a dispatched lane.

    A MARKER, NOT A CONTROL — a lane could unset `POGA_DISPATCH`. It exists so that the
    lazy self-authorization case (a lane minting its own grant) is visibly different from
    an operator's, rather than indistinguishable. Anything relying on this for safety has
    misread D10."""
    return "dispatched-lane" if os.environ.get("POGA_DISPATCH", "").strip() else "interactive"


def _grant_parse_ttl(text: str) -> int:
    """`90m` / `4h` / `2d` / bare seconds -> seconds. Raises ValueError on anything else."""
    t = (text or "").strip().lower()
    if not t:
        raise ValueError("empty duration")
    units = {"s": 1, "m": 60, "h": 3600, "d": 86400}
    mult = 1
    if t[-1] in units:
        mult = units[t[-1]]
        t = t[:-1]
    try:
        n = float(t)
    except ValueError:
        raise ValueError(f"cannot read {text!r} as a duration — try 30m, 4h, 2d")
    if n <= 0:
        raise ValueError(f"duration must be positive, got {text!r}")
    return int(n * mult)


def _grant_id() -> str:
    """`G-<hex>`, minted not drawn (D4). Drawn allocation governs identifiers in a TRACKED
    FILE namespace where two lanes collide at land time; a grant lands no file, so there is
    nothing to collide and no allocator is warranted."""
    d = _grant_dir()
    for _ in range(64):
        gid = f"G-{secrets.token_hex(3)}"
        if d is None or not (d / f"{gid}.json").exists():
            return gid
    # Astronomically unlikely; widen rather than return a colliding id, because
    # `_grant_write` would otherwise replace a live grant with no trace.
    return f"G-{secrets.token_hex(8)}"


def _grant_read(gid: str) -> dict | None:
    d = _grant_dir()
    if d is None:
        return None
    return _coord_read(d / f"{gid}.json")


def _grant_write(rec: dict) -> bool:
    d = _grant_dir(create=True)
    if d is None:
        return False
    try:
        atomic_write(d / f"{rec['grant_id']}.json",
                     json.dumps(rec, ensure_ascii=False, indent=2) + "\n")
        return True
    except Exception:
        return False


def _grant_list(include_expired: bool = False) -> dict:
    """Live grants keyed by id, newest first. `{}` means none; a caller that must
    distinguish "none" from "cannot read the store" checks `_grant_dir()` itself."""
    d = _grant_dir()
    if d is None:
        return {}
    out = {}
    try:
        files = sorted(d.glob("G-*.json"))
    except Exception:
        return {}
    for f in files:
        rec = _coord_read(f)
        if not rec:
            continue
        if not include_expired and (_coord_expired(rec) or rec.get("revoked_at")):
            continue
        out[rec.get("grant_id", f.stem)] = rec
    return dict(sorted(out.items(),
                       key=lambda kv: kv[1].get("expires_at", 0), reverse=True))


def _grant_mint(items, lanes, verbs, ttl: int, note: str = "") -> dict:
    """Build and persist a grant. Returns the record; `written` says whether it landed."""
    rec = _coord_record(_coord_identity(), ttl)
    rec.update({
        "grant_id": _grant_id(),
        "kind": GRANTS_DIRNAME,
        "items": list(items) or [GRANT_WILDCARD],
        "lanes": list(lanes) or [GRANT_WILDCARD],
        "verbs": list(verbs) or list(GRANT_ROUTINE_VERBS),
        "origin": _grant_origin(),
        "note": note or "",
        "revoked_at": "",
    })
    rec["written"] = _grant_write(rec)
    return rec


def _grant_scope_line(rec: dict) -> str:
    """One printable line describing what a grant covers."""
    def show(vals):
        return "any" if not vals or GRANT_WILDCARD in vals else ", ".join(vals)
    return (f"items={show(rec.get('items'))} · lanes={show(rec.get('lanes'))} · "
            f"for={show(rec.get('verbs'))}")


# ── WI-0292: an unverifiable grant says so when it is ISSUED ───────────────────
#: The commands a lane actually TYPES to verify a grant. All three spellings, because
#: they are one capability reached three ways: `poga authorize check` execs
#: `python3 session.py authorize-check` as a CHILD process (poga:1029-1031), and a child
#: is never permission-checked — only the spelling a lane types is. A tree that admits
#: any one of these can verify a grant; a tree that admits none cannot.
GRANT_CHECK_SPELLINGS = (
    "poga authorize check",
    "./poga authorize check",
    "python3 session.py authorize-check",
)

#: THREE answers, never two ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
#: CANNOT TELL is its own state and is reported as loudly as UNVERIFIABLE: "I could not
#: read the allow-list" must never render as "the allow-list is fine". That collapse is
#: the shape of the original defect — the operator read silence as success.
GRANT_VERIFIABLE = "VERIFIABLE"
GRANT_UNVERIFIABLE = "UNVERIFIABLE"
GRANT_VERIFY_UNKNOWN = "CANNOT TELL"

#: A dispatched lane really does load the user-level settings file, so an honest reading
#: of "what may this lane run" has to include it. Named as a MODULE GLOBAL rather than
#: computed inside the function because it is a read of AMBIENT STATE — the developer's
#: own home directory — and a test that silently depended on it would pass or fail on
#: whose machine ran it ([`evidence-is-separated-from-state-by-construction`](habits/master.md#evidence-is-separated-from-state-by-construction)).
#: The fixture neutralises it the same way it neutralises `ROOT`: by assignment.
USER_SETTINGS_PATH = Path.home() / ".claude" / "settings.json"


def _bash_allow_matches(rule: str, command: str) -> bool:
    """Does one Claude Code permission rule admit `command` without a prompt?

    Deliberately CONSERVATIVE: a false VERIFIABLE is the expensive error here, because it
    is precisely the false read on the operator's side that this whole check exists to
    remove. Only the three shapes this repo's settings actually use are honoured —
    `Bash(cmd)` exact, `Bash(cmd:*)` prefix, `Bash(cmd *)` prefix. Anything else, and any
    rule for another tool, answers no rather than guessing.

    NOT HANDLED, ON PURPOSE: the `git -C` exception documented in standard-settings.json's
    `//git-c` note — Claude Code's matcher parses git's global options, so no allow-string
    ever fires for `git -C <path> <verb>`. No grant-verification spelling is a git command,
    so that exception cannot reach this caller; if one ever is, this returns a too-generous
    answer and the note above is where to start."""
    if not (rule.startswith("Bash(") and rule.endswith(")")):
        return False
    body = rule[len("Bash("):-1].strip()
    if body.endswith(":*") or body.endswith(" *"):
        prefix = body[:-2].strip()
        if not prefix:
            return False
        return command == prefix or command.startswith(prefix + " ")
    return command == body


def _lane_settings_files() -> list:
    """The permission files a DISPATCHED LANE actually loads — not the ones this tree has.

    The distinction is the whole point and is easy to get backwards. A lane runs in a git
    WORKTREE, and `.claude/settings.json` is the only tracked file under `.claude/`, so it
    is the only one that reaches the lane. `.claude/settings.local.json` — where Claude
    Code piles up every one-off approval anyone has ever clicked (see `PERMISSION_PILE`) —
    is gitignored and does NOT propagate into a worktree. Counting it here would
    manufacture exactly the false read this check exists to remove: the operator mints
    from the main checkout, where the pile makes almost everything look allowed, while the
    lane that has to USE the grant sees none of it.

    Returns (project_settings, extra_files). The project file is the AUTHORITY — it is the
    generated floor + this system's extras — so an absent or unreadable one is CANNOT TELL,
    never a quiet pass."""
    project = ROOT / ".claude" / "settings.json"
    extras = [p for p in (USER_SETTINGS_PATH,) if p is not None and p.exists()]
    return project, extras


def _read_permission_rules(path) -> tuple:
    """(allow, deny, error) for one settings file. `error` is None when it parsed."""
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return [], [], "absent"
    except Exception as e:  # malformed JSON, unreadable, wrong shape
        return [], [], str(e) or e.__class__.__name__
    perms = data.get("permissions") if isinstance(data, dict) else None
    if not isinstance(perms, dict):
        return [], [], None
    allow = [r for r in (perms.get("allow") or []) if isinstance(r, str)]
    deny = [r for r in (perms.get("deny") or []) if isinstance(r, str)]
    return allow, deny, None


def grant_verifiability(gid: str = "G-xxxxxx") -> tuple:
    """Can a dispatched lane RUN the read side of a grant minted here? -> (state, detail).

    WI-0292. ADR-0112's entire design is that a lane CITES a grant instead of trusting a
    peer's prose, which makes `authorize check` the load-bearing half. But a dispatched
    lane is a detached tmux TUI carrying the default permission posture and no human
    attached (`_dispatch_spawn_command` passes no `-p`, no `--permission-mode`, no
    `--allowedTools`), so a command matching no allow entry does not fail fast — it raises
    a prompt into a pane nobody is looking at. MEASURED 2026-09-05: lane poga-28, holding
    G-47b435, could not run the check, correctly refused to act on a grant it could not
    verify, and the operator who minted that grant to unblock three lanes found out an
    hour later that it had unblocked none. A mechanism whose verifier cannot run degrades
    to the thing it replaced, and it does so silently.

    ASKED AT MINT TIME ON PURPOSE. The operator is standing right here when the grant is
    written; the lane that will need it is not, and has no channel back. Moving this one
    question from use-time to issue-time is the difference between a one-line warning and
    an hour of a lane's life spent discovering the same fact by refusal.

    WHAT THIS DOES NOT CLAIM. It reads the allow-list, which is what decides whether the
    command runs unprompted. It does not RUN the command, and it cannot see a
    `--permission-mode` or `--dangerously-skip-permissions` an operator passes by hand —
    neither of which the dispatch path sets. VERIFIABLE therefore means "no permission
    rule stands in the way of the lane typing this", never "the check will succeed"."""
    project, extras = _lane_settings_files()
    allow, deny, err = _read_permission_rules(project)
    if err is not None:
        why = ("does not exist" if err == "absent"
               else f"could not be parsed ({err})")
        return GRANT_VERIFY_UNKNOWN, (
            f"whether a dispatched lane can verify {gid} is UNKNOWN: {project} {why}, "
            f"and that file is the authority on what a lane may run unprompted. Treat "
            f"this grant as unverifiable until that is fixed.")

    unread = []
    for extra in extras:
        e_allow, e_deny, e_err = _read_permission_rules(extra)
        if e_err not in (None, "absent"):
            unread.append(extra)
            continue
        allow = allow + e_allow
        deny = deny + e_deny

    for spelling in GRANT_CHECK_SPELLINGS:
        command = f"{spelling} {gid}"
        if any(_bash_allow_matches(r, command) for r in deny):
            continue
        hit = next((r for r in allow if _bash_allow_matches(r, command)), None)
        if hit:
            return GRANT_VERIFIABLE, (
                f"a dispatched lane can run `{spelling} {gid}` unprompted "
                f"(admitted by {hit}).")

    tail = ""
    if unread:
        # A file we could not read can only ADD permissions, so the honest direction is
        # to keep the warning and name what we could not see — an over-warning costs a
        # line, a false all-clear costs a lane.
        tail = (" Could not read " + ", ".join(str(p) for p in unread) +
                ", which could only have widened this.")
    return GRANT_UNVERIFIABLE, (
        f"NO DISPATCHED LANE CAN VERIFY {gid}. Nothing in {project} admits "
        f"`poga authorize check` (or `python3 session.py authorize-check`), and a "
        f"dispatched lane is non-interactive — the command will not be refused, it will "
        f"hang on a permission prompt with no one attached. A lane handed this grant can "
        f"only trust the peer prose ADR-0112 exists to distrust, or refuse. Add the "
        f"read-only pair to standard-settings.json and re-run "
        f"`python3 curate/gen_settings.py`." + tail)


def resolve_grant(gid: str, verb: str = "", item: str = "", lane: str = "") -> tuple:
    """Resolve a grant id against the act a lane is about to perform (ADR-0112 D8).

    Returns `(state, sentence)` where state is one of the GRANT_* outcomes and the
    sentence is quotable BACK TO THE OPERATOR — which is precisely what a refusing lane
    cannot produce today. Only `GRANT_GRANTED` authorizes anything.

    FAILS CLOSED, which INVERTS this file's otherwise universal coordination contract.
    Every other `_coord_*` helper fails open, because coordination is an optimization that
    must never brick its caller; authorization is not an optimization, so an unreadable
    store resolves to CANNOT TELL and CANNOT TELL is refused. Stated here because a future
    reader who has internalized the fail-open rule will otherwise "fix" this."""
    if _grant_dir() is None:
        return (GRANT_CANNOT_TELL,
                "CANNOT TELL — no coordination store is reachable from this tree, so no "
                "grant can be resolved. Treating as NOT authorized.")
    gid = (gid or "").strip()
    if not gid:
        return (GRANT_NO_SUCH, "NO SUCH GRANT — no grant id was supplied.")
    rec = _grant_read(gid)
    if rec is None:
        return (GRANT_NO_SUCH,
                f"NO SUCH GRANT — {gid} is not in the coordination store. It may never "
                f"have existed, or the store may have been cleared since it was minted.")
    if rec.get("kind") != GRANTS_DIRNAME:
        # Hardening, not a known hole: nothing found a path that reaches another kind's
        # record through this reader. Cheap enough that "no reachable path today" is not
        # a reason to leave the door unlatched.
        return (GRANT_NO_SUCH,
                f"NO SUCH GRANT — {gid} names a record that is not a grant.")
    if rec.get("revoked_at"):
        return (GRANT_REVOKED,
                f"REVOKED — {gid} was revoked at {rec['revoked_at']}. "
                f"It authorizes nothing.")
    if _coord_expired(rec):
        return (GRANT_EXPIRED,
                f"EXPIRED — {gid} expired at {rec.get('expires_iso', '?')} "
                f"(granted {rec.get('created_at', '?')}). A fresh grant is needed.")

    misses = []
    if verb:
        verbs = rec.get("verbs") or []
        if GRANT_WILDCARD not in verbs and verb not in verbs:
            misses.append(f"it covers {', '.join(verbs) or '(nothing)'}, not {verb!r}")
    if item:
        items = rec.get("items") or []
        if GRANT_WILDCARD not in items and item not in items:
            misses.append(f"it covers items {', '.join(items)}, not {item}")
    if lane:
        lanes = rec.get("lanes") or []
        if GRANT_WILDCARD not in lanes and lane not in lanes:
            misses.append(f"it covers lanes {', '.join(lanes)}, not {lane}")
    if misses:
        return (GRANT_OUT_OF_SCOPE,
                f"OUT OF SCOPE — {gid} does not cover this act: " + "; ".join(misses) +
                f". Its scope is {_grant_scope_line(rec)}.")

    return (GRANT_GRANTED,
            f"authorized via grant {gid} at {rec.get('created_at', '?')} "
            f"(expires {rec.get('expires_iso', '?')}; {_grant_scope_line(rec)}"
            + (f"; origin {rec['origin']}" if rec.get("origin") else "") + ")")



GRANT_TRAILER_KEY = "Authorized-By"

# WI-0280. THE GRANT A LANE CITES FOR THIS INVOCATION — set once, from `--grant` on the
# verb being run, at `main()`'s choke point. Empty means no grant was named, which is the
# overwhelmingly common case and the one that must stay argv-identical to pre-ADR-0112.
#
# THIS REPLACES AN `os.environ.get("POGA_GRANT")` FALLBACK, and the replacement is the
# point rather than a refactor. An environment variable is the wrong shape for an
# authorization citation in four specific ways, all of which this module global closes:
# it is EXPORTABLE, so one `export` authorizes every commit in a shell until somebody
# remembers to unset it; it is INHERITED, so every child process a session spawns carries
# it silently; it OUTLIVES THE ACT it was named for, where a grant authorizes an act; and
# it is INVISIBLE IN THE RECORD, where an argv flag is the very thing an audit reads. D10
# already concedes the grant proves intent and time rather than identity — a channel that
# can be switched on for a whole shell, out of band, gives up the intent half too, which
# is the half ADR-0112 exists to keep. Nothing ever set the variable (`_dispatch_spawn_command`
# and the `poga` launcher were both checked, and both still are, by the DISPATCH_ENV_VARS
# and launcher tests), so retiring it removes a channel nobody was using and nobody was
# told about.
#
# A module global rather than a threaded parameter, for this file's own stated reason:
# `_store_autocommit` is the one hook point every store write passes through precisely so
# that "a verb added tomorrow cannot forget a step that is not its to remember", and a
# `grant=` parameter on eight writers is exactly the shape that argument rejects. Set at
# the choke point, read at the hook point, and bounded to a single CLI invocation — a
# session.py process runs one verb and exits.
_GRANT_CITED = ""


def cite_grant(gid: str) -> str:
    """Record the grant this invocation cites. Called ONCE, from `main()`. Returns it."""
    global _GRANT_CITED
    _GRANT_CITED = (gid or "").strip()
    return _GRANT_CITED


def cited_grant() -> str:
    """The grant id named on this invocation's command line, or `""`."""
    return _GRANT_CITED



# ── Dispatch: fan a work-item range out to peer lanes (WI-0032) ──────────────────
# "Get the list. Go do items 1-10." The dispatcher RESOLVES an ordinal range against
# the session's pinned snapshot, ORDERS it on blocked-by, shows ONE plan for ONE
# approval, then SPAWNS lanes — and immediately stops being special.
#
# G1 — THE DISPATCHER IS A LAUNCHER, NOT A BOSS (ADR-0051 is binding). Assignment
# happens at spawn, once. Nothing here holds a claim on another session's behalf,
# arbitrates anything, or collects results. Each spawned lane SELF-CLAIMS at startup
# and lands through the same CAS gate as a hand-opened one; a lost race is reported by
# the lane, not resolved by a coordinator.
#
# THE WAVE TRIGGER IS THE LANDING SESSION, NOT A MASTER (the operator's ruling, session ~105:
# the sessions count themselves, with no master). A dispatch beyond the cap does not
# leave a supervisor running to feed it. Instead each lane, as it LANDS, pulls the next
# queued item and spawns it — the queue drains itself. The right to spawn a given item
# is drawn by exclusive-create on a spawn slot (`numbers-are-drawn-never-picked`), so
# two lanes landing at once cannot both take the same item.
#
# Two run shapes, per the operator's ruling: the DEFAULT is one wave then stop (re-run
# `poga dispatch` for the next — the launcher keeps no standing state), and `--run X`
# sets a budget of X lanes for the chain to work through before it stops on its own.
DISPATCH_DIRNAME = "dispatch"
DISPATCH_SPAWN_KIND = "dispatch-spawn"
DISPATCH_SPAWN_TTL_SECONDS = 24 * 3600
# WI-0298 / brief D6 — every kind a LANE EXIT must free, in one step.
#
# `COORD_KINDS` is the tuple every sweep already iterates, and the dispatch slot was never
# on it: a lane could land, be torn down and be reaped with its spawn slot still held, so
# the freed capacity was invisible and the next wave under-spawned. That is the WI-0166
# shape a third time — a kind missing from the tuple that drives the sweeps is a record
# nothing can ever free — so the exit surface is named ONCE here rather than assembled at
# each of the four call sites (land, teardown, reap, recovery), which is exactly the
# wiring-routes-one-at-a-time mistake WI-0078 was.
LANE_EXIT_KINDS = COORD_KINDS + (DISPATCH_SPAWN_KIND,)
# WI-0312 — what a CLOSE frees, which is everything above except the spawn slot.
#
# The exception is not a hedge, it is the sequence. `_dispatch_after_land` runs at the end
# of a successful land, inside it, and DRAWS a spawn slot for the next queued item — keyed
# by this lane's own identity and journal, because this lane is the one doing the spawning.
# The close's exit runs seconds later. Freeing that slot would release the spawn right for
# a lane that is starting up as we watch, and the whole reason the slot is drawn rather
# than computed is that two lanes landing at once must not both spawn one item.
#
# A lane's OWN slot is not at stake either way: it was written by the PARENT that spawned
# it, so it carries the parent's key and this exit never matched it. Teardown and the
# reaper still free the full set — by the time a lane's branch is gone, whatever it spawned
# has its own records and its own claim.
LANE_EXIT_CLOSE_KINDS = COORD_KINDS
# WI-0259 — the CROSS-dispatch half of the spawn right. `dispatch-spawn` is keyed
# `{dispatch_id}__{wid}`, so it arbitrates only WITHIN one dispatch; two overlapping
# dispatches could both draw their own slot for the same item and open two lanes for it.
# This guard is keyed on the ITEM ALONE, so the draw is machine-wide.
#
# It exists to bridge exactly one window: a dispatched lane SELF-CLAIMS at its own startup
# (the operator's ruling, carried in `_dispatch_prompt`), so the claim record — the durable
# exclusion `_dispatch_order` already reads — is written by the child, tens of seconds to
# minutes after the spawn. The guard covers that gap and NOTHING MORE.
#
# THE TTL IS THE GUARANTEE, and `_dispatch_item_sweep` is a fast path over it — stated
# that way round on purpose, because the reverse is the tempting and wrong reading. The
# sweep only fires when a dispatch path happens to run while the claim is live; it is not
# driven by the claim, so nothing promises it ever runs. What bounds the guard in every
# case is the clock.
#
# Which is why the number matters, and why it is deliberately NOT the 24h of the
# per-dispatch slot: that slot is a permanent provenance record, this is a bridge, and a
# bridge with a day-long TTL is precisely the re-dispatch block WI-0259 warned about. At
# 15 minutes the guard is several times the widest observed boot-to-claim, and it has
# always lapsed long before a lane that DID claim finishes its work — so the torn-down-
# then-re-dispatched lane, the case the block would have hurt, never meets a live guard
# at all. A dead spawn frees itself without an operator verb.
DISPATCH_ITEM_KIND = "dispatch-item"
DISPATCH_ITEM_TTL_SECONDS = 15 * 60
DISPATCH_CAP_DEFAULT = 5
# Named spawn surfaces. Dispatch REFUSES an unlisted one rather than degrading: the
# phantom-session saga was a launcher-surface problem, and "try it and see" is how a
# session ends up unowned. Declared per system in session.config.json (`spawn_surface`);
# the default is `auto`, which DETECTS (see `_dispatch_surface`).
SPAWN_SURFACES = ("Terminal", "iTerm2", "tmux")
# The subset that drives a GUI app over Apple Events, and therefore only works from a
# session inside the user's Aqua login. `tmux` is deliberately not here: it is a plain
# child process, so it works identically from a GUI tab, an SSH login, and a LaunchAgent.
GUI_SPAWN_SURFACES = ("Terminal", "iTerm2")

# WI-0248 — THE SPAWN RECEIPT. `tmux new-session` exiting 0 says tmux accepted the
# request; `has-session` says a process is alive. NEITHER says the lane was told what to
# do. Measured 2026-09-03 (D-d9202c): three of five lanes came up at a virgin prompt with
# no brief, and every surface still called them spawned — the dispatch record counted
# them, the tmux session existed, attach showed a healthy prompt. A lane that never got
# its instruction is indistinguishable from one thinking hard, and it sits there forever.
#
# The grace is how long a lane has to produce its receipt before the wave calls it
# unbriefed. Sized from observation, not taste: this lane's own SessionStart hook wrote
# its liveness sidecar within seconds of launch. It is a CEILING, not a sleep — the
# confirm pass returns the moment every slot resolves, so a healthy five-lane wave costs
# about one poll, and the full grace is only ever paid by a wave that is actually broken.
DISPATCH_BRIEF_GRACE_SECONDS = 45
DISPATCH_BRIEF_POLL_SECONDS = 2
# After a re-brief, how long to wait for the lane to prove it started WORKING (its
# `.pending-start` marker being consumed by the first heartbeat). A TUI that has just
# booted needs longer to accept typed input than to answer a process check.
DISPATCH_REBRIEF_CONFIRM_SECONDS = 30


PREFLIGHT_FAILURE_DIRNAME = "preflight-failures"


#: The uppercase lead-in that marks a work item's acceptance criteria. Not a markdown
#: heading: declarations begin a line, optionally indented or in a markdown list.
#: Mentions elsewhere in prose do not declare readiness (WI-0309).
WI_ACCEPTANCE_MARK = "ACCEPTANCE"
#: `ACCEPTANCE MET`/`ACCEPTANCE MET AND PINNED` is a RECEIPT that the work is finished,
#: not a criterion for doing it. A naive substring match reads a closed item's receipt as
#: readiness, which is the exact `declare-what-a-check-assumes` collapse — two different
#: facts arriving at the same answer.
WI_ACCEPTANCE_RECEIPTS = ("ACCEPTANCE MET", "ACCEPTANCE RECORDED", "ACCEPTANCE VERIFIED")
#: An open decision on the item. `OPEN DECISION` is the literal in the store; the others
#: are the near neighbours a writer reaches for. Deliberately narrow and uppercase — the
#: word "decision" appears in 46 items as ordinary prose, and matching that would refuse
#: nearly everything for saying the word.
WI_OPEN_DECISION_MARKS = ("OPEN DECISION", "OPEN QUESTION", "DECISION NEEDED",
                          "UNDECIDED", "NEEDS A DECISION")

# Share the declaration syntax across the gate and its callers (including views).
# Horizontal whitespace cannot consume the next line; a word boundary excludes
# longer words such as ACCEPTANCES. Existing lead-ins and receipt wording still count.
WI_ACCEPTANCE_RE = re.compile(
    r"^[^\S\r\n]*(?:[-*][^\S\r\n]+)?" + re.escape(WI_ACCEPTANCE_MARK) + r"\b",
    re.MULTILINE | re.IGNORECASE)
WI_OPEN_DECISION_RE = re.compile(
    r"^[^\S\r\n]*(?:[-*][^\S\r\n]+)?(?:" +
    "|".join(re.escape(mark) for mark in WI_OPEN_DECISION_MARKS) + r")\b",
    re.MULTILINE | re.IGNORECASE)


#: WI-0376. The uppercase lead-in that declares WHICH FILES an item touches — its
#: "independence list", the thing a wave is composed from. Same shape and same argument
#: as `WI_ACCEPTANCE_MARK` above: a marker an author writes on purpose is a declaration,
#: checkable and fixable by editing one line, where a judgment call about which files a
#: title "implies" is exactly what P15 says not to put in code. It is parsed from the
#: item body rather than added to `WI_FIELD_RE` because four items already carry this
#: exact line and the agenda's own Bin A format is built on it — a new frontmatter field
#: would strand every one of them behind a 365-file migration to say what they already say.
WI_FILES_MARK = "FILES"
#: Line-initial, optionally a markdown list item, optionally indented. `\b` so FILESYSTEM
#: does not declare anything. CASE-SENSITIVE, unlike `WI_ACCEPTANCE_RE`, and the reason is
#: the word rather than the convention: "acceptance" is section vocabulary, "files" is an
#: everyday noun a writer reaches for mid-sentence. MEASURED on this store before choosing:
#: 4 items carry a line-initial `FILES:` and ZERO carry a line-initial lowercase `files:`,
#: so IGNORECASE would cost nothing today — it is refused for what it would match later,
#: because a declaration that can be made by accident is not a declaration.
WI_FILES_RE = re.compile(
    r"^[^\S\r\n]*(?:[-*][^\S\r\n]+)?" + WI_FILES_MARK + r"\b[^\S\r\n]*:(.*)$",
    re.MULTILINE)
#: A declared entry is a path when it looks like one — one unbroken word, which is what
#: separates `deploy/runner.py` and the extensionless-but-real `LICENSE` from WI-0350's
#: prose fragment "the registry schema". Requiring a slash or a dot instead would be
#: tighter and would throw away `LICENSE` and `NOTICE`, both of which WI-0383 genuinely
#: declares; requiring neither would read "the" out of "the registry schema" as a path.
WI_PATHISH_RE = re.compile(r"^[A-Za-z0-9_.\-]+(?:/[A-Za-z0-9_.\-]*)*/?$")
#: A path the author ANNOTATED: `deploy/registry.json (example-app row -> cutover: auto)`,
#: `tests/test_deploy_runner.py (+15 tests)`. Both are real entries in WI-0350's compiled
#: notes and both would read as unparseable prose on a bare word test, reporting a fully
#: declared item as only partly assessed. The annotation is dropped and the path kept.
WI_ANNOTATED_PATH_RE = re.compile(r"^(\S+)\s*\(.*\)$")
#: A work-item id anywhere in a commit subject or body.
WI_ID_IN_TEXT_RE = re.compile(r"\bWI-\d{4}\b")


def _process_chain(pid: int, limit: int = 8) -> list[tuple[int, str]]:
    """[(pid, argv)] from `pid` upward, nearest ancestor first. Empty when unreadable.

    ONE `ps` call rather than one per generation — the same whole-machine enumeration the
    lane-process scanner and `_pf_stranded_runtimes` already use, so there is one process-
    table convention in this file and not two. Walking up from a map is free once the
    table is in hand.

    Every failure returns SHORT, never wrong: a truncated chain makes the caller answer
    `unknown`, which is a state it handles.

    UNDER THE GATE the chain is empty (ADR-0119 D4) — the same `unknown` the caller already
    handles. Found by the completeness detector on its first run rather than by me: this
    and `_dispatch_runtime_pid` are two `ps` reaches the hand-written guard list missed,
    which is the whole argument for deriving the list from the source
    ([`ship-the-detector-with-the-capability`](habits/master.md#ship-the-detector-with-the-capability))."""
    if _under_gate():
        return []
    try:
        r = subprocess.run(["ps", "-axo", "pid=,ppid=,command="],
                           capture_output=True, text=True, check=False,
                           timeout=DISPATCH_SPAWN_TIMEOUT_SECONDS)
    except Exception:
        return []
    if r.returncode != 0:
        return []
    table: dict[int, tuple[int, str]] = {}
    for line in (r.stdout or "").splitlines():
        parts = line.split(None, 2)
        if len(parts) < 3:
            continue
        try:
            table[int(parts[0])] = (int(parts[1]), parts[2])
        except ValueError:
            continue
    out: list[tuple[int, str]] = []
    cur = pid
    for _ in range(limit):
        row = table.get(cur)
        if row is None:
            break
        out.append((cur, row[1]))
        cur = row[0]
        if cur <= 1:
            break
    return out


def _applescript_str(s: str) -> str:
    """Quote a shell command line for embedding in an AppleScript string literal."""
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


# ── A dispatched lane's end of life (WI-0249) ──────────────────────────────────
# `session.py end` closes the RECORD. It never closed the SESSION: the tmux command is
# `poga <prompt>`, which execs the runtime, and the runtime is still running after its own
# harness has stamped the journal closed. So a dispatched lane read as finished everywhere
# that mattered — journal ended, branch merged, handoff recompiled — while the process held
# a lane slot, a coordination record carrying `dispatch_id`, and a live tmux session, and
# went on burning tokens if anything woke it.
#
# `lane-close` is deliberately NOT in `COORD_KINDS`, on the same argument `_dispatch_dir`
# makes for dispatch records: it is not a HOLD. It has no TTL to refresh, no owner to
# release it from, and a lifetime measured in the seconds between `end` writing it and the
# wrapper shell reading it. Putting it in that tuple would hand it to the TTL reaper and
# the teardown release, neither of which has anything to say about a one-shot signal.
LANE_CLOSE_KIND = "lane-close"


# WI-0399 — THE LAUNCH RECEIPT, and it is the wrapper's half of the auto-exit.
#
# A closed session used to sit at its runtime's exit prompt until the operator closed the
# terminal by hand. `lane-exit` (WI-0249) already knew how to end a runtime, but the only
# way it could NAME one was `_dispatch_runtime_pid`, which finds the process by matching
# `POGA_DISPATCH=<id>` in an ancestor's command line — so it worked for a dispatched lane
# and for nothing else. A hand-opened session had no handle at all.
#
# `poga` has that handle and always did: `exec` REPLACES the wrapper's process image while
# KEEPING its pid, so `$$` read just before the exec IS the runtime, on every launch path
# and every runtime. This record is the wrapper writing that number down where the close
# can read it back.
#
# RUNTIME-AGNOSTIC BY CONSTRUCTION, which is a requirement here rather than a nicety. The
# exit lives in the wrapper and in `session.py`, never in a Claude hook: a Claude-only exit
# path would have to be rebuilt for Codex and Antigravity, and the floor is expressed as
# runtime-agnostic obligations with per-runtime bindings (ADR-0041).
#
# NOT A HOLD, for the same reason `lane-close` is not one: no TTL to refresh, no owner to
# release it from, nothing for the reaper or the teardown release to say about it. It is
# one fact about one launch, overwritten by the next launch into the same slot.
LANE_LAUNCH_KIND = "lane-launch"


#: How long a closed ATTENDED session holds its terminal open after printing the close
#: summary, before the runtime is signalled. The pause is the entire reason a human-opened
#: session does not just vanish: the summary is printed to a terminal somebody is looking
#: at, and a window that closes the instant it appears has not communicated anything.
#:
#: Zero for a dispatched lane in a detached pane — nobody is reading it, and the summary is
#: read off the board instead. That is not an optimisation; holding a detached pane
#: open for a reader who does not exist is what WI-0249 removed.
CLOSE_READ_PAUSE_SECONDS = 8.0


# WI-0399, the companion half — WHERE A CLOSE SUMMARY IS READ.
#
# The terminal is the wrong surface for it and always was: a summary printed there is
# gone the moment the window closes, it is only ever visible on the machine that ran the
# session, and with the auto-exit above the window now closes ITSELF. So the close
# publishes a record and the board renders it, exactly as `attention` already
# publishes "this lane needs you" and the board renders THAT.
#
# BOARD = WHERE IT IS READ, NOTIFICATION = THAT THERE IS SOMETHING TO READ. That split is
# the design rather than an implementation detail (operator, 2026-09-18): a notification
# carrying the whole summary makes the board redundant, and a board with no notification
# is a page nobody opens. Hence one record carrying both the full summary and its first
# line, and two consumers reading different fields of it.
#
# DELIBERATELY NOT IN `COORD_KINDS`, and the reason is sharper here than for `lane-close`:
# the kinds in that tuple are HOLDS, and the lane exit releases every one of them the
# moment a session closes. A close record put there would be deleted by the very event it
# exists to record. It expires on its own `expires_at` instead, which a reader checks
# against the clock with no write happening anywhere (the same read the board already does
# for an attention record).
SESSION_CLOSE_KIND = "session-close"


#: How long a close record stays renderable. A day, because the panel it feeds is "closed
#: TODAY" — a record older than that is history, and history is what the journal and the
#: handoff are for. Matches `ATTENTION_TTL_SECONDS` so the board ages both feeds the same
#: way.
SESSION_CLOSE_TTL_SECONDS = 24 * 3600


#: The cap on the one-line form of a close summary. A notification line, not a paragraph:
#: long enough to say which session closed and what it left, short enough that it cannot
#: quietly become a second copy of the summary and make the board pointless.
CLOSE_SUMMARY_LINE_CAP = 200


#: How long the reaper waits after SIGTERM before SIGKILL. Long enough for a runtime that
#: handles the signal to write whatever it writes on the way out; short enough that a
#: dispatch queue is not held up by one that ignores it. The escalation is what makes this
#: mechanism independent of how any particular runtime treats SIGTERM — a fact we could not
#: measure here (the probe was refused by the sandbox) and therefore must not depend on.
LANE_EXIT_GRACE_SECONDS = 10


#: The turns a dispatched lane gets by default (WI-0288 R2 (2)). One work item, landed
#: and closed, with room for the gate to be contended and retried — not a number derived
#: from anything, and deliberately generous: the budget exists to bound a lane that has
#: stopped converging, not to cut short one that is working. `--max-turns` overrides it.
DISPATCH_TURN_BUDGET_DEFAULT = 60


def _turn_budget_path(sid: str) -> Path:
    return SESSION_STATE_DIR / f"{sid}.turns"


def _turn_budget_used(sid: str) -> int:
    """Turns this session has spent. 0 when nothing has been counted — and reading a
    corrupt or unreadable counter is 0 too, because this is a hot-path hook that must
    never brick the tool it rides on (the `check-bash` fail-open contract)."""
    try:
        return int(_turn_budget_path(sid).read_text(encoding="utf-8").strip() or 0)
    except Exception:
        return 0


def _turn_budget_count(sid: str, event: str) -> int:
    """Count one TURN. Returns the new total.

    A TURN IS A `Stop`, NEVER A TOOL CALL — the load-bearing distinction. `heartbeat` is
    bound to both `Stop` and an all-tools `PreToolUse` (ADR-0054), and PreToolUse fires
    many times inside a single working turn. Counting beats instead of turns would burn a
    60-turn budget inside one turn that read a few files, which is not a bound on session
    length at all — it is a random early kill dressed as one.

    Only a DISPATCHED lane is counted. A session operator opened is his own and is bounded by
    him; a budget that fired in a hand-opened session would be the substrate deciding his
    conversation was over."""
    if event != "Stop" or not os.environ.get("POGA_DISPATCH", "").strip():
        return _turn_budget_used(sid)
    used = _turn_budget_used(sid) + 1
    with contextlib.suppress(Exception):
        SESSION_STATE_DIR.mkdir(parents=True, exist_ok=True)
        atomic_write(_turn_budget_path(sid), f"{used}\n")
    return used


def _turn_budget_notice(sid: str) -> str:
    """What the lane is told at the turn boundary once its budget is spent — empty while
    it still has turns, and empty for any session that has no budget at all.

    WHY A NOTICE AND NOT A KILL. The lane holds unlanded work in a worktree, so killing
    the runtime at turn N would strand exactly what the budget exists to protect. The
    sanctioned end of a dispatched lane is the one R3 already ships — park the item with
    its reasoning, land, close — and the notice's whole job is to route an out-of-turns
    lane into that same path rather than a different one. It names the verb, because an
    instruction with no way to carry it out is not an instruction."""
    budget = 0
    with contextlib.suppress(Exception):
        budget = int(os.environ.get("POGA_TURN_BUDGET", "").strip() or 0)
    if budget <= 0 or not os.environ.get("POGA_DISPATCH", "").strip():
        return ""
    used = _turn_budget_used(sid)
    if used < budget:
        return ""
    return (f"TURN BUDGET SPENT — {used}/{budget} turns. This lane has run out of the "
            f"turns its dispatch gave it. Do not start new work. Finish the turn you are "
            f"on, then close: if the item is done, land and close with `python3 "
            f"session.py merge --commit \"<message>\"`. If it is not done, PARK it — "
            f"write what you learned and what is left onto the item, then land and close "
            f"the same way. A dispatched lane needs no --confirm; its dispatch is its "
            f"authorization. Parking is the sanctioned outcome here, not a failure.")


def _tmux_bin() -> str | None:
    """Absolute path to tmux, or None. Resolved rather than assumed: a spawned lane's own
    shell may not have Homebrew on PATH (the same non-interactive-ssh gap STANDARD.md
    documents for `brew`), so the launcher passes a full path.

    NOT GATE-GUARDED, deliberately, and the first cut of ADR-0119 D4 got this wrong.
    Answering None under the gate looked like one cheap guard covering every `send-keys` in
    the tree — and it also made `_dispatch_resolve_surface` refuse, so `poga dispatch`
    PLANNING (which spawns nothing) exited 2 and eight `CliTest` cases failed under the
    gate and passed outside it. That is precisely the disease being cured, wearing the
    cure's clothes: a gate whose verdict differs from reality is worse than one that reads
    the machine, because it fails work that is fine. A lookup is not a reach; the guard
    belongs on the functions that actually spawn."""
    return shutil.which("tmux") or shutil.which("tmux", path="/opt/homebrew/bin:/usr/local/bin")


# Where macOS puts Ghostty's binary when the app is installed and nothing symlinks it onto
# PATH — which is the DEFAULT install, not an unusual one. Named as a constant because the
# refusal below has to print it: "not on PATH" is only actionable next to where it IS.
GHOSTTY_APP_DIR = "/Applications/Ghostty.app/Contents/MacOS"
GHOSTTY_APP_BIN = f"{GHOSTTY_APP_DIR}/ghostty"


def _ghostty_bin() -> str | None:
    """Absolute path to ghostty, or None. `_tmux_bin`'s argument, one machine later.

    WI-0167: a standard install puts Ghostty at `GHOSTTY_APP_BIN` and nothing
    puts it on PATH, so `shutil.which` answers None while the app sits plainly in
    /Applications. The caller's old `which("ghostty") or "ghostty"` turned that None into a
    bare name under `shell=True`, and the window died `command not found` — exit 127,
    surfaced as a generic template failure by the one subsystem built to refuse BY NAME.

    The second lookup is the same shape `_tmux_bin` uses for Homebrew: a second PATH to
    search, not a path to assume, so `which` still decides whether anything runnable is
    actually there. That also keeps the whole resolution answerable by mocking `which`.

    NOT gate-guarded, for `_tmux_bin`'s reason: a lookup is not a reach."""
    return shutil.which("ghostty") or shutil.which("ghostty", path=GHOSTTY_APP_DIR)


# A spawn must fail FAST and loudly. Found live (session ~105): with macOS Automation
# permission not yet granted to the host app, `osascript` does not error — it BLOCKS on
# the Apple Event until the ~120 s system timeout, so a dispatch of five items would sit
# silently for ten minutes before reporting anything. A hung launcher is the silent-strand
# failure this design exists to prevent, arriving through the launcher itself.
DISPATCH_SPAWN_TIMEOUT_SECONDS = 20
# Recognisable Apple Event failures whose real cause is a missing Automation grant. The
# error text is the only signal available, and a bare "-1712 timed out" sends the reader
# to debug their command line rather than System Settings.
_APPLE_EVENT_PERMISSION_HINT = (
    "Two different causes look identical here. If this session is inside the Runner's GUI "
    "login, macOS Automation permission is probably not granted: give your terminal app "
    "(and Claude Code, if you dispatch from a session) permission under "
    "System Settings → Privacy & Security → Automation, then re-run. If it is an SSH login "
    "(launchd manager 'Background', not 'Aqua'), no grant applies — Apple Events cannot "
    "reach a GUI app from outside the login session at all; use `spawn_surface: tmux` or "
    "'auto'. Either way, a lane can always be opened by hand: `poga` in the repo."
)


def _tmux_session_name(did: str, wid: str) -> str:
    """The tmux session name for a dispatched lane. Carries the dispatch id AND the item so
    `tmux ls` answers "what is running and why" without consulting the dispatch record —
    the same provenance-in-the-name argument as the spawn slot. `.` and `:` are reserved in
    tmux target syntax, so they are mapped out."""
    safe = re.sub(r"[^A-Za-z0-9_-]", "-", f"{did}-{wid}")
    return f"poga-{safe}"


# ── Attention: a lane may block on a question, never invisibly (ADR-0101) ────────────
# A dispatched lane is told to ask questions exactly as it would in a hand-opened session,
# so it will ask — and then wait. ADR-0100 makes the common case visible by giving every
# lane a window. This is the floor under the residual case: a window you have scrolled past
# is indistinguishable from a window with nothing in it, and every liveness signal we keep
# answers "did the process move", never "is a human there". Two abandoned lanes on
# 2026-08-22 read `interactive · idle` and `live — protected` for hours while nobody had
# been near either. So the record, not the interrupt, is what makes "waiting" true.

ATTENTION_KIND = "attention"
# Deliberately long. A question asked at 23:00 is still a real question at 08:00, and the
# thing that matters is its AGE, not whether some window has elapsed. Expiry exists only so
# a machine that dies mid-question does not leave a permanent ghost.
ATTENTION_TTL_SECONDS = 24 * 3600
# WI-0278: the append-only twin of the record above is `ESCALATION_LOG_SUFFIX`, defined up
# with the other `.session-state/` filenames because the janitor's retention list — three
# thousand lines above here — has to name it. The `attention` record answers "is a human
# being waited on RIGHT NOW"; the ledger answers "what did this session escalate, and how
# long did each one wait", which the live record structurally cannot carry because every
# clear destroys the event at the moment it is answered.


NOTIFY_TEXT_KEYS = ("message", "notification", "text")
# How many raw payloads to keep. Small on purpose: this exists to ANSWER a question
# (which key carries the text), not to become a log nobody prunes.
NOTIFY_PAYLOAD_KEEP = 20


# ── Attach: the operator's machine opens a window per dispatched lane (ADR-0100) ─────
# Dispatch runs on the WORK machine and spawns headless tmux lanes. This half runs on the
# machine the operator is sitting at and opens one local window per lane, each attached to
# that lane's tmux session. The split exists because a process on the work machine cannot
# open a window on the operator's machine: under mosh/ssh the launchd manager is
# `Background`, Apple Events cannot leave it, and no permission grant changes that. The
# code that opens windows has to run where the windows are.

ATTACH_POLL_SECONDS = 20
# Built-in launch templates. `{name}` is the tmux session name, and the command comes in
# TWO conventions because terminals genuinely disagree about which they want:
#
#   {cmd}   ONE shell-quoted argument — for a terminal whose flag takes a command STRING
#           it will hand to a shell (`tmux new-window -n x 'mosh … -- tmux attach …'`).
#   {argv}  the command line RAW, so the shell word-splits it into separate arguments —
#           for a terminal whose flag takes a command AND ITS ARGUMENTS.
#
# Ghostty is the second kind, and getting this wrong is not a subtle failure: with `{cmd}`
# it received the whole line as one argv element and ran `login -flp <user> 'mosh <host> --
# tmux attach -t poga-…'`, so `login` looked for a program by that entire name and the
# window opened showing `No such file or directory`. The check (session ~172):
# `ghostty -e "sleep 60"` errors, `ghostty -e sleep 60` does not. The
# template had never been run before then, which is why it shipped wrong.
#
# `{argv}` is raw but not unsafe: `_attach_command` builds `cmd` from already-quoted
# parts (host and session name both go through `shlex.quote`), so what interpolates here
# is a well-formed shell command line, not user text.
#
# Terminal and iTerm2 are not templates — they go through the AppleScript opener that
# dispatch already uses, so there is one implementation of that awkwardness rather than two.
ATTACH_TEMPLATES = {
    # `ghostty` itself is NOT here — it goes through the AppleScript dictionary so the
    # lanes land as TABS IN ONE WINDOW, which its CLI cannot do at all. This is the
    # window-per-lane form, kept as a named escape hatch for a desk that wants windows or a
    # Ghostty whose scripting is disabled (`macos-applescript = false`).
    "ghostty-window": "{ghostty} -e {argv}",
    # The overflow path from ADR-0100: no new window, a new WINDOW INSIDE the tmux the
    # operator is already attached to. Works where nothing else does — inside a plain ssh
    # session with no GUI anywhere.
    "tmux-window": "{tmux} new-window -n {name} {cmd}",
}
ATTACH_APPLESCRIPT = ("Terminal", "iTerm2")


DRILL_ITEM_PREFIX = "DRILL-"


DRILL_SCRIPT = """#!/bin/sh
# A FAKE lane, for exercising dispatch -> attach without touching anything real.
lane="$1"
poga="$2"
echo "════════ DRILL LANE $lane ════════"
echo "This is NOT a real lane. No journal is written, no session number is drawn, no"
echo "branch or worktree exists, and no BACKLOG item is touched."
echo
# THE ONE REAL THING IT DOES. the operator's ruling, session ~173: tests get as close to the real
# thing as possible. Claim and release are what a dispatched lane does first
# and last, they write to the shared coordination store, and until now the drill skipped
# exactly them — so the part that can leave residue was the part never rehearsed. The item
# is synthetic; the claim is the production code path.
if [ -n "$poga" ]; then
    echo "-- claiming $lane (real claim, synthetic item) --"
    "$poga" work claim "$lane" || echo "  claim REFUSED — that is a finding, not a pass."
    echo
fi
release_and_exit() {
    if [ -n "$poga" ]; then
        echo "-- releasing $lane --"
        "$poga" work release "$lane" || echo "  release FAILED — that is a finding."
    fi
    exit "${1:-0}"
}
echo "Type anything and press enter to see it echoed — that proves the tab is a live"
echo "terminal and not a screenshot. Type 'quit' to end this lane (and release its claim)."
echo "Closing the tab should DETACH and leave this running; that is the thing to test."
echo
while :; do
    printf '%s> ' "$lane"
    if IFS= read -r line; then
        case "$line" in
            quit) echo "  [$lane] ending."; release_and_exit 0 ;;
            "")   : ;;
            *)    echo "  [$lane] echo: $line" ;;
        esac
    else
        # Detached: no stdin. Sleep rather than spin, and stay alive so the operator can
        # reattach — a drill lane that dies on detach would fake a pass of the very test
        # this exists to run.
        sleep 3
    fi
done
"""


# WI-0183 raise modes, least to most intrusive. Every one is a real command in Ghostty's
# dictionary rather than a synthesized keystroke.
#
#   off       do nothing. The attention record is still written and still counted.
#   select    `select tab` — silent and in-place. The tab is selected INSIDE its window; if
#             Ghostty is behind another app nothing visible happens at all.
#   activate  `select tab` + `activate window` — the window comes to the front and Ghostty
#             becomes frontmost. This is the plain "come here".
#   focus     `select tab` + `focus` on the tab's focused terminal.
#
# THE LADDER IS NOT AS EVEN AS IT LOOKS, and the first version of this comment oversold it
# by calling `focus` the most intrusive. Per Ghostty's dictionary BOTH `activate window`
# and `focus` bring the window to the front — `focus` is documented as "Focus a terminal,
# bringing its window to the front". The real gap is between `select` (nothing moves) and
# the other two (the window moves). `activate` targets the WINDOW; `focus` targets one
# terminal SURFACE inside the tab, which only differs when that tab is split into panes.
# Stated accurately here because this comment is the reference the config points at.
#
# ALL FOUR EXIST BECAUSE operator RULED FOR ALL FOUR (session ~173: the mode is a setting that
# offers every option, and the operator picks). The item had proposed picking one and reserving
# `focus` for an age threshold; the threshold survives as `attach_raise_after`, which
# escalates to `focus` on its own, but the base mode is his to set rather than mine.
ATTACH_RAISE_MODES = ("off", "select", "activate", "focus")
# the operator's call, session ~173, after the three were laid out side by side: `activate` as the
# default for now — the plain come-here rather than the silent badge. "For now" is worth
# keeping: this is the first setting chosen before anyone has watched a
# tab actually raise, so it is a starting point to revise against real fan-outs, not a
# settled preference. `session.config.json` declares it explicitly so changing it is a
# config edit rather than a code change.
ATTACH_RAISE_DEFAULT = "activate"


NO_RENUMBER_HELP = (
    "WI-0169: REFUSE a land whose new WI numbers collide with the trunk, instead of "
    "remapping them. The land normally draws replacements, moves each item's file, H1, "
    "notes, claim and blocked-by edges, rewrites the citations this lane authored, and "
    "prints every change. Pass this to see the collision list first and remap by hand "
    "with `session.py wi-renumber`."
)
